# =============================================================================
# Effect Type Name Conversion Helpers
# =============================================================================

def effect_type_to_display(effect_type: str) -> str:
    """Convert internal effect_type (e.g., 'pixel_chase') to display text (e.g., 'Pixel Chase')."""
    if not effect_type:
        return "Static"
    # Convert underscores to spaces and title case
    return effect_type.replace('_', ' ').title()


def display_to_effect_type(display_text: str) -> str:
    """Convert display text (e.g., 'Pixel Chase') to internal effect_type (e.g., 'pixel_chase')."""
    if not display_text:
        return "static"
    # Convert to lowercase and replace spaces with underscores
    return display_text.lower().replace(' ', '_')


# =============================================================================
# MIDI Manager for MIDI Learn functionality
# Uses Windows native MIDI (winmm) on Windows, mido as fallback for other platforms
# =============================================================================

class MIDIManager(QObject):
    """Manages MIDI input for triggering presets via MIDI learn."""
    
    # Signal emitted when a MIDI message is received (for learn mode)
    midi_received = pyqtSignal(str)  # Emits a string like "note:60" or "cc:1"
    # Signal for triggering presets from MIDI (cross-thread safe)
    midi_trigger = pyqtSignal(str)   # Emits midi_key to trigger presets
    # Signal for fader CC values (continuous control)
    midi_cc_value = pyqtSignal(str, int)  # Emits (cc_key, value 0-127)
    # Signal for pitch bend values (V1-M / MCU motorized faders, 14-bit)
    midi_pb_value = pyqtSignal(str, int)  # Emits (pb_key like "pb:1", value 0-16383)
    # Signal for encoder-style note messages (d2=127 for one direction, d2=0 for other)
    midi_encoder_value = pyqtSignal(str, int)  # Emits (note_key like "note:96", direction: 1=up, -1=down)
    # Signal for fader-controlled execution intensity (for effects with fader intensity control)
    midi_fader_intensity = pyqtSignal(str, int)  # Emits (midi_key, intensity_pct 0-100)
    # Signal for connection status changes (for UI updates)
    connection_changed = pyqtSignal(bool)  # Emits True when connected, False when disconnected
    # Signal for reconnection events (for UI notification)
    reconnected = pyqtSignal(str)  # Emits device name when auto-reconnected
    # Signal for flash button press/release from MIDI (fader_id, is_pressed)
    midi_flash_event = pyqtSignal(str, bool)
    # Signal for dynamic button press/release (slot_index, is_pressed)
    midi_dynamic_button_event = pyqtSignal(int, bool)
    # Signal for fader touch (slot_index, is_touched) — maps physical touch-sensitive faders to UI highlight
    midi_fader_touch = pyqtSignal(int, bool)
    # Signal for MTC quarter-frame from connected MIDI device (piece 0-7, nibble value)
    midi_mtc_quarter_frame = pyqtSignal(int, int)
    # Signal for MTC full-frame from connected MIDI device (hh, mm, ss, ff)
    midi_mtc_full_frame = pyqtSignal(int, int, int, int)
    
    # APC mini mk2 LED color values (velocity)
    LED_OFF = 0
    LED_GREEN = 21      # Green
    LED_GREEN_BLINK = 22
    LED_RED = 5         # Red  
    LED_YELLOW = 9      # Yellow/Amber
    LED_ORANGE = 84     # Orange
    LED_BLUE = 67       # Blue
    LED_PURPLE = 53     # Purple
    LED_CYAN = 37       # Cyan
    LED_WHITE = 3       # White
    
    def __init__(self, parent=None):
        super().__init__(parent)
        # Support multiple MIDI controllers
        self._connections = []  # List of connection dicts: {'port': mido_port, 'name': str, 'thread': Thread, 'winmm_handle': handle, 'winmm_callback': callback, 'winmm_device_id': int, 'winmm_out_handle': handle}
        self._running = False
        self._learn_mode = False
        self._last_received_key = None  # For polling in learn mode
        self._last_received_device = None  # Track which device sent last message (for learn mode)
        self._mappings = {}  # Map midi_key -> list of preset_ids
        self._preset_callbacks = {}  # Map preset_id -> callback function
        self._preset_colors = {}  # Map preset_id -> hex color for LED feedback
        self._fader_mappings = {}  # Map cc_key -> fader_id (e.g., "master", "effect_speed")
        self._fader_callbacks = {}  # Map fader_id -> callback function(value 0-127)
        self._mapping_devices = {}  # Map midi_key -> device_name (track which controller made each mapping)
        self._encoder_directions = {}  # Map note_key -> direction (1=increment, -1=decrement)
        self._flash_mappings = {}  # Map note_key -> fader_id (for flash buttons)
        self._flash_callbacks = {}  # Map fader_id -> {'press': callback, 'release': callback}
        self._dynamic_button_slots = {}  # Map note_key -> slot_index (for dynamic flash buttons)
        self._touch_note_mappings: dict[str, int] = {}  # Map note_key -> dynamic slot index (fader touch)
        self._relative_ccs: set[str] = set()  # CC keys that are jog wheels / relative encoders
        self._trigger_queue: Queue = Queue()  # Thread-safe queue for trigger dispatch
        # Blinking LED state for active preset
        self._blink_timer = None
        self._blink_midi_key = None
        self._blink_preset_id = None
        self._blink_color = self.LED_GREEN
        self._blink_state = False  # True = on, False = off
        
        # Auto-reconnect support for sleep/wake
        self._saved_ports = []  # Ports to auto-reconnect to
        self._watchdog_timer = None  # Timer to check connection health
        self._last_connection_check = 0  # Timestamp of last successful check
        self._reconnect_in_progress = False  # Prevent concurrent reconnect attempts
        
        # V1-M small screen (secondary display) buffer — must send all 56 bytes at once
        self._strip_upper = [b'       '] * 8  # 8 x 7-byte ASCII for upper row
        self._strip_lower = [b'       '] * 8  # 8 x 7-byte ASCII for lower row
        
        # Connect trigger signal to handler (queued for cross-thread safety)
        self.midi_trigger.connect(self._trigger_preset, Qt.ConnectionType.QueuedConnection)
        # Connect CC value signal to fader handler
        self.midi_cc_value.connect(self._handle_cc_value, Qt.ConnectionType.QueuedConnection)
        # Connect pitch bend signal to fader handler (V1-M / MCU)
        self.midi_pb_value.connect(self._handle_pb_value, Qt.ConnectionType.QueuedConnection)
        # Connect encoder signal to handler (for note-based rotary encoders)
        self.midi_encoder_value.connect(self._handle_encoder_value, Qt.ConnectionType.QueuedConnection)

        # Fast poll timer to drain _trigger_queue on the main thread
        self._trigger_poll_timer = QTimer(self)
        self._trigger_poll_timer.setInterval(15)  # ~67 Hz
        self._trigger_poll_timer.timeout.connect(self._drain_trigger_queue)
        self._trigger_poll_timer.start()
        
    def _drain_trigger_queue(self):
        """Process all pending trigger keys from the thread-safe queue (runs on main thread)."""
        while not self._trigger_queue.empty():
            try:
                midi_key = self._trigger_queue.get_nowait()
                logger.info(f"[MIDI DRAIN] Processing trigger: {midi_key}")
                self._trigger_preset(midi_key)
            except Empty:
                break

    @property
    def is_available(self) -> bool:
        return MIDI_AVAILABLE
    
    @property
    def is_connected(self) -> bool:
        return len(self._connections) > 0
    
    @property
    def has_v1m_connection(self) -> bool:
        """Return True if an Icon V1-M / MCU-compatible controller is connected."""
        for conn in self._connections:
            if conn.get('winmm_out_handle') is None:
                continue
            name = conn.get('name', '').lower()
            if 'icon' in name or 'v1' in name or 'mcu' in name:
                return True
        return False

    def get_connected_devices(self) -> list:
        """Get list of currently connected MIDI device names."""
        return [conn['name'] for conn in self._connections]
    
    def start_watchdog(self, ports_to_watch: list = None):
        """Start the connection watchdog timer for auto-reconnect after sleep/wake.
        
        Args:
            ports_to_watch: List of port names to auto-reconnect to. If None, uses currently connected ports.
        """
        if ports_to_watch:
            self._saved_ports = list(ports_to_watch)
        elif self._connections:
            self._saved_ports = [conn['name'] for conn in self._connections]
        
        if not self._saved_ports:
            print("[MIDI] No ports to watch for auto-reconnect")
            return
        
        # Create watchdog timer if not exists
        if self._watchdog_timer is None:
            self._watchdog_timer = QTimer(self)
            self._watchdog_timer.timeout.connect(self._watchdog_check)
        
        # Check every 3 seconds
        self._watchdog_timer.start(3000)
        print(f"[MIDI] Watchdog started, monitoring: {self._saved_ports}")
    
    def stop_watchdog(self):
        """Stop the connection watchdog timer."""
        if self._watchdog_timer:
            self._watchdog_timer.stop()
            print("[MIDI] Watchdog stopped")
    
    def _watchdog_check(self):
        """Periodic check for MIDI device health and reconnection."""
        if self._reconnect_in_progress:
            return
        
        try:
            # Get currently available ports
            available_ports = self.get_input_ports()
            
            # Check if any saved ports have disappeared (device unplugged/sleep)
            disconnected_ports = []
            for conn in list(self._connections):
                port_name = conn['name']
                if port_name not in available_ports:
                    print(f"[MIDI] Device disconnected (sleep/unplug?): {port_name}")
                    disconnected_ports.append(port_name)
                    # Clean up the dead connection
                    self._cleanup_dead_connection(conn)
            
            # If we had connections and lost them all, emit signal
            if disconnected_ports and not self._connections:
                self.connection_changed.emit(False)
            
            # Try to reconnect to any saved ports that are now available but not connected
            connected_names = [c['name'] for c in self._connections]
            for saved_port in self._saved_ports:
                if saved_port in available_ports and saved_port not in connected_names:
                    print(f"[MIDI] Device available again, reconnecting: {saved_port}")
                    self._reconnect_in_progress = True
                    try:
                        if self.connect(saved_port):
                            print(f"[MIDI] Auto-reconnected to: {saved_port}")
                            self.reconnected.emit(saved_port)
                            self.connection_changed.emit(True)
                            # Re-initialize MCU devices if needed
                            conn = next((c for c in self._connections if c['name'] == saved_port), None)
                            if conn and conn.get('winmm_out_handle'):
                                if 'icon' in saved_port.lower() and 'v1' in saved_port.lower():
                                    print(f"[MIDI] Re-initializing Icon V1-M after reconnect...")
                                    self._initialize_mcu_device(conn['winmm_out_handle'])
                            # Refresh LEDs after reconnect
                            QTimer.singleShot(500, self.refresh_all_leds)
                    finally:
                        self._reconnect_in_progress = False
                        
        except Exception as e:
            print(f"[MIDI] Watchdog check error: {e}")
            import traceback
            traceback.print_exc()
    
    def _cleanup_dead_connection(self, conn: dict):
        """Clean up a connection that has gone dead (device unplugged/sleep)."""
        port_name = conn['name']
        
        try:
            # Try to close Windows MIDI handles (may fail if device is gone)
            if conn.get('winmm_handle'):
                try:
                    winmm = ctypes.windll.winmm
                    winmm.midiInStop(conn['winmm_handle'])
                    winmm.midiInClose(conn['winmm_handle'])
                except Exception:
                    pass  # Device already gone
            
            if conn.get('winmm_out_handle'):
                try:
                    winmm = ctypes.windll.winmm
                    winmm.midiOutClose(conn['winmm_out_handle'])
                except Exception:
                    pass  # Device already gone
            
            # Try to close mido port
            if conn.get('port'):
                try:
                    conn['port'].close()
                except Exception:
                    pass  # Port already invalid
        except Exception as e:
            print(f"[MIDI] Error cleaning up dead connection: {e}")
        
        # Remove from connections list
        if conn in self._connections:
            self._connections.remove(conn)
            print(f"[MIDI] Removed dead connection: {port_name}")

    def get_input_ports(self) -> list:
        """Get list of available MIDI input ports."""
        ports = []
        
        # Windows native MIDI
        if HAS_WINDOWS_MIDI:
            try:
                winmm = ctypes.windll.winmm
                num_devs = winmm.midiInGetNumDevs()
                
                class MIDIINCAPS(ctypes.Structure):
                    _fields_ = [
                        ("wMid", ctypes.wintypes.WORD),
                        ("wPid", ctypes.wintypes.WORD),
                        ("vDriverVersion", ctypes.wintypes.DWORD),
                        ("szPname", ctypes.c_wchar * 32),
                        ("dwSupport", ctypes.wintypes.DWORD),
                    ]
                
                for i in range(num_devs):
                    caps = MIDIINCAPS()
                    res = winmm.midiInGetDevCapsW(i, ctypes.byref(caps), ctypes.sizeof(caps))
                    if res == 0:
                        ports.append(f"[{i}] {caps.szPname}")
            except Exception as e:
                print(f"[MIDI] Error enumerating Windows MIDI devices: {e}")
        
        # mido fallback
        elif HAS_MIDI_MIDO:
            try:
                ports = list(mido.get_input_names())
            except Exception as e:
                print(f"[MIDI] Error getting mido input ports: {e}")
        
        return ports
    
    def connect(self, port_name: str) -> bool:
        """Connect to a MIDI input port (can be called multiple times for multiple controllers)."""
        if not MIDI_AVAILABLE:
            return False
        
        # Check if already connected to this port
        if any(conn['name'] == port_name for conn in self._connections):
            print(f"[MIDI] Already connected to: {port_name}")
            return True
        
        # Windows native MIDI
        if HAS_WINDOWS_MIDI and port_name.startswith("["):
            try:
                # Parse device ID from format "[0] Device Name"
                dev_id = int(port_name.split("]")[0].strip("["))
                return self._connect_winmm(dev_id, port_name)
            except Exception as e:
                print(f"[MIDI] Failed to parse Windows MIDI device: {e}")
                return False
        
        # mido fallback
        elif HAS_MIDI_MIDO:
            try:
                port = mido.open_input(port_name)
                thread = threading.Thread(target=self._midi_loop_mido, args=(port,), daemon=True)
                thread.start()
                
                self._connections.append({
                    'port': port,
                    'name': port_name,
                    'thread': thread,
                    'winmm_handle': None,
                    'winmm_callback': None,
                    'winmm_device_id': None,
                    'winmm_out_handle': None
                })
                self._running = True
                print(f"[MIDI] Connected via mido: {port_name}")
                return True
            except Exception as e:
                print(f"[MIDI] Failed to connect via mido to {port_name}: {e}")
                return False
        
        return False
    
    def disconnect_port(self, port_name: str):
        """Disconnect a specific MIDI port."""
        conn = next((c for c in self._connections if c['name'] == port_name), None)
        if not conn:
            return
        
        # Close Windows MIDI
        if conn.get('winmm_handle'):
            try:
                winmm = ctypes.windll.winmm
                winmm.midiInStop(conn['winmm_handle'])
                winmm.midiInClose(conn['winmm_handle'])
                print(f"[MIDI] Closed Windows MIDI input: {port_name}")
            except Exception as e:
                print(f"[MIDI] Error closing Windows MIDI input: {e}")
        
        if conn.get('winmm_out_handle'):
            try:
                winmm = ctypes.windll.winmm
                winmm.midiOutClose(conn['winmm_out_handle'])
                print(f"[MIDI] Closed Windows MIDI output: {port_name}")
            except Exception as e:
                print(f"[MIDI] Error closing Windows MIDI output: {e}")
        
        # Close mido port
        if conn.get('port'):
            try:
                conn['port'].close()
                print(f"[MIDI] Closed mido port: {port_name}")
            except Exception as e:
                print(f"[MIDI] Error closing mido port: {e}")
        
        self._connections.remove(conn)
        print(f"[MIDI] Disconnected: {port_name}")
    
    def disconnect(self):
        """Disconnect all MIDI ports."""
        for conn in list(self._connections):
            self.disconnect_port(conn['name'])
        self._connections.clear()
        self._running = False
    
    def _connect_winmm(self, device_id: int, port_name: str) -> bool:
        """Connect to a Windows MIDI input device using winmm."""
        try:
            winmm = ctypes.windll.winmm
            
            # Define callback type with 64-bit safe pointer sizes
            DWORD_PTR = ctypes.c_size_t
            CALLBACK = ctypes.WINFUNCTYPE(None, ctypes.wintypes.HANDLE, ctypes.wintypes.UINT, 
                                          DWORD_PTR, DWORD_PTR, DWORD_PTR)
            
            def midi_in_callback(hMidiIn, wMsg, dwInstance, dwParam1, dwParam2):
                MIM_DATA = 0x3C3
                MIM_OPEN = 0x3C1
                MIM_CLOSE = 0x3C2
                MIM_LONGDATA = 0x3C4
                MIM_ERROR = 0x3C5
                MIM_LONGERROR = 0x3C6
                MIM_MOREDATA = 0x3CC
                
                # Debug all messages
                if wMsg != MIM_DATA:
                    print(f"[MIDI] Callback ({port_name}): wMsg=0x{wMsg:X} dwParam1=0x{dwParam1:X}")
                
                if wMsg == MIM_DATA:
                    msg = dwParam1
                    status = msg & 0xFF
                    data1 = (msg >> 8) & 0xFF
                    data2 = (msg >> 16) & 0xFF
                    status_type = status & 0xF0
                    channel = status & 0x0F
                    
                    # ── MTC Quarter Frame (system common 0xF1) ──
                    # Handle before debug print to avoid flooding at 240 Hz
                    if status == 0xF1:
                        piece = (data1 >> 4) & 0x07
                        nibble_val = data1 & 0x0F
                        try:
                            self.midi_mtc_quarter_frame.emit(piece, nibble_val)
                        except Exception:
                            pass
                        return  # MTC handled, don't process as note/CC

                    print(f"[MIDI] Data from {port_name}: status=0x{status:02X} type=0x{status_type:02X} ch={channel} d1={data1} d2={data2}")
                    midi_key = None
                    is_fader = False  # Track if this is a fader-type input
                    
                    if status_type == 0x80:  # Note Off
                        note_key = f"note:{data1}"
                        # Check fader touch release
                        if note_key in self._touch_note_mappings and not self._learn_mode:
                            slot_idx = self._touch_note_mappings[note_key]
                            print(f"[MIDI Touch] Note OFF key={note_key} slot={slot_idx} -> release")
                            try:
                                self.midi_fader_touch.emit(slot_idx, False)
                            except Exception as e:
                                print(f"[MIDI] Touch release emit error: {e}")
                        # Check dynamic button slots for release
                        if note_key in self._dynamic_button_slots and not self._learn_mode:
                            slot_idx = self._dynamic_button_slots[note_key]
                            print(f"[MIDI DynBtn] Note OFF: {note_key} -> release slot {slot_idx}")
                            try:
                                self.midi_dynamic_button_event.emit(slot_idx, False)
                            except Exception as e:
                                print(f"[MIDI DynBtn] Release emit error: {e}")
                        # Check flash mappings for release
                        elif note_key in self._flash_mappings and not self._learn_mode:
                            fader_id = self._flash_mappings[note_key]
                            print(f"[MIDI Flash] Note OFF: {note_key} -> release {fader_id}")
                            try:
                                self.midi_flash_event.emit(fader_id, False)
                            except Exception as e:
                                print(f"[MIDI Flash] Release emit error: {e}")
                    elif status_type == 0x90:  # Note On (may have velocity 0 for encoders)
                        # Check fader touch notes first (e.g. Icon V1-M notes 104-112)
                        touch_key = f"note:{data1}"
                        if touch_key in self._touch_note_mappings and not self._learn_mode:
                            slot_idx = self._touch_note_mappings[touch_key]
                            is_touched = data2 > 0
                            print(f"[MIDI Touch] key={touch_key} slot={slot_idx} touched={is_touched}")
                            try:
                                self.midi_fader_touch.emit(slot_idx, is_touched)
                            except Exception as e:
                                print(f"[MIDI] Touch emit error: {e}")
                        # Filter out Icon V1-M fader touch detection notes (104-112)
                        # These notes are sent when touching faders, not pressing buttons
                        # APC mini pads use notes 0-63, 64-71, 112-119 on channel 0
                        # Icon V1-M fader touches use notes 104-112 on channel 0
                        # Allow them through in learn mode so touch learn can capture them
                        if not (channel == 0 and 104 <= data1 <= 112) or self._learn_mode:
                            note_key = f"note:{data1}"
                            
                            # In learn mode, always capture note messages (for encoder learning)
                            if self._learn_mode:
                                midi_key = note_key
                            # Check explicit trigger mappings first (e.g., page nav arrows)
                            # These take priority over dynamic button/flash slots
                            elif note_key in self._mappings and data2 > 0:
                                midi_key = note_key
                            # Check dynamic button slots (note on with vel>0 = press, vel=0 = release)
                            elif note_key in self._dynamic_button_slots:
                                slot_idx = self._dynamic_button_slots[note_key]
                                is_pressed = data2 > 0
                                print(f"[MIDI DynBtn] Note ON vel={data2}: {note_key} -> {'press' if is_pressed else 'release'} slot {slot_idx}")
                                try:
                                    self.midi_dynamic_button_event.emit(slot_idx, is_pressed)
                                except Exception as e:
                                    print(f"[MIDI DynBtn] emit error: {e}")
                            # Check flash mappings (note on with vel>0 = press, vel=0 = release)
                            elif note_key in self._flash_mappings:
                                fader_id = self._flash_mappings[note_key]
                                is_pressed = data2 > 0
                                print(f"[MIDI Flash] Note ON vel={data2}: {note_key} -> {'press' if is_pressed else 'release'} {fader_id}")
                                try:
                                    self.midi_flash_event.emit(fader_id, is_pressed)
                                except Exception as e:
                                    print(f"[MIDI Flash] emit error: {e}")
                            # Check if this note is mapped as a fader (encoder mode)
                            elif note_key in self._fader_mappings:
                                # Encoder-style: d2=127 (or high) = increase, d2=0 = decrease
                                direction = 1 if data2 >= 64 else -1
                                is_fader = True
                                print(f"[MIDI] Encoder note: {note_key} direction={direction} (d2={data2})")
                                try:
                                    self.midi_encoder_value.emit(note_key, direction)
                                except Exception as e:
                                    print(f"[MIDI] Encoder emit error: {e}")
                            elif data2 > 0:
                                # Regular note on (button press)
                                midi_key = note_key
                    elif status_type == 0xB0:  # Control Change
                        # Include channel in CC key so different channels are unique
                        # Icon V1-M sends same CC# on different channels for each fader
                        cc_key = f"cc:{channel}:{data1}"
                        is_fader = True
                        # Always emit CC value for fader control
                        try:
                            self.midi_cc_value.emit(cc_key, data2)
                        except Exception as e:
                            print(f"[MIDI] CC value emit error: {e}")
                        # Check if this fader is mapped to a preset for intensity control
                        if not self._learn_mode and cc_key in self._mappings:
                            try:
                                # Map CC value (0-127) to percentage (0-100)
                                intensity_pct = int(data2 * 100 / 127)
                                self.midi_fader_intensity.emit(cc_key, intensity_pct)
                            except Exception as e:
                                print(f"[MIDI] Intensity emit error: {e}")
                        # Only allow CC to be learned, never to trigger presets as button
                        if self._learn_mode:
                            midi_key = cc_key
                        elif not self._learn_mode and cc_key in self._mappings:
                            # CC key has explicit trigger mapping (e.g. page nav)
                            # Check if it has a callback (not just fader intensity)
                            has_cb = any(
                                pid in self._preset_callbacks
                                for pid in self._mappings.get(cc_key, [])
                            )
                            if has_cb:
                                midi_key = cc_key
                                logger.info(f"[MIDI] CC {cc_key} has trigger callback, setting midi_key")
                    elif status_type == 0xE0:  # Pitch Bend (V1-M / MCU motorized faders)
                        # Pitch bend uses 14-bit value: LSB in data1, MSB in data2
                        # Channel determines which fader (channel 0 = fader 1, etc.)
                        pb_value = (data2 << 7) | data1  # 0-16383
                        pb_key = f"pb:{channel + 1}"  # Use 1-indexed fader number
                        is_fader = True
                        print(f"[MIDI] Pitch Bend: fader {channel + 1}, value={pb_value} (14-bit)")
                        # Emit pitch bend value for fader control
                        try:
                            self.midi_pb_value.emit(pb_key, pb_value)
                        except Exception as e:
                            print(f"[MIDI] Pitch Bend emit error: {e}")
                        # Check if this fader is mapped to a preset for intensity control
                        if not self._learn_mode and pb_key in self._mappings:
                            try:
                                # Map PB value (0-16383) to percentage (0-100)
                                intensity_pct = int(pb_value * 100 / 16383)
                                self.midi_fader_intensity.emit(pb_key, intensity_pct)
                            except Exception as e:
                                print(f"[MIDI] Intensity emit error: {e}")
                        # For learn mode, treat any movement as a "key"
                        if self._learn_mode:
                            midi_key = pb_key
                    
                    if midi_key:
                        logger.info(f"[MIDI CB] midi_key={midi_key} fader={is_fader} learn={self._learn_mode}")
                        print(f"[MIDI] Received: {midi_key} (fader={is_fader}, learn_mode={self._learn_mode})")
                        if self._learn_mode:
                            # Store key for polling (more reliable than cross-thread signal)
                            self._last_received_key = midi_key
                            self._last_received_device = port_name  # Track which device sent this
                            # Also try signal (may not work from callback thread)
                            try:
                                self.midi_received.emit(midi_key)
                            except Exception as e:
                                print(f"[MIDI] Signal emit error: {e}")
                        elif not is_fader:
                            # Only trigger button-style presets for note messages, not faders
                            # Faders use the midi_fader_intensity path instead
                            try:
                                logger.info(f"[MIDI CB] Queuing trigger for: {midi_key}")
                                print(f"[MIDI] Queuing trigger for: {midi_key}")
                                self._trigger_queue.put(midi_key)
                            except Exception as e:
                                print(f"[MIDI] Trigger queue error: {e}")
                        elif is_fader and midi_key in self._mappings:
                            # Fader-type key (CC/PB) that has an explicit trigger mapping
                            try:
                                logger.info(f"[MIDI CB] Fader key queuing trigger: {midi_key}")
                                print(f"[MIDI] Fader key has trigger callback, queuing: {midi_key}")
                                self._trigger_queue.put(midi_key)
                            except Exception as e:
                                print(f"[MIDI] Trigger queue error: {e}")

                elif wMsg == MIM_LONGDATA:
                    # SysEx message received — check for MTC full-frame
                    # dwParam1 is a pointer to the MIDIHDR structure
                    try:
                        sysex_hdr = getattr(self, '_mcu_sysex_hdr', None)
                        sysex_buf = getattr(self, '_mcu_sysex_buf', None)
                        if sysex_hdr is not None and sysex_buf is not None:
                            n = sysex_hdr.dwBytesRecorded
                            if n >= 10:
                                raw = bytes(sysex_buf[:n])
                                # MTC full-frame SysEx: F0 7F 7F 01 01 hh mm ss ff F7
                                if (raw[0] == 0xF0 and raw[1] == 0x7F
                                        and raw[3] == 0x01 and raw[4] == 0x01
                                        and n >= 10):
                                    hh = raw[5] & 0x1F
                                    mm = raw[6]
                                    ss = raw[7]
                                    ff = raw[8]
                                    rate_bits = (raw[5] >> 5) & 0x03
                                    fps = {0: 24, 1: 25, 2: 29.97, 3: 30}.get(rate_bits, 30)
                                    try:
                                        self.midi_mtc_full_frame.emit(hh, mm, ss, ff)
                                    except Exception:
                                        pass
                            # Re-queue the SysEx buffer for the next message
                            sysex_hdr.dwBytesRecorded = 0
                            try:
                                winmm = ctypes.windll.winmm
                                winmm.midiInAddBuffer(
                                    hMidiIn,
                                    ctypes.byref(sysex_hdr),
                                    ctypes.sizeof(sysex_hdr))
                            except Exception:
                                pass
                    except Exception as e:
                        print(f"[MIDI] MIM_LONGDATA error: {e}")
            
            # Keep callback reference to prevent GC
            callback = CALLBACK(midi_in_callback)
            
            # Open MIDI input
            hIn = ctypes.c_void_p()
            res = winmm.midiInOpen(ctypes.byref(hIn), device_id, callback, 0, 0x00030000)
            if res != 0:
                print(f"[MIDI] Failed to open Windows MIDI device {device_id}, error={res}")
                return False
            
            # Start receiving
            res = winmm.midiInStart(hIn)
            if res != 0:
                winmm.midiInClose(hIn)
                print(f"[MIDI] Failed to start Windows MIDI input, error={res}")
                return False
            
            print(f"[MIDI] Connected via Windows MIDI: {port_name}")
            
            # Open MIDI output for LED feedback (find matching output device)
            hOut = self._open_winmm_output(port_name)
            
            # Add to connections list
            self._connections.append({
                'port': None,
                'name': port_name,
                'thread': None,
                'winmm_handle': hIn,
                'winmm_callback': callback,
                'winmm_device_id': device_id,
                'winmm_out_handle': hOut
            })
            self._running = True
            
            # Initialize MCU mode for Icon V1-M (makes faders send data)
            if 'icon' in port_name.lower() and 'v1' in port_name.lower():
                print(f"[MIDI] Detected Icon V1-M, sending MCU handshake...")
                self._initialize_mcu_device(hOut, hIn)
            
            return True
            
        except Exception as e:
            print(f"[MIDI] Windows MIDI connection error: {e}")
            return False
    
    def _open_winmm_output(self, input_port_name: str):
        """Open the matching MIDI output device for LED feedback. Returns handle or None."""
        try:
            winmm = ctypes.windll.winmm
            
            # Get number of output devices
            num_devs = winmm.midiOutGetNumDevs()
            print(f"[MIDI] Found {num_devs} MIDI output devices")
            
            class MIDIOUTCAPS(ctypes.Structure):
                _fields_ = [
                    ("wMid", ctypes.wintypes.WORD),
                    ("wPid", ctypes.wintypes.WORD),
                    ("vDriverVersion", ctypes.wintypes.DWORD),
                    ("szPname", ctypes.c_wchar * 32),
                    ("wTechnology", ctypes.wintypes.WORD),
                    ("wVoices", ctypes.wintypes.WORD),
                    ("wNotes", ctypes.wintypes.WORD),
                    ("wChannelMask", ctypes.wintypes.WORD),
                    ("dwSupport", ctypes.wintypes.DWORD),
                ]
            
            # Extract device name from input port name (format: "[0] Device Name")
            input_dev_name = input_port_name.split("] ", 1)[-1] if "] " in input_port_name else input_port_name
            print(f"[MIDI] Looking for output matching: '{input_dev_name}'")
            
            # Find matching output device
            for i in range(num_devs):
                caps = MIDIOUTCAPS()
                res = winmm.midiOutGetDevCapsW(i, ctypes.byref(caps), ctypes.sizeof(caps))
                if res == 0:
                    out_name = caps.szPname
                    print(f"[MIDI]   Output [{i}]: '{out_name}'")
                    # Check if output device name matches input device name (case insensitive, partial match)
                    if input_dev_name.lower() in out_name.lower() or out_name.lower() in input_dev_name.lower():
                        # Open MIDI output
                        hOut = ctypes.c_void_p()
                        res = winmm.midiOutOpen(ctypes.byref(hOut), i, 0, 0, 0)
                        if res == 0:
                            print(f"[MIDI] Opened output for LED feedback: [{i}] {out_name}")
                            return hOut
                        else:
                            print(f"[MIDI] Failed to open output device {i}, error={res}")
            
            print(f"[MIDI] No matching output device found for LED feedback")
            return None
            
        except Exception as e:
            print(f"[MIDI] Error opening MIDI output: {e}")
            import traceback
            traceback.print_exc()
            return None
    
    def _initialize_mcu_device(self, hOut, hIn=None):
        """Initialize Mackie Control device (Icon V1-M) via MCU host handshake.
        
        The Icon V1-M in MCU mode won't send fader data until it receives
        the proper MCU host connection SysEx handshake:
          1. Host -> Device: Host Connection Query  (F0 00 00 66 14 01 ...)
          2. Device -> Host: Host Connection Reply   (F0 00 00 66 14 02 ...)
          3. Host -> Device: Host Connection Confirm (F0 00 00 66 14 03 ...)
        Without this, the device accepts output (faders move) but won't
        send fader positions back.
        """
        if not hOut:
            return
        
        try:
            import time
            winmm = ctypes.windll.winmm
            
            # --- Prepare SysEx input buffer so device responses are captured ---
            if hIn:
                try:
                    class MIDIHDR_IN(ctypes.Structure):
                        _fields_ = [
                            ("lpData", ctypes.c_char_p),
                            ("dwBufferLength", ctypes.wintypes.DWORD),
                            ("dwBytesRecorded", ctypes.wintypes.DWORD),
                            ("dwUser", ctypes.POINTER(ctypes.wintypes.DWORD)),
                            ("dwFlags", ctypes.wintypes.DWORD),
                            ("lpNext", ctypes.c_void_p),
                            ("reserved", ctypes.wintypes.DWORD),
                            ("dwOffset", ctypes.wintypes.DWORD),
                            ("dwReserved", ctypes.POINTER(ctypes.wintypes.DWORD)),
                        ]
                    
                    sysex_buf = ctypes.create_string_buffer(256)
                    in_hdr = MIDIHDR_IN()
                    in_hdr.lpData = ctypes.cast(sysex_buf, ctypes.c_char_p)
                    in_hdr.dwBufferLength = 256
                    in_hdr.dwBytesRecorded = 0
                    in_hdr.dwFlags = 0
                    
                    res = winmm.midiInPrepareHeader(hIn, ctypes.byref(in_hdr), ctypes.sizeof(in_hdr))
                    if res == 0:
                        winmm.midiInAddBuffer(hIn, ctypes.byref(in_hdr), ctypes.sizeof(in_hdr))
                        print("[MIDI] SysEx input buffer prepared for MCU handshake response")
                    # Store references to prevent GC
                    self._mcu_sysex_buf = sysex_buf
                    self._mcu_sysex_hdr = in_hdr
                except Exception as e:
                    print(f"[MIDI] Warning: Could not prepare SysEx input buffer: {e}")
            
            # --- MCU Host Connection Query ---
            # F0 00 00 66 <dev_id> 01 <serial:7 bytes> <challenge:4 bytes> F7
            # Mackie manufacturer ID = 00 00 66
            # dev_id 14 = MCU main unit, 15 = MCU extender
            serial = bytes([0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07])
            challenge = bytes([0x11, 0x22, 0x33, 0x44])
            
            # Try main unit (device ID 0x14)
            host_query = bytes([0xF0, 0x00, 0x00, 0x66, 0x14, 0x01]) + serial + challenge + bytes([0xF7])
            print(f"[MIDI] Sending MCU Host Connection Query (main unit, {len(host_query)} bytes)...")
            self._send_sysex_to_handle(hOut, host_query)
            time.sleep(0.3)
            
            # Send Host Connection Confirmation immediately
            # (Most MCU clones accept this without validating the challenge response)
            host_confirm = bytes([0xF0, 0x00, 0x00, 0x66, 0x14, 0x03]) + serial + challenge + bytes([0xF7])
            print(f"[MIDI] Sending MCU Host Connection Confirmation (main unit)...")
            self._send_sysex_to_handle(hOut, host_confirm)
            time.sleep(0.2)
            
            # Also try extender device ID (0x15) in case device is in extender mode
            host_query_ext = bytes([0xF0, 0x00, 0x00, 0x66, 0x15, 0x01]) + serial + challenge + bytes([0xF7])
            print(f"[MIDI] Sending MCU Host Connection Query (extender)...")
            self._send_sysex_to_handle(hOut, host_query_ext)
            time.sleep(0.2)
            
            host_confirm_ext = bytes([0xF0, 0x00, 0x00, 0x66, 0x15, 0x03]) + serial + challenge + bytes([0xF7])
            print(f"[MIDI] Sending MCU Host Connection Confirmation (extender)...")
            self._send_sysex_to_handle(hOut, host_confirm_ext)
            time.sleep(0.1)
            
            # Reset all fader LEDs/buttons to known state
            for note in range(0, 127):
                msg = 0x80 | (note << 8) | (0 << 16)
                winmm.midiOutShortMsg(hOut, msg)
            
            # Enable SMPTE/Beats display mode (Note 0x35 = 53) so the
            # V1-M shows the timecode area on its LCD.
            msg = 0x90 | (0x35 << 8) | (0x7F << 16)  # Note On, SMPTE/Beats, vel 127
            winmm.midiOutShortMsg(hOut, msg)
            
            # Send assignment display characters (CC 0x4B/0x4A) to
            # indicate SMPTE mode.  Value 0x05='5', 0x04='4' → "54"
            # (the exact digits are cosmetic; what matters is that the
            # assignment CCs are sent so the controller enters TC mode).
            winmm.midiOutShortMsg(hOut, 0xB0 | (0x4B << 8) | (0x00 << 16))
            winmm.midiOutShortMsg(hOut, 0xB0 | (0x4A << 8) | (0x00 << 16))
            
            # Blank all 10 timecode digit positions so the display
            # starts in a known state (0x20 = space in MCU 7-segment encoding).
            for cc in range(0x40, 0x4A):
                winmm.midiOutShortMsg(hOut, 0xB0 | (cc << 8) | (0x20 << 16))
            
            print("[MIDI] MCU handshake complete - V1-M should now send fader data")
            
        except Exception as e:
            print(f"[MIDI] Error initializing MCU device: {e}")
            import traceback
            traceback.print_exc()
    
    def _send_sysex_to_handle(self, hOut, data: bytes):
        """Send a SysEx message to a specific winmm output handle."""
        import time
        winmm = ctypes.windll.winmm
        
        class MIDIHDR(ctypes.Structure):
            _fields_ = [
                ("lpData", ctypes.c_char_p),
                ("dwBufferLength", ctypes.wintypes.DWORD),
                ("dwBytesRecorded", ctypes.wintypes.DWORD),
                ("dwUser", ctypes.POINTER(ctypes.wintypes.DWORD)),
                ("dwFlags", ctypes.wintypes.DWORD),
                ("lpNext", ctypes.c_void_p),
                ("reserved", ctypes.wintypes.DWORD),
                ("dwOffset", ctypes.wintypes.DWORD),
                ("dwReserved", ctypes.POINTER(ctypes.wintypes.DWORD)),
            ]
        
        hdr = MIDIHDR()
        hdr.lpData = ctypes.c_char_p(data)
        hdr.dwBufferLength = len(data)
        hdr.dwBytesRecorded = len(data)
        hdr.dwFlags = 0
        
        res = winmm.midiOutPrepareHeader(hOut, ctypes.byref(hdr), ctypes.sizeof(hdr))
        if res != 0:
            print(f"[MIDI] SysEx prepare failed: error={res}")
            return
        
        res = winmm.midiOutLongMsg(hOut, ctypes.byref(hdr), ctypes.sizeof(hdr))
        if res != 0:
            print(f"[MIDI] SysEx send failed: error={res}")
        
        # Wait for send to complete
        for _ in range(50):
            if hdr.dwFlags & 0x00000001:  # MHDR_DONE
                break
            time.sleep(0.01)
        
        winmm.midiOutUnprepareHeader(hOut, ctypes.byref(hdr), ctypes.sizeof(hdr))
    
    def send_led(self, note: int, color: int, channel: int = 0):
        """Send LED feedback to all connected MIDI devices (Note On message)."""
        for conn in self._connections:
            hOut = conn.get('winmm_out_handle')
            if hOut is None:
                continue
            
            try:
                winmm = ctypes.windll.winmm
                # Build Note On message: status | note | velocity
                # Channel 0 = 0x90, Channel 9 = 0x99 (APC mini uses channel 0 for pads, 9 for some buttons)
                status = 0x90 | (channel & 0x0F)
                msg = status | (note << 8) | (color << 16)
                winmm.midiOutShortMsg(hOut, msg)
            except Exception as e:
                print(f"[MIDI] Error sending LED to {conn['name']}: {e}")
    
    def send_cc(self, cc_num: int, value: int, channel: int = 0):
        """Send Control Change message to all connected devices (for motorized fader feedback).
        
        Args:
            cc_num: CC number (0-127)
            value: CC value (0-127)
            channel: MIDI channel (0-15)
        """
        for conn in self._connections:
            hOut = conn.get('winmm_out_handle')
            if hOut is None:
                continue
            
            try:
                winmm = ctypes.windll.winmm
                # Build CC message: status | cc_num | value
                # 0xB0 = Control Change on channel 0, 0xB1 = channel 1, etc.
                status = 0xB0 | (channel & 0x0F)
                msg = status | (cc_num << 8) | (value << 16)
                print(f"[MIDI] Sending CC to {conn['name']}: CC#{cc_num} Ch{channel} Val={value} (0x{msg:08X})")
                winmm.midiOutShortMsg(hOut, msg)
            except Exception as e:
                print(f"[MIDI] Error sending CC to {conn['name']}: {e}")
    
    def send_pitch_bend(self, value: int, channel: int = 0):
        """Send Pitch Bend message to all connected devices (for Icon V1-M motorized fader feedback).
        
        Icon V1-M uses Pitch Bend in MCU mode:
        - Faders 1-8: Channels 0-7 (0xE0-0xE7)
        - Master Fader: Channel 8 (0xE8)
        
        Args:
            value: 14-bit pitch bend value (0-16383)
            channel: MIDI channel (0-15)
        """
        for conn in self._connections:
            hOut = conn.get('winmm_out_handle')
            if hOut is None:
                continue
            
            try:
                winmm = ctypes.windll.winmm
                # Pitch Bend is 14-bit: split into 7-bit LSB and MSB
                lsb = value & 0x7F
                msb = (value >> 7) & 0x7F
                
                # Build Pitch Bend message: status | lsb | msb
                # 0xE0 = Pitch Bend on channel 0, 0xE1 = channel 1, etc.
                status = 0xE0 | (channel & 0x0F)
                msg = status | (lsb << 8) | (msb << 16)
                
                print(f"[MIDI] Sending Pitch Bend to {conn['name']}: Ch{channel} Val={value} (0x{msg:08X})")
                result = winmm.midiOutShortMsg(hOut, msg)
                if result != 0:
                    print(f"[MIDI] Pitch Bend send failed to {conn['name']}: error {result}")
            except Exception as e:
                print(f"[MIDI] Error sending Pitch Bend to {conn['name']}: {e}")
    
    def send_fader_feedback(self, midi_key: str, value: int):
        """Send motorized fader feedback based on MIDI key.
        
        Icon V1-M uses Pitch Bend for motorized faders in MCU mode.
        
        Args:
            midi_key: MIDI key like "cc:8:0" or "pb:9" (pitch bend channel 9)
            value: Fader value 0-127 (will be scaled to 0-16383 for pitch bend)
        """
        if not midi_key:
            print(f"[MIDI] No MIDI key provided for fader feedback")
            return
        
        try:
            # Parse midi_key format
            parts = midi_key.split(":")
            
            if midi_key.startswith("pb:"):
                # Pitch Bend format: "pb:channel"
                if len(parts) >= 2:
                    channel = int(parts[1]) - 1  # pb:9 means channel 8 (0-indexed)
                    # Scale 7-bit value (0-127) to 14-bit (0-16383) for pitch bend
                    pitch_bend_value = int((value / 127) * 16383)
                    
                    print(f"[MIDI] Fader feedback: {midi_key} -> Ch{channel} Val={value}/127 -> PB={pitch_bend_value}")
                    self.send_pitch_bend(pitch_bend_value, channel)
                else:
                    print(f"[MIDI] Invalid Pitch Bend key format: {midi_key}")
                    
            elif midi_key.startswith("cc:"):
                # CC format: "cc:channel:number"
                if len(parts) >= 3:
                    channel = int(parts[1])
                    cc_num = int(parts[2])
                    
                    # CC messages (like APC mini faders) should send CC feedback, not pitch bend
                    # Only pitch bend keys (pb:X) should send pitch bend feedback
                    print(f"[MIDI] Fader feedback: {midi_key} -> Ch{channel} CC={cc_num} Val={value}/127 (CC, not PB)")
                    self.send_cc(cc_num, value, channel)
                else:
                    print(f"[MIDI] Invalid CC key format: {midi_key}")
            else:
                print(f"[MIDI] Unknown MIDI key type: {midi_key}")
        except Exception as e:
            print(f"[MIDI] Error sending fader feedback: {e}")
            import traceback
            traceback.print_exc()
    
    def send_sysex(self, data: bytes):
        """Send a SysEx message to all connected MIDI devices."""
        success = False
        
        for conn in self._connections:
            hOut = conn.get('winmm_out_handle')
            if hOut is None:
                continue
            
            try:
                winmm = ctypes.windll.winmm
                
                # Prepare MIDI header structure
                class MIDIHDR(ctypes.Structure):
                    _fields_ = [
                        ("lpData", ctypes.c_char_p),
                        ("dwBufferLength", ctypes.wintypes.DWORD),
                        ("dwBytesRecorded", ctypes.wintypes.DWORD),
                        ("dwUser", ctypes.POINTER(ctypes.wintypes.DWORD)),
                        ("dwFlags", ctypes.wintypes.DWORD),
                        ("lpNext", ctypes.c_void_p),
                        ("reserved", ctypes.wintypes.DWORD),
                        ("dwOffset", ctypes.wintypes.DWORD),
                        ("dwReserved", ctypes.POINTER(ctypes.wintypes.DWORD)),
                    ]
                
                # Allocate header
                hdr = MIDIHDR()
                hdr.lpData = ctypes.c_char_p(data)
                hdr.dwBufferLength = len(data)
                hdr.dwBytesRecorded = len(data)
                hdr.dwFlags = 0
                
                # Prepare header
                res = winmm.midiOutPrepareHeader(hOut, ctypes.byref(hdr), ctypes.sizeof(hdr))
                if res != 0:
                    print(f"[MIDI] Failed to prepare SysEx header for {conn['name']}, error={res}")
                    continue
                
                # Send long message (SysEx)
                res = winmm.midiOutLongMsg(hOut, ctypes.byref(hdr), ctypes.sizeof(hdr))
                if res != 0:
                    print(f"[MIDI] Failed to send SysEx to {conn['name']}, error={res}")
                    winmm.midiOutUnprepareHeader(hOut, ctypes.byref(hdr), ctypes.sizeof(hdr))
                    continue
                
                # Wait for message to complete (poll MHDR_DONE flag)
                import time
                for _ in range(50):  # 500ms timeout
                    if hdr.dwFlags & 0x00000001:  # MHDR_DONE
                        break
                    time.sleep(0.01)
                
                # Unprepare header
                winmm.midiOutUnprepareHeader(hOut, ctypes.byref(hdr), ctypes.sizeof(hdr))
                print(f"[MIDI] SysEx sent successfully to {conn['name']}: {data.hex()}")
                success = True
                
            except Exception as e:
                print(f"[MIDI] Error sending SysEx to {conn['name']}: {e}")
                import traceback
                traceback.print_exc()
        
        return success
    
    def update_v1m_lcd(self, fader_num: int, text: str, row: int = 0):
        """Update the large shared LCD on Icon V1-M for a specific fader.

        V1-M hardware row mapping (confirmed by test_v1m_display.py):
          Physical top    = MCU row 1  (SysEx 0x12, offsets 56..111)
          Physical bottom = MCU row 0  (SysEx 0x12, offsets  0..55)

        The large LCD has exactly 2 rows of 7 characters per fader slot.
        When *row* is 0 (default), text up to 14 characters is auto-wrapped:
          first 7 chars → top (row 1), remainder → bottom (row 0).

        Args:
            fader_num: Fader number 1-9.
            text: Text to display (up to 14 chars; wraps across 2 rows).
            row: 0 = auto-wrap layout (default).
        """
        if not (1 <= fader_num <= 9):
            return False

        def _safe7(s: str) -> str:
            safe = ''.join(c if 0x20 <= ord(c) <= 0x7E else ' ' for c in s)
            return safe[:7].ljust(7)

        if row == 0:
            line_top = _safe7(text[0:7])      # first 7 chars → physical top (MCU row 1)
            line_bot = _safe7(text[7:14])      # next 7 chars  → physical bottom (MCU row 0)
            # Always write both rows so stale text is cleared
            rows_to_send = [
                (1, line_top),   # physical top
                (0, line_bot),   # physical bottom
            ]
        else:
            rows_to_send = [(row, _safe7(text))]

        sent = False
        for conn in self._connections:
            hOut = conn.get('winmm_out_handle')
            if hOut is None:
                continue
            name = conn.get('name', '').lower()
            if 'icon' not in name and 'v1' not in name and 'mcu' not in name:
                continue
            for r, safe in rows_to_send:
                position = (fader_num - 1) * 7 + (56 if r else 0)
                text_bytes = safe.encode('ascii')
                for dev_id in (0x14, 0x15):
                    sysex = bytes([
                        0xF0, 0x00, 0x00, 0x66, dev_id, 0x12, position,
                    ]) + text_bytes + bytes([0xF7])
                    try:
                        self._send_sysex_to_handle(hOut, sysex)
                        sent = True
                    except Exception as exc:
                        print(f"[MIDI] V1-M LCD send error (dev 0x{dev_id:02X}): {exc}")

        if sent:
            display = text[:28].strip()
            print(f"[MIDI] V1-M LCD fader {fader_num}: '{display}'")
        return sent

    def update_v1m_lcd_all(self, labels: list[str], row: int = 0):
        """Convenience: update scribble-strip text for faders 1-N in one call.

        Args:
            labels: List of up to 9 strings (index 0 = fader 1).
            row: 0 = auto-wrap, 1 = explicit single row.
        """
        for i, label in enumerate(labels[:9], start=1):
            self.update_v1m_lcd(i, label, row=row)

    def send_v1m_meter(self, channel: int, level: int):
        """Set the LED meter level for a fader on the Icon V1-M.

        MCU meters use Channel Aftertouch (0xD0).  The single data byte
        encodes both the channel (high nibble, bits 4-6) and the level
        (low nibble, bits 0-3).

        Args:
            channel: Fader number 0-7 (0 = leftmost fader).
            level:   Meter level 0-12 (0 = off, 12 = clip).
                     0x0E = set overload LED, 0x0F = clear overload LED.
        """
        if not (0 <= channel <= 7):
            return
        level = max(0, min(12, level))
        data_byte = ((channel & 0x07) << 4) | (level & 0x0F)
        for conn in self._connections:
            hOut = conn.get('winmm_out_handle')
            if hOut is None:
                continue
            name = conn.get('name', '').lower()
            if 'icon' not in name and 'v1' not in name and 'mcu' not in name:
                continue
            try:
                winmm = ctypes.windll.winmm
                msg = 0xD0 | (data_byte << 8)
                winmm.midiOutShortMsg(hOut, msg)
            except Exception:
                pass  # Meter updates are best-effort

    # ── Small per-channel scribble strips (Icon V1-M) ────────────
    #
    # These are the tiny individual LCD screens next to each fader,
    # separate from the large shared MCU LCD driven by 0x12.
    #
    # Text:  Icon SysEx  F0 00 02 4E 15 13 <offset> <chars> F7
    #        Same offset scheme as MCU LCD (row0: ch*7, row1: 56+ch*7)
    #        (discovered from bjoluc/cubase-mcu-midiremote LcdManager)
    #
    # Color: Icon SysEx F0 00 02 4E 16 14
    #                   <R1 G1 B1> ... <R8 G8 B8> F7
    #        (RGB values 0-127, all 8 channels in one message)

    def update_v1m_strip(self, channel: int, upper: str = '', lower: str = '',
                         color_idx: int = 0):
        """Write text to the small per-fader scribble strip on Channel *channel*.

        The V1-M secondary display requires all 56 bytes per row sent in one
        SysEx message.  Buffer slots are rotated: physical fader N maps to
        buffer slot (N+5)%8.

        Uses Icon SysEx: F0 00 02 4E 15 13 <offset> <56 bytes> F7

        Args:
            channel: 1-8 (physical strip number).
            upper: Upper row text (max 7 ASCII chars).
            lower: Lower row text (max 7 ASCII chars).
            color_idx: Unused (kept for API compat).
        """
        if not (1 <= channel <= 8):
            return False

        def _safe7(s: str) -> bytes:
            safe = ''.join(c if 0x20 <= ord(c) <= 0x7E else ' ' for c in s)
            return safe[:7].ljust(7).encode('ascii')

        # Physical fader → buffer slot mapping
        slot = channel - 1  # 0-indexed, 1:1 mapping
        self._strip_upper[slot] = _safe7(upper)
        self._strip_lower[slot] = _safe7(lower)

        return self._flush_v1m_strips()

    def _flush_v1m_strips(self):
        """Send the full 112-byte secondary display buffer in one message."""
        upper_buf = b''.join(self._strip_upper)  # 56 bytes
        lower_buf = b''.join(self._strip_lower)  # 56 bytes
        full_buf = upper_buf + lower_buf          # 112 bytes

        sent = False
        for conn in self._connections:
            hOut = conn.get('winmm_out_handle')
            if hOut is None:
                continue
            name = conn.get('name', '').lower()
            if 'icon' not in name and 'v1' not in name and 'mcu' not in name:
                continue
            try:
                # Send all 112 bytes from offset 0 in one SysEx
                sysex = bytes([0xF0, 0x00, 0x02, 0x4E, 0x15, 0x13, 0]) + full_buf + bytes([0xF7])
                self._send_sysex_to_handle(hOut, sysex)
                sent = True
            except Exception as exc:
                print(f"[MIDI] V1-M strip send error: {exc}")
        return sent

    def update_v1m_strip_colors(self, colors: list[tuple[int, int, int]]):
        """Set the RGB backlight colour of each small per-fader strip.

        Uses the Icon-proprietary SysEx:
          F0 00 02 4E 16 14 [R1 G1 B1] … [R8 G8 B8] F7
        Values are 0-127 per component.

        Args:
            colors: List of up to 8 (r, g, b) tuples with values 0-255.
                    Values are scaled to 0-127 for MIDI.  Missing channels
                    default to (0, 0, 0).
        """
        # Pad to 8 channels
        padded = list(colors[:8])
        while len(padded) < 8:
            padded.append((0, 0, 0))

        data = []
        for r, g, b in padded:
            data.extend([
                max(0, min(127, r >> 1)),   # 0-255 → 0-127
                max(0, min(127, g >> 1)),
                max(0, min(127, b >> 1)),
            ])

        sysex = bytes([0xF0, 0x00, 0x02, 0x4E, 0x16, 0x14] + data + [0xF7])

        sent = False
        for conn in self._connections:
            hOut = conn.get('winmm_out_handle')
            if hOut is None:
                continue
            name = conn.get('name', '').lower()
            if 'icon' not in name and 'v1' not in name and 'mcu' not in name:
                continue
            try:
                self._send_sysex_to_handle(hOut, sysex)
                sent = True
            except Exception as exc:
                print(f"[MIDI] V1-M strip color error: {exc}")
        return sent

    def send_mcu_timecode(self, hh: int, mm: int, ss: int, ff: int):
        """Send timecode to the MCU 7-segment timecode display on Icon V1-M.

        MCU protocol uses CC messages on channel 0 to drive a 10-digit
        7-segment display.  The CC numbers are 0x40-0x49 (64-73):
          CC 0x49 = digit 1 (leftmost, tens-of-hours)
          CC 0x48 = digit 2 (ones-of-hours)
          …
          CC 0x40 = digit 10 (rightmost, sub-frames / unused)
        Bit 5 (0x20) in the value lights the decimal-point/colon next to
        that digit.  Value bits 0-3 encode the character (0-9, 0x0A=blank).

        Additionally sets the assignment display (CC 0x4A-0x4B) and keeps
        the SMPTE/Beats button LED lit so the V1-M renders its TC area.
        """
        # All 10 digit positions — unused sub-frame slots show blank (space).
        # MCU digit encoding: ASCII 0x30-0x39 for '0'-'9', 0x20 for blank.
        # Bit 6 (0x40) lights the dot/colon separator to the right of that digit.
        def _d(n):
            return 0x30 + n  # ASCII digit
        digits = [
            (0x49, _d(hh // 10)),                # tens-of-hours
            (0x48, _d(hh % 10) | 0x40),          # ones-of-hours  + separator
            (0x47, _d(mm // 10)),                # tens-of-minutes
            (0x46, _d(mm % 10) | 0x40),          # ones-of-minutes + separator
            (0x45, _d(ss // 10)),                # tens-of-seconds
            (0x44, _d(ss % 10) | 0x40),          # ones-of-seconds + separator
            (0x43, _d(ff // 10)),                # tens-of-frames
            (0x42, _d(ff % 10)),                 # ones-of-frames
            (0x41, 0x20),                        # sub-frame tens (blank)
            (0x40, 0x20),                        # sub-frame ones (blank)
        ]
        for conn in self._connections:
            hOut = conn.get('winmm_out_handle')
            if hOut is None:
                continue
            name = conn.get('name', '').lower()
            if 'icon' not in name and 'v1' not in name and 'mcu' not in name:
                continue
            try:
                winmm = ctypes.windll.winmm
                # Ensure SMPTE button LED stays lit (activates TC area)
                winmm.midiOutShortMsg(hOut, 0x90 | (0x35 << 8) | (0x7F << 16))
                # Assignment display — any valid pair keeps TC mode active
                winmm.midiOutShortMsg(hOut, 0xB0 | (0x4B << 8) | (0x00 << 16))
                winmm.midiOutShortMsg(hOut, 0xB0 | (0x4A << 8) | (0x00 << 16))
                # Time digits
                for cc, val in digits:
                    msg = 0xB0 | (cc << 8) | (val << 16)
                    winmm.midiOutShortMsg(hOut, msg)
            except Exception as exc:
                print(f"[MIDI] V1-M timecode send error: {exc}")

    def hex_to_led_color(self, hex_color: str) -> int:
        """Convert hex color to closest APC mini mk2 LED color using distance matching."""
        if not hex_color or not hex_color.startswith('#'):
            return self.LED_GREEN  # Default
        
        try:
            # Parse hex color
            r = int(hex_color[1:3], 16)
            g = int(hex_color[3:5], 16)
            b = int(hex_color[5:7], 16)
            
            # Reference colors for each LED option (approximate RGB values)
            led_colors = [
                (self.LED_RED, (255, 0, 0)),
                (self.LED_GREEN, (0, 255, 0)),
                (self.LED_BLUE, (0, 0, 255)),
                (self.LED_YELLOW, (255, 255, 0)),
                (self.LED_ORANGE, (255, 128, 0)),
                (self.LED_PURPLE, (128, 0, 255)),
                (self.LED_CYAN, (0, 255, 255)),
                (self.LED_WHITE, (255, 255, 255)),
            ]
            
            # Find closest color by Euclidean distance
            best_led = self.LED_GREEN
            best_distance = float('inf')
            
            for led, (ref_r, ref_g, ref_b) in led_colors:
                distance = (r - ref_r)**2 + (g - ref_g)**2 + (b - ref_b)**2
                if distance < best_distance:
                    best_distance = distance
                    best_led = led
            
            print(f"[MIDI] Color conversion: {hex_color} -> RGB({r},{g},{b}) -> LED {best_led}")
            return best_led
        except Exception as e:
            print(f"[MIDI] Color conversion error: {e}")
            return self.LED_GREEN
    
    def update_led_for_mapping(self, midi_key: str, is_mapped: bool, color: int = None):
        """Update LED state for a MIDI key based on mapping status."""
        if not midi_key.startswith("note:"):
            return  # Only notes have LEDs on APC mini
        
        try:
            note = int(midi_key.split(":")[1])
            if is_mapped:
                led_color = color if color is not None else self.LED_GREEN
            else:
                led_color = self.LED_OFF
            
            # APC mini mk2 button layout:
            # - Clip Launch pads (8x8 grid): notes 0-63 on channel 0 (0x90)
            # - Scene Launch buttons (vertical column): notes 112-119 on channel 9 (0x99)
            # - Track Select buttons (bottom row): notes 100-107 on channel 9 (0x99)
            # - Shift button: note 122 on channel 9
            # - Control buttons: notes 120, 121, etc. on channel 9 (0x99)
            
            if note < 64:
                # Main pad grid - channel 0
                self.send_led(note, led_color, channel=0)
            else:
                # Scene launch, track select, and control buttons - channel 9
                self.send_led(note, led_color, channel=9)
                
            color_name = {
                self.LED_OFF: 'OFF', self.LED_GREEN: 'green', self.LED_RED: 'red',
                self.LED_BLUE: 'blue', self.LED_YELLOW: 'yellow', self.LED_ORANGE: 'orange',
                self.LED_PURPLE: 'purple', self.LED_CYAN: 'cyan', self.LED_WHITE: 'white'
            }.get(led_color, str(led_color))
            print(f"[MIDI] LED update: note {note} -> {color_name}")
        except Exception as e:
            print(f"[MIDI] Error updating LED: {e}")
    
    def refresh_all_leds(self):
        """Update all LEDs based on current mappings with preset colors."""
        if not self.is_connected:
            return
        
        # Update LEDs for all mapped keys using preset colors
        for midi_key, preset_ids in self._mappings.items():
            if preset_ids:
                # Get color from first preset mapped to this key
                preset_id = preset_ids[0]
                led_color = self.get_preset_led_color(preset_id)
                self.update_led_for_mapping(midi_key, True, led_color)
            
        print(f"[MIDI] Refreshed LEDs for {len(self._mappings)} mapped buttons")
    
    def disconnect(self):
        """Disconnect all MIDI ports."""
        # Turn off all LEDs before disconnecting
        for midi_key in self._mappings.keys():
            self.update_led_for_mapping(midi_key, False)
        
        # Disconnect all ports
        for conn in list(self._connections):
            self.disconnect_port(conn['name'])
        self._connections.clear()
        self._running = False
    
    def _midi_loop_mido(self, port):
        """Background thread to read MIDI messages via mido.
        
        Args:
            port: The mido port to read from.
        """
        while self._running and port:
            try:
                for msg in port.iter_pending():
                    self._handle_message_mido(msg)
                time.sleep(0.01)
            except Exception as e:
                print(f"[MIDI] Error in mido loop for {port.name}: {e}")
                break
    
    def _handle_message_mido(self, msg):
        """Handle a MIDI message from mido."""
        midi_key = None
        is_fader = False  # Track if this is a fader-type input (CC or PB)
        
        if msg.type == 'note_on' and msg.velocity > 0:
            # Check fader touch notes first
            touch_key = f"note:{msg.note}"
            if touch_key in self._touch_note_mappings and not self._learn_mode:
                slot_idx = self._touch_note_mappings[touch_key]
                self.midi_fader_touch.emit(slot_idx, True)
            # Filter out Icon V1-M fader touch detection notes (104-112 on channel 0)
            if not (msg.channel == 0 and 104 <= msg.note <= 112):
                midi_key = f"note:{msg.note}"
        elif msg.type == 'note_off' or (msg.type == 'note_on' and msg.velocity == 0):
            # Note release — check fader touch release
            touch_key = f"note:{msg.note}"
            if touch_key in self._touch_note_mappings and not self._learn_mode:
                slot_idx = self._touch_note_mappings[touch_key]
                self.midi_fader_touch.emit(slot_idx, False)
        elif msg.type == 'control_change':
            # Include channel in CC key (Icon V1-M uses different channels per fader)
            cc_key = f"cc:{msg.channel}:{msg.control}"
            is_fader = True
            # Emit CC value for fader control
            self.midi_cc_value.emit(cc_key, msg.value)
            # Check if this fader is mapped to a preset for intensity control
            if not self._learn_mode and cc_key in self._mappings:
                # Map CC value (0-127) to percentage (0-100)
                intensity_pct = int(msg.value * 100 / 127)
                self.midi_fader_intensity.emit(cc_key, intensity_pct)
            # Only allow CC to be learned, never to trigger presets as button
            if self._learn_mode:
                midi_key = cc_key
            elif cc_key in self._mappings:
                # CC has explicit trigger mapping (e.g. page nav)
                has_cb = any(
                    pid in self._preset_callbacks
                    for pid in self._mappings.get(cc_key, [])
                )
                if has_cb:
                    midi_key = cc_key
        elif msg.type == 'pitchwheel':
            # Pitch bend for MCU-style faders
            pb_value = msg.pitch + 8192  # mido uses -8192 to 8191, convert to 0-16383
            pb_key = f"pb:{msg.channel + 1}"  # 1-indexed
            is_fader = True
            self.midi_pb_value.emit(pb_key, pb_value)
            # Check if this fader is mapped to a preset for intensity control
            if not self._learn_mode and pb_key in self._mappings:
                # Map PB value (0-16383) to percentage (0-100)
                intensity_pct = int(pb_value * 100 / 16383)
                self.midi_fader_intensity.emit(pb_key, intensity_pct)
            if self._learn_mode:
                midi_key = pb_key
        
        if midi_key:
            print(f"[MIDI] Received: {midi_key} (fader={is_fader})")
            if self._learn_mode:
                self.midi_received.emit(midi_key)
            elif not is_fader:
                # Only trigger button-style presets for note messages, not faders
                # Faders use the midi_fader_intensity path instead
                self._trigger_queue.put(midi_key)
            elif is_fader and midi_key in self._mappings:
                # Fader-type key (CC/PB) with an explicit trigger callback
                has_callback = any(
                    pid in self._preset_callbacks
                    for pid in self._mappings[midi_key]
                )
                if has_callback:
                    self._trigger_queue.put(midi_key)
    
    def _trigger_preset(self, midi_key: str):
        """Trigger any presets mapped to this MIDI key."""
        mapped_ids = self._mappings.get(midi_key, [])
        logger.info(f"[MIDI TRIGGER] key={midi_key} mapped_preset_ids={mapped_ids} callbacks={list(self._preset_callbacks.keys())}")
        print(f"[MIDI] _trigger_preset called with key: {midi_key}")
        print(f"[MIDI] Mapped preset IDs for this key: {mapped_ids}")
        print(f"[MIDI] Current callbacks: {list(self._preset_callbacks.keys())}")
        
        if midi_key in self._mappings:
            for preset_id in self._mappings[midi_key]:
                print(f"[MIDI] Found mapping: {midi_key} -> {preset_id}")
                if preset_id in self._preset_callbacks:
                    print(f"[MIDI] Triggering preset: {preset_id}")
                    logger.info(f"[MIDI TRIGGER] Firing callback for: {preset_id}")
                    # Call callback on main thread via QTimer
                    callback = self._preset_callbacks[preset_id]
                    QTimer.singleShot(0, callback)
                else:
                    logger.info(f"[MIDI TRIGGER] No callback found for preset_id: {preset_id}")
    
    def set_learn_mode(self, enabled: bool):
        """Enable/disable MIDI learn mode."""
        self._learn_mode = enabled
        print(f"[MIDI] Learn mode: {enabled}")
    
    def set_preset_color(self, preset_id: str, hex_color: str):
        """Store the color for a preset for LED feedback."""
        self._preset_colors[preset_id] = hex_color
    
    def get_preset_led_color(self, preset_id: str) -> int:
        """Get the LED color for a preset."""
        hex_color = self._preset_colors.get(preset_id)
        if hex_color:
            return self.hex_to_led_color(hex_color)
        # Default colors for special presets
        if preset_id == "__OFF__":
            return self.LED_RED
        return self.LED_GREEN
    
    def get_midi_key_for_preset(self, preset_id: str) -> str | None:
        """Get the first MIDI key mapped to a preset, or None."""
        for midi_key, preset_ids in self._mappings.items():
            if preset_id in preset_ids:
                return midi_key
        return None
    
    def start_blink(self, preset_id: str):
        """Start blinking the LED for the active preset.
        
        Args:
            preset_id: The preset ID that is now active
        """
        # Stop any existing blink first
        self.stop_blink()
        
        # Find the MIDI key for this preset
        midi_key = self.get_midi_key_for_preset(preset_id)
        if not midi_key:
            print(f"[MIDI Blink] No MIDI mapping for preset {preset_id}")
            return
        
        self._blink_preset_id = preset_id
        self._blink_midi_key = midi_key
        self._blink_color = self.get_preset_led_color(preset_id)
        self._blink_state = True  # Start with LED on
        
        # Create and start timer
        self._blink_timer = QTimer()
        self._blink_timer.timeout.connect(self._blink_tick)
        self._blink_timer.start(300)  # 300ms on/off for visible blink
        
        print(f"[MIDI Blink] Started blinking {midi_key} for preset {preset_id}")
    
    def stop_blink(self):
        """Stop blinking and restore the LED to solid color."""
        if self._blink_timer:
            self._blink_timer.stop()
            self._blink_timer.deleteLater()
            self._blink_timer = None
        
        # Restore the LED to solid color if we were blinking
        if self._blink_midi_key and self._blink_preset_id:
            self.update_led_for_mapping(self._blink_midi_key, True, self._blink_color)
            print(f"[MIDI Blink] Stopped blinking {self._blink_midi_key}")
        
        self._blink_midi_key = None
        self._blink_preset_id = None
        self._blink_state = False
    
    def _blink_tick(self):
        """Timer callback to toggle the blinking LED."""
        if not self._blink_midi_key:
            return
        
        self._blink_state = not self._blink_state
        
        if self._blink_state:
            # Turn LED on with the preset color
            self.update_led_for_mapping(self._blink_midi_key, True, self._blink_color)
        else:
            # Turn LED off
            self.update_led_for_mapping(self._blink_midi_key, False)

    def add_mapping(self, midi_key: str, preset_id: str, hex_color: str = None):
        """Add a MIDI key mapping to a preset."""
        if midi_key not in self._mappings:
            self._mappings[midi_key] = []
        if preset_id not in self._mappings[midi_key]:
            self._mappings[midi_key].append(preset_id)
            print(f"[MIDI] Added mapping: {midi_key} -> {preset_id}")
            # Store color if provided
            if hex_color:
                self._preset_colors[preset_id] = hex_color
            # Light up the button on the MIDI device with the appropriate color
            led_color = self.get_preset_led_color(preset_id)
            self.update_led_for_mapping(midi_key, True, led_color)
    
    def remove_mapping(self, midi_key: str, preset_id: str):
        """Remove a specific MIDI key mapping from a preset."""
        if midi_key in self._mappings:
            if preset_id in self._mappings[midi_key]:
                self._mappings[midi_key].remove(preset_id)
            if not self._mappings[midi_key]:
                del self._mappings[midi_key]
                # Turn off the LED since no mappings remain
                self.update_led_for_mapping(midi_key, False)
    
    def clear_mappings_for_preset(self, preset_id: str):
        """Clear all MIDI mappings for a preset."""
        keys_to_remove = []
        keys_to_turn_off = []
        for midi_key, preset_ids in self._mappings.items():
            if preset_id in preset_ids:
                preset_ids.remove(preset_id)
            if not preset_ids:
                keys_to_remove.append(midi_key)
                keys_to_turn_off.append(midi_key)
        for key in keys_to_remove:
            del self._mappings[key]
        # Turn off LEDs for keys that no longer have mappings
        for key in keys_to_turn_off:
            self.update_led_for_mapping(key, False)
        print(f"[MIDI] Cleared mappings for preset: {preset_id}")
    
    def get_mappings_for_preset(self, preset_id: str) -> list:
        """Get all MIDI keys mapped to a preset."""
        keys = []
        for midi_key, preset_ids in self._mappings.items():
            if preset_id in preset_ids:
                keys.append(midi_key)
        return keys
    
    def register_preset_callback(self, preset_id: str, callback):
        """Register a callback to be called when a preset is triggered via MIDI."""
        self._preset_callbacks[preset_id] = callback
    
    def unregister_preset_callback(self, preset_id: str):
        """Unregister a preset callback."""
        if preset_id in self._preset_callbacks:
            del self._preset_callbacks[preset_id]
    
    # ---- Fader mapping methods ----
    
    def add_fader_mapping(self, cc_key: str, fader_id: str):
        """Add a CC fader mapping."""
        # Remove any existing mapping for this fader
        self.remove_fader_mapping_by_id(fader_id)
        self._fader_mappings[cc_key] = fader_id
        print(f"[MIDI] Added fader mapping: {cc_key} -> {fader_id}")
    
    def remove_fader_mapping(self, cc_key: str):
        """Remove a CC fader mapping by CC key."""
        if cc_key in self._fader_mappings:
            del self._fader_mappings[cc_key]
            print(f"[MIDI] Removed fader mapping: {cc_key}")
    
    def remove_fader_mapping_by_id(self, fader_id: str):
        """Remove a CC fader mapping by fader ID."""
        keys_to_remove = [k for k, v in self._fader_mappings.items() if v == fader_id]
        for key in keys_to_remove:
            del self._fader_mappings[key]
            print(f"[MIDI] Removed fader mapping: {key} -> {fader_id}")
    
    def get_fader_mapping(self, fader_id: str) -> str | None:
        """Get the CC key mapped to a fader, or None."""
        for cc_key, fid in self._fader_mappings.items():
            if fid == fader_id:
                return cc_key
        return None
    
    def register_fader_callback(self, fader_id: str, callback):
        """Register a callback for fader value changes (receives 0-127)."""
        self._fader_callbacks[fader_id] = callback
    
    def unregister_fader_callback(self, fader_id: str):
        """Unregister a fader callback."""
        if fader_id in self._fader_callbacks:
            del self._fader_callbacks[fader_id]
    
    def _handle_cc_value(self, cc_key: str, value: int):
        """Handle incoming CC value for fader mappings."""
        if cc_key in self._fader_mappings:
            fader_id = self._fader_mappings[cc_key]
            if fader_id in self._fader_callbacks:
                callback = self._fader_callbacks[fader_id]
                if cc_key in self._relative_ccs:
                    # Relative CC (jog wheel / encoder): convert to direction
                    # Protocol: 1-63 = CW (positive ticks), 65-127 = CCW (negative ticks)
                    if value == 0 or value == 64:
                        return  # No movement
                    elif value <= 63:
                        direction = 1   # Clockwise
                    else:
                        direction = -1  # Counter-clockwise
                    # Route through encoder-style callback (direction, max=0)
                    QTimer.singleShot(0, lambda d=direction: callback(d, 0))
                else:
                    # Absolute CC: pass raw value with 7-bit range (0-127)
                    QTimer.singleShot(0, lambda: callback(value, 127))
    
    def _handle_pb_value(self, pb_key: str, value: int):
        """Handle incoming Pitch Bend value for fader mappings (V1-M / MCU)."""
        if pb_key in self._fader_mappings:
            fader_id = self._fader_mappings[pb_key]
            if fader_id in self._fader_callbacks:
                # Call callback on main thread via QTimer
                # Pitch Bend uses 14-bit (0-16383)
                callback = self._fader_callbacks[fader_id]
                QTimer.singleShot(0, lambda: callback(value, 16383))
    
    def _handle_encoder_value(self, note_key: str, direction: int):
        """Handle incoming encoder-style note message for fader mappings.
        
        Encoders may use different notes for CW/CCW (e.g., note:96=CW, note:97=CCW).
        Or they may use a single note with d2=127 for CW and d2=0 for CCW.
        
        Args:
            note_key: The note key like "note:96"
            direction: 1 for d2>=64, -1 for d2<64
        """
        # Check if this note is mapped as a fader
        if note_key in self._fader_mappings:
            fader_id = self._fader_mappings[note_key]
            if fader_id in self._fader_callbacks:
                # Check if this note has a defined encoder direction
                # (e.g., note:96 = +1 for CW, note:97 = -1 for CCW)
                encoder_dir = self._encoder_directions.get(note_key, 1)  # Default to increment
                
                # Only respond to d2=127 (direction=1) clicks, ignore d2=0 releases
                if direction != 1:
                    return
                
                callback = self._fader_callbacks[fader_id]
                # Pass encoder_dir as the value and 0 as max to indicate encoder mode
                QTimer.singleShot(0, lambda d=encoder_dir: callback(d, 0))
    
    def set_encoder_direction(self, note_key: str, direction: int):
        """Set the direction for an encoder note.
        
        Args:
            note_key: The note key like "note:96"
            direction: 1 for increment, -1 for decrement
        """
        if not hasattr(self, '_encoder_directions'):
            self._encoder_directions = {}
        self._encoder_directions[note_key] = direction
        print(f"[MIDI] Encoder direction set: {note_key} = {'+' if direction > 0 else '-'}")
    
    def start_fader_learn(self, callback):
        """Start fader learn mode - will call callback(midi_key) when a CC or PB is received.
        
        Args:
            callback: Function to call with the midi_key when a fader message is received
        """
        self._fader_learn_callback = callback
        self._last_received_key = None
        # Don't clear _last_received_device here - it will be set by incoming MIDI
        self.set_learn_mode(True)
        
        # Start polling timer - disconnect any previous connections first
        if not hasattr(self, '_fader_learn_timer'):
            self._fader_learn_timer = QTimer()
        else:
            try:
                self._fader_learn_timer.timeout.disconnect()
            except:
                pass
        
        def check_fader():
            if self._last_received_key:
                key = self._last_received_key
                # Don't clear _last_received_device - the callback needs it!
                self._last_received_key = None
                if key.startswith("cc:") or key.startswith("pb:"):
                    print(f"[DEBUG start_fader_learn] Found key={key}, _last_received_device={self._last_received_device}")
                    # Store the callback before stopping (stop clears it)
                    cb = self._fader_learn_callback
                    # Stop the timer but DON'T call stop_fader_learn yet
                    # because we need _last_received_device to still be available
                    if hasattr(self, '_fader_learn_timer') and self._fader_learn_timer:
                        self._fader_learn_timer.stop()
                    self.set_learn_mode(False)
                    self._fader_learn_callback = None
                    # Call the callback - it can access _last_received_device
                    if cb:
                        cb(key)
        
        self._fader_learn_timer.timeout.connect(check_fader)
        self._fader_learn_timer.start(50)
    
    def stop_fader_learn(self):
        """Stop fader learn mode."""
        self.set_learn_mode(False)
        self._fader_learn_callback = None
        if hasattr(self, '_fader_learn_timer') and self._fader_learn_timer:
            self._fader_learn_timer.stop()
            try:
                self._fader_learn_timer.timeout.disconnect()
            except:
                pass
    
    def get_fader_mappings_dict(self) -> dict:
        """Get all fader mappings as a dict for serialization.
        Returns dict with fader_id as key, midi_key as value (for feedback lookup).
        """
        # Invert the dict: fader_id -> midi_key (for motorized fader feedback)
        return {fader_id: midi_key for midi_key, fader_id in self._fader_mappings.items()}
    
    def load_fader_mappings(self, mappings: dict):
        """Load fader mappings from a dict.
        Input format: {fader_id: midi_key or [midi_keys]} (from settings file)
        Internal format: {midi_key: fader_id} (for MIDI input lookup)
        """
        self._fader_mappings = {}
        if mappings:
            for fader_id, midi_keys in mappings.items():
                # Support both single key (string) and multiple keys (list)
                if isinstance(midi_keys, str):
                    midi_keys = [midi_keys]
                for midi_key in midi_keys:
                    self._fader_mappings[midi_key] = fader_id
        print(f"[MIDI] Loaded {len(self._fader_mappings)} fader mappings: {self._fader_mappings}")
    
    def get_mappings_dict(self) -> dict:
        """Get all mappings as a dict for serialization."""
        return dict(self._mappings)
    
    def load_mappings(self, mappings: dict):
        """Load mappings from a dict."""
        self._mappings = {}
        for midi_key, preset_ids in mappings.items():
            self._mappings[midi_key] = list(preset_ids)
    
    def set_mapping_device(self, midi_key: str, device_name: str):
        """Record which device made a mapping."""
        self._mapping_devices[midi_key] = device_name
    
    def get_mapping_device(self, midi_key: str) -> str:
        """Get the device name that made a mapping, or 'Unknown' if not recorded."""
        return self._mapping_devices.get(midi_key, "Unknown")
    
    def get_mapping_devices_dict(self) -> dict:
        """Get all device mappings for serialization."""
        return dict(self._mapping_devices)
    
    def load_mapping_devices(self, devices: dict):
        """Load device mappings from a dict."""
        self._mapping_devices = dict(devices) if devices else {}
    
    def get_last_received_device(self) -> str:
        """Get the name of the device that sent the last MIDI message (for learn mode)."""
        return self._last_received_device or "Unknown"
    
    # =========================================================================
    # Dynamic MIDI Fader Mapping
    # =========================================================================
    
    def set_dynamic_mode_enabled(self, enabled: bool):
        """Enable or disable dynamic MIDI fader mapping mode."""
        self._dynamic_mode_enabled = enabled
    
    def is_dynamic_mode_enabled(self) -> bool:
        """Check if dynamic MIDI fader mapping is enabled."""
        return getattr(self, '_dynamic_mode_enabled', False)
    
    def set_dynamic_fader_slots(self, slots: dict):
        """Set the dynamic fader slot mappings.
        
        Args:
            slots: Dict mapping slot index (0-based) to midi_key (e.g., {0: 'pb:1', 1: 'pb:2'})
        """
        self._dynamic_fader_slots = slots
    
    def get_dynamic_fader_slots(self) -> dict:
        """Get the dynamic fader slot mappings."""
        return getattr(self, '_dynamic_fader_slots', {})
    
    def get_dynamic_slot_for_midi_key(self, midi_key: str) -> int:
        """Get the slot index for a MIDI key, or -1 if not found."""
        slots = self.get_dynamic_fader_slots()
        for slot_idx, key in slots.items():
            if key == midi_key:
                return slot_idx
        return -1
    
    def set_dynamic_fader_count(self, count: int):
        """Set the number of dynamic fader slots."""
        self._dynamic_fader_count = count
    
    def get_dynamic_fader_count(self) -> int:
        """Get the number of dynamic fader slots."""
        return getattr(self, '_dynamic_fader_count', 8)

    def set_dynamic_button_slots(self, slots: dict):
        """Set the dynamic button slot mappings.

        Args:
            slots: Dict mapping slot index (0-based) to note_key (e.g., {0: 'note:60'})
        """
        self._dynamic_button_slots = {v: k for k, v in slots.items()}  # Store as note_key -> slot_index

    def get_dynamic_button_slots(self) -> dict:
        """Get the dynamic button slot mappings as {note_key: slot_index}."""
        return getattr(self, '_dynamic_button_slots', {})

    def get_dynamic_button_slots_by_index(self) -> dict:
        """Get the dynamic button slot mappings as {slot_index: note_key}."""
        return {v: k for k, v in self.get_dynamic_button_slots().items()}
    
    @staticmethod
    def format_midi_key(midi_key: str) -> str:
        """Format a MIDI key for display."""
        if midi_key.startswith("note:"):
            note_num = int(midi_key.split(":")[1])
            # Convert to note name
            notes = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B']
            octave = (note_num // 12) - 1
            note_name = notes[note_num % 12]
            return f"Note {note_name}{octave} ({note_num})"
        elif midi_key.startswith("cc:"):
            parts = midi_key.split(":")
            if len(parts) == 3:  # cc:channel:number
                channel = int(parts[1])
                cc_num = int(parts[2])
                return f"CC {cc_num} Ch{channel}"
            else:  # Legacy format cc:number
                cc_num = int(parts[1])
                return f"CC {cc_num}"
        elif midi_key.startswith("pb:"):
            fader_num = int(midi_key.split(":")[1])
            return f"Pitch Bend {fader_num}"
        return midi_key


# Global MIDI manager instance
_midi_manager = None

def get_midi_manager() -> MIDIManager:
    """Get the global MIDI manager instance."""
    global _midi_manager
    if _midi_manager is None:
        _midi_manager = MIDIManager()
    return _midi_manager


class HorizontalTabBar(QTabBar):
    """Custom tab bar that draws horizontal text for west/east positioned tabs."""
    
    # Signal to request opening a tab in a new window
    openInNewWindowRequested = pyqtSignal(int)
    # Signal emitted when a view icon below the tabs is clicked
    viewIconClicked = pyqtSignal(str)  # view_id
    # Signals for view icon context menu actions
    viewIconUpdateRequested = pyqtSignal(str)  # view_id
    viewIconDeleteRequested = pyqtSignal(str)  # view_id
    # Signal emitted when user right-clicks blank area to create a new view
    createNewViewRequested = pyqtSignal()
    # Signal for renaming a view icon
    viewIconRenameRequested = pyqtSignal(str)  # view_id
    # Signals for view icon MIDI learn
    viewIconMidiLearnRequested = pyqtSignal(str)  # view_id
    viewIconMidiClearRequested = pyqtSignal(str)  # view_id
    
    _ICON_ROW_H = 68   # height of each icon row (icon + label)
    _ICON_SIZE  = 36    # rendered icon size
    _ICON_PAD   = 6     # gap between last tab and first icon
    _LABEL_H    = 16    # height reserved for the name label
    _HEADER_H   = 20    # height for 'Saved Views' header
    
    def __init__(self, parent=None):
        super().__init__(parent)
        self._view_icons: list[tuple[str, 'QPixmap', str]] = []  # (view_id, pixmap, name)
        self.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.customContextMenuRequested.connect(self._show_context_menu)
        self.setMouseTracking(True)
        self._hovered_icon_idx = -1
        self._active_view_id: str | None = None
    
    def _show_context_menu(self, pos):
        """Show context menu for tab."""
        tab_index = self.tabAt(pos)
        if tab_index >= 0:
            menu = QMenu(self)
            menu.setStyleSheet(self._get_touch_menu_stylesheet())
            new_window_action = menu.addAction("📺 Open in New Window")
            new_window_action.triggered.connect(lambda: self.openInNewWindowRequested.emit(tab_index))
            menu.exec(self.mapToGlobal(pos))
    
    def _get_touch_menu_stylesheet(self):
        """Return a stylesheet for touch-friendly context menus."""
        return """
            QMenu {
                background-color: #2d2d2d;
                border: 1px solid #555;
                border-radius: 6px;
                padding: 8px 4px;
            }
            QMenu::item {
                background-color: transparent;
                padding: 14px 24px;
                margin: 2px 4px;
                border-radius: 4px;
                font-size: 15px;
                min-width: 200px;
            }
            QMenu::item:selected {
                background-color: #4a4a4a;
            }
            QMenu::separator {
                height: 1px;
                background: #555;
                margin: 8px 12px;
            }
        """
    
    def tabSizeHint(self, index):
        # Return size with swapped dimensions for horizontal text
        size = super().tabSizeHint(index)
        size.transpose()
        text = self.tabText(index)
        if '\n' in text:
            size.setWidth(max(size.width(), 100))
            size.setHeight(52)
        else:
            size.setWidth(max(size.width(), 90))
            size.setHeight(40)
        return size
    
    def sizeHint(self):
        """Extend height to include view icon rows below the tabs."""
        sh = super().sizeHint()
        if self._view_icons:
            extra = self._ICON_PAD + self._HEADER_H + len(self._view_icons) * self._ICON_ROW_H
            sh.setHeight(sh.height() + extra)
        return sh
    
    def minimumSizeHint(self):
        sh = super().minimumSizeHint()
        if self._view_icons:
            extra = self._ICON_PAD + self._HEADER_H + len(self._view_icons) * self._ICON_ROW_H
            sh.setHeight(sh.height() + extra)
        return sh
    
    # -- view icon helpers --------------------------------------------------
    
    def set_view_icons(self, icons: list[tuple[str, 'QPixmap', str]]):
        """Set view icons below tabs.  *icons* = [(view_id, QPixmap, name), ...]"""
        self._view_icons = list(icons)
        self._hovered_icon_idx = -1
        self.update()
    
    def set_active_view(self, view_id: str | None):
        """Mark *view_id* as the currently active view for highlight."""
        self._active_view_id = view_id
        self.update()
    
    def _icon_top_y(self) -> int:
        """Y pixel where the first icon row starts (below header)."""
        n = self.count()
        if n:
            return self.tabRect(n - 1).bottom() + 1 + self._ICON_PAD + self._HEADER_H
        return self._ICON_PAD + self._HEADER_H

    def _header_top_y(self) -> int:
        """Y pixel where the 'Saved Views' header starts."""
        n = self.count()
        if n:
            return self.tabRect(n - 1).bottom() + 1 + self._ICON_PAD
        return self._ICON_PAD
    
    def _icon_rect(self, idx: int):
        """Return the QRect for view-icon row *idx*."""
        from PyQt6.QtCore import QRect
        top = self._icon_top_y() + idx * self._ICON_ROW_H
        return QRect(0, top, self.width(), self._ICON_ROW_H)
    
    def _icon_index_at(self, pos) -> int:
        """Return the icon index at *pos*, or -1."""
        y = pos.y()
        top = self._icon_top_y()
        if y < top or not self._view_icons:
            return -1
        idx = int((y - top) // self._ICON_ROW_H)
        if 0 <= idx < len(self._view_icons):
            return idx
        return -1
    
    # -- events -------------------------------------------------------------
    
    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        
        for index in range(self.count()):
            rect = self.tabRect(index)
            is_selected = (index == self.currentIndex())
            
            # Draw tab background
            if is_selected:
                painter.fillRect(rect, QColor("#1e1e1e"))  # Selected background
            else:
                painter.fillRect(rect, QColor("#2d2d2d"))  # Normal background
            
            # Draw text
            painter.save()
            font = painter.font()
            font.setBold(is_selected)
            painter.setFont(font)
            
            if is_selected:
                painter.setPen(QColor("#c97a50"))  # Highlight color for selected
            else:
                painter.setPen(QColor("#cccccc"))  # Normal text color
            
            painter.drawText(rect, Qt.AlignmentFlag.AlignCenter | Qt.TextFlag.TextWordWrap, self.tabText(index))
            painter.restore()
            
            # Draw bottom border for selected tab
            if is_selected:
                painter.setPen(QColor("#c97a50"))
                painter.drawLine(rect.right(), rect.top() + 5, rect.right(), rect.bottom() - 5)
        
        # -- draw "Saved Views" header and view icons below the tabs --
        if self._view_icons:
            painter.save()
            hdr_font = painter.font()
            hdr_font.setPixelSize(11)
            hdr_font.setBold(True)
            painter.setFont(hdr_font)
            painter.setPen(QColor('#888888'))
            from PyQt6.QtCore import QRect as _QRect
            hdr_y = self._header_top_y()
            hdr_rect = _QRect(0, hdr_y, self.width(), self._HEADER_H)
            painter.drawText(hdr_rect, Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignVCenter, 'Saved Views')
            painter.restore()
        for i, (vid, pix, name) in enumerate(self._view_icons):
            row_rect = self._icon_rect(i)
            if row_rect.top() > self.height():
                break  # off-screen
            
            is_active = (vid == self._active_view_id)
            hovered = (i == self._hovered_icon_idx)
            if is_active:
                painter.fillRect(row_rect, QColor("#2a3a5a"))
                # Draw left accent bar for active view
                painter.fillRect(row_rect.left(), row_rect.top() + 4,
                                 3, row_rect.height() - 8, QColor("#c97a50"))
            elif hovered:
                painter.fillRect(row_rect, QColor("#3d3d5d"))
            
            # Centre the pixmap in the upper part of the row
            sz = self._ICON_SIZE
            icon_area_h = row_rect.height() - self._LABEL_H
            x = (row_rect.width() - sz) // 2
            y = row_rect.top() + (icon_area_h - sz) // 2
            painter.drawPixmap(x, y, pix.scaled(
                sz, sz,
                Qt.AspectRatioMode.KeepAspectRatio,
                Qt.TransformationMode.SmoothTransformation,
            ))
            # Draw shortcut name below the icon
            painter.save()
            label_font = painter.font()
            label_font.setPixelSize(10)
            if is_active:
                label_font.setBold(True)
            painter.setFont(label_font)
            painter.setPen(QColor('#c97a50') if is_active else QColor('#bbbbbb'))
            from PyQt6.QtCore import QRect as _QRect
            label_rect = _QRect(0, row_rect.top() + icon_area_h, row_rect.width(), self._LABEL_H)
            painter.drawText(label_rect, Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignTop, name)
            painter.restore()
        
        painter.end()
    
    def mousePressEvent(self, event):
        idx = self._icon_index_at(event.pos())
        if idx >= 0:
            if event.button() == Qt.MouseButton.LeftButton:
                self.viewIconClicked.emit(self._view_icons[idx][0])
                return
            if event.button() == Qt.MouseButton.RightButton:
                self._show_view_icon_context_menu(idx, event.globalPosition().toPoint())
                return
        # Right-click on blank area below tabs → create new view
        if event.button() == Qt.MouseButton.RightButton:
            y = event.pos().y()
            tabs_bottom = self.tabRect(self.count() - 1).bottom() if self.count() else 0
            if y > tabs_bottom:
                self._show_blank_area_context_menu(event.globalPosition().toPoint())
                return
        super().mousePressEvent(event)
    
    def _show_blank_area_context_menu(self, global_pos):
        """Show context menu when right-clicking on blank area below saved views."""
        menu = QMenu(self)
        menu.setStyleSheet(self._get_touch_menu_stylesheet())
        new_view_action = menu.addAction("➕ Create New View")
        new_view_action.triggered.connect(self.createNewViewRequested.emit)
        menu.exec(global_pos)

    def _show_view_icon_context_menu(self, idx: int, global_pos):
        """Show context menu for a view icon (Update / Delete / MIDI Learn)."""
        vid, _pix, name = self._view_icons[idx]
        menu = QMenu(self)
        menu.setStyleSheet(self._get_touch_menu_stylesheet())
        update_action = menu.addAction(f"\U0001f504 Update \"{name}\" to Current View")
        rename_action = menu.addAction("\u270f\ufe0f Rename...")
        menu.addSeparator()
        midi_learn_action = menu.addAction("\U0001f3b9 Learn MIDI...")
        midi_clear_action = menu.addAction("\u274c Clear MIDI")
        menu.addSeparator()
        delete_action = menu.addAction(f"\U0001f5d1 Delete \"{name}\"")
        chosen = menu.exec(global_pos)
        if chosen is update_action:
            self.viewIconUpdateRequested.emit(vid)
        elif chosen is rename_action:
            self.viewIconRenameRequested.emit(vid)
        elif chosen is delete_action:
            self.viewIconDeleteRequested.emit(vid)
        elif chosen is midi_learn_action:
            self.viewIconMidiLearnRequested.emit(vid)
        elif chosen is midi_clear_action:
            self.viewIconMidiClearRequested.emit(vid)
    
    def mouseMoveEvent(self, event):
        idx = self._icon_index_at(event.pos())
        if idx != self._hovered_icon_idx:
            self._hovered_icon_idx = idx
            self.update()
        super().mouseMoveEvent(event)
    
    def leaveEvent(self, event):
        if self._hovered_icon_idx != -1:
            self._hovered_icon_idx = -1
            self.update()
        super().leaveEvent(event)


class NumericTableWidgetItem(QTableWidgetItem):
    """A QTableWidgetItem that sorts numerically instead of alphabetically."""
    
    def __init__(self, text: str, sort_value: int | float):
        super().__init__(text)
        self._sort_value = sort_value
    
    def __lt__(self, other):
        if isinstance(other, NumericTableWidgetItem):
            return self._sort_value < other._sort_value
        return super().__lt__(other)


class HorizontalTabWidget(QTabWidget):
    """Tab widget with horizontal text for west position."""
    
    # Signal to request opening a tab in a new window
    openTabInNewWindow = pyqtSignal(int)
    # Signal emitted when a view icon in the tab bar is clicked
    viewIconClicked = pyqtSignal(str)  # view_id
    # Signals for view icon context menu actions
    viewIconUpdateRequested = pyqtSignal(str)  # view_id
    viewIconDeleteRequested = pyqtSignal(str)  # view_id
    # Signal for renaming a view icon
    viewIconRenameRequested = pyqtSignal(str)  # view_id
    # Signal emitted when user right-clicks blank area to create a new view
    createNewViewRequested = pyqtSignal()
    # Signals for view icon MIDI learn
    viewIconMidiLearnRequested = pyqtSignal(str)  # view_id
    viewIconMidiClearRequested = pyqtSignal(str)  # view_id
    
    def __init__(self, parent=None):
        super().__init__(parent)
        tab_bar = HorizontalTabBar()
        self.setTabBar(tab_bar)
        tab_bar.openInNewWindowRequested.connect(self.openTabInNewWindow.emit)
        tab_bar.viewIconClicked.connect(self.viewIconClicked.emit)
        tab_bar.viewIconUpdateRequested.connect(self.viewIconUpdateRequested.emit)
        tab_bar.viewIconDeleteRequested.connect(self.viewIconDeleteRequested.emit)
        tab_bar.viewIconRenameRequested.connect(self.viewIconRenameRequested.emit)
        tab_bar.createNewViewRequested.connect(self.createNewViewRequested.emit)
        tab_bar.viewIconMidiLearnRequested.connect(self.viewIconMidiLearnRequested.emit)
        tab_bar.viewIconMidiClearRequested.connect(self.viewIconMidiClearRequested.emit)
    
    def set_view_icons(self, icons: list[tuple[str, 'QPixmap', str]]):
        """Pass view icons through to the tab bar."""
        self.tabBar().set_view_icons(icons)
    
    def set_active_view(self, view_id: str | None):
        """Pass active view through to the tab bar."""
        self.tabBar().set_active_view(view_id)


class DetachedTabWindow(QMainWindow):
    """A detached window containing a tab's content."""
    
    closed = pyqtSignal(str)  # Emits tab_name when closed
    moved_by_user = pyqtSignal(str)  # Emits tab_name when user moves window
    position_changed = pyqtSignal(int, int)  # Emits (x, y) when window moves
    
    def __init__(self, tab_name: str, content_widget: QWidget, parent=None):
        # Always pass None as parent to make this a truly independent top-level window
        super().__init__(None)
        self.tab_name = tab_name
        self._main_window = parent  # Store reference to main window
        self.setWindowTitle(f"Lighting Designer - {tab_name}")
        self.setMinimumSize(400, 300)
        self._always_on_top = False
        
        # Set window flags for an independent window that stays on top of main window
        self.setWindowFlags(
            Qt.WindowType.Window |
            Qt.WindowType.WindowTitleHint |
            Qt.WindowType.WindowSystemMenuHint |
            Qt.WindowType.WindowMinMaxButtonsHint |
            Qt.WindowType.WindowCloseButtonHint
        )
        
        # Apply dark stylesheet
        self.setStyleSheet(DARK_STYLESHEET)
        
        # Create container widget with colored background for border effect
        self._container = QWidget()
        self._container.setObjectName("borderContainer")
        self._border_width = 5
        
        # Layout with margins to create border effect
        container_layout = QVBoxLayout(self._container)
        container_layout.setContentsMargins(self._border_width, self._border_width, 
                                            self._border_width, self._border_width)
        container_layout.setSpacing(0)
        
        # Pin-to-top button bar
        pin_row = QHBoxLayout()
        pin_row.setContentsMargins(0, 0, 0, 0)
        pin_row.setSpacing(0)
        pin_row.addStretch()
        self._pin_btn = QPushButton("📌")
        self._pin_btn.setFixedSize(28, 22)
        self._pin_btn.setToolTip("Pin window on top of all windows")
        self._pin_btn.setCheckable(True)
        self._pin_btn.setStyleSheet(
            "QPushButton { background: transparent; border: none; font-size: 13px; padding: 0; }"
            "QPushButton:checked { background: #3a6a3a; border-radius: 4px; }")
        self._pin_btn.clicked.connect(self._toggle_always_on_top)
        pin_row.addWidget(self._pin_btn)
        container_layout.addLayout(pin_row)
        
        # Store content widget reference
        self._content_widget = content_widget
        container_layout.addWidget(content_widget)
        
        # Set container as central widget
        self.setCentralWidget(self._container)
        
        # Set initial inactive border color
        self._updateBorderColor(False)
        
        # Track if position was restored (to ignore initial move events)
        self._restore_complete = False
        self._user_moved = False
        self._using_fallback_position = False  # True if monitor was disconnected
        self._syncing = False  # True when syncing position from main window
        self._was_visible_before_minimize = True  # Track visibility before main window minimized
    
    def _updateBorderColor(self, active: bool):
        """Update the border color based on active state."""
        # Safety check - container may be deleted during window close
        try:
            if not hasattr(self, '_container') or self._container is None:
                return
            color = "#27ae60" if active else "#555"
            self._container.setStyleSheet(f"QWidget#borderContainer {{ background-color: {color}; }}")
        except RuntimeError:
            pass  # Widget was deleted

    def changeEvent(self, event):
        """Handle window activation state changes."""
        super().changeEvent(event)
        if event.type() == QEvent.Type.ActivationChange:
            self._updateBorderColor(self.isActiveWindow())
    
    def markRestoreComplete(self):
        """Call after restore is done to start tracking user moves."""
        self._restore_complete = True
    
    def setUsingFallbackPosition(self, using_fallback: bool):
        """Mark this window as using a fallback position (monitor disconnected)."""
        self._using_fallback_position = using_fallback
    
    def moveEvent(self, event):
        """Track user-initiated moves."""
        super().moveEvent(event)
        if not self._syncing:  # Don't emit if we're syncing from main window
            if self._restore_complete and not self._user_moved:
                self._user_moved = True
                # If user moves window, they've chosen a new position - clear fallback flag
                self._using_fallback_position = False
                self.moved_by_user.emit(self.tab_name)
            elif self._restore_complete:
                # Emit position change for synchronization
                pos = self.pos()
                self.position_changed.emit(pos.x(), pos.y())
    
    def resizeEvent(self, event):
        """Track user-initiated resizes."""
        super().resizeEvent(event)
        if self._restore_complete and not self._user_moved:
            self._user_moved = True
            # If user resizes window, they've chosen a new position - clear fallback flag
            self._using_fallback_position = False
            self.moved_by_user.emit(self.tab_name)
    
    def wasMovedByUser(self) -> bool:
        """Return True if user moved or resized this window."""
        return self._user_moved
    
    def shouldSavePosition(self) -> bool:
        """Return True if this window's position should be saved.
        
        Don't save if using fallback position (monitor disconnected).
        """
        return not self._using_fallback_position
    
    def moveToSynced(self, x: int, y: int):
        """Move the window without triggering position_changed signal (for sync from main)."""
        self._syncing = True
        self.move(x, y)
        self._syncing = False
    
    def _toggle_always_on_top(self):
        """Toggle always-on-top from the pin button."""
        self.setAlwaysOnTop(self._pin_btn.isChecked())

    def setAlwaysOnTop(self, on_top: bool):
        """Set or clear WindowStaysOnTopHint and persist the choice."""
        self._always_on_top = on_top
        self._pin_btn.setChecked(on_top)
        self._pin_btn.setToolTip("Unpin window" if on_top else "Pin window on top of all windows")
        flags = self.windowFlags()
        if on_top:
            flags |= Qt.WindowType.WindowStaysOnTopHint
        else:
            flags &= ~Qt.WindowType.WindowStaysOnTopHint
        was_visible = self.isVisible()
        self.setWindowFlags(flags)
        if was_visible:
            self.show()
        # Auto-save via main window if available
        if self._main_window and hasattr(self._main_window, '_save_detached_window_state'):
            if hasattr(self, '_is_fader_window') and getattr(self, '_is_fader_window', False):
                self._main_window._save_fader_windows_state()
            else:
                self._main_window._save_detached_window_state()

    def isAlwaysOnTop(self) -> bool:
        return self._always_on_top

    def closeEvent(self, event):
        """Emit signal when window is closed."""
        self.closed.emit(self.tab_name)
        event.accept()


class ScalingLabel(QLabel):
    """A QLabel that scales its font size to fit the available width."""
    
    def __init__(self, text: str = "", parent=None, min_font_size: int = 8, max_font_size: int = 18):
        super().__init__(text, parent)
        self._min_font_size = min_font_size
        self._max_font_size = max_font_size
        self._base_style = ""
    
    def setBaseStyle(self, style: str):
        """Set the base stylesheet (without font-size, which will be calculated)."""
        self._base_style = style
        self._updateFontSize()
    
    def setText(self, text: str):
        """Override setText to recalculate font size."""
        super().setText(text)
        self._updateFontSize()
    
    def resizeEvent(self, event):
        """Recalculate font size on resize."""
        super().resizeEvent(event)
        self._updateFontSize()
    
    def _updateFontSize(self):
        """Calculate and apply the optimal font size to fit the text."""
        text = self.text()
        if not text:
            # Use max font size for empty text
            self.setStyleSheet(f"{self._base_style} font-size: {self._max_font_size}px;")
            return
        
        available_width = self.width() - 10  # Account for padding
        if available_width <= 0:
            available_width = 100  # Fallback
        
        # Binary search for optimal font size
        font = self.font()
        best_size = self._min_font_size
        
        for size in range(self._max_font_size, self._min_font_size - 1, -1):
            font.setPixelSize(size)
            from PyQt6.QtGui import QFontMetrics
            fm = QFontMetrics(font)
            text_width = fm.horizontalAdvance(text)
            if text_width <= available_width:
                best_size = size
                break
        
        self.setStyleSheet(f"{self._base_style} font-size: {best_size}px;")


def _calc_tile_font_size(text: str, max_width: int, max_height: int,
                         pad_h: int = 16, pad_v: int = 32,
                         min_size: int = 7, max_size: int = 16) -> int:
    """Return the largest font size (px) at which *text* fits inside a tile.

    Text is allowed to word-wrap.  The function binary-searches from
    *max_size* down to *min_size* using QFontMetrics to measure.  The
    available rectangle is ``(max_width - pad_h) × (max_height - pad_v)``
    to account for button padding and the accent stripe.
    """
    from PyQt6.QtGui import QFont, QFontMetrics
    from PyQt6.QtCore import Qt as _Qt, QRect

    avail_w = max_width - pad_h
    avail_h = max_height - pad_v

    best = min_size
    for sz in range(max_size, min_size - 1, -1):
        font = QFont('Segoe UI', sz)
        font.setWeight(QFont.Weight.DemiBold)
        font.setPixelSize(sz)
        fm = QFontMetrics(font)
        br = fm.boundingRect(QRect(0, 0, avail_w, 0),
                             _Qt.AlignmentFlag.AlignCenter |
                             _Qt.TextFlag.TextWordWrap, text)
        if br.width() <= avail_w and br.height() <= avail_h:
            best = sz
            break
    return best


class _WordWrapButtonMixin:
    """Mixin for QPushButton subclasses that draws text with word-wrap.

    Call ``_setup_tile_font(font_size_px)`` after construction to store the
    desired pixel size.  ``paintEvent`` is overridden to draw centred,
    word-wrapped text inside the button's content rect (respecting padding
    and the bottom accent stripe).
    """

    _tile_font_size: int = 12

    def _setup_tile_font(self, font_size_px: int):
        self._tile_font_size = font_size_px

    def paintEvent(self, event):          # noqa: N802
        """Draw the button background via the stylesheet engine, then
        paint the label ourselves with word-wrap."""
        from PyQt6.QtWidgets import QStylePainter, QStyleOptionButton, QStyle
        from PyQt6.QtGui import QFont, QPainter
        from PyQt6.QtCore import Qt as _Qt, QRect

        # 1. Let Qt draw background / border / stripe from the stylesheet
        sp = QStylePainter(self)
        opt = QStyleOptionButton()
        self.initStyleOption(opt)
        opt.text = ""                     # suppress built-in text draw
        sp.drawControl(QStyle.ControlElement.CE_PushButton, opt)

        # 2. Draw text with word-wrap ourselves
        font = QFont('Segoe UI', self._tile_font_size)
        font.setWeight(QFont.Weight.DemiBold)
        font.setPixelSize(self._tile_font_size)
        sp.setFont(font)
        sp.setPen(opt.palette.buttonText().color())

        # Content rect (inside padding): 8px left/right, 12px top, 20px bottom (accent)
        cr = QRect(8, 8, self.width() - 16, self.height() - 28)
        sp.drawText(cr,
                    _Qt.AlignmentFlag.AlignCenter | _Qt.TextFlag.TextWordWrap,
                    self.text())
        sp.end()


class FlowLayout(QLayout):
    """A layout that arranges widgets in rows, wrapping to new rows when space runs out."""
    
    def __init__(self, parent=None, margin=0, h_spacing=10, v_spacing=10):
        super().__init__(parent)
        self._items = []
        self._h_spacing = h_spacing
        self._v_spacing = v_spacing
        if margin >= 0:
            self.setContentsMargins(margin, margin, margin, margin)
    
    def addItem(self, item):
        self._items.append(item)
    
    def count(self):
        return len(self._items)
    
    def itemAt(self, index):
        if 0 <= index < len(self._items):
            return self._items[index]
        return None
    
    def takeAt(self, index):
        if 0 <= index < len(self._items):
            return self._items.pop(index)
        return None
    
    def horizontalSpacing(self):
        return self._h_spacing
    
    def verticalSpacing(self):
        return self._v_spacing
    
    def expandingDirections(self):
        return Qt.Orientation(0)
    
    def hasHeightForWidth(self):
        return True
    
    def heightForWidth(self, width):
        return self._do_layout(QRect(0, 0, width, 0), test_only=True)
    
    def setGeometry(self, rect):
        super().setGeometry(rect)
        self._do_layout(rect, test_only=False)
    
    def sizeHint(self):
        return self.minimumSize()
    
    def minimumSize(self):
        size = QSize()
        for item in self._items:
            size = size.expandedTo(item.minimumSize())
        margins = self.contentsMargins()
        size += QSize(margins.left() + margins.right(), margins.top() + margins.bottom())
        return size
    
    def _do_layout(self, rect, test_only):
        """Arrange items in rows that wrap to fit the available width."""
        margins = self.contentsMargins()
        effective_rect = rect.adjusted(margins.left(), margins.top(), -margins.right(), -margins.bottom())
        x = effective_rect.x()
        y = effective_rect.y()
        line_height = 0
        
        for item in self._items:
            widget = item.widget()
            if widget is None:
                continue
            
            item_size = item.sizeHint()
            next_x = x + item_size.width() + self._h_spacing
            
            # Wrap to next line if item doesn't fit (unless it's the first item on the line)
            if next_x - self._h_spacing > effective_rect.right() + 1 and line_height > 0:
                x = effective_rect.x()
                y = y + line_height + self._v_spacing
                next_x = x + item_size.width() + self._h_spacing
                line_height = 0
            
            if not test_only:
                item.setGeometry(QRect(x, y, item_size.width(), item_size.height()))
            
            x = next_x
            line_height = max(line_height, item_size.height())
        
        total_height = y + line_height - rect.y() + margins.bottom()
        
        # Update parent widget's minimum height so scroll area works correctly
        if not test_only and self.parentWidget():
            self.parentWidget().setMinimumHeight(total_height)
        
        return total_height


class ResizableGraphicsView(QGraphicsView):
    """A graphics view that emits a signal when resized."""
    
    resized = pyqtSignal()
    
    def __init__(self, scene=None, parent=None):
        if scene:
            super().__init__(scene, parent)
        else:
            super().__init__(parent)
        self._resize_timer = QTimer()
        self._resize_timer.setSingleShot(True)
        self._resize_timer.timeout.connect(self.resized.emit)
    
    def resizeEvent(self, event):
        super().resizeEvent(event)
        # Debounce resize events to avoid too many refreshes
        self._resize_timer.start(100)


class _VizOverlayRectItem(QGraphicsRectItem):
    """Draggable / resizable rectangle that marks where the visualizer overlay sits.

    The user can click-drag to reposition, or drag the bottom-right corner
    handle to resize.  A dashed green border makes it clearly visible on the
    stage layout.
    """

    _HANDLE_SIZE = 14  # px size of the resize handle in the corner

    def __init__(self, rect: QRectF, gui, parent=None):
        super().__init__(rect, parent)
        self._gui = gui
        self._resizing = False
        self._drag_start = None
        self._rect_start = None

        # Visual style — dashed green border, semi-transparent fill
        self.setPen(QPen(QColor(76, 175, 80, 200), 2, Qt.PenStyle.DashLine))
        self.setBrush(QBrush(QColor(76, 175, 80, 25)))
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsMovable, True)
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemSendsGeometryChanges, True)
        self.setCursor(Qt.CursorShape.OpenHandCursor)
        self.setAcceptHoverEvents(True)
        self._interactive = True  # When False, all mouse events pass through

    def set_interactive(self, interactive: bool):
        """Toggle whether the overlay rect accepts mouse input.

        When *not* interactive the rect drops to z=-5 (behind fixtures) and
        ignores all mouse buttons so the user can freely drag fixtures.
        """
        self._interactive = interactive
        if interactive:
            self.setZValue(100)
            self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsMovable, True)
            self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)
            self.setAcceptedMouseButtons(Qt.MouseButton.AllButtons)
            self.setAcceptHoverEvents(True)
            self.setCursor(Qt.CursorShape.OpenHandCursor)
            self.setPen(QPen(QColor(76, 175, 80, 200), 2, Qt.PenStyle.DashLine))
        else:
            self.setZValue(-5)  # Behind fixtures but in front of video frame
            self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsMovable, False)
            self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, False)
            self.setAcceptedMouseButtons(Qt.MouseButton.NoButton)
            self.setAcceptHoverEvents(False)
            self.setCursor(Qt.CursorShape.ArrowCursor)
            self.setPen(QPen(QColor(76, 175, 80, 80), 1, Qt.PenStyle.DashLine))

    # -- helpers ---------------------------------------------------------

    def _handle_rect(self) -> QRectF:
        """Return the bottom-right resize handle area in *item* coords."""
        r = self.rect()
        hs = self._HANDLE_SIZE
        return QRectF(r.right() - hs, r.bottom() - hs, hs, hs)

    # -- paint -----------------------------------------------------------

    def paint(self, painter: QPainter, option, widget=None):
        super().paint(painter, option, widget)
        # Draw a small resize grip in the bottom-right corner
        painter.setPen(Qt.PenStyle.NoPen)
        painter.setBrush(QBrush(QColor(76, 175, 80, 160)))
        hr = self._handle_rect()
        painter.drawRect(hr)
        # Draw two small diagonal lines as a visual grip
        painter.setPen(QPen(QColor(255, 255, 255, 180), 1))
        x0, y0 = hr.right() - 3, hr.bottom() - 3
        for i in range(3):
            offset = i * 3
            painter.drawLine(QPointF(x0 - offset, y0),
                             QPointF(x0, y0 - offset))
        # Label
        painter.setPen(QPen(QColor(200, 255, 200, 200), 1))
        painter.setFont(QFont("Segoe UI", 8))
        painter.drawText(self.rect().adjusted(6, 4, 0, 0), "Visualizer Overlay")

    # -- hover -----------------------------------------------------------

    def hoverMoveEvent(self, event):
        if self._handle_rect().contains(event.pos()):
            self.setCursor(Qt.CursorShape.SizeFDiagCursor)
        else:
            self.setCursor(Qt.CursorShape.OpenHandCursor)
        super().hoverMoveEvent(event)

    # -- mouse -----------------------------------------------------------

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            if self._handle_rect().contains(event.pos()):
                self._resizing = True
                self._drag_start = event.pos()
                self._rect_start = QRectF(self.rect())
                event.accept()
                return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._resizing and self._drag_start:
            delta = event.pos() - self._drag_start
            new_w = max(60, self._rect_start.width() + delta.x())
            new_h = max(40, self._rect_start.height() + delta.y())
            self.setRect(QRectF(0, 0, new_w, new_h))
            self.update()
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if self._resizing:
            self._resizing = False
            self._drag_start = None
            self._rect_start = None
            # Persist geometry back to gui
            self._save_geom()
            event.accept()
            return
        # Persist position after move
        self._save_geom()
        super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self, event):
        """Double-click to snap overlay to full stage."""
        self._fit_to_stage()
        event.accept()

    def contextMenuEvent(self, event):
        """Right-click menu with Fit to Stage option."""
        if not self._interactive:
            event.ignore()
            return
        from PyQt6.QtWidgets import QMenu
        menu = QMenu()
        fit_action = menu.addAction("Fit to Stage")
        result = menu.exec(event.screenPos())
        if result == fit_action:
            self._fit_to_stage()
        event.accept()

    def _fit_to_stage(self):
        """Snap the overlay rect to cover the full stage area."""
        view = (getattr(self._gui, '_main_location_view', None)
                or getattr(self._gui, 'location_view', None))
        if view is None:
            return
        _aw = max(1, view.viewport().width() - 40)
        _ah = max(1, view.viewport().height() - 40)
        _tr = 16.0 / 9.0
        if _aw / _ah > _tr:
            vh = _ah; vw = int(_ah * _tr)
        else:
            vw = _aw; vh = int(_aw / _tr)
        self.setPos(0, 0)
        self.setRect(QRectF(0, 0, float(vw), float(vh)))
        self._save_geom()
        self.update()

    def _save_geom(self):
        """Store the current geometry so it survives scene refreshes."""
        geom = (
            self.pos().x(), self.pos().y(),
            self.rect().width(), self.rect().height(),
        )
        self._gui._viz_overlay_rect_geom = geom
        # Persist to app settings so it survives app restarts
        if hasattr(self._gui, 'app_settings'):
            self._gui.app_settings['viz_overlay_rect_geom'] = list(geom)
            # Also store proportional (0-1) geometry so the overlay scales
            # correctly when the view/window is resized.
            view = (getattr(self._gui, '_main_location_view', None)
                    or getattr(self._gui, 'location_view', None))
            if view is not None:
                _aw = max(1, view.viewport().width() - 40)
                _ah = max(1, view.viewport().height() - 40)
                _tr = 16.0 / 9.0
                if _aw / _ah > _tr:
                    vh = _ah; vw = int(_ah * _tr)
                else:
                    vw = _aw; vh = int(_aw / _tr)
                rel = [geom[0] / vw, geom[1] / vh,
                       geom[2] / vw, geom[3] / vh]
                self._gui.app_settings['viz_overlay_rect_geom_rel'] = rel
                self._gui._viz_overlay_rect_geom_rel = tuple(rel)
            self._gui._save_app_settings()


class DraggableFixtureItem(QGraphicsEllipseItem):
    """A draggable fixture item for the location view."""
    
    def __init__(self, fixture: 'PatchedFixture', stage_width: float, stage_height: float, gui):
        self.fixture = fixture
        self.stage_width = stage_width
        self.stage_height = stage_height
        self.gui = gui
        
        # Size proportional to stage width so it matches the visualizer
        # effect rendering after the frame is scaled to the overlay rect.
        # At 1280 render width the spot is 40px; scale accordingly.
        size = max(20, stage_width * 40.0 / 1280.0)
        super().__init__(-size/2, -size/2, size, size)
        
        # Position based on fixture's location
        x = fixture.location_x * stage_width
        y = fixture.location_y * stage_height
        self.setPos(x, y)
        
        # Enable interactions - check if layout is locked
        is_locked = gui._stage_layout_locked if hasattr(gui, '_stage_layout_locked') else False
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsMovable, not is_locked)
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable)
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemSendsGeometryChanges)
        self.setAcceptHoverEvents(True)
        self.setCursor(Qt.CursorShape.ForbiddenCursor if is_locked else Qt.CursorShape.OpenHandCursor)
        
        # Add label - wrap to 2-3 lines for readability
        label_text = fixture.label or fixture.profile.name
        # Wrap text to ~10 chars per line, max 3 lines
        max_chars_per_line = 10
        lines = []
        words = label_text.split()
        current_line = ""
        for word in words:
            if len(current_line) + len(word) + 1 <= max_chars_per_line:
                current_line = f"{current_line} {word}".strip()
            else:
                if current_line:
                    lines.append(current_line)
                current_line = word
        if current_line:
            lines.append(current_line)
        # Limit to 3 lines
        if len(lines) > 3:
            lines = lines[:3]
            lines[2] = lines[2][:max_chars_per_line-3] + "..." if len(lines[2]) > max_chars_per_line-3 else lines[2]
        wrapped_text = "\n".join(lines)
        
        self.label = QGraphicsTextItem(wrapped_text, self)
        self.label.setDefaultTextColor(QColor(200, 200, 200))
        font = self.label.font()
        font.setPointSize(8)
        self.label.setFont(font)
        # Center label below the fixture
        label_rect = self.label.boundingRect()
        self.label.setPos(-label_rect.width() / 2, size / 2 + 2)
        
        # Store full label text for tooltip
        self._full_label_text = label_text
        
        # Set tooltip with fixture info (always shows on hover regardless of label visibility)
        tooltip = f"{label_text}\nUniverse: {fixture.universe}, Address: {fixture.address}"
        self.setToolTip(tooltip)
        
        # Universe/address badge
        badge_text = f"{fixture.universe}.{fixture.address}"
        self.badge = QGraphicsTextItem(badge_text, self)
        self.badge.setDefaultTextColor(QColor(150, 150, 150))
        badge_font = self.badge.font()
        badge_font.setPointSize(7)
        self.badge.setFont(badge_font)
        badge_rect = self.badge.boundingRect()
        self.badge.setPos(-badge_rect.width() / 2, -size / 2 - badge_rect.height())
        
        # Add glow effect for live visualization
        self._glow_effect = QGraphicsDropShadowEffect()
        self._glow_effect.setBlurRadius(0)
        self._glow_effect.setOffset(0, 0)
        self._glow_effect.setColor(QColor(0, 0, 0, 0))
        self.setGraphicsEffect(self._glow_effect)
        self._current_live_color = None
        
        # Add beam direction indicator for moving heads (initially hidden)
        self._beam_line = QGraphicsLineItem(0, 0, 0, 0, self)
        self._beam_pen = QPen(QColor(255, 255, 0, 150), 3, Qt.PenStyle.SolidLine)
        self._beam_pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        self._beam_line.setPen(self._beam_pen)
        self._beam_line.setVisible(False)
        self._beam_line.setZValue(-1)  # Draw behind the fixture circle
        
        # Add light beam cone for realistic visualization
        self._beam_cone = QGraphicsPathItem(self)
        self._beam_cone.setVisible(False)
        self._beam_cone.setZValue(-2)  # Draw behind beam line and fixture
        self._beam_cone_color = QColor(255, 255, 255, 80)
        
        # Set initial appearance (must be after label is created)
        self._update_appearance(False)
    
    def update_live_color(self, r: int, g: int, b: int, intensity: int):
        """Update the fixture's appearance based on live DMX output.
        
        Args:
            r: Red value 0-255
            g: Green value 0-255
            b: Blue value 0-255
            intensity: Overall intensity 0-255
        """
        # For fixtures with no RGB (LED bars, strobes), default to white
        if r == 0 and g == 0 and b == 0 and intensity > 0:
            r, g, b = 255, 255, 255  # White light
        
        # Scale RGB by intensity (dimmer value)
        # When intensity is 0, the light is off regardless of RGB values
        scale = intensity / 255.0
        effective_r = int(r * scale)
        effective_g = int(g * scale)
        effective_b = int(b * scale)
        
        # Calculate effective brightness from the scaled values
        # Note: For fixtures with dimmers, the brightness is determined by the dimmer,
        # which scales the RGB output. For fixtures without dimmers (RGB only),
        # the brightness is determined by the max RGB value directly.
        brightness = max(effective_r, effective_g, effective_b)
        
        if brightness < 1:  # Changed from 10 to 1 to catch strobe flashes
            # Light is off - remove glow, show "off" state
            self._glow_effect.setBlurRadius(0)
            self._glow_effect.setColor(QColor(0, 0, 0, 0))
            self._current_live_color = None
            # Restore "off" appearance (dark/muted)
            self._update_appearance(self.isSelected())
        else:
            # Light is on - show glow with color
            # Create glow color with alpha based on brightness
            glow_color = QColor(effective_r, effective_g, effective_b, min(255, brightness + 100))
            
            # Set glow effect
            glow_radius = 15 + (brightness / 255.0) * 30  # 15-45 radius based on brightness
            self._glow_effect.setBlurRadius(glow_radius)
            self._glow_effect.setColor(glow_color)
            
            # Update fixture fill color to match output
            self._current_live_color = QColor(effective_r, effective_g, effective_b)
            
            # Update label color to white for visibility when lit
            self.label.setDefaultTextColor(QColor(255, 255, 255))
            
            # Blend with selection state
            if self.isSelected():
                self.setPen(QPen(QColor(201, 122, 80), 3))  # Orange selection
            else:
                # Outline color matches glow but darker
                outline_color = QColor(effective_r // 2, effective_g // 2, effective_b // 2)
                self.setPen(QPen(outline_color, 2))
            
            # Set fill to light color (lighter for visibility)
            fill_color = QColor(
                min(255, effective_r + 50),
                min(255, effective_g + 50), 
                min(255, effective_b + 50)
            )
            self.setBrush(QBrush(fill_color))
    
    def update_beam_direction(self, pan: int, tilt: int, intensity: int):
        """Update the beam direction indicator based on pan/tilt values.
        
        Args:
            pan: Pan value 0-255 (128 = center)
            tilt: Tilt value 0-255 (128 = center)
            intensity: Overall intensity 0-255 (affects beam visibility)
        """
        # Only show beam if fixture has movement and light is on
        if intensity < 1:
            self._beam_line.setVisible(False)
            self._beam_cone.setVisible(False)
            return
        
        # Check if this fixture has pan/tilt capabilities
        has_pan_tilt = False
        if self.fixture and self.fixture.mode:
            for ch in self.fixture.mode.channels:
                if ch.type.lower() in ('pan', 'tilt'):
                    has_pan_tilt = True
                    break
        
        if not has_pan_tilt:
            self._beam_line.setVisible(False)
            self._beam_cone.setVisible(False)
            return
        
        # Get calibration values from fixture (with defaults)
        pan_offset = getattr(self.fixture, 'pan_offset', 0.0)
        pan_invert = getattr(self.fixture, 'pan_invert', False)
        pan_range = getattr(self.fixture, 'pan_range', 540.0)
        tilt_offset = getattr(self.fixture, 'tilt_offset', 0.0)
        tilt_invert = getattr(self.fixture, 'tilt_invert', False)
        tilt_range = getattr(self.fixture, 'tilt_range', 270.0)
        
        # Convert DMX values to angles using fixture-specific ranges
        # Pan: 0-255 maps to full pan range (e.g., 540° = -270° to +270°)
        # For visualization, we use a fraction of that (visible arc)
        half_pan_range = pan_range / 2.0
        pan_normalized = (pan / 255.0) - 0.5  # -0.5 to +0.5
        if pan_invert:
            pan_normalized = -pan_normalized
        pan_angle = pan_normalized * pan_range + pan_offset
        # Clamp to visible arc (-90 to +90 for 2D visualization)
        pan_angle = max(-90.0, min(90.0, pan_angle * (90.0 / half_pan_range)))
        
        # Tilt: 0-255 maps to full tilt range (e.g., 270° = -135° to +135°)
        half_tilt_range = tilt_range / 2.0
        tilt_normalized = (tilt / 255.0) - 0.5  # -0.5 to +0.5
        if tilt_invert:
            tilt_normalized = -tilt_normalized
        tilt_angle = tilt_normalized * tilt_range + tilt_offset
        # Clamp and invert (Y grows downward in screen coordinates)
        tilt_angle = max(-60.0, min(60.0, tilt_angle * (60.0 / half_tilt_range)))
        tilt_angle = -tilt_angle  # Invert for screen Y
        
        # Calculate beam endpoint (in fixture-local coordinates)
        # Beam length scales with intensity
        beam_length = 80 + (intensity / 255.0) * 60  # 80-140 pixels
        
        # Mirror factor (flip when viewing from opposite side of stage)
        # From the other side: pan (left/right) reverses, tilt direction reverses
        if getattr(self.gui, '_stage_beams_mirrored', False):
            pan_angle = -pan_angle
            tilt_angle = -tilt_angle
        
        # Convert angles to radians for calculation
        import math
        pan_rad = math.radians(pan_angle)
        tilt_rad = math.radians(tilt_angle)
        
        # Top-down projection model:
        #   Pan  → direction of beam on stage floor (compass angle)
        #   Tilt → how far the beam reaches along that direction
        #          (centre / straight-down = short dot, tilted = long throw)
        tilt_reach = abs(math.sin(tilt_rad))           # 0 at centre, 1 at max tilt
        effective_length = beam_length * max(0.15, tilt_reach)  # always show a small stub
        
        # Pan direction on the 2D stage plane
        # pan_rad = 0 → beam projects downstage (positive Y on screen)
        end_x = math.sin(pan_rad) * effective_length
        end_y = math.cos(pan_rad) * effective_length
        
        # Update beam line (center line of beam)
        self._beam_line.setLine(0, 0, end_x, end_y)
        
        # Create light beam cone with gradient
        # Beam spreads out as it goes further
        beam_spread = 15 + (intensity / 255.0) * 10  # 15-25 degree spread
        spread_rad = math.radians(beam_spread)
        
        # Calculate cone edge points (perpendicular to beam direction)
        beam_direction = math.atan2(end_y, end_x)
        perp_angle = beam_direction + math.pi / 2
        
        # Width at the end of the beam (cone opening)
        end_width = beam_length * math.tan(spread_rad)
        
        # Calculate cone vertices
        # Start with small opening at fixture
        start_width = 5
        
        # Four corners of the beam cone
        sx1 = math.cos(perp_angle) * start_width
        sy1 = math.sin(perp_angle) * start_width
        sx2 = -sx1
        sy2 = -sy1
        
        ex1 = end_x + math.cos(perp_angle) * end_width
        ey1 = end_y + math.sin(perp_angle) * end_width
        ex2 = end_x - math.cos(perp_angle) * end_width
        ey2 = end_y - math.sin(perp_angle) * end_width
        
        # Create cone path
        from PyQt6.QtGui import QPainterPath, QLinearGradient
        cone_path = QPainterPath()
        cone_path.moveTo(sx1, sy1)
        cone_path.lineTo(ex1, ey1)
        cone_path.lineTo(ex2, ey2)
        cone_path.lineTo(sx2, sy2)
        cone_path.closeSubpath()
        
        self._beam_cone.setPath(cone_path)
        
        # Update colors based on current light color
        if self._current_live_color:
            r = self._current_live_color.red()
            g = self._current_live_color.green()
            b = self._current_live_color.blue()
            
            # Create gradient from fixture to end of beam
            gradient = QLinearGradient(0, 0, end_x, end_y)
            
            # Bright at source, fading toward end
            alpha_start = min(200, 80 + int(intensity * 0.5))
            alpha_end = max(10, alpha_start // 4)
            
            gradient.setColorAt(0.0, QColor(r, g, b, alpha_start))
            gradient.setColorAt(0.3, QColor(r, g, b, int(alpha_start * 0.7)))
            gradient.setColorAt(0.7, QColor(r, g, b, int(alpha_start * 0.3)))
            gradient.setColorAt(1.0, QColor(r, g, b, alpha_end))
            
            self._beam_cone.setBrush(QBrush(gradient))
            self._beam_cone.setPen(QPen(Qt.PenStyle.NoPen))
            
            # Update center beam line color
            beam_color = QColor(r, g, b, 220)
            self._beam_pen.setColor(beam_color)
            self._beam_pen.setWidth(2)
            self._beam_line.setPen(self._beam_pen)
        else:
            # Default white beam
            gradient = QLinearGradient(0, 0, end_x, end_y)
            alpha = min(150, 50 + int(intensity * 0.4))
            gradient.setColorAt(0.0, QColor(255, 255, 255, alpha))
            gradient.setColorAt(1.0, QColor(255, 255, 255, alpha // 4))
            self._beam_cone.setBrush(QBrush(gradient))
            self._beam_cone.setPen(QPen(Qt.PenStyle.NoPen))
        
        self._beam_line.setVisible(True)
        self._beam_cone.setVisible(True)
    
    def _get_category_color(self) -> QColor:
        """Get the color for this fixture's category (for label when off)."""
        category = self.fixture.profile.category.lower()
        if 'mover' in category or 'moving' in category or 'spot' in category:
            return QColor(100, 150, 255)  # Blue for movers
        elif 'wash' in category:
            return QColor(255, 150, 100)  # Orange for wash
        elif 'strobe' in category or 'blinder' in category:
            return QColor(255, 255, 150)  # Yellow for strobes
        elif 'bar' in category or 'strip' in category:
            return QColor(150, 255, 150)  # Green for bars
        else:
            return QColor(180, 180, 180)  # Light gray for others
    
    def _update_appearance(self, selected: bool):
        """Update the item's visual appearance.
        
        When fixture is off: dark/muted fill with category-colored text label.
        This keeps fixtures visually quiet but identifiable by type.
        """
        # Get category color for label
        category_color = self._get_category_color()
        
        # Set label text color to category color when off
        self.label.setDefaultTextColor(category_color)
        
        # Dark/muted fill color for "off" state
        off_color = QColor(50, 50, 55)  # Dark gray
        
        if selected:
            self.setPen(QPen(QColor(201, 122, 80), 3))  # Orange selection
            self.setBrush(QBrush(off_color.lighter(130)))
        else:
            self.setPen(QPen(QColor(80, 80, 90), 2))  # Dark border
            self.setBrush(QBrush(off_color))
    
    def set_label_visible(self, visible: bool):
        """Show or hide the fixture name label and badge.
        
        When hidden, the fixture name is still available via tooltip on hover.
        """
        self.label.setVisible(visible)
        self.badge.setVisible(visible)
    
    def itemChange(self, change, value):
        if change == QGraphicsItem.GraphicsItemChange.ItemPositionChange:
            # Constrain to stage bounds
            new_pos = value
            x = max(0, min(self.stage_width, new_pos.x()))
            y = max(0, min(self.stage_height, new_pos.y()))
            return QPointF(x, y)
        elif change == QGraphicsItem.GraphicsItemChange.ItemPositionHasChanged:
            # Update fixture location
            x_norm = self.pos().x() / self.stage_width
            y_norm = self.pos().y() / self.stage_height
            self.gui._on_location_fixture_moved(self.fixture.id, x_norm, y_norm)
        elif change == QGraphicsItem.GraphicsItemChange.ItemSelectedHasChanged:
            selected = bool(value)
            self._update_appearance(selected)
            # Skip selection tracking during programmatic bulk operations (search)
            if getattr(self.gui, '_programmatic_selection', False):
                return super().itemChange(change, value)
            # Treat rubber-band selections as multi-select so we don't
            # deselect everything the rubber-band just selected.
            modifiers = QApplication.keyboardModifiers()
            multi = bool(modifiers & Qt.KeyboardModifier.ControlModifier)
            if not multi:
                # Check if the scene has >1 selected items right now —
                # that means a rubber-band or programmatic multi-select
                # is in progress, so treat it as multi.
                scene = self.scene()
                if scene and len(scene.selectedItems()) > 1:
                    multi = True
            self.gui._on_location_fixture_selected(self.fixture.id, selected, multi)
        return super().itemChange(change, value)
    
    def _is_layout_locked(self) -> bool:
        """Check if layout is locked."""
        return self.gui._stage_layout_locked if hasattr(self.gui, '_stage_layout_locked') else False
    
    def hoverEnterEvent(self, event):
        if self._is_layout_locked():
            self.setCursor(Qt.CursorShape.ForbiddenCursor)
        else:
            self.setCursor(Qt.CursorShape.OpenHandCursor)
        super().hoverEnterEvent(event)
    
    def mousePressEvent(self, event):
        if not self._is_layout_locked():
            self.setCursor(Qt.CursorShape.ClosedHandCursor)
        # Record peer positions for group drag
        self._group_drag_start = None
        if event.button() == Qt.MouseButton.LeftButton and self.isSelected() and not self._is_layout_locked():
            peers = [it for it in self.scene().selectedItems()
                     if isinstance(it, (DraggableFixtureItem, PixelMappedFixtureItem, SquareFixtureItem)) and it is not self]
            if peers:
                self._group_drag_start = event.scenePos()
                self._group_peer_origins = {id(it): QPointF(it.pos()) for it in peers}
                self._group_peers = peers
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        # Group drag: move peers by the same delta
        if getattr(self, '_group_drag_start', None) is not None:
            delta = event.scenePos() - self._group_drag_start
            for peer in self._group_peers:
                origin = self._group_peer_origins.get(id(peer))
                if origin:
                    new_x = max(0, min(peer.stage_width, origin.x() + delta.x()))
                    new_y = max(0, min(peer.stage_height, origin.y() + delta.y()))
                    peer.setPos(new_x, new_y)
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        self._group_drag_start = None
        if self._is_layout_locked():
            self.setCursor(Qt.CursorShape.ForbiddenCursor)
        else:
            self.setCursor(Qt.CursorShape.OpenHandCursor)
        super().mouseReleaseEvent(event)
    
    def mouseDoubleClickEvent(self, event):
        """Open fixture control dialog on double-click."""
        if event.button() == Qt.MouseButton.LeftButton:
            # Get all selected fixtures, include this one if not selected
            selected = self._get_selected_fixtures()
            if self.fixture not in selected:
                selected = [self.fixture]
            self.gui._open_fixture_control(selected)
        super().mouseDoubleClickEvent(event)
    
    def contextMenuEvent(self, event):
        """Show context menu on right-click."""
        menu = QMenu()
        menu.setStyleSheet(self.gui._get_touch_menu_stylesheet())
        
        # Edit fixture option
        edit_action = menu.addAction("✏️ Edit Fixture...")
        edit_action.triggered.connect(lambda: self.gui._edit_fixture(self.fixture))
        
        # Get all selected fixtures (including this one if not selected)
        selected_fixtures = self._get_selected_fixtures()
        if self.fixture not in selected_fixtures:
            selected_fixtures = [self.fixture]
        
        # Control option (same as double-click)
        control_action = menu.addAction("🎛️ Control")
        _ctrl_fixtures = list(selected_fixtures)
        control_action.triggered.connect(lambda: self.gui._open_fixture_control(_ctrl_fixtures))

        # Trackpad option — only if fixture has pan or tilt channels
        has_pt = False
        if self.fixture.mode:
            for ch in self.fixture.mode.channels:
                if ch.type.lower() in ('pan', 'tilt'):
                    has_pt = True
                    break
        if has_pt:
            trackpad_action = menu.addAction("🎯 Trackpad")
            trackpad_action.triggered.connect(lambda: self.gui._open_pan_tilt_trackpad(self.fixture))

        menu.addSeparator()
        
        # Check if any selected fixtures are currently identified
        any_identified = any(f.id in self.gui._individually_identified for f in selected_fixtures)
        all_identified = all(f.id in self.gui._individually_identified for f in selected_fixtures)
        
        if len(selected_fixtures) > 1:
            # Multiple fixtures selected
            if all_identified:
                stop_identify_action = menu.addAction(f"⬛ Stop Identify ({len(selected_fixtures)} fixtures)")
                stop_identify_action.triggered.connect(lambda: self._identify_selected_fixtures(False))
            else:
                identify_action = menu.addAction(f"🔦 Identify {len(selected_fixtures)} Fixtures")
                identify_action.triggered.connect(lambda: self._identify_selected_fixtures(True))
                if any_identified:
                    stop_identify_action = menu.addAction(f"⬛ Stop Identify ({len(selected_fixtures)} fixtures)")
                    stop_identify_action.triggered.connect(lambda: self._identify_selected_fixtures(False))
        else:
            # Single fixture
            is_identified = self.fixture.id in self.gui._individually_identified
            if is_identified:
                stop_identify_action = menu.addAction("⬛ Stop Identify")
                stop_identify_action.triggered.connect(lambda: self._identify_fixture(False))
            else:
                identify_action = menu.addAction("🔦 Identify Fixture")
                identify_action.triggered.connect(lambda: self._identify_fixture(True))
        
        # Stop all identifies if any are active
        if self.gui._individually_identified:
            stop_all_action = menu.addAction("⬛ Stop All Identifies")
            stop_all_action.triggered.connect(self.gui._stop_all_individual_identifies)
        
        menu.addSeparator()
        
        # Select action
        select_action = menu.addAction("✓ Select")
        select_action.triggered.connect(lambda: self.setSelected(True))
        
        # Deselect all action
        deselect_action = menu.addAction("✗ Deselect All")
        deselect_action.triggered.connect(self._deselect_all)
        
        menu.exec(event.screenPos())
    
    def _get_selected_fixtures(self):
        """Get all selected fixtures in the scene."""
        fixtures = []
        if self.scene():
            for item in self.scene().items():
                if isinstance(item, DraggableFixtureItem) and item.isSelected():
                    fixtures.append(item.fixture)
        return fixtures
    
    def _identify_selected_fixtures(self, on: bool):
        """Send identify signal to all selected fixtures."""
        selected_fixtures = self._get_selected_fixtures()
        if not selected_fixtures:
            selected_fixtures = [self.fixture]
        
        for fixture in selected_fixtures:
            if on:
                self.gui._individually_identified.add(fixture.id)
            else:
                self.gui._individually_identified.discard(fixture.id)
        
        self.gui._send_locate_to_fixtures(selected_fixtures, on)
    
    def _identify_fixture(self, on: bool):
        """Send identify signal to this specific fixture only."""
        if on:
            self.gui._individually_identified.add(self.fixture.id)
        else:
            self.gui._individually_identified.discard(self.fixture.id)
        self.gui._send_locate_to_fixtures([self.fixture], on)
    
    def _deselect_all(self):
        """Deselect all fixtures in the scene."""
        if self.scene():
            for item in self.scene().items():
                # Check by class name to avoid forward reference issues
                if type(item).__name__ in ('DraggableFixtureItem', 'PixelMappedFixtureItem', 'SquareFixtureItem'):
                    item.setSelected(False)


class SquareFixtureItem(QGraphicsRectItem):
    """A square fixture item for non-light equipment (Smoke, Haze, Laser)."""

    _CATEGORY_LABELS = {
        'smoke machine': 'SMOKE',
        'haze machine': 'HAZE',
        'laser': 'LASER',
    }

    def __init__(self, fixture: 'PatchedFixture', stage_width: float, stage_height: float, gui):
        self.fixture = fixture
        self.stage_width = stage_width
        self.stage_height = stage_height
        self.gui = gui

        size = max(24, stage_width * 44.0 / 1280.0)
        super().__init__(-size / 2, -size / 2, size, size)

        x = fixture.location_x * stage_width
        y = fixture.location_y * stage_height
        self.setPos(x, y)

        is_locked = gui._stage_layout_locked if hasattr(gui, '_stage_layout_locked') else False
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsMovable, not is_locked)
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable)
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemSendsGeometryChanges)
        self.setAcceptHoverEvents(True)
        self.setCursor(Qt.CursorShape.ForbiddenCursor if is_locked else Qt.CursorShape.OpenHandCursor)

        # Short category label centred inside the box
        cat_key = (fixture.profile.category or '').lower()
        box_text = self._CATEGORY_LABELS.get(cat_key, cat_key.upper()[:5])
        self._inner_label = QGraphicsTextItem(box_text, self)
        self._inner_label.setDefaultTextColor(QColor(220, 220, 220))
        inner_font = self._inner_label.font()
        inner_font.setPointSize(7)
        inner_font.setBold(True)
        self._inner_label.setFont(inner_font)
        ir = self._inner_label.boundingRect()
        self._inner_label.setPos(-ir.width() / 2, -ir.height() / 2)

        # Fixture name label below the box
        label_text = fixture.label or fixture.profile.name
        self.label = QGraphicsTextItem(label_text, self)
        self.label.setDefaultTextColor(QColor(200, 200, 200))
        lfont = self.label.font()
        lfont.setPointSize(8)
        self.label.setFont(lfont)
        lr = self.label.boundingRect()
        self.label.setPos(-lr.width() / 2, size / 2 + 2)

        self._full_label_text = label_text
        self.setToolTip(f"{label_text}\nUniverse: {fixture.universe}, Address: {fixture.address}")

        # Address badge above the box
        badge_text = f"{fixture.universe}.{fixture.address}"
        self.badge = QGraphicsTextItem(badge_text, self)
        self.badge.setDefaultTextColor(QColor(150, 150, 150))
        bf = self.badge.font()
        bf.setPointSize(7)
        self.badge.setFont(bf)
        br = self.badge.boundingRect()
        self.badge.setPos(-br.width() / 2, -size / 2 - br.height())

        # Glow effect (reused by live viz)
        self._glow_effect = QGraphicsDropShadowEffect()
        self._glow_effect.setBlurRadius(0)
        self._glow_effect.setOffset(0, 0)
        self._glow_effect.setColor(QColor(0, 0, 0, 0))
        self.setGraphicsEffect(self._glow_effect)
        self._current_live_color = None

        self._update_appearance(False)

    # -- public API expected by the viz timer / selection helpers -----------

    def update_live_color(self, r: int, g: int, b: int, intensity: int):
        scale = intensity / 255.0
        er, eg, eb = int(r * scale), int(g * scale), int(b * scale)
        brightness = max(er, eg, eb)
        if brightness < 1:
            self._glow_effect.setBlurRadius(0)
            self._glow_effect.setColor(QColor(0, 0, 0, 0))
            self._current_live_color = None
            self._update_appearance(self.isSelected())
        else:
            glow_color = QColor(er, eg, eb, min(255, brightness + 100))
            self._glow_effect.setBlurRadius(15 + (brightness / 255.0) * 30)
            self._glow_effect.setColor(glow_color)
            self._current_live_color = QColor(er, eg, eb)
            fill = QColor(min(255, er + 50), min(255, eg + 50), min(255, eb + 50))
            self.setBrush(QBrush(fill))
            self._inner_label.setDefaultTextColor(QColor(255, 255, 255))
            self.label.setDefaultTextColor(QColor(255, 255, 255))
            if self.isSelected():
                self.setPen(QPen(QColor(201, 122, 80), 3))
            else:
                self.setPen(QPen(QColor(er // 2, eg // 2, eb // 2), 2))

    def update_beam_direction(self, pan: int, tilt: int, intensity: int):
        pass  # No beam for these fixture types

    def set_label_visible(self, visible: bool):
        self.label.setVisible(visible)
        self.badge.setVisible(visible)

    def _update_appearance(self, selected: bool):
        cat = (self.fixture.profile.category or '').lower()
        if 'smoke' in cat:
            cat_color = QColor(160, 160, 180)
        elif 'haze' in cat:
            cat_color = QColor(130, 170, 200)
        elif 'laser' in cat:
            cat_color = QColor(80, 255, 80)
        else:
            cat_color = QColor(180, 180, 180)
        self._inner_label.setDefaultTextColor(cat_color)
        self.label.setDefaultTextColor(cat_color)
        off_color = QColor(50, 50, 55)
        if selected:
            self.setPen(QPen(QColor(201, 122, 80), 3))
            self.setBrush(QBrush(off_color.lighter(130)))
        else:
            self.setPen(QPen(QColor(80, 80, 90), 2))
            self.setBrush(QBrush(off_color))

    def itemChange(self, change, value):
        if change == QGraphicsItem.GraphicsItemChange.ItemPositionChange:
            new_pos = value
            x = max(0, min(self.stage_width, new_pos.x()))
            y = max(0, min(self.stage_height, new_pos.y()))
            return QPointF(x, y)
        elif change == QGraphicsItem.GraphicsItemChange.ItemPositionHasChanged:
            x_norm = self.pos().x() / self.stage_width
            y_norm = self.pos().y() / self.stage_height
            self.gui._on_location_fixture_moved(self.fixture.id, x_norm, y_norm)
        elif change == QGraphicsItem.GraphicsItemChange.ItemSelectedHasChanged:
            selected = bool(value)
            self._update_appearance(selected)
            if getattr(self.gui, '_programmatic_selection', False):
                return super().itemChange(change, value)
            multi = (QApplication.keyboardModifiers() & Qt.KeyboardModifier.ControlModifier) != 0
            if not multi:
                scene = self.scene()
                if scene and len(scene.selectedItems()) > 1:
                    multi = True
            self.gui._on_location_fixture_selected(self.fixture.id, selected, multi)
        return super().itemChange(change, value)

    def _is_layout_locked(self) -> bool:
        return self.gui._stage_layout_locked if hasattr(self.gui, '_stage_layout_locked') else False

    def hoverEnterEvent(self, event):
        self.setCursor(Qt.CursorShape.ForbiddenCursor if self._is_layout_locked() else Qt.CursorShape.OpenHandCursor)
        super().hoverEnterEvent(event)

    def mousePressEvent(self, event):
        if not self._is_layout_locked():
            self.setCursor(Qt.CursorShape.ClosedHandCursor)
        self._group_drag_start = None
        if event.button() == Qt.MouseButton.LeftButton and self.isSelected() and not self._is_layout_locked():
            peers = [it for it in self.scene().selectedItems()
                     if isinstance(it, (DraggableFixtureItem, PixelMappedFixtureItem, SquareFixtureItem)) and it is not self]
            if peers:
                self._group_drag_start = event.scenePos()
                self._group_peer_origins = {id(it): QPointF(it.pos()) for it in peers}
                self._group_peers = peers
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if getattr(self, '_group_drag_start', None) is not None:
            delta = event.scenePos() - self._group_drag_start
            for peer in self._group_peers:
                origin = self._group_peer_origins.get(id(peer))
                if origin:
                    new_x = max(0, min(peer.stage_width, origin.x() + delta.x()))
                    new_y = max(0, min(peer.stage_height, origin.y() + delta.y()))
                    peer.setPos(new_x, new_y)
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        self._group_drag_start = None
        self.setCursor(Qt.CursorShape.ForbiddenCursor if self._is_layout_locked() else Qt.CursorShape.OpenHandCursor)
        super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.gui._open_fixture_control([self.fixture])
        super().mouseDoubleClickEvent(event)

    def contextMenuEvent(self, event):
        menu = QMenu()
        menu.setStyleSheet(self.gui._get_touch_menu_stylesheet())
        edit_action = menu.addAction("✏️ Edit Fixture...")
        edit_action.triggered.connect(lambda: self.gui._edit_fixture(self.fixture))
        control_action = menu.addAction("🎛️ Control")
        control_action.triggered.connect(lambda: self.gui._open_fixture_control([self.fixture]))
        # Trackpad option — only if fixture has pan or tilt channels
        has_pt = False
        if self.fixture.mode:
            for ch in self.fixture.mode.channels:
                if ch.type.lower() in ('pan', 'tilt'):
                    has_pt = True
                    break
        if has_pt:
            trackpad_action = menu.addAction("🎯 Trackpad")
            trackpad_action.triggered.connect(lambda: self.gui._open_pan_tilt_trackpad(self.fixture))
        menu.exec(event.screenPos())


class PixelMappedFixtureItem(QGraphicsRectItem):
    """A draggable pixel-mapped fixture item for the location view.
    
    Renders fixtures with addressable pixels as a grid of pixel rectangles,
    each showing its live DMX color. Supports drag-to-resize.
    """
    
    # Minimum size in pixels (screen coordinates)
    MIN_WIDTH = 8
    MIN_HEIGHT = 20
    # Handle size for resize
    HANDLE_SIZE = 8
    
    def __init__(self, fixture: 'PatchedFixture', stage_width: float, stage_height: float, gui):
        self.fixture = fixture
        self.stage_width = stage_width
        self.stage_height = stage_height
        self.gui = gui
        
        # Calculate size based on fixture's visual dimensions
        width = max(self.MIN_WIDTH, fixture.visual_width * stage_width)
        height = max(self.MIN_HEIGHT, fixture.visual_height * stage_height)
        
        super().__init__(-width/2, -height/2, width, height)
        
        # Position based on fixture's location
        x = fixture.location_x * stage_width
        y = fixture.location_y * stage_height
        self.setPos(x, y)
        
        # Enable interactions - check if layout is locked
        is_locked = gui._stage_layout_locked if hasattr(gui, '_stage_layout_locked') else False
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsMovable, not is_locked)
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable)
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemSendsGeometryChanges)
        self.setAcceptHoverEvents(True)
        self.setCursor(Qt.CursorShape.ForbiddenCursor if is_locked else Qt.CursorShape.OpenHandCursor)
        
        # Store lock state for resize check
        self._is_locked = is_locked
        
        # Store current dimensions (can be changed by resize)
        self._width = width
        self._height = height
        
        # Resize state
        self._resizing = False
        self._resize_edge = None  # 'right', 'bottom', 'corner', or None
        self._resize_start_pos = None
        self._resize_start_rect = None
        
        # Create pixel rectangles as children
        self._pixel_items = []
        self._create_pixel_grid()
        
        # Add label below fixture
        label_text_raw = fixture.label or fixture.profile.name
        label_text = label_text_raw
        # Wrap text to ~12 chars per line, max 2 lines
        max_chars = 12
        if len(label_text) > max_chars:
            lines = [label_text[:max_chars], label_text[max_chars:max_chars*2]]
            label_text = "\n".join(lines)
        
        # Store full label text for tooltip
        self._full_label_text = label_text_raw
        
        # Set tooltip with fixture info (always shows on hover regardless of label visibility)
        tooltip = f"{label_text_raw}\nUniverse: {fixture.universe}, Address: {fixture.address}"
        self.setToolTip(tooltip)
        
        self.label = QGraphicsTextItem(label_text, self)
        self.label.setDefaultTextColor(QColor(200, 200, 200))
        font = self.label.font()
        font.setPointSize(8)
        self.label.setFont(font)
        self.label.setZValue(2)  # Label in front (positioned below fixture, no overlap)
        self._update_label_position()
        
        # Universe/address badge
        badge_text = f"{fixture.universe}.{fixture.address}"
        self.badge = QGraphicsTextItem(badge_text, self)
        self.badge.setDefaultTextColor(QColor(150, 150, 150))
        badge_font = self.badge.font()
        badge_font.setPointSize(7)
        self.badge.setFont(badge_font)
        self.badge.setZValue(2)  # Badge in front (positioned above fixture, no overlap)
        self._update_badge_position()
        
        # Create resize handles (initially hidden, shown on selection)
        self._resize_handles = []
        self._create_resize_handles()
        
        # Set initial appearance
        self._update_appearance(False)
        
        # Store live pixel colors for visualization
        self._pixel_colors = {}  # pixel_num -> QColor
    
    def _create_pixel_grid(self):
        """Create the grid of pixel items based on fixture configuration."""
        # Clear existing pixels
        for item in self._pixel_items:
            if item.scene():
                item.scene().removeItem(item)
        self._pixel_items = []
        
        # Read pixel grid size from profile
        profile = self.fixture.profile
        rows = max(1, profile.pixel_rows)
        cols = max(1, profile.pixel_columns)
        
        # Use a small border inside the fixture rect
        border = 2
        available_w = self._width - 2 * border
        available_h = self._height - 2 * border
        
        # Calculate pixel size to fit within available space (with gaps)
        gap = 1  # Small gap between pixels
        pixel_w = (available_w - gap * (cols - 1)) / cols
        pixel_h = (available_h - gap * (rows - 1)) / rows
        
        # Ensure positive pixel size (for very small fixtures)
        pixel_w = max(2, pixel_w)
        pixel_h = max(2, pixel_h)
        
        # Calculate total grid size and center it within the fixture
        total_grid_w = cols * pixel_w + (cols - 1) * gap
        total_grid_h = rows * pixel_h + (rows - 1) * gap
        
        # Starting position to center the grid
        start_x = -total_grid_w / 2
        start_y = -total_grid_h / 2
        
        for row in range(rows):
            for col in range(cols):
                pixel_num = row * cols + col + 1  # 1-indexed
                
                # Calculate position within the fixture rect (centered)
                x = start_x + col * (pixel_w + gap)
                y = start_y + row * (pixel_h + gap)
                
                pixel_item = QGraphicsRectItem(x, y, pixel_w, pixel_h, self)
                pixel_item.setBrush(QBrush(QColor(30, 30, 35)))  # Dark when off
                pixel_item.setPen(QPen(QColor(50, 50, 55), 1))
                pixel_item.setData(0, pixel_num)  # Store pixel number
                pixel_item.setZValue(0)  # Same level as fixture body
                self._pixel_items.append(pixel_item)
    
    def _create_resize_handles(self):
        """Create resize handles at corners and edges."""
        # Clear existing handles
        for handle in self._resize_handles:
            if handle.scene():
                handle.scene().removeItem(handle)
        self._resize_handles = []
        
        # Only create corner handle for now (bottom-right)
        handle_size = self.HANDLE_SIZE
        handle = QGraphicsRectItem(
            self._width/2 - handle_size,
            self._height/2 - handle_size,
            handle_size, handle_size, self
        )
        handle.setBrush(QBrush(QColor(201, 122, 80)))
        handle.setPen(QPen(QColor(255, 150, 100), 1))
        handle.setCursor(Qt.CursorShape.SizeFDiagCursor)
        handle.setData(0, 'corner')  # Store handle type
        handle.setVisible(False)  # Hidden until selected
        self._resize_handles.append(handle)
    
    def _update_label_position(self):
        """Update label position below the fixture."""
        label_rect = self.label.boundingRect()
        self.label.setPos(-label_rect.width() / 2, self._height / 2 + 2)
    
    def _update_badge_position(self):
        """Update badge position above the fixture."""
        badge_rect = self.badge.boundingRect()
        self.badge.setPos(-badge_rect.width() / 2, -self._height / 2 - badge_rect.height())
    
    def _update_appearance(self, selected: bool):
        """Update the item's visual appearance."""
        if selected:
            self.setPen(QPen(QColor(201, 122, 80), 2))  # Orange selection
            # Show resize handles
            for handle in self._resize_handles:
                handle.setVisible(True)
        else:
            self.setPen(QPen(QColor(80, 80, 90), 1))
            # Hide resize handles
            for handle in self._resize_handles:
                handle.setVisible(False)
        
        # Background color for the fixture outline
        self.setBrush(QBrush(QColor(25, 25, 30, 100)))  # Semi-transparent dark
    
    def set_label_visible(self, visible: bool):
        """Show or hide the fixture name label and badge.
        
        When hidden, the fixture name is still available via tooltip on hover.
        """
        self.label.setVisible(visible)
        self.badge.setVisible(visible)
    
    def update_live_color(self, r: int, g: int, b: int, intensity: int):
        """Update the fixture's appearance based on live DMX output.
        
        For pixel-mapped fixtures, this updates all pixels uniformly.
        Call update_pixel_color() for per-pixel updates.
        """
        # Scale by intensity
        scale = intensity / 255.0 if intensity > 0 else 0
        effective_r = int(r * scale)
        effective_g = int(g * scale)
        effective_b = int(b * scale)
        
        brightness = max(effective_r, effective_g, effective_b)
        
        if brightness < 1:
            # All pixels off
            for item in self._pixel_items:
                item.setBrush(QBrush(QColor(30, 30, 35)))
                item.setPen(QPen(QColor(50, 50, 55), 1))
        else:
            # All pixels same color
            color = QColor(effective_r, effective_g, effective_b)
            for item in self._pixel_items:
                item.setBrush(QBrush(color))
                item.setPen(QPen(color.darker(120), 1))
    
    def update_pixel_color(self, pixel_num: int, r: int, g: int, b: int, intensity: int = 255, row: int = None, col: int = None):
        """Update a specific pixel's color.
        
        Args:
            pixel_num: 1-indexed pixel number
            r, g, b: RGB values 0-255
            intensity: Optional intensity multiplier
            row: Row from profile (1-indexed, row 1 = top)
            col: Column from profile (1-indexed, col 1 = left)
        """
        # Find the pixel item by row/col if provided, otherwise by pixel_num
        target_item = None
        
        if row is not None and col is not None:
            # Use row/col to find the correct visual pixel
            profile = self.fixture.profile
            rows = max(1, profile.pixel_rows)
            cols = max(1, profile.pixel_columns)
            
            # Convert profile row/col to visual grid index
            # Profile row 1 = TOP visually, profile row N = BOTTOM visually
            visual_row = row - 1  # Convert 1-indexed to 0-indexed
            visual_col = col - 1
            
            # Calculate visual pixel index: row * cols + col (row-major order)
            visual_idx = visual_row * cols + visual_col
            
            if 0 <= visual_idx < len(self._pixel_items):
                target_item = self._pixel_items[visual_idx]
        else:
            # Fall back to finding by pixel_num (legacy behavior)
            for item in self._pixel_items:
                if item.data(0) == pixel_num:
                    target_item = item
                    break
        
        if target_item:
            scale = intensity / 255.0 if intensity > 0 else 0
            effective_r = int(r * scale)
            effective_g = int(g * scale)
            effective_b = int(b * scale)
            brightness = max(effective_r, effective_g, effective_b)
            
            # Check if we have any color at all (before intensity scaling)
            has_color = max(r, g, b) > 0
            
            # For preview purposes, ALWAYS show the color visibly
            # Calculate a preview-friendly version that's always visible
            if has_color:
                # Always show a visible version of the color
                # Use the raw RGB values scaled for preview visibility
                max_rgb = max(r, g, b)
                if max_rgb > 0 and scale >= 0.08:
                    # Above 8% - show color with full fading
                    # Scale goes from 0.08 to 1.0, map to visible range
                    display_r = int(r * scale)
                    display_g = int(g * scale)
                    display_b = int(b * scale)
                    
                    # Ensure minimum visibility at 8% threshold
                    min_val = 20
                    if r > 25:
                        display_r = max(display_r, min_val)
                    if g > 25:
                        display_g = max(display_g, min_val)
                    if b > 25:
                        display_b = max(display_b, min_val)
                else:
                    # Below 8% brightness - show as off
                    display_r = display_g = display_b = 0
                
                color = QColor(display_r, display_g, display_b)
                target_item.setBrush(QBrush(color))
                target_item.setPen(QPen(color.darker(120), 1))
            elif brightness > 0:
                # No color but has intensity (white/dimmer only)
                gray_val = max(50, int(255 * scale))
                target_item.setBrush(QBrush(QColor(gray_val, gray_val, gray_val)))
                target_item.setPen(QPen(QColor(70, 70, 75), 1))
            else:
                # Completely off - dark background
                target_item.setBrush(QBrush(QColor(30, 30, 35)))
                target_item.setPen(QPen(QColor(50, 50, 55), 1))
        
        # Store the color
        self._pixel_colors[pixel_num] = QColor(r, g, b)
    
    def update_beam_direction(self, pan: int, tilt: int, intensity: int):
        """Pixel fixtures don't have beam direction - stub for compatibility."""
        pass
    
    def _get_resize_edge(self, pos: QPointF) -> Optional[str]:
        """Determine which resize edge/corner the position is near."""
        rect = self.rect()
        margin = self.HANDLE_SIZE
        
        near_right = abs(pos.x() - rect.right()) < margin
        near_bottom = abs(pos.y() - rect.bottom()) < margin
        near_left = abs(pos.x() - rect.left()) < margin
        near_top = abs(pos.y() - rect.top()) < margin
        
        if near_right and near_bottom:
            return 'corner'
        elif near_right:
            return 'right'
        elif near_bottom:
            return 'bottom'
        
        return None
    
    def hoverMoveEvent(self, event):
        """Update cursor based on position for resize feedback."""
        # Show forbidden cursor when locked
        if getattr(self, '_is_locked', False):
            self.setCursor(Qt.CursorShape.ForbiddenCursor)
            super().hoverMoveEvent(event)
            return
            
        if self.isSelected():
            edge = self._get_resize_edge(event.pos())
            if edge == 'corner':
                self.setCursor(Qt.CursorShape.SizeFDiagCursor)
            elif edge == 'right':
                self.setCursor(Qt.CursorShape.SizeHorCursor)
            elif edge == 'bottom':
                self.setCursor(Qt.CursorShape.SizeVerCursor)
            else:
                self.setCursor(Qt.CursorShape.OpenHandCursor)
        else:
            self.setCursor(Qt.CursorShape.OpenHandCursor)
        super().hoverMoveEvent(event)
    
    def hoverEnterEvent(self, event):
        if getattr(self, '_is_locked', False):
            self.setCursor(Qt.CursorShape.ForbiddenCursor)
        else:
            self.setCursor(Qt.CursorShape.OpenHandCursor)
        super().hoverEnterEvent(event)
    
    def mousePressEvent(self, event):
        """Handle mouse press for both move and resize."""
        # Block resize when locked
        if getattr(self, '_is_locked', False):
            super().mousePressEvent(event)
            return
            
        if event.button() == Qt.MouseButton.LeftButton and self.isSelected():
            edge = self._get_resize_edge(event.pos())
            if edge:
                self._resizing = True
                self._resize_edge = edge
                self._resize_start_pos = event.scenePos()
                self._resize_start_rect = QRectF(self.rect())
                event.accept()
                return
        
        # Record peer positions for group drag
        self._group_drag_start = None
        if event.button() == Qt.MouseButton.LeftButton and self.isSelected() and not getattr(self, '_is_locked', False):
            edge = self._get_resize_edge(event.pos()) if self.isSelected() else None
            if not edge:  # Not a resize — set up group drag
                peers = [it for it in self.scene().selectedItems()
                         if isinstance(it, (DraggableFixtureItem, PixelMappedFixtureItem, SquareFixtureItem)) and it is not self]
                if peers:
                    self._group_drag_start = event.scenePos()
                    self._group_peer_origins = {id(it): QPointF(it.pos()) for it in peers}
                    self._group_peers = peers
        self.setCursor(Qt.CursorShape.ClosedHandCursor)
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        """Handle mouse move for resize and group drag."""
        # Group drag: move peers by the same delta
        if getattr(self, '_group_drag_start', None) is not None and not self._resizing:
            delta = event.scenePos() - self._group_drag_start
            for peer in self._group_peers:
                origin = self._group_peer_origins.get(id(peer))
                if origin:
                    new_x = max(0, min(peer.stage_width, origin.x() + delta.x()))
                    new_y = max(0, min(peer.stage_height, origin.y() + delta.y()))
                    peer.setPos(new_x, new_y)
        if self._resizing and self._resize_start_pos:
            delta = event.scenePos() - self._resize_start_pos
            new_rect = QRectF(self._resize_start_rect)
            
            if self._resize_edge in ('corner', 'right'):
                new_width = max(self.MIN_WIDTH, new_rect.width() + delta.x())
                new_rect.setWidth(new_width)
            
            if self._resize_edge in ('corner', 'bottom'):
                new_height = max(self.MIN_HEIGHT, new_rect.height() + delta.y())
                new_rect.setHeight(new_height)
            
            # Center the rect
            new_rect.moveCenter(QPointF(0, 0))
            self.setRect(new_rect)
            self._width = new_rect.width()
            self._height = new_rect.height()
            
            # Update pixel grid and labels
            self._create_pixel_grid()
            self._update_label_position()
            self._update_badge_position()
            self._create_resize_handles()
            for handle in self._resize_handles:
                handle.setVisible(True)
            
            event.accept()
            return
        
        super().mouseMoveEvent(event)
    
    def mouseReleaseEvent(self, event):
        """Handle mouse release - save resize if was resizing."""
        self._group_drag_start = None
        if self._resizing:
            self._resizing = False
            self._resize_edge = None
            self._resize_start_pos = None
            self._resize_start_rect = None
            
            # Save new visual dimensions to fixture
            self.fixture.visual_width = self._width / self.stage_width
            self.fixture.visual_height = self._height / self.stage_height
            
            # Notify GUI of change
            if hasattr(self.gui, '_on_fixture_resized'):
                self.gui._on_fixture_resized(self.fixture.id)
            
            event.accept()
            return
        
        self.setCursor(Qt.CursorShape.OpenHandCursor)
        super().mouseReleaseEvent(event)
    
    def mouseDoubleClickEvent(self, event):
        """Open fixture control dialog on double-click."""
        if event.button() == Qt.MouseButton.LeftButton:
            selected = self._get_selected_fixtures()
            if self.fixture not in selected:
                selected = [self.fixture]
            self.gui._open_fixture_control(selected)
        super().mouseDoubleClickEvent(event)
    
    def itemChange(self, change, value):
        if change == QGraphicsItem.GraphicsItemChange.ItemPositionChange:
            # Constrain to stage bounds
            new_pos = value
            x = max(0, min(self.stage_width, new_pos.x()))
            y = max(0, min(self.stage_height, new_pos.y()))
            return QPointF(x, y)
        elif change == QGraphicsItem.GraphicsItemChange.ItemPositionHasChanged:
            # Update fixture location
            x_norm = self.pos().x() / self.stage_width
            y_norm = self.pos().y() / self.stage_height
            self.gui._on_location_fixture_moved(self.fixture.id, x_norm, y_norm)
        elif change == QGraphicsItem.GraphicsItemChange.ItemSelectedHasChanged:
            selected = bool(value)
            self._update_appearance(selected)
            if getattr(self.gui, '_programmatic_selection', False):
                return super().itemChange(change, value)
            modifiers = QApplication.keyboardModifiers()
            multi = bool(modifiers & Qt.KeyboardModifier.ControlModifier)
            if not multi:
                scene = self.scene()
                if scene and len(scene.selectedItems()) > 1:
                    multi = True
            self.gui._on_location_fixture_selected(self.fixture.id, selected, multi)
        return super().itemChange(change, value)
    
    def contextMenuEvent(self, event):
        """Show context menu on right-click."""
        menu = QMenu()
        menu.setStyleSheet(self.gui._get_touch_menu_stylesheet())
        
        # Edit fixture option
        edit_action = menu.addAction("✏️ Edit Fixture...")
        edit_action.triggered.connect(lambda: self.gui._edit_fixture(self.fixture))
        
        # Control option (same as double-click)
        selected_for_ctrl = self._get_selected_fixtures()
        if self.fixture not in selected_for_ctrl:
            selected_for_ctrl = [self.fixture]
        control_action = menu.addAction("🎛️ Control")
        _ctrl_fixtures = list(selected_for_ctrl)
        control_action.triggered.connect(lambda: self.gui._open_fixture_control(_ctrl_fixtures))

        # Trackpad option — only if fixture has pan or tilt channels
        has_pt = False
        if self.fixture.mode:
            for ch in self.fixture.mode.channels:
                if ch.type.lower() in ('pan', 'tilt'):
                    has_pt = True
                    break
        if has_pt:
            trackpad_action = menu.addAction("🎯 Trackpad")
            trackpad_action.triggered.connect(lambda: self.gui._open_pan_tilt_trackpad(self.fixture))

        # Pixel mapping option
        pixel_action = menu.addAction("🔲 Pixel Mapping...")
        pixel_action.triggered.connect(lambda: self._open_pixel_mapping())
        
        # Make all same size option - count how many of same type
        same_type_count = self._count_same_type_fixtures()
        if same_type_count > 1:
            size_action = menu.addAction(f"📐 Make All Same Size ({same_type_count} fixtures)")
            size_action.setToolTip("Resize all fixtures of this type to match this fixture's size")
            size_action.triggered.connect(lambda: self._make_all_same_size())
        
        menu.addSeparator()
        
        # Get selected fixtures
        selected_fixtures = self._get_selected_fixtures()
        if self.fixture not in selected_fixtures:
            selected_fixtures = [self.fixture]
        
        # Identify options
        any_identified = any(f.id in self.gui._individually_identified for f in selected_fixtures)
        all_identified = all(f.id in self.gui._individually_identified for f in selected_fixtures)
        
        if len(selected_fixtures) > 1:
            if all_identified:
                stop_action = menu.addAction(f"⬛ Stop Identify ({len(selected_fixtures)} fixtures)")
                stop_action.triggered.connect(lambda: self._identify_selected_fixtures(False))
            else:
                identify_action = menu.addAction(f"🔦 Identify {len(selected_fixtures)} Fixtures")
                identify_action.triggered.connect(lambda: self._identify_selected_fixtures(True))
        else:
            is_identified = self.fixture.id in self.gui._individually_identified
            if is_identified:
                stop_action = menu.addAction("⬛ Stop Identify")
                stop_action.triggered.connect(lambda: self._identify_fixture(False))
            else:
                identify_action = menu.addAction("🔦 Identify Fixture")
                identify_action.triggered.connect(lambda: self._identify_fixture(True))
        
        menu.addSeparator()
        
        # Select/deselect
        select_action = menu.addAction("✓ Select")
        select_action.triggered.connect(lambda: self.setSelected(True))
        
        deselect_action = menu.addAction("✗ Deselect All")
        deselect_action.triggered.connect(self._deselect_all)
        
        menu.exec(event.screenPos())
    
    def _open_pixel_mapping(self):
        """Open the pixel mapping dialog for this fixture."""
        artnet = getattr(self.gui, 'artnet', None) if self.gui else None
        dialog = PixelMappingDialog(self.gui, self.fixture, artnet)
        if dialog.exec():
            # Refresh the pixel grid display
            self._create_pixel_grid()
    
    def _get_selected_fixtures(self):
        """Get all selected fixtures in the scene."""
        fixtures = []
        if self.scene():
            for item in self.scene().items():
                if isinstance(item, (DraggableFixtureItem, PixelMappedFixtureItem, SquareFixtureItem)) and item.isSelected():
                    fixtures.append(item.fixture)
        return fixtures
    
    def _identify_selected_fixtures(self, on: bool):
        """Send identify signal to all selected fixtures."""
        selected_fixtures = self._get_selected_fixtures()
        if not selected_fixtures:
            selected_fixtures = [self.fixture]
        
        for fixture in selected_fixtures:
            if on:
                self.gui._individually_identified.add(fixture.id)
            else:
                self.gui._individually_identified.discard(fixture.id)
        
        self.gui._send_locate_to_fixtures(selected_fixtures, on)
    
    def _identify_fixture(self, on: bool):
        """Send identify signal to this specific fixture only."""
        if on:
            self.gui._individually_identified.add(self.fixture.id)
        else:
            self.gui._individually_identified.discard(self.fixture.id)
        self.gui._send_locate_to_fixtures([self.fixture], on)
    
    def _deselect_all(self):
        """Deselect all fixtures in the scene."""
        if self.scene():
            for item in self.scene().items():
                if isinstance(item, (DraggableFixtureItem, PixelMappedFixtureItem, SquareFixtureItem)):
                    item.setSelected(False)
    
    def _count_same_type_fixtures(self):
        """Count fixtures of the same type (profile) in the scene."""
        count = 0
        profile = self.fixture.profile
        if self.scene():
            for item in self.scene().items():
                if isinstance(item, PixelMappedFixtureItem):
                    if (item.fixture.profile.manufacturer == profile.manufacturer and 
                        item.fixture.profile.name == profile.name):
                        count += 1
        return count
    
    def _make_all_same_size(self):
        """Resize all fixtures of the same type to match this fixture's size."""
        profile = self.fixture.profile
        target_width = self.fixture.visual_width
        target_height = self.fixture.visual_height
        
        if not self.scene():
            return
        
        resized_count = 0
        for item in self.scene().items():
            if isinstance(item, PixelMappedFixtureItem):
                if (item.fixture.profile.manufacturer == profile.manufacturer and 
                    item.fixture.profile.name == profile.name and
                    item.fixture.id != self.fixture.id):
                    # Update fixture dimensions
                    item.fixture.visual_width = target_width
                    item.fixture.visual_height = target_height
                    
                    # Update the graphics item's actual size
                    new_width = max(self.MIN_WIDTH, target_width * item.stage_width)
                    new_height = max(self.MIN_HEIGHT, target_height * item.stage_height)
                    item._width = new_width
                    item._height = new_height
                    item.setRect(-new_width/2, -new_height/2, new_width, new_height)
                    
                    # Rebuild pixel grid and update positions
                    item._create_pixel_grid()
                    item._update_label_position()
                    item._update_badge_position()
                    item._create_resize_handles()
                    item.update()
                    
                    resized_count += 1
        
        # Mark project as dirty
        if resized_count > 0 and hasattr(self.gui, '_mark_dirty'):
            self.gui._mark_dirty()
            print(f"[PixelMappedFixture] Resized {resized_count} fixtures to {target_width:.3f} x {target_height:.3f}")


def get_network_interfaces() -> list[tuple[str, str, str]]:
    """
    Get list of network interfaces with their IPs and broadcast addresses.
    Returns list of (interface_name, ip_address, broadcast_address) tuples.
    """
    interfaces = []
    
    try:
        import psutil
        for iface_name, addrs in psutil.net_if_addrs().items():
            # Skip Bluetooth and virtual adapters
            if 'bluetooth' in iface_name.lower():
                continue
            
            for addr in addrs:
                if addr.family == socket.AF_INET:  # IPv4 only
                    ip = addr.address
                    # Skip localhost
                    if ip.startswith('127.'):
                        continue
                    
                    # Calculate broadcast address
                    if addr.netmask:
                        ip_parts = [int(x) for x in ip.split('.')]
                        mask_parts = [int(x) for x in addr.netmask.split('.')]
                        broadcast_parts = [ip_parts[i] | (255 - mask_parts[i]) for i in range(4)]
                        broadcast = '.'.join(str(x) for x in broadcast_parts)
                    else:
                        broadcast = ip.rsplit('.', 1)[0] + '.255'
                    
                    interfaces.append((iface_name, ip, broadcast))
    except ImportError:
        # psutil not available, try basic socket method
        try:
            hostname = socket.gethostname()
            ip = socket.gethostbyname(hostname)
            if not ip.startswith('127.'):
                broadcast = ip.rsplit('.', 1)[0] + '.255'
                interfaces.append(('Default', ip, broadcast))
        except:
            pass
    except Exception as e:
        print(f"Error getting network interfaces: {e}")
    
    return interfaces


