class NoWheelComboBox(QComboBox):
    """ComboBox that ignores wheel events to prevent accidental changes while scrolling."""
    
    def wheelEvent(self, event):
        # Ignore wheel events - let parent handle scrolling
        event.ignore()


class NoWheelSlider(QSlider):
    """Slider that ignores wheel events to prevent accidental changes while scrolling."""
    
    def wheelEvent(self, event):
        # Ignore wheel events - let parent handle scrolling
        event.ignore()


class NoWheelSpinBox(QSpinBox):
    """SpinBox that ignores wheel events to prevent accidental changes while scrolling."""
    
    def wheelEvent(self, event):
        # Ignore wheel events - let parent handle scrolling
        event.ignore()


class _WheelGuard(QObject):
    """App-level event filter that prevents scroll-wheel from changing
    unfocused sliders, spin-boxes, and combo-boxes.  The ignored event
    propagates up to the nearest scroll area so the window scrolls instead."""
    _GUARDED = (QSlider, QSpinBox, QDoubleSpinBox, QComboBox)

    def eventFilter(self, obj, event):
        if event.type() == QEvent.Type.Wheel and isinstance(obj, self._GUARDED):
            if not obj.hasFocus():
                event.ignore()
                return True            # consumed — parent will scroll
        return False


class FocusTrackingSlider(QSlider):
    """Slider that emits signals when it gains/loses focus, for tracking active slider."""
    focusGained = pyqtSignal(int)  # Emits row index
    focusLost = pyqtSignal(int)    # Emits row index
    
    def __init__(self, orientation, row_index: int, parent=None):
        super().__init__(orientation, parent)
        self.row_index = row_index
    
    def focusInEvent(self, event):
        super().focusInEvent(event)
        self.focusGained.emit(self.row_index)
    
    def focusOutEvent(self, event):
        super().focusOutEvent(event)
        self.focusLost.emit(self.row_index)


class JumpSlider(QSlider):
    """Slider that jumps directly to clicked position instead of paging.
    
    Standard QSlider behavior: clicking on the track moves by page step.
    This slider: clicking anywhere moves the handle directly to that position,
    keeping the finger/mouse as the center of the handle.
    
    Properly accounts for groove margins and handle size using Qt's style system.
    """
    
    def __init__(self, orientation=Qt.Orientation.Vertical, parent=None):
        super().__init__(orientation, parent)
    
    def _value_from_position(self, pos_x: float, pos_y: float) -> int:
        """Calculate slider value from a position, accounting for groove/handle geometry."""
        opt = QStyleOptionSlider()
        self.initStyleOption(opt)
        
        # Get the groove rectangle (the actual clickable track area)
        style = self.style()
        groove_rect = style.subControlRect(
            QStyle.ComplexControl.CC_Slider, opt, 
            QStyle.SubControl.SC_SliderGroove, self
        )
        
        # Get handle rectangle to know its size
        handle_rect = style.subControlRect(
            QStyle.ComplexControl.CC_Slider, opt,
            QStyle.SubControl.SC_SliderHandle, self
        )
        
        if self.orientation() == Qt.Orientation.Vertical:
            # For vertical: calculate based on Y position within groove
            # Account for half the handle height at each end
            handle_half = handle_rect.height() / 2
            slider_min = groove_rect.top() + handle_half
            slider_max = groove_rect.bottom() - handle_half
            slider_length = slider_max - slider_min
            
            if slider_length <= 0:
                slider_length = groove_rect.height()
                slider_min = groove_rect.top()
            
            # Invert for vertical (top = max, bottom = min)
            pos_in_groove = pos_y - slider_min
            ratio = 1.0 - (pos_in_groove / slider_length) if slider_length > 0 else 0.5
        else:
            # For horizontal: calculate based on X position within groove
            handle_half = handle_rect.width() / 2
            slider_min = groove_rect.left() + handle_half
            slider_max = groove_rect.right() - handle_half
            slider_length = slider_max - slider_min
            
            if slider_length <= 0:
                slider_length = groove_rect.width()
                slider_min = groove_rect.left()
            
            pos_in_groove = pos_x - slider_min
            ratio = pos_in_groove / slider_length if slider_length > 0 else 0.5
        
        # Clamp and convert to value
        ratio = max(0.0, min(1.0, ratio))
        return int(self.minimum() + ratio * (self.maximum() - self.minimum()))
    
    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            new_value = self._value_from_position(event.position().x(), event.position().y())
            self.setValue(new_value)
            event.accept()
        else:
            super().mousePressEvent(event)
    
    def mouseMoveEvent(self, event):
        # Continue tracking as user drags
        if event.buttons() & Qt.MouseButton.LeftButton:
            new_value = self._value_from_position(event.position().x(), event.position().y())
            self.setValue(new_value)
            event.accept()
        else:
            super().mouseMoveEvent(event)


class TouchScrollArea(QScrollArea):
    """ScrollArea with touch-friendly drag-to-scroll support (like iPad/mobile).
    
    Dragging vertically anywhere scrolls the view with momentum.
    Sliders only respond to taps, not vertical drags.
    """
    
    def __init__(self, parent=None):
        super().__init__(parent)
        self._dragging = False
        self._drag_start_y = 0
        self._drag_start_scroll = 0
        self._last_y = 0
        self._last_time = 0
        self._velocity = 0.0
        self._mouse_dragging = False
        self._drag_started = False  # True once we've moved past threshold
        self._press_widget = None   # Widget that received the press
        self._press_pos = None      # Local position of press
        self._sending_synthetic = False  # Prevent recursion when sending events
        self._slider_dragging = False  # True when user is dragging a slider handle
        self._momentum_timer = QTimer(self)
        self._momentum_timer.timeout.connect(self._do_momentum)
        
        # Make accept touch
        self.viewport().setAttribute(Qt.WidgetAttribute.WA_AcceptTouchEvents, True)
        self.setAttribute(Qt.WidgetAttribute.WA_AcceptTouchEvents, True)
        
        # Set scroll bar policy
        self.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
    
    def setWidget(self, widget):
        """Override to install event filter on content widget."""
        super().setWidget(widget)
        if widget:
            widget.installEventFilter(self)
            # Also install on all children
            self._install_filter_recursive(widget)
    
    def _install_filter_recursive(self, widget):
        """Install event filter on widget and all descendants."""
        widget.installEventFilter(self)
        for child in widget.findChildren(QWidget):
            child.installEventFilter(self)
    
    def _is_slider(self, widget):
        """Check if widget is a slider-type control."""
        if isinstance(widget, QSlider):
            return True
        class_name = widget.__class__.__name__
        return 'Slider' in class_name
    
    def _is_on_slider_handle(self, slider, local_pos):
        """Check if position is on the slider handle (groove area)."""
        if not isinstance(slider, QSlider):
            return False
        
        # Get slider geometry
        opt = slider.style().styleHint(QStyle.StyleHint.SH_Slider_AbsoluteSetButtons)
        
        # For horizontal slider, check if click is near the handle position
        if slider.orientation() == Qt.Orientation.Horizontal:
            # Calculate handle position
            slider_length = slider.width()
            handle_width = max(20, slider_length // 10)  # Approximate handle width
            slider_range = slider.maximum() - slider.minimum()
            if slider_range == 0:
                return False
            value_pos = (slider.value() - slider.minimum()) / slider_range
            handle_center = int(value_pos * (slider_length - handle_width)) + handle_width // 2
            
            # Check if click is within handle area (with some margin)
            margin = handle_width // 2 + 10
            if abs(local_pos.x() - handle_center) < margin:
                return True
        else:
            # Vertical slider
            slider_length = slider.height()
            handle_height = max(20, slider_length // 10)
            slider_range = slider.maximum() - slider.minimum()
            if slider_range == 0:
                return False
            value_pos = (slider.value() - slider.minimum()) / slider_range
            handle_center = int((1 - value_pos) * (slider_length - handle_height)) + handle_height // 2
            
            margin = handle_height // 2 + 10
            if abs(local_pos.y() - handle_center) < margin:
                return True
        
        return False
    
    def _is_scrollbar(self, widget):
        """Check if widget is a scrollbar."""
        from PyQt6.QtWidgets import QScrollBar
        if isinstance(widget, QScrollBar):
            return True
        # Check if it's our own scrollbar
        if widget == self.verticalScrollBar() or widget == self.horizontalScrollBar():
            return True
        return False
    
    def eventFilter(self, watched, event):
        """Handle mouse events on any child widget for drag scrolling."""
        # Don't filter our own synthetic events
        if self._sending_synthetic:
            return False
        
        # Let scrollbars handle their own events
        if self._is_scrollbar(watched):
            return super().eventFilter(watched, event)
        
        # Let sliders handle ALL their own events - no interference
        if self._is_slider(watched):
            return False  # Don't filter slider events at all
        
        event_type = event.type()
        
        # Handle mouse events
        if event_type == QEvent.Type.MouseButtonPress:
            if event.button() == Qt.MouseButton.LeftButton:
                self._mouse_dragging = True
                self._drag_started = False
                self._press_widget = watched
                self._press_pos = event.position()
                global_pos = event.globalPosition()
                self._drag_start_y = global_pos.y()
                self._drag_start_scroll = self.verticalScrollBar().value()
                self._last_y = global_pos.y()
                self._last_time = time.time() * 1000
                self._velocity = 0.0
                self._momentum_timer.stop()
                return False
                
        elif event_type == QEvent.Type.MouseMove:
            if self._mouse_dragging:
                global_pos = event.globalPosition()
                current_y = global_pos.y()
                delta = self._drag_start_y - current_y
                
                # Check threshold
                if abs(delta) > 8:
                    self._drag_started = True
                
                if self._drag_started:
                    # Calculate velocity
                    current_time = time.time() * 1000
                    dt = (current_time - self._last_time) / 1000.0
                    if dt > 0:
                        self._velocity = (self._last_y - current_y) / dt * 0.016
                    self._last_y = current_y
                    self._last_time = current_time
                    
                    # Scroll
                    self.verticalScrollBar().setValue(int(self._drag_start_scroll + delta))
                    return True  # Consume event when scrolling
                    
        elif event_type == QEvent.Type.MouseButtonRelease:
            if event.button() == Qt.MouseButton.LeftButton:
                was_dragging = self._drag_started
                press_widget = self._press_widget
                press_pos = self._press_pos
                self._mouse_dragging = False
                self._drag_started = False
                self._press_widget = None
                self._press_pos = None
                
                if was_dragging:
                    # Start momentum if velocity is significant
                    if abs(self._velocity) > 1.0:
                        self._momentum_timer.start(16)
                    return True  # Consume release if we were scrolling
                else:
                    # It was a tap, not a drag - send click to slider if that's what was pressed
                    if press_widget and self._is_slider(press_widget) and press_pos:
                        # Simulate a full click on the slider at the original position
                        press_event = QMouseEvent(
                            QEvent.Type.MouseButtonPress,
                            press_pos,
                            event.globalPosition(),
                            Qt.MouseButton.LeftButton,
                            Qt.MouseButton.LeftButton,
                            Qt.KeyboardModifier.NoModifier
                        )
                        release_event = QMouseEvent(
                            QEvent.Type.MouseButtonRelease,
                            press_pos,
                            event.globalPosition(),
                            Qt.MouseButton.LeftButton,
                            Qt.MouseButton.NoButton,
                            Qt.KeyboardModifier.NoModifier
                        )
                        self._sending_synthetic = True
                        try:
                            QApplication.sendEvent(press_widget, press_event)
                            QApplication.sendEvent(press_widget, release_event)
                        finally:
                            self._sending_synthetic = False
                        return True
        
        return super().eventFilter(watched, event)
    
    def event(self, event):
        """Handle touch events for scrolling."""
        if event.type() == QEvent.Type.TouchBegin:
            points = event.points()
            if points:
                self._dragging = True
                self._drag_start_y = points[0].position().y()
                self._drag_start_scroll = self.verticalScrollBar().value()
                self._last_y = self._drag_start_y
                self._last_time = event.timestamp()
                self._velocity = 0.0
                self._momentum_timer.stop()
            event.accept()
            return True
            
        elif event.type() == QEvent.Type.TouchUpdate:
            if self._dragging:
                points = event.points()
                if points:
                    current_y = points[0].position().y()
                    delta = self._drag_start_y - current_y
                    
                    # Calculate velocity
                    current_time = event.timestamp()
                    dt = (current_time - self._last_time) / 1000.0
                    if dt > 0:
                        self._velocity = (self._last_y - current_y) / dt * 0.016
                    self._last_y = current_y
                    self._last_time = current_time
                    
                    # Scroll
                    self.verticalScrollBar().setValue(int(self._drag_start_scroll + delta))
            event.accept()
            return True
            
        elif event.type() == QEvent.Type.TouchEnd:
            if self._dragging:
                self._dragging = False
                # Start momentum if velocity is significant
                if abs(self._velocity) > 1.0:
                    self._momentum_timer.start(16)
            event.accept()
            return True
        
        return super().event(event)
    
    def _do_momentum(self):
        """Apply momentum scrolling."""
        if abs(self._velocity) < 0.5:
            self._momentum_timer.stop()
            return
        
        self._velocity *= 0.92  # Friction
        sb = self.verticalScrollBar()
        new_val = sb.value() + int(self._velocity)
        
        if new_val <= sb.minimum() or new_val >= sb.maximum():
            self._momentum_timer.stop()
        else:
            sb.setValue(new_val)
    
    def wheelEvent(self, event):
        """Handle wheel events normally."""
        super().wheelEvent(event)


class AddFixtureDialog(QDialog):
    """Dialog for adding a new fixture to the patch."""
    
    def __init__(self, parent, project: LightingProject, profiles: list[FixtureProfile], artnet=None):
        super().__init__(parent)
        self.project = project
        self.profiles = profiles
        self.artnet = artnet  # For DMX testing
        self.selected_profile: FixtureProfile | None = None
        self.selected_mode: str = ""
        self.test_sliders: list[tuple[QSlider, QLabel]] = []
        
        self.setWindowTitle("Add Fixture")
        self.setMinimumWidth(500)
        self.setMinimumHeight(450)
        self.resize(650, 650)
        self.setStyleSheet(DARK_STYLESHEET)
        self._setup_ui()
    
    def _setup_ui(self):
        main_layout = QVBoxLayout(self)
        main_layout.setSpacing(8)
        main_layout.setContentsMargins(12, 12, 12, 12)
        
        # Main scroll area for all content
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.Shape.NoFrame)
        scroll_widget = QWidget()
        layout = QVBoxLayout(scroll_widget)
        layout.setSpacing(10)
        layout.setContentsMargins(0, 0, 8, 0)  # Right margin for scrollbar
        
        # Fixture type selection
        type_group = QGroupBox("Fixture Type")
        type_layout = QFormLayout(type_group)
        type_layout.setSpacing(8)
        
        self.profile_combo = QComboBox()
        # Sort profiles: custom first, then built-in, then OFL
        sorted_profiles = sorted(self.profiles, key=lambda p: (
            0 if p.is_custom else (1 if not p.ofl_key else 2),
            p.manufacturer.lower(),
            p.name.lower()
        ))
        for p in sorted_profiles:
            prefix = "★ " if p.is_custom else ("📦 " if p.ofl_key else "")
            self.profile_combo.addItem(f"{prefix}{p.full_name}", p)
        self.profile_combo.currentIndexChanged.connect(self._on_profile_changed)
        type_layout.addRow("Fixture:", self.profile_combo)
        
        self.mode_combo = QComboBox()
        self.mode_combo.currentIndexChanged.connect(self._on_mode_changed)
        type_layout.addRow("Mode:", self.mode_combo)
        
        layout.addWidget(type_group)
        
        # Address settings
        addr_group = QGroupBox("DMX Address")
        addr_layout = QFormLayout(addr_group)
        
        self.universe_spin = QSpinBox()
        # Allow up to 16 universes - project will auto-expand if needed
        self.universe_spin.setRange(1, max(16, self.project.universe_count))
        self.universe_spin.setValue(1)
        self.universe_spin.valueChanged.connect(self._update_next_address)
        addr_layout.addRow("Universe:", self.universe_spin)
        
        self.address_spin = QSpinBox()
        self.address_spin.setRange(1, 512)
        self.address_spin.setValue(1)
        addr_layout.addRow("Start Address:", self.address_spin)
        
        self.channels_label = QLabel("Channels: 0")
        addr_layout.addRow(self.channels_label)
        
        layout.addWidget(addr_group)
        
        # Label
        label_group = QGroupBox("Identification")
        label_layout = QFormLayout(label_group)
        
        self.label_edit = QLineEdit()
        self.label_edit.setPlaceholderText("e.g., Front Left, Wash 1")
        label_layout.addRow("Label:", self.label_edit)
        
        layout.addWidget(label_group)
        
        # Test section
        test_group = QGroupBox("🔦 Channel Test (sends DMX)")
        test_layout = QVBoxLayout(test_group)
        
        # Test address row
        test_addr_layout = QHBoxLayout()
        test_addr_layout.addWidget(QLabel("Test Universe:"))
        self.test_universe_spin = QSpinBox()
        self.test_universe_spin.setRange(1, 16)
        self.test_universe_spin.setValue(1)
        test_addr_layout.addWidget(self.test_universe_spin)
        
        test_addr_layout.addSpacing(20)
        test_addr_layout.addWidget(QLabel("Test Start Address:"))
        self.test_address_spin = QSpinBox()
        self.test_address_spin.setRange(1, 512)
        self.test_address_spin.setValue(1)
        test_addr_layout.addWidget(self.test_address_spin)
        
        test_addr_layout.addSpacing(20)
        self.all_off_btn = QPushButton("All Off")
        self.all_off_btn.clicked.connect(self._test_all_off)
        test_addr_layout.addWidget(self.all_off_btn)
        
        self.all_on_btn = QPushButton("All On")
        self.all_on_btn.clicked.connect(self._test_all_on)
        test_addr_layout.addWidget(self.all_on_btn)
        
        test_addr_layout.addStretch()
        test_layout.addLayout(test_addr_layout)
        
        # Scrollable slider area for test sliders
        test_scroll = TouchScrollArea()
        test_scroll.setWidgetResizable(True)
        test_scroll.setMaximumHeight(180)
        test_scroll.setStyleSheet("QScrollArea { border: none; }")
        
        self.sliders_container = QWidget()
        self.sliders_layout = QVBoxLayout(self.sliders_container)
        self.sliders_layout.setSpacing(4)
        self.sliders_layout.setContentsMargins(0, 0, 0, 0)
        
        test_scroll.setWidget(self.sliders_container)
        test_layout.addWidget(test_scroll)
        
        layout.addWidget(test_group)
        
        # Finish scroll area
        layout.addStretch()
        scroll.setWidget(scroll_widget)
        main_layout.addWidget(scroll)
        
        # Buttons (outside scroll area)
        button_box = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel
        )
        button_box.accepted.connect(self.accept)
        button_box.rejected.connect(self.reject)
        main_layout.addWidget(button_box)
        
        # Initialize
        self._on_profile_changed(0)
        self._update_next_address()
    
    def _on_profile_changed(self, index):
        self.selected_profile = self.profile_combo.currentData()
        self.mode_combo.clear()
        if self.selected_profile:
            for mode in self.selected_profile.modes:
                self.mode_combo.addItem(f"{mode.name} ({mode.channel_count}ch)", mode.name)
            self._update_channel_count()
            self._build_test_sliders()
    
    def _on_mode_changed(self, index):
        self._update_channel_count()
        self._build_test_sliders()
    
    def _build_test_sliders(self):
        """Build test sliders for the current mode's channels."""
        # Clear existing sliders
        while self.sliders_layout.count():
            item = self.sliders_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
        self.test_sliders.clear()
        
        if not self.selected_profile:
            return
        
        mode_name = self.mode_combo.currentData()
        if not mode_name:
            return
        mode = self.selected_profile.get_mode(mode_name)
        if not mode:
            return
        
        # Create slider for each channel
        for i, ch in enumerate(mode.channels):
            row = QWidget()
            row_layout = QHBoxLayout(row)
            row_layout.setContentsMargins(0, 0, 0, 0)
            row_layout.setSpacing(8)
            
            # Channel label
            label = QLabel(f"Ch {i+1}: {ch.name}")
            label.setFixedWidth(150)
            label.setStyleSheet("color: #a0a0a0;")
            row_layout.addWidget(label)
            
            # Type indicator
            type_label = QLabel(f"[{ch.type}]")
            type_label.setFixedWidth(80)
            type_label.setStyleSheet("color: #606060; font-size: 11px;")
            row_layout.addWidget(type_label)
            
            # Slider
            slider = QSlider(Qt.Orientation.Horizontal)
            slider.setRange(0, 255)
            slider.setValue(0)
            slider.setMinimumWidth(150)
            row_layout.addWidget(slider, 1)
            
            # Value label
            value_label = QLabel("0")
            value_label.setFixedWidth(35)
            value_label.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
            row_layout.addWidget(value_label)
            
            # Connect slider
            slider.valueChanged.connect(lambda val, lbl=value_label, ch_idx=i: self._on_test_slider_changed(val, lbl, ch_idx))
            
            self.sliders_layout.addWidget(row)
            self.test_sliders.append((slider, value_label))
        
        self.sliders_layout.addStretch()
    
    def _on_test_slider_changed(self, value: int, label: QLabel, channel_index: int):
        """Handle test slider value change - send DMX."""
        label.setText(str(value))
        
        if self.artnet:
            universe = self.test_universe_spin.value()
            start_addr = self.test_address_spin.value()
            uni = self.artnet.get_universe(universe)
            dmx_addr = start_addr + channel_index
            if 1 <= dmx_addr <= 512:
                uni.set_channel(dmx_addr, value)
    
    def _test_all_off(self):
        """Set all test sliders to 0."""
        for slider, label in self.test_sliders:
            slider.setValue(0)
    
    def _test_all_on(self):
        """Set all test sliders to 255."""
        for slider, label in self.test_sliders:
            slider.setValue(255)
    
    def _update_channel_count(self):
        if self.selected_profile and self.mode_combo.currentData():
            mode = self.selected_profile.get_mode(self.mode_combo.currentData())
            if mode:
                self.channels_label.setText(f"Channels: {mode.channel_count}")
    
    def _update_next_address(self):
        universe = self.universe_spin.value()
        next_addr = self.project.get_next_address(universe)
        if next_addr > 0:
            self.address_spin.setValue(next_addr)
    
    def get_fixture(self) -> PatchedFixture | None:
        if not self.selected_profile:
            return None
        
        mode_name = self.mode_combo.currentData() or self.selected_profile.modes[0].name
        
        return PatchedFixture(
            id=str(uuid.uuid4()),
            profile=self.selected_profile,
            mode_name=mode_name,
            universe=self.universe_spin.value(),
            address=self.address_spin.value(),
            label=self.label_edit.text().strip()
        )


