                # Delete button in column 2
                del_btn = QPushButton("✕")
                del_btn.setFixedSize(40, 25)
                del_btn.clicked.connect(lambda checked, row=i: self._delete_gobo(row))
                self.gobo_table.setCellWidget(i, 2, del_btn)
        
