    def _on_slider_focus_gained(self, row: int):
        """Called when a slider gains focus - turn on dimmer/shutter."""
        self.active_slider_row = row
        # Turn on dimmer and shutter for preview
        if self.fixture and self.artnet:
            self._set_dimmer_on()
    
    def _on_slider_focus_lost(self, row: int):
        """Called when a slider loses focus."""
        if self.active_slider_row == row:
            self.active_slider_row = -1
    
    def _set_dimmer_on(self):
        """Turn on dimmer and shutter for the fixture."""
        if not self.fixture or not self.artnet:
            return
        
        uni = self.artnet.get_universe(self.fixture.universe)
        
        # Access the parent dialog to get channel types
        parent = self.parent()
        if hasattr(parent, 'channel_widgets'):
            # We're in the CreateFixtureDialog
            for i, widget_data in enumerate(parent.channel_widgets):
                ch_type = widget_data[1].currentText().lower()  # type_combo is index 1
                dmx_addr = self.fixture.address + i
                if ch_type in ('dimmer', 'intensity', 'master', 'master dimmer'):
                    uni.set_channel(dmx_addr, 255)
                    print(f"[Gobo Preview] Set dimmer channel {dmx_addr} to 255")
                elif ch_type == 'shutter':
                    uni.set_channel(dmx_addr, 255)
                    print(f"[Gobo Preview] Set shutter channel {dmx_addr} to 255")
                elif ch_type == 'strobe':
                    uni.set_channel(dmx_addr, 0)
                    print(f"[Gobo Preview] Set strobe channel {dmx_addr} to 0 (open)")
        elif hasattr(parent, 'channels_table'):
            # We're in the EditProfileDialog
            for i in range(parent.channels_table.rowCount()):
                type_combo = parent.channels_table.cellWidget(i, 2)
                if type_combo:
                    ch_type = type_combo.currentText().lower()
                    dmx_addr = self.fixture.address + i
                    if ch_type in ('dimmer', 'intensity', 'master', 'master dimmer'):
                        uni.set_channel(dmx_addr, 255)
                        print(f"[Gobo Preview] Set dimmer channel {dmx_addr} to 255")
                    elif ch_type == 'shutter':
                        uni.set_channel(dmx_addr, 255)
                        print(f"[Gobo Preview] Set shutter channel {dmx_addr} to 255")
                    elif ch_type == 'strobe':
                        uni.set_channel(dmx_addr, 0)
                        print(f"[Gobo Preview] Set strobe channel {dmx_addr} to 0 (open)")
    
    def _on_preview_slider_changed(self, value: int, row: int):
        """Send DMX value when preview slider changes."""
        if row != self.active_slider_row:
            return
        
        # Update the DMX Value spinbox
        value_spin = self.gobo_table.cellWidget(row, 1)
        if value_spin:
            value_spin.blockSignals(True)
            value_spin.setValue(value)
            value_spin.blockSignals(False)
            if 0 <= row < len(self.gobos):
                self.gobos[row]['value'] = value
        
        if self.fixture and self.artnet:
            # Keep dimmer on
            self._set_dimmer_on()
            # Send gobo value
            uni = self.artnet.get_universe(self.fixture.universe)
            dmx_addr = self.fixture.address + self.channel_index
            uni.set_channel(dmx_addr, value)
            print(f"[Gobo Preview] Sent value {value} to universe {self.fixture.universe} channel {dmx_addr}")
    
    def _set_gobo_count(self, count: int):
        """Set the number of gobos."""
        self._sync_table_to_data()
        current = len(self.gobos)
        if count > current:
            # Add gobos
            for i in range(current, count):
                self.gobos.append({"name": f"Gobo {i + 1}", "value": i * 20})
        elif count < current:
            # Remove gobos
            self.gobos = self.gobos[:count]
        self._refresh_table()
    
    def _sync_table_to_data(self):
        """Sync current table edits back into self.gobos before refresh."""
        for i in range(min(self.gobo_table.rowCount(), len(self.gobos))):
            name_item = self.gobo_table.item(i, 0)
            value_widget = self.gobo_table.cellWidget(i, 1)
            if name_item:
                self.gobos[i]['name'] = name_item.text()
            if value_widget:
                self.gobos[i]['value'] = value_widget.value()

    def _add_gobo(self):
        """Add a new gobo entry."""
        self._sync_table_to_data()
        idx = len(self.gobos)
        self.gobos.append({"name": f"Gobo {idx + 1}", "value": idx * 20})
        self._refresh_table()
    
    def _delete_gobo(self, row: int):
        """Delete a gobo entry."""
        self._sync_table_to_data()
        if 0 <= row < len(self.gobos):
            self.gobos.pop(row)
            self._refresh_table()
    
    def _clear_all(self):
        """Clear all gobos."""
        self.gobos = []
        self._refresh_table()
    
    def _load_preset(self, preset_gobos: list[dict]):
        """Load a preset gobo configuration."""
        self.gobos = [g.copy() for g in preset_gobos]
        self._refresh_table()
    
    def _save(self):
        """Save the gobo configuration."""
        # Update gobos from table
        for i in range(self.gobo_table.rowCount()):
            name_item = self.gobo_table.item(i, 0)
            value_widget = self.gobo_table.cellWidget(i, 1)
            
            if name_item and value_widget:
                self.gobos[i]['name'] = name_item.text()
                self.gobos[i]['value'] = value_widget.value()
        
        self.accept()
    
    def get_gobos(self) -> list[dict]:
        """Get the configured gobos."""
        return self.gobos

    def _turn_off_dmx(self):
        """Turn off all DMX output for this fixture."""
        if not self.fixture or not self.artnet:
            return
        uni = self.artnet.get_universe(self.fixture.universe)
        # Turn off the gobo channel
        dmx_addr = self.fixture.address + self.channel_index
        uni.set_channel(dmx_addr, 0)
        # Turn off dimmer/shutter channels
        parent = self.parent()
        if hasattr(parent, 'channels_table'):
            for i in range(parent.channels_table.rowCount()):
                type_combo = parent.channels_table.cellWidget(i, 2)
                if type_combo:
                    ch_type = type_combo.currentText().lower()
                    if ch_type in ('dimmer', 'intensity', 'master', 'master dimmer'):
                        uni.set_channel(self.fixture.address + i, 0)
                    elif ch_type in ('shutter', 'strobe'):
                        uni.set_channel(self.fixture.address + i, 0)

    def done(self, result):
        """Override done to turn off DMX when dialog closes."""
        self._turn_off_dmx()
        super().done(result)


