        layout.addWidget(btn_widget)
        
        # Also add a slider for fine control
        slider_widget = self._create_standard_slider(ch_idx, channel)
        layout.addWidget(slider_widget)
        
        widget.slider = slider_widget.slider
        widget.value_label = slider_widget.value_label
        return widget
    
