        fill_layout.addWidget(snake_btn)
        
        snake_v_btn = QPushButton("Snake ↕")
        snake_v_btn.setToolTip("Snake Vertical: columns left-to-right, alternates direction each column")
        snake_v_btn.setMinimumWidth(60)
        snake_v_btn.clicked.connect(lambda: self._auto_fill("snake_vertical"))
        fill_layout.addWidget(snake_v_btn)
        
        cols_down_btn = QPushButton("Col ↓")
        cols_down_btn.setToolTip("Columns Top-to-Bottom: fill column-by-column going down")
        cols_down_btn.setMinimumWidth(60)
        cols_down_btn.clicked.connect(lambda: self._auto_fill("columns_down"))
        fill_layout.addWidget(cols_down_btn)
        
        cols_up_btn = QPushButton("Col ↑")
        cols_up_btn.setToolTip("Columns Bottom-to-Top: fill column-by-column going up")
        cols_up_btn.setMinimumWidth(60)
        cols_up_btn.clicked.connect(lambda: self._auto_fill("columns_up"))
        fill_layout.addWidget(cols_up_btn)
        
        clear_btn = QPushButton("Clear")
