            settings_btn.setStyleSheet("font-size: 10px; padding: 2px 4px; min-height: 20px;")
            settings_btn.clicked.connect(lambda checked, row=i: self._edit_channel_settings(row))
            
            # Store existing color wheel data
            if ch.color_wheel_colors:
                self.color_wheel_data[i] = list(ch.color_wheel_colors)
            
            # Store existing effect values data  
