    # Thread-safe signal for update-check results (emitted from worker thread)
    _update_result_signal = pyqtSignal(dict, bool)
    
    def __init__(self):
        super().__init__()
        self.setWindowTitle("Lighting Designer")
        self.setMinimumSize(800, 500)
        self.setStyleSheet(DARK_STYLESHEET)

        # Connect thread-safe timecode display signal
