    def _setup_shortcuts(self):
        """Setup keyboard shortcuts."""
        # Ctrl+D: Duplicate selected fixture
        QShortcut(QKeySequence("Ctrl+D"), self, self._duplicate_fixture)
        # Ctrl+Shift+D: Duplicate with auto-increment address
        QShortcut(QKeySequence("Ctrl+Shift+D"), self, self._duplicate_fixture_increment)
        # Delete: Remove selected fixture
        QShortcut(QKeySequence("Delete"), self, self._delete_selected_fixtures)
        # Ctrl+N: New fixture
        QShortcut(QKeySequence("Ctrl+N"), self, self._add_fixture)
        # Ctrl+E: Edit selected fixture
        QShortcut(QKeySequence("Ctrl+E"), self, self._edit_selected_fixture)
        # Escape: Blackout
        QShortcut(QKeySequence("Escape"), self, self._blackout)
    
