    def _create_fixtures_tab(self) -> QWidget:
        """Create the Fixtures tab with fixture type brightness cap faders."""
        widget = QWidget()
        layout = QVBoxLayout(widget)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(10)
        
        # Header with page controls
        header_layout = QHBoxLayout()
        
        header_label = QLabel("Fixture Type Brightness")
        header_label.setStyleSheet("font-size: 20px; font-weight: bold; color: #c97a50;")
        header_layout.addWidget(header_label)
        
        header_layout.addSpacing(20)
        
        # Page selector (shown when more than 7 fixture types - leaving room for master)
        page_label = QLabel("Page:")
        page_label.setStyleSheet("font-size: 14px; font-weight: bold;")
        header_layout.addWidget(page_label)
        
        self.fixture_type_faders_page_combo = QComboBox()
        self.fixture_type_faders_page_combo.setMinimumWidth(150)
        self.fixture_type_faders_page_combo.setStyleSheet("""
            QComboBox {
                font-size: 13px;
                padding: 8px;
                border-radius: 6px;
                background-color: #3d3d3d;
                color: white;
            }
        """)
        self.fixture_type_faders_page_combo.currentIndexChanged.connect(self._on_fixture_type_faders_page_changed)
        header_layout.addWidget(self.fixture_type_faders_page_combo)
        
        header_layout.addStretch()
        
        # Reset all button
        reset_btn = QPushButton("🔄 Reset All to 100%")
        reset_btn.setMaximumWidth(160)
        reset_btn.setStyleSheet("""
            QPushButton {
                font-size: 12px;
                padding: 8px 12px;
                border-radius: 6px;
                background-color: #3d4d5a;
                color: white;
                font-weight: bold;
            }
            QPushButton:hover {
                background-color: #4d5d6a;
            }
        """)
        reset_btn.clicked.connect(self._reset_all_fixture_type_faders)
        header_layout.addWidget(reset_btn)
        
        layout.addLayout(header_layout, 0)
        
        # Description
        desc_label = QLabel("Set maximum brightness caps for each fixture type. Fixtures can NEVER exceed their cap, regardless of effects or master level. Use to balance brightness across different fixture types.")
        desc_label.setStyleSheet("color: #808080; font-size: 12px;")
        desc_label.setWordWrap(True)
        layout.addWidget(desc_label)
        
