    def _on_fixture_type_fader_changed(self, profile_name: str, value: int):
        """Handle fixture type fader value change."""
        # Prevent feedback loops during sync
        if getattr(self, '_syncing_fixture_type_fader', False):
            return
            
        try:
            cap = value / 100.0
            
            # Update effect engine
            if hasattr(self, 'effect_engine') and self.effect_engine:
                self.effect_engine.set_fixture_type_cap(profile_name, cap)
            
            # Sync to all other slider instances for this fixture type
            self._sync_fixture_type_fader_value(profile_name, value)
            
            # Re-trigger active group faders so stored DMX recomputes with new cap.
            # Without this the pre-computed override values are stale and the
            # master dimmer has no visible effect on group-fader-controlled fixtures.
            self._refresh_active_group_faders()

            # Send MIDI feedback if mapped
            self._send_fixture_type_fader_feedback(profile_name, value)
        except Exception as e:
            print(f"[FixtureTypeFader] ERROR: {e}")
    
    def _sync_fixture_type_fader_value(self, profile_name: str, value: int):
        """Sync fixture type fader value across all window instances."""
        if profile_name not in self._all_fixture_type_fader_sliders:
            return
        
        self._syncing_fixture_type_fader = True
        try:
            valid_sliders = []
            for slider in self._all_fixture_type_fader_sliders[profile_name]:
                try:
                    if slider.value() != value:
                        slider.blockSignals(True)
                        slider.setValue(value)
                        slider.blockSignals(False)
                    # Update value label if it exists
                    if hasattr(slider, '_value_label'):
                        slider._value_label.setText(f"{value}%")
                    valid_sliders.append(slider)
                except RuntimeError:
                    pass  # Slider was deleted
            
            # Update tracking with only valid sliders
            if valid_sliders:
                self._all_fixture_type_fader_sliders[profile_name] = valid_sliders
            else:
                del self._all_fixture_type_fader_sliders[profile_name]
        finally:
            self._syncing_fixture_type_fader = False
    
    def _send_fixture_type_fader_feedback(self, profile_name: str, value: int):
        """Send MIDI feedback for fixture type fader."""
        midi_mgr = get_midi_manager()
        fader_id = f"fixture_type_{profile_name}"
        
        fader_mappings = self.app_settings.get('midi_fader_mappings', {})
        midi_keys = fader_mappings.get(fader_id)
        
        if midi_keys:
            midi_value = int((value / 100.0) * 127)
            midi_value = max(0, min(127, midi_value))
            
            # Support both single key (string) and multiple keys (list)
            if isinstance(midi_keys, str):
                midi_keys = [midi_keys]
            
            for midi_key in midi_keys:
                midi_mgr.send_fader_feedback(midi_key, midi_value)

    def _send_fixture_type_page_midi_feedback(self):
        """Send MIDI feedback for all fixture-type faders visible on the current page.

        Called after a page change so that per-profile MIDI mappings (non-dynamic)
        update the motorized faders to match the new page's slider positions.
        """
        if not hasattr(self, 'fixture_type_fader_widgets'):
            return
        for profile_name, slider in self.fixture_type_fader_widgets.items():
            try:
                self._send_fixture_type_fader_feedback(profile_name, slider.value())
            except RuntimeError:
                pass  # Slider may have been deleted

    def _on_fixture_type_faders_page_changed(self, index: int):
        """Handle fixture type faders page change."""
        # Check if the signal came from a detached window's combo box
        sender = self.sender() if hasattr(self, 'sender') else None
        if sender and hasattr(self, '_detached_fixture_type_fader_data'):
            for data in self._detached_fixture_type_fader_data:
                if data.get('page_combo') is sender:
                    # Update the detached window's page and repopulate it
                    data['page'] = index
                    self._populate_fixture_type_faders_for_layout(data)
                    # Refresh dynamic MIDI slider references for the detached window
                    detached_win = self._detached_windows.get("MASTER DIMMERS")
                    if detached_win:
                        self._on_dynamic_window_activated(detached_win)
                    # Send per-profile MIDI feedback for new page faders
                    self._send_fixture_type_page_midi_feedback()
                    return
        # Default: update the main window
        self._fixture_type_faders_page = index
        self._populate_fixture_type_faders()
        # Refresh dynamic MIDI slider references so motorized faders sync
        self._update_dynamic_sliders_for_main_tab("MASTER DIMMERS")
        # Send per-profile MIDI feedback for new page faders
        self._send_fixture_type_page_midi_feedback()

    def _populate_fixture_type_faders_for_layout(self, data: dict):
        """Populate fixture type faders for a detached window by temporarily swapping attributes."""
        saved = {
            'fixture_type_faders_layout': self.fixture_type_faders_layout,
            'fixture_type_fader_widgets': self.fixture_type_fader_widgets,
            'fixture_type_faders_page_combo': self.fixture_type_faders_page_combo,
            '_fixture_type_faders_page': self._fixture_type_faders_page,
            '_fixture_type_faders_per_page': self._fixture_type_faders_per_page,
        }
        try:
            self.fixture_type_faders_layout = data['layout']
            self.fixture_type_fader_widgets = data['widgets']
            self.fixture_type_faders_page_combo = data['page_combo']
            self._fixture_type_faders_page = data['page']
            self._fixture_type_faders_per_page = data['per_page']
            self._populate_fixture_type_faders()
            data['page'] = self._fixture_type_faders_page
            data['widgets'] = self.fixture_type_fader_widgets
        finally:
            for attr, value in saved.items():
                setattr(self, attr, value)
    
    def _reset_all_fixture_type_faders(self):
        """Reset all fixture type faders to 100%."""
        if hasattr(self, 'effect_engine') and self.effect_engine:
            self.effect_engine.clear_fixture_type_caps()
        
        # Update all slider widgets across all windows
        for profile_name, sliders in list(self._all_fixture_type_fader_sliders.items()):
            valid_sliders = []
            for slider in sliders:
                try:
                    slider.blockSignals(True)
                    slider.setValue(100)
                    slider.blockSignals(False)
                    if hasattr(slider, '_value_label'):
                        slider._value_label.setText("100%")
                    valid_sliders.append(slider)
                except RuntimeError:
                    pass  # Slider was deleted
            if valid_sliders:
                self._all_fixture_type_fader_sliders[profile_name] = valid_sliders
            else:
                del self._all_fixture_type_fader_sliders[profile_name]
    
    def _show_fixture_type_fader_context_menu(self, pos, profile_name: str, slider: QSlider):
        """Show context menu for fixture type fader MIDI learning."""
        midi_mgr = get_midi_manager()
        fader_id = f"fixture_type_{profile_name}"
        
        menu = QMenu(self)
        menu.setStyleSheet("""
            QMenu {
                background-color: #2d2d2d;
                border: 1px solid #444;
                border-radius: 4px;
                padding: 4px;
            }
            QMenu::item {
                padding: 8px 16px;
                color: white;
            }
            QMenu::item:selected {
                background-color: #3d3d3d;
            }
        """)
        
        # Check if already mapped
        fader_mappings = self.app_settings.get('midi_fader_mappings', {})
        existing_mapping = fader_mappings.get(fader_id)

        if existing_mapping:
            # Show current mapping(s)
            mappings = [existing_mapping] if isinstance(existing_mapping, str) else existing_mapping
            for midi_key in mappings:
                display = MIDIManager.format_midi_key(midi_key)
                mapped_action = menu.addAction(f"✓ MIDI: {display}")
                mapped_action.setEnabled(False)
            menu.addSeparator()
            add_action = menu.addAction("➕ Add Another MIDI...")
            add_action.triggered.connect(lambda: self._start_fixture_type_fader_midi_learn(profile_name, slider))
            clear_action = menu.addAction("❌ Clear MIDI Mapping")
            clear_action.triggered.connect(lambda: self._clear_fixture_type_fader_midi_mapping(profile_name, slider))
        else:
            learn_action = menu.addAction("🎹 Learn MIDI Fader...")
            learn_action.triggered.connect(lambda: self._start_fixture_type_fader_midi_learn(profile_name, slider))

        menu.exec(slider.mapToGlobal(pos))
    
    def _start_fixture_type_fader_midi_learn(self, profile_name: str, slider: QSlider):
        """Start MIDI learn for a fixture type fader."""
        midi_mgr = get_midi_manager()
        fader_id = f"fixture_type_{profile_name}"
        
        # Create learning dialog - parent to slider's window for correct monitor
        parent_window = slider.window() if slider else self
        dialog = QDialog(parent_window)
        dialog.setWindowTitle(f"MIDI Learn: {profile_name}")
        dialog.setFixedSize(300, 150)
        dialog.setStyleSheet("""
            QDialog {
                background-color: #2d2d2d;
            }
            QLabel {
                color: white;
                font-size: 14px;
            }
        """)
        
        layout = QVBoxLayout(dialog)
        label = QLabel(f"Move a fader on your MIDI controller\\nto assign it to '{profile_name}'")
        label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        layout.addWidget(label)
        
        cancel_btn = QPushButton("Cancel")
        cancel_btn.clicked.connect(dialog.reject)
        layout.addWidget(cancel_btn)
        
        # Start learning
        def on_midi_learned(midi_key: str):
            # Save mapping
            fader_mappings = self.app_settings.get('midi_fader_mappings', {})
            fader_mappings[fader_id] = midi_key
            self.app_settings['midi_fader_mappings'] = fader_mappings
            
            # Record which device made this mapping
            device_name = midi_mgr.get_last_received_device()
            print(f"[DEBUG MIDI LEARN] midi_key={midi_key}, device_name={device_name}")
            print(f"[DEBUG MIDI LEARN] _last_received_device={midi_mgr._last_received_device}")
            midi_mgr.set_mapping_device(midi_key, device_name)
            self.app_settings['midi_mapping_devices'] = midi_mgr.get_mapping_devices_dict()
            print(f"[DEBUG MIDI LEARN] Saved mapping_devices: {self.app_settings['midi_mapping_devices']}")
            
            self._save_app_settings()
            
            # Update MIDI label on all slider instances
            self._refresh_fader_midi_label(fader_id, has_mapping=True)
            
            # Register callback (use fader_id, not midi_key — _handle_pb/cc looks up by fader_id)
            midi_mgr.register_fader_callback(fader_id, lambda val, max_val=127, pn=profile_name: self._on_fixture_type_midi_fader(pn, val, max_val))
            
            # Also update _fader_mappings so the static handler can route this key
            midi_mgr._fader_mappings[midi_key] = fader_id
            
            dialog.accept()
        
        midi_mgr.start_fader_learn(on_midi_learned)
        
        result = dialog.exec()
        if result == QDialog.DialogCode.Rejected:
            midi_mgr.stop_fader_learn()
    
    def _clear_fixture_type_fader_midi_mapping(self, profile_name: str, slider: QSlider):
        """Clear MIDI mapping for a fixture type fader."""
        fader_id = f"fixture_type_{profile_name}"
        fader_mappings = self.app_settings.get('midi_fader_mappings', {})
        
        if fader_id in fader_mappings:
            midi_key = fader_mappings.pop(fader_id)
            self.app_settings['midi_fader_mappings'] = fader_mappings
            self._save_app_settings()
            
            # Unregister callback
            midi_mgr = get_midi_manager()
            midi_mgr.unregister_fader_callback(midi_key)
            
            # Update MIDI label on all slider instances
            self._refresh_fader_midi_label(fader_id, has_mapping=False)
    
    def _on_fixture_type_midi_fader(self, profile_name: str, midi_value: int, max_val: int = 127):
        """Handle MIDI fader input for fixture type."""
        # Convert MIDI value to 0-100 using max_val for correct scaling
        if max_val > 0:
            scaled_value = int((midi_value / max_val) * 100)
        else:
            scaled_value = int((midi_value / 127.0) * 100)
        
        # Sync all slider instances for this fixture type
        self._sync_fixture_type_fader_value(profile_name, scaled_value)
        
        # Update effect engine
        if hasattr(self, 'effect_engine') and self.effect_engine:
            self.effect_engine.set_fixture_type_cap(profile_name, scaled_value / 100.0)
    
    def _on_fixtures_tab_master_changed(self, value: int):
        """Handle master fader change from fixtures tab."""
        # Sync with main master slider - this will trigger _on_master_changed which applies the level
        if hasattr(self, 'master_slider'):
            self.master_slider.setValue(value)  # This will call _on_master_changed
    
