    def _create_group_faders_content(self) -> QWidget:
        """Create the Group Faders content with faders for each group."""
        widget = QWidget()
        layout = QVBoxLayout(widget)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(10)
        
        # Header with page controls
        header_layout = QHBoxLayout()
        
        header_label = QLabel("Group Faders")
        header_label.setStyleSheet("font-size: 20px; font-weight: bold; color: #c97a50;")
        header_layout.addWidget(header_label)
        
        header_layout.addSpacing(20)
        
        # Page selector (shown when more than 8 groups)
        page_label = QLabel("Page:")
        page_label.setStyleSheet("font-size: 14px; font-weight: bold;")
        header_layout.addWidget(page_label)
        
        self.group_faders_page_combo = QComboBox()
        self.group_faders_page_combo.setMinimumWidth(150)
        self.group_faders_page_combo.setStyleSheet("""
            QComboBox {
                font-size: 13px;
                padding: 8px;
                border-radius: 6px;
                background-color: #3d3d3d;
                color: white;
            }
        """)
        self.group_faders_page_combo.currentIndexChanged.connect(self._on_group_faders_page_changed)
        header_layout.addWidget(self.group_faders_page_combo)
        
        header_layout.addStretch()
        
        # Reset all button - resets all group faders to OFF
        reset_btn = QPushButton("🔄 All OFF")
        reset_btn.setMaximumWidth(120)
        reset_btn.setStyleSheet("""
            QPushButton {
                font-size: 12px;
                padding: 8px 12px;
                border-radius: 6px;
                background-color: #5a3d3d;
                color: white;
                font-weight: bold;
            }
            QPushButton:hover {
                background-color: #6a4d4d;
            }
        """)
        reset_btn.clicked.connect(self._reset_all_group_faders)
        header_layout.addWidget(reset_btn)
        
        layout.addLayout(header_layout, 0)
        
        # Description
        desc_label = QLabel("Direct control faders for fixture groups. Raise fader to turn on fixtures with the selected color. Overrides effects when active.")
        desc_label.setStyleSheet("color: #808080; font-size: 12px;")
        desc_label.setWordWrap(True)
        layout.addWidget(desc_label)
        
        # Faders container
        faders_container = QWidget()
        self.group_faders_layout = QHBoxLayout(faders_container)
        self.group_faders_layout.setSpacing(5)
        self.group_faders_layout.setContentsMargins(0, 0, 0, 10)
        
        layout.addWidget(faders_container, 1)
        
        # Store fader widgets
        self.group_fader_widgets = {}  # group_id -> slider widget
        self._group_faders_page = 0
        self._group_faders_per_page = 8
        
        # Initialize
        self._populate_group_faders()
        
        return widget
    
    def _populate_group_faders(self):
        """Populate the group faders layout based on current page."""
        # Clear existing faders
        while self.group_faders_layout.count():
            item = self.group_faders_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
        
        self.group_fader_widgets.clear()
        
        # Get all groups
        groups = list(self.project.groups) if self.project else []
        
        # Update page combo
        total_pages = max(1, (len(groups) + self._group_faders_per_page - 1) // self._group_faders_per_page)
        
        self.group_faders_page_combo.blockSignals(True)
        self.group_faders_page_combo.clear()
        for i in range(total_pages):
            self.group_faders_page_combo.addItem(f"Page {i + 1}")
        if self._group_faders_page >= total_pages:
            self._group_faders_page = 0
        self.group_faders_page_combo.setCurrentIndex(self._group_faders_page)
        self.group_faders_page_combo.blockSignals(False)
        
        # Show/hide page controls based on number of groups
        self.group_faders_page_combo.setVisible(len(groups) > self._group_faders_per_page)
        
        if not groups:
            # Show "no groups" message
            no_groups_label = QLabel("No groups defined.\nCreate groups in the Group Editor tab.")
            no_groups_label.setStyleSheet("color: #666; font-size: 14px;")
            no_groups_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
            self.group_faders_layout.addWidget(no_groups_label)
            return
        
        # Calculate which groups to show on this page
        start_idx = self._group_faders_page * self._group_faders_per_page
        end_idx = min(start_idx + self._group_faders_per_page, len(groups))
        page_groups = groups[start_idx:end_idx]
        
        accent_color = "#50a0c9"  # Different color for group faders (blue-ish)
        
        # Get stored group fader colors (defaults to white)
        group_fader_colors = self.app_settings.get('group_fader_colors', {})
        
        for group in page_groups:
            # Get current intensity from effect engine - DEFAULT TO 0 (OFF)
            current_intensity = 0
            if hasattr(self, 'effect_engine') and self.effect_engine:
                if group.id in self.effect_engine._group_intensities:
                    # Use existing value if already set
                    current_intensity = int(self.effect_engine.get_group_intensity(group.id) * 100)
            
            # Get fader color for this group (default white)
            fader_color = group_fader_colors.get(group.id, "#FFFFFF")
            
            # Container for each fader
            fader_container = QWidget()
            fader_container.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
            fader_v_layout = QVBoxLayout(fader_container)
            fader_v_layout.setContentsMargins(3, 3, 3, 3)
            fader_v_layout.setSpacing(3)
            
            # Group name label at top - allow word wrap for two-row display
            name_label = ScalingLabel(group.name, min_font_size=9, max_font_size=14)
            name_label.setWordWrap(True)
            name_label.setBaseStyle(f"""
                QLabel {{
                    font-weight: bold;
                    padding: 4px;
                    border-radius: 3px;
                    background-color: {group.color};
                    color: white;
                    border: 1px solid #444;
                }}
            """)
            name_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
            name_label.setFixedHeight(50)  # Fixed height for consistent fader alignment
            fader_v_layout.addWidget(name_label)
            
            # Fixture count label
            count_label = QLabel(f"{len(group.fixture_ids)} fixtures")
            count_label.setStyleSheet("""
                QLabel {
                    color: #888;
                    font-size: 10px;
                    text-align: center;
                    background-color: #1a1a1a;
                    border-radius: 3px;
                    padding: 2px;
                }
            """)
            count_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
            count_label.setFixedHeight(20)  # Fixed height for consistent fader alignment
            fader_v_layout.addWidget(count_label)
            
            # Vertical slider (fader) - touch-friendly
            slider = JumpSlider(Qt.Orientation.Vertical)
            slider.setMinimum(0)
            slider.setMaximum(100)
            slider.setValue(current_intensity)
            slider.setMinimumHeight(100)
            slider.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
            
            slider.setStyleSheet(f"""
                QSlider::groove:vertical {{
                    background-color: #2a2a2a;
                    width: 40px;
                    border-radius: 20px;
                    margin: 0px 0px 40px 0px;
                    border: 3px solid #1a1a1a;
                }}
                QSlider::handle:vertical {{
                    background-color: {accent_color};
                    border-radius: 15px;
                    width: 50px;
                    height: 30px;
                    margin: -15px -25px;
                    border: 3px solid #3080a0;
                }}
                QSlider::handle:vertical:hover {{
                    background-color: #70c0e9;
                    border: 3px solid #50a0c9;
                }}
                QSlider::handle:vertical:pressed {{
                    background-color: #90e0ff;
                }}
            """)
            
            # Store group_id for callbacks
            slider._group_id = group.id
            slider._group_name = group.name
            slider._fader_color = fader_color
            
            # Connect value change
            slider.valueChanged.connect(lambda val, gid=group.id: self._on_group_fader_changed(gid, val))
            
            # Right-click for context menu (MIDI learning)
            slider.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
            slider.customContextMenuRequested.connect(
                lambda pos, gid=group.id, gname=group.name, sl=slider: 
                self._show_group_fader_context_menu(pos, gid, gname, sl)
            )
            
            fader_v_layout.addWidget(slider, 1)
            
            # Value label below slider - FLASH on click-hold, MIDI learn on right-click
            group_fader_id = f"group_{group.id}"
            value_label = QLabel(f"{current_intensity}%")
            value_label.setStyleSheet("""
                QLabel {
                    font-size: 11px;
                    font-weight: bold;
                    color: #50a0c9;
                    text-align: center;
                    background-color: #2d2d2d;
                    border-radius: 3px;
                    padding: 4px 2px;
                }
                QLabel:hover {
                    background-color: #1a3548;
                    border: 1px solid #50a0c9;
                }
            """)
            value_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
            value_label.setMaximumHeight(24)
            value_label.setCursor(Qt.CursorShape.PointingHandCursor)
            value_label.setToolTip("Click & hold to flash (max)\nRight-click for MIDI learn")
            slider._value_label = value_label
            slider.valueChanged.connect(lambda val, lbl=value_label: lbl.setText(f"{val}%"))

            # Flash: click-hold maxes fader, release restores
            value_label._flash_fader_id = group_fader_id
            value_label._flash_fader_idx = 0
            value_label._flash_pre_value = 0
            value_label._flash_slider = slider
            value_label._flash_accent = "#50a0c9"  # group accent color
            value_label.mousePressEvent = lambda event, lbl=value_label, sl=slider, fid=group_fader_id, fidx=0: \
                self._on_flash_label_pressed(event, lbl, sl, fid, fidx)
            value_label.mouseReleaseEvent = lambda event, lbl=value_label, sl=slider, fid=group_fader_id, fidx=0: \
                self._on_flash_label_released(event, lbl, sl, fid, fidx)
            value_label.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
            value_label.customContextMenuRequested.connect(
                lambda pos, fid=group_fader_id, fname=group.name, lbl=value_label: \
                    self._show_flash_midi_context_menu(pos, fid, fname, lbl))
            fader_v_layout.addWidget(value_label)
            
            # Store color button reference as None (color squares removed from UI)
            slider._color_btn = None
            
            # MIDI info label - show icon only when mapped
            midi_mgr = get_midi_manager()
            fader_mappings = self.app_settings.get('midi_fader_mappings', {})
            midi_keys = fader_mappings.get(f"group_{group.id}")
            midi_label = QLabel("")
            if midi_keys:
                if isinstance(midi_keys, str):
                    midi_keys = [midi_keys]
                count = len(midi_keys)
                midi_label.setText(f"🎹 MIDI ({count})" if count > 1 else "🎹 MIDI")
                midi_label.setStyleSheet("color: #50c9a0; font-size: 9px;")
            else:
                midi_label.setStyleSheet("color: #666; font-size: 9px;")
            midi_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
            midi_label.setMaximumHeight(16)
            slider._midi_label = midi_label
            fader_v_layout.addWidget(midi_label)
            
            # Output shortcut indicator label
            output_label = QLabel("")
            output_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
            output_label.setMaximumHeight(14)
            output_label.setStyleSheet("color: #666; font-size: 9px;")
            slider._output_label = output_label
            group_fader_id_check = f"group_{group.id}"
            if self._fader_has_shortcut_output(group_fader_id_check):
                output_label.setText("📡 O")
                output_label.setStyleSheet("color: #50e8a0; font-size: 9px; font-weight: bold;")
            fader_v_layout.addWidget(output_label)
            
            # Show override indicator if enabled
            override_faders = self.app_settings.get('group_fader_overrides', {})
            if override_faders.get(group.id, False):
                self._update_group_fader_override_indicator(group.id, slider, True)
            # Apply output fader style if output assigned (and not override)
            elif self._fader_has_shortcut_output(group_fader_id_check):
                self._apply_output_fader_style(slider, 'group')
            
            self.group_faders_layout.addWidget(fader_container, 1)
            self.group_fader_widgets[group.id] = slider
        
        # Add spacer if fewer than 8 faders on this page
        remaining = self._group_faders_per_page - len(page_groups)
        for _ in range(remaining):
            spacer = QWidget()
            spacer.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
            self.group_faders_layout.addWidget(spacer, 1)
    
    def _pick_group_fader_color(self, group_id: str, color_btn: QPushButton, slider: QSlider):
        """Open color picker for group fader, or show color wheel presets if fixtures have them."""
        from PyQt6.QtWidgets import QColorDialog, QMenu
        
        # Get current color
        current_color = slider._fader_color if hasattr(slider, '_fader_color') else "#FFFFFF"
        
        # Check if any fixture in this group has a color wheel
        group = self.project.get_group_by_id(group_id)
        color_wheel_colors = []
        
        if group:
            for fixture_id in group.fixture_ids:
                fixture = self.project.get_fixture_by_id(fixture_id)
                if fixture and fixture.mode:
                    for ch in fixture.mode.channels:
                        if ch.type.lower() == 'color_wheel' and ch.color_wheel_colors:
                            # Found color wheel - collect its colors
                            color_wheel_colors = ch.color_wheel_colors
                            break
                if color_wheel_colors:
                    break  # Use first fixture's color wheel we find
        
        if color_wheel_colors:
            # Show menu of color wheel presets
            menu = QMenu(self)
            menu.setStyleSheet("""
                QMenu {
                    background-color: #2d2d2d;
                    border: 1px solid #555;
                    padding: 4px;
                }
                QMenu::item {
                    padding: 8px 20px;
                    color: #fff;
                }
                QMenu::item:selected {
                    background-color: #c97a50;
                }
            """)
            
            for wheel_color in color_wheel_colors:
                color_name = wheel_color.get('name', 'Unknown')
                color_hex = wheel_color.get('color', '#ffffff')
                color_value = wheel_color.get('value', 0)
                
                # Create action with colored icon
                action = menu.addAction(f"  {color_name}")
                action.setData({'hex': color_hex, 'value': color_value, 'name': color_name})
                
                # Set background color preview using stylesheet
                action.setIcon(self._create_color_icon(color_hex))
            
            # Add option to use color picker anyway
            menu.addSeparator()
            picker_action = menu.addAction("🎨 Custom Color (closest match)...")
            picker_action.setData({'picker': True})
            
            # Show menu at button position
            action = menu.exec(color_btn.mapToGlobal(color_btn.rect().bottomLeft()))
            
            if action:
                data = action.data()
                if data and data.get('picker'):
                    # User wants color picker - will find closest match
                    # Create dialog instance to ensure proper parenting and modality
                    dlg = QColorDialog(QColor(current_color), self.window())
                    dlg.setWindowTitle("Select Fader Color")
                    dlg.setWindowModality(Qt.WindowModality.ApplicationModal)
                    if dlg.exec() == QColorDialog.DialogCode.Accepted:
                        color = dlg.currentColor()
                        hex_color = color.name()
                        self._apply_group_fader_color(group_id, hex_color, color_btn, slider)
                elif data:
                    # User selected a preset color
                    hex_color = data.get('hex', '#ffffff')
                    self._apply_group_fader_color(group_id, hex_color, color_btn, slider)
        else:
            # No color wheel - use standard color picker
            # Create dialog instance to ensure proper parenting and modality
            dlg = QColorDialog(QColor(current_color), self.window())
            dlg.setWindowTitle("Select Fader Color")
            dlg.setWindowModality(Qt.WindowModality.ApplicationModal)
            if dlg.exec() == QColorDialog.DialogCode.Accepted:
                color = dlg.currentColor()
                hex_color = color.name()
                self._apply_group_fader_color(group_id, hex_color, color_btn, slider)
    
    def _create_color_icon(self, hex_color: str):
        """Create a small colored icon for menu items."""
        from PyQt6.QtGui import QPixmap, QIcon, QPainter, QBrush
        from PyQt6.QtCore import Qt
        
        pixmap = QPixmap(16, 16)
        pixmap.fill(Qt.GlobalColor.transparent)
        painter = QPainter(pixmap)
        painter.setBrush(QBrush(QColor(hex_color)))
        painter.setPen(Qt.PenStyle.NoPen)
        painter.drawRect(0, 0, 16, 16)
        painter.end()
        return QIcon(pixmap)
    
    def _apply_group_fader_color(self, group_id: str, hex_color: str, color_btn: QPushButton, slider: QSlider):
        """Apply a color to a group fader."""
        # Update button appearance
        color_btn.setStyleSheet(f"""
            QPushButton {{
                background-color: {hex_color};
                border: 2px solid #555;
                border-radius: 4px;
            }}
            QPushButton:hover {{
                border: 2px solid #888;
            }}
        """)
        
        # Store on slider
        slider._fader_color = hex_color
        
        # Save to settings
        group_fader_colors = self.app_settings.get('group_fader_colors', {})
        group_fader_colors[group_id] = hex_color
        self.app_settings['group_fader_colors'] = group_fader_colors
        self._save_app_settings()
        
        # If fader is currently up, re-apply the color
        if slider.value() > 0:
            self._on_group_fader_changed(group_id, slider.value())
    
    def _on_group_faders_page_changed(self, index: int):
        """Handle group faders page change."""
        # Check if the signal came from a detached window's combo box
        sender = self.sender() if hasattr(self, 'sender') else None
        if sender and hasattr(self, '_detached_group_fader_data'):
            for data in self._detached_group_fader_data:
                if data.get('page_combo') is sender:
                    # Update the detached window's page and repopulate it
                    data['page'] = index
                    self._populate_group_faders_for_layout(data)
                    # Refresh dynamic MIDI slider references for the detached window
                    detached_win = self._detached_windows.get("GROUPS")
                    if detached_win:
                        self._on_dynamic_window_activated(detached_win)
                    return
        # Default: update the main window
        self._group_faders_page = index
        self._populate_group_faders()
        # Refresh dynamic MIDI slider references so motorized faders sync
        self._update_dynamic_sliders_for_main_tab("GROUPS")
    
    def _on_group_fader_changed(self, group_id: str, value: int):
        """Handle group fader value change - controls dimmer, shutter, and color.
        
        Output is capped by master fader and fixture type faders.
        Handles both RGB fixtures and color wheel fixtures.
        
        When fader is at 0, turns off lights and releases control back to effect engine.
        """
        try:
            from .effect_engine import find_closest_color_wheel_value
        except ImportError:
            from effect_engine import find_closest_color_wheel_value
        
        try:
            # Get the group
            group = self.project.get_group_by_id(group_id)
            if not group:
                return
            
            # When fader is at 0, release control back to effect engine / overlay
            if value == 0:
                # Track previous value for rise detection
                if not hasattr(self, '_group_fader_prev_values'):
                    self._group_fader_prev_values = {}
                self._group_fader_prev_values[group_id] = 0
                
                # If the video overlay is active, skip the channel-zero pass
                # so the overlay can seamlessly resume driving these fixtures
                # on the very next timer tick (no single-frame blackout flash).
                overlay_active = (getattr(self, '_viz_overlay_frame', None) is not None
                                  and getattr(self, '_viz_overlay_bounds', None) is not None)
                
                if not overlay_active:
                    # No overlay — turn off all fixtures in this group
                    for fixture_id in group.fixture_ids:
                        fixture = self.project.get_fixture_by_id(fixture_id)
                        if not fixture or not fixture.mode:
                            continue
                        
                        base_addr = fixture.address
                        uni = fixture.universe
                        
                        # Set all dimmer/shutter/color channels to off
                        for i, ch in enumerate(fixture.mode.channels):
                            ch_type = ch.type.lower()
                            addr = base_addr + i
                            
                            if ch_type in ('dimmer', 'intensity', 'master', 'master dimmer'):
                                self.artnet.set_channel(uni, addr, 0)
                            elif ch_type in ('shutter', 'strobe'):
                                self.artnet.set_channel(uni, addr, 0)
                            elif ch_type in ('red', 'green', 'blue', 'white'):
                                self.artnet.set_channel(uni, addr, 0)
                            elif ch_type == 'on_off':
                                self.artnet.set_channel(uni, addr, getattr(ch, 'off_value', 0))
                
                # Clear group intensity override in effect engine so effects/overlay can take over
                if hasattr(self, 'effect_engine') and self.effect_engine:
                    self.effect_engine.set_group_intensity(group_id, None)  # None = no override
                    # Release override fixtures so effects can resume control
                    fader_id = f"group_{group_id}"
                    self.effect_engine.release_override_fixtures(fader_id)
                
                # Fire assigned OSC/MIDI shortcut on fader off
                fader_id = f"group_{group_id}"
                self._fire_fader_shortcut_if_assigned(fader_id, 'off')
                
                # Send MIDI feedback
                self._send_group_fader_feedback(group_id, value)
                
                # If ALL group faders are now at 0 and no effect is running,
                # select the execute OFF button so the UI reflects the idle state.
                if self._are_all_group_faders_at_zero():
                    running = (hasattr(self, 'effect_engine') and self.effect_engine
                               and self.effect_engine.is_running())
                    if not running and self._are_all_faders_at_zero():
                        self._active_execute_preset_id = "__OFF__"
                        self._update_execute_button_selection("__OFF__")
                
                return
            
            # Fire assigned shortcut on rise from 0
            fader_id = f"group_{group_id}"
            if not hasattr(self, '_group_fader_prev_values'):
                self._group_fader_prev_values = {}
            prev = self._group_fader_prev_values.get(group_id, 0)
            if prev == 0 and value > 0:
                self._fire_fader_shortcut_if_assigned(fader_id, 'rise')
            self._group_fader_prev_values[group_id] = value
            
            # Register group fader fixtures with effect engine so the HTP
            # merge loop skips these channels.  Without this, the merge thread
            # (40 fps) overwrites the values we set below, causing visible
            # flashing.  The fixtures are released when the fader returns to 0.
            fader_id = f"group_{group_id}"
            if hasattr(self, 'effect_engine') and self.effect_engine:
                self.effect_engine.set_override_fixtures(fader_id, group.fixture_ids)
            
            # Collect DMX values for continuous re-assertion by the effect engine
            override_dmx_values: dict[tuple[int, int], int] = {}
            
            # Get master fader value as a cap (0.0-1.0)
            master_cap = 1.0
            if hasattr(self, 'master_slider'):
                master_cap = self.master_slider.value() / 100.0
            
            # Base intensity from fader
            base_intensity = value / 100.0
            
            # Get the fader color for this group
            group_fader_colors = self.app_settings.get('group_fader_colors', {})
            fader_color = group_fader_colors.get(group_id, "#FFFFFF")
            
            # Apply to all fixtures in the group - this overrides any effects
            for fixture_id in group.fixture_ids:
                fixture = self.project.get_fixture_by_id(fixture_id)
                if not fixture or not fixture.mode:
                    continue
                
                # Get fixture type cap (0.0-1.0)
                fixture_type_cap = 1.0
                if hasattr(self, 'effect_engine') and self.effect_engine:
                    fixture_type_cap = self.effect_engine.get_fixture_type_cap(fixture.profile.name)
                
                # Final intensity is capped by both master and fixture type faders
                intensity = base_intensity * master_cap * fixture_type_cap
                
                # Check if fixture has color wheel
                color_wheel_channel = None
                has_color_wheel = False
                for ch in fixture.mode.channels:
                    if ch.type.lower() == 'color_wheel' and ch.color_wheel_colors:
                        color_wheel_channel = ch
                        has_color_wheel = True
                        break
                
                # Parse color to RGB with final intensity (for RGB fixtures)
                try:
                    color = QColor(fader_color)
                    red = int(color.red() * intensity)
                    green = int(color.green() * intensity)
                    blue = int(color.blue() * intensity)
                except:
                    red = green = blue = int(255 * intensity)
                
                # For color wheel fixtures, find the closest color
                color_wheel_dmx = -1
                if has_color_wheel and color_wheel_channel:
                    color_wheel_dmx, _ = find_closest_color_wheel_value(
                        fader_color, color_wheel_channel.color_wheel_colors
                    )
                
                base_addr = fixture.address
                uni = fixture.universe
                
                # Set dimmer/intensity based on fader (capped)
                dimmer_val = int(255 * intensity)
                
                # Find channel indices by iterating through mode channels
                for i, ch in enumerate(fixture.mode.channels):
                    ch_type = ch.type.lower()
                    addr = base_addr + i
                    
                    # Dimmer/intensity channels
                    if ch_type in ('dimmer', 'intensity', 'master', 'master dimmer'):
                        self.artnet.set_channel(uni, addr, dimmer_val)
                        override_dmx_values[(uni, addr)] = dimmer_val
                    
                    # Shutter - open when fader > 0
                    elif ch_type == 'shutter':
                        self.artnet.set_channel(uni, addr, 255)
                        override_dmx_values[(uni, addr)] = 255
                    
                    # Strobe - off (0) so the fixture doesn't actually strobe
                    elif ch_type == 'strobe':
                        self.artnet.set_channel(uni, addr, 0)
                        override_dmx_values[(uni, addr)] = 0
                    
                    # Color wheel channel - set to closest color, fallback to 0 (open/white)
                    elif ch_type == 'color_wheel':
                        cw_val = color_wheel_dmx if color_wheel_dmx >= 0 else 0
                        self.artnet.set_channel(uni, addr, cw_val)
                        override_dmx_values[(uni, addr)] = cw_val
                    
                    # RGB color channels - only set if no color wheel
                    elif ch_type == 'red':
                        if not has_color_wheel:
                            self.artnet.set_channel(uni, addr, red)
                            override_dmx_values[(uni, addr)] = red
                        else:
                            self.artnet.set_channel(uni, addr, 0)  # Turn off RGB when using color wheel
                            override_dmx_values[(uni, addr)] = 0
                    elif ch_type == 'green':
                        if not has_color_wheel:
                            self.artnet.set_channel(uni, addr, green)
                            override_dmx_values[(uni, addr)] = green
                        else:
                            self.artnet.set_channel(uni, addr, 0)
                            override_dmx_values[(uni, addr)] = 0
                    elif ch_type == 'blue':
                        if not has_color_wheel:
                            self.artnet.set_channel(uni, addr, blue)
                            override_dmx_values[(uni, addr)] = blue
                        else:
                            self.artnet.set_channel(uni, addr, 0)
                            override_dmx_values[(uni, addr)] = 0
                    
                    # White channel - use for white color, off for other colors
                    elif ch_type == 'white':
                        if fader_color.upper() == "#FFFFFF" and not has_color_wheel:
                            self.artnet.set_channel(uni, addr, dimmer_val)
                            override_dmx_values[(uni, addr)] = dimmer_val
                        else:
                            self.artnet.set_channel(uni, addr, 0)
                            override_dmx_values[(uni, addr)] = 0
                    
                    # On/Off channel - on when fader > 0
                    elif ch_type == 'on_off':
                        on_val = getattr(ch, 'on_value', 255)
                        self.artnet.set_channel(uni, addr, on_val)
                        override_dmx_values[(uni, addr)] = on_val
            
            # Store DMX values for continuous re-assertion by effect engine loops
            if hasattr(self, 'effect_engine') and self.effect_engine:
                self.effect_engine.store_override_dmx(fader_id, override_dmx_values)
            
            # Also update effect engine group intensity (for interaction with effects)
            if hasattr(self, 'effect_engine') and self.effect_engine:
                self.effect_engine.set_group_intensity(group_id, intensity)
            
            # Send MIDI feedback if mapped
            self._send_group_fader_feedback(group_id, value)
        except Exception as e:
            print(f"[GroupFader] ERROR: {e}")
            import traceback
            traceback.print_exc()
    
    def _refresh_active_group_faders(self):
        """Re-trigger all group faders that are currently non-zero.

        Group faders pre-compute absolute DMX values (intensity * master_cap *
        fixture_type_cap) and store them for continuous re-assertion.  When the
        master or a fixture-type cap changes after a fader was moved those
        stored values are stale.  Calling this method recomputes them with the
        current caps without the user needing to touch the fader again.
        """
        if not hasattr(self, 'group_fader_widgets'):
            return
        for group_id, slider in self.group_fader_widgets.items():
            try:
                val = slider.value()
                if val > 0:
                    self._on_group_fader_changed(group_id, val)
            except RuntimeError:
                pass  # Slider was deleted

    def _send_group_fader_feedback(self, group_id: str, value: int):
        """Send MIDI feedback for group fader."""
        midi_mgr = get_midi_manager()
        fader_id = f"group_{group_id}"
        
        fader_mappings = self.app_settings.get('midi_fader_mappings', {})
        midi_keys = fader_mappings.get(fader_id)
        
        if midi_keys:
            midi_value = int((value / 100.0) * 127)
            midi_value = max(0, min(127, midi_value))
            
            # Support both single key (string) and multiple keys (list)
            if isinstance(midi_keys, str):
                midi_keys = [midi_keys]
            
            for midi_key in midi_keys:
                midi_mgr.send_fader_feedback(midi_key, midi_value)
    
    def _reset_all_group_faders(self):
        """Reset all group faders to 0 (OFF)."""
        if hasattr(self, 'effect_engine') and self.effect_engine:
            self.effect_engine.clear_group_intensities()
            self.effect_engine.clear_all_overrides()
        
        # Update all slider widgets - reset to 0 (OFF)
        for group_id, slider in self.group_fader_widgets.items():
            slider.blockSignals(True)
            slider.setValue(0)
            slider.blockSignals(False)
            if hasattr(slider, '_value_label'):
                slider._value_label.setText("0%")
            # Also trigger the actual change to update DMX
            self._on_group_fader_changed(group_id, 0)
    
    def _show_group_fader_context_menu(self, pos, group_id: str, group_name: str, slider: QSlider):
        """Show context menu for group fader MIDI learning."""
        midi_mgr = get_midi_manager()
        fader_id = f"group_{group_id}"
        
        menu = QMenu(self)
        menu.setStyleSheet(self._get_touch_menu_stylesheet())
        
        # Check if dynamic MIDI mode is enabled
        dynamic_mode = midi_mgr.is_dynamic_mode_enabled()
        
        # Header showing group name
        header_action = menu.addAction(f"🎚️ {group_name}")
        header_action.setEnabled(False)
        menu.addSeparator()
        
        # Check if already mapped to MIDI (support multiple mappings)
        fader_mappings = self.app_settings.get('midi_fader_mappings', {})
        existing_mappings = fader_mappings.get(fader_id)
        
        if existing_mappings and not dynamic_mode:
            # Support both single key (string) and multiple keys (list)
            if isinstance(existing_mappings, str):
                existing_mappings = [existing_mappings]
            
            # Show all current mappings
            for midi_key in existing_mappings:
                display = MIDIManager.format_midi_key(midi_key)
                mapped_action = menu.addAction(f"✓ MIDI: {display}")
                mapped_action.setEnabled(False)
            
            menu.addSeparator()
            add_action = menu.addAction("➕ Add Another MIDI...")
            add_action.triggered.connect(lambda: self._start_group_fader_midi_learn(fader_id, group_name, slider))
            clear_action = menu.addAction("❌ Clear All MIDI Mappings")
            clear_action.triggered.connect(lambda: self._clear_group_fader_midi_mapping(fader_id))
        else:
            learn_action = menu.addAction("🎹 Learn MIDI Fader...")
            if dynamic_mode:
                learn_action.setEnabled(False)
                learn_action.setText("🎹 Learn MIDI Fader... (Dynamic Mode Active)")
            else:
                learn_action.triggered.connect(lambda: self._start_group_fader_midi_learn(fader_id, group_name, slider))
        
        menu.addSeparator()
        
        # Override mode toggle
        override_faders = self.app_settings.get('group_fader_overrides', {})
        is_override = override_faders.get(group_id, False)
        override_action = menu.addAction(f"{'✅' if is_override else '⬜'} Override Mode")
        override_action.setToolTip("When enabled, this fader can run alongside effects.\nIt takes full control of its fixtures, bypassing the effect engine.")
        override_action.triggered.connect(lambda: self._toggle_group_fader_override(group_id, slider))
        
        menu.addSeparator()
        
        # OSC/MIDI Shortcut output assignment
        self._build_fader_shortcut_submenu(menu, fader_id)
        
        menu.addSeparator()
        
        # Quick set options
        set_100 = menu.addAction("⬆️ Set to 100%")
        set_100.triggered.connect(lambda: slider.setValue(100))
        set_50 = menu.addAction("➡️ Set to 50%")
        set_50.triggered.connect(lambda: slider.setValue(50))
        set_0 = menu.addAction("⬇️ Set to 0%")
        set_0.triggered.connect(lambda: slider.setValue(0))
        
        menu.exec(slider.mapToGlobal(pos))
    
    def _start_group_fader_midi_learn(self, fader_id: str, group_name: str, slider: QSlider):
        """Start MIDI learn mode for a group fader."""
        midi_mgr = get_midi_manager()
        if not midi_mgr.is_connected:
            QMessageBox.warning(self._get_active_window(), "No MIDI Device", "Connect a MIDI device first in Settings > MIDI.")
            return
        
        # Open MIDI learning dialog - parent to slider's window for correct monitor
        parent_window = slider.window() if slider else self
        dialog = QDialog(parent_window)
        dialog.setWindowTitle(f"Learn MIDI for '{group_name}'")
        dialog.setMinimumWidth(400)
        layout = QVBoxLayout()
        
        label = QLabel("Turn or move a MIDI fader/knob...\n\n(Waiting for input)")
        label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        label.setStyleSheet("font-size: 14px; padding: 20px;")
        layout.addWidget(label)
        
        # List of learned MIDI controls
        learned_list = QListWidget()
        learned_list.setMaximumHeight(100)
        layout.addWidget(QLabel("Learned MIDI controls:"))
        layout.addWidget(learned_list)
        
        # Buttons
        button_layout = QHBoxLayout()
        learn_more_button = QPushButton("Learn Another")
        ok_button = QPushButton("OK")
        cancel_button = QPushButton("Cancel")
        learn_more_button.setMinimumHeight(40)
        ok_button.setMinimumHeight(40)
        cancel_button.setMinimumHeight(40)
        ok_button.setEnabled(False)
        button_layout.addWidget(learn_more_button)
        button_layout.addWidget(ok_button)
        button_layout.addWidget(cancel_button)
        layout.addLayout(button_layout)
        
        dialog.setLayout(layout)
        
        # Enable MIDI learn mode
        midi_mgr.set_learn_mode(True)
        learned_keys = []
        
        def on_midi_received(midi_key):
            nonlocal learned_keys
            if midi_key.startswith("cc:") or midi_key.startswith("pb:"):
                if midi_key not in learned_keys:
                    learned_keys.append(midi_key)
                    # Store the device name that sent this message
                    device_name = getattr(midi_mgr, '_last_received_device', None)
                    if device_name:
                        midi_mgr._mapping_devices[midi_key] = device_name
                    display = MIDIManager.format_midi_key(midi_key)
                    learned_list.addItem(display)
                    label.setText(f"✓ Learned: {display}\n\nLearn another or click OK")
                    ok_button.setEnabled(True)
        
        midi_mgr.midi_received.connect(on_midi_received)
        ok_button.clicked.connect(dialog.accept)
        cancel_button.clicked.connect(dialog.reject)
        learn_more_button.clicked.connect(lambda: label.setText("Waiting for next MIDI input..."))
        
        result = dialog.exec()
        
        midi_mgr.set_learn_mode(False)
        midi_mgr.midi_received.disconnect(on_midi_received)
        
        if result == QDialog.DialogCode.Accepted and learned_keys:
            # Get existing mappings for this fader
            fader_mappings = self.app_settings.get('midi_fader_mappings', {})
            existing_mappings = fader_mappings.get(fader_id, [])
            if isinstance(existing_mappings, str):
                existing_mappings = [existing_mappings]
            
            # Combine existing and new mappings (avoid duplicates)
            all_keys = list(existing_mappings)
            for key in learned_keys:
                if key not in all_keys:
                    all_keys.append(key)
            
            # Register MIDI mappings for all keys
            for cc_key in all_keys:
                midi_mgr._fader_mappings[cc_key] = fader_id
            
            # Register callback (once, handles all mapped keys)
            midi_mgr.register_fader_callback(fader_id, 
                lambda val, max_val, gid=fader_id.replace("group_", ""): 
                self._on_midi_group_fader(gid, val, max_val))
            
            # Save mapping to settings - store as list for multiple mappings
            fader_mappings[fader_id] = all_keys if len(all_keys) > 1 else all_keys[0]
            self.app_settings['midi_fader_mappings'] = fader_mappings
            # Also save the device mappings so controller names persist
            self.app_settings['midi_mapping_devices'] = midi_mgr.get_mapping_devices_dict()
            self._save_app_settings()
            
            display_list = ", ".join([MIDIManager.format_midi_key(k) for k in learned_keys])
            print(f"[MIDI] Group '{group_name}' assigned to {display_list}")
            
            # Refresh group faders to update MIDI label
            self._populate_group_faders()
    
    def _clear_group_fader_midi_mapping(self, fader_id: str):
        """Clear MIDI mapping for a group fader."""
        midi_mgr = get_midi_manager()
        
        fader_mappings = self.app_settings.get('midi_fader_mappings', {})
        if fader_id in fader_mappings:
            old_mappings = fader_mappings[fader_id]
            
            # Remove all mappings from MIDI manager
            if isinstance(old_mappings, str):
                old_mappings = [old_mappings]
            for old_mapping in old_mappings:
                if old_mapping in midi_mgr._fader_mappings:
                    del midi_mgr._fader_mappings[old_mapping]
            
            # Remove callback
            if fader_id in midi_mgr._fader_callbacks:
                del midi_mgr._fader_callbacks[fader_id]
            
            # Remove from settings
            del fader_mappings[fader_id]
            self._save_app_settings()
            
            print(f"[MIDI] Cleared mapping for {fader_id}")
            
            # Refresh group faders to update MIDI label
            self._populate_group_faders()
    
    def _toggle_group_fader_override(self, group_id: str, slider: QSlider):
        """Toggle override mode for a group fader.
        
        When override is ON, this fader can coexist with running effects.
        Its fixtures are excluded from effect engine output and driven directly by the fader.
        """
        override_faders = self.app_settings.get('group_fader_overrides', {})
        is_override = override_faders.get(group_id, False)
        
        # Toggle
        new_state = not is_override
        override_faders[group_id] = new_state
        self.app_settings['group_fader_overrides'] = override_faders
        self._save_app_settings()
        
        fader_id = f"group_{group_id}"
        
        if new_state:
            # Turning override ON
            print(f"[Override] Enabled override mode for group fader '{group_id[:8]}...'")
            # If fader is currently above 0, register override fixtures immediately
            if slider.value() > 0 and hasattr(self, 'effect_engine') and self.effect_engine:
                group = self.project.get_group_by_id(group_id)
                if group:
                    self.effect_engine.set_override_fixtures(fader_id, group.fixture_ids)
            # Update visual indicator
            self._update_group_fader_override_indicator(group_id, slider, True)
        else:
            # Turning override OFF — release fixtures back to effect engine
            print(f"[Override] Disabled override mode for group fader '{group_id[:8]}...'")
            if hasattr(self, 'effect_engine') and self.effect_engine:
                self.effect_engine.release_override_fixtures(fader_id)
            # Update visual indicator
            self._update_group_fader_override_indicator(group_id, slider, False)
    
    def _update_group_fader_override_indicator(self, group_id: str, slider: QSlider, is_override: bool):
        """Update the visual indicator on a group fader to show override state."""
        if is_override:
            # Red slider handle to visually distinguish override faders
            slider.setStyleSheet("""
                QSlider::groove:vertical {
                    background-color: #2a2020;
                    width: 40px;
                    border-radius: 20px;
                    margin: 0px 0px 40px 0px;
                    border: 3px solid #3a1515;
                }
                QSlider::handle:vertical {
                    background-color: #e04050;
                    border-radius: 15px;
                    width: 50px;
                    height: 30px;
                    margin: -15px -25px;
                    border: 3px solid #b03040;
                }
                QSlider::handle:vertical:hover {
                    background-color: #ff5565;
                    border: 3px solid #e04050;
                }
                QSlider::handle:vertical:pressed {
                    background-color: #ff7080;
                }
            """)
        else:
            # Restore normal blue slider handle
            accent_color = "#50a0c9"
            slider.setStyleSheet(f"""
                QSlider::groove:vertical {{
                    background-color: #2a2a2a;
                    width: 40px;
                    border-radius: 20px;
                    margin: 0px 0px 40px 0px;
                    border: 3px solid #1a1a1a;
                }}
                QSlider::handle:vertical {{
                    background-color: {accent_color};
                    border-radius: 15px;
                    width: 50px;
                    height: 30px;
                    margin: -15px -25px;
                    border: 3px solid #3080a0;
                }}
                QSlider::handle:vertical:hover {{
                    background-color: #70c0e9;
                    border: 3px solid #50a0c9;
                }}
                QSlider::handle:vertical:pressed {{
                    background-color: #90e0ff;
                }}
            """)

        if hasattr(slider, '_midi_label'):
            label = slider._midi_label
            if is_override:
                # Show override indicator (combine with existing MIDI text)
                current_text = label.text()
                if '🔒' not in current_text:
                    if current_text:
                        label.setText(f"🔒 OVR | {current_text}")
                    else:
                        label.setText("🔒 OVR")
                    label.setStyleSheet("color: #ff9944; font-size: 9px; font-weight: bold;")
            else:
                # Remove override indicator, restore original
                current_text = label.text().replace("🔒 OVR | ", "").replace("🔒 OVR", "").strip()
                label.setText(current_text)
                if current_text:
                    label.setStyleSheet("color: #50c9a0; font-size: 9px;")
                else:
                    label.setStyleSheet("color: #666; font-size: 9px;")
    
    def _on_midi_group_fader(self, group_id: str, value: int, max_val: int):
        """Handle MIDI input for a group fader."""
        # Scale to 0-100 based on max_val (127 for CC, 16383 for pitch bend)
        scaled_value = int((value / max_val) * 100)
        scaled_value = max(0, min(100, scaled_value))  # Clamp to 0-100
        
        # Update the slider if visible
        if group_id in self.group_fader_widgets:
            slider = self.group_fader_widgets[group_id]
            slider.blockSignals(True)
            slider.setValue(scaled_value)
            slider.blockSignals(False)
            if hasattr(slider, '_value_label'):
                slider._value_label.setText(f"{scaled_value}%")
        
        # Apply the actual DMX changes (dimmer, shutter, color)
        self._on_group_fader_changed(group_id, scaled_value)
    
    def _refresh_group_faders_tab(self):
        """Refresh the group faders when groups change."""
        if hasattr(self, 'group_faders_layout'):
            self._populate_group_faders()
        
        # Also refresh any detached GROUPS windows
        if hasattr(self, '_detached_group_fader_data'):
            valid = []
            for data in self._detached_group_fader_data:
                try:
                    layout = data['layout']
                    # Verify the layout's parent widget still exists
                    parent = layout.parentWidget()
                    if parent is None or not parent.isVisible():
                        continue
                    self._populate_group_faders_for_layout(data)
                    valid.append(data)
                except RuntimeError:
                    # Widget was deleted
                    pass
            self._detached_group_fader_data = valid

    def _populate_group_faders_for_layout(self, data: dict):
        """Populate group faders for a detached window by temporarily swapping attributes."""
        # Save main window's group fader refs
        saved = {
            'group_faders_layout': self.group_faders_layout,
            'group_fader_widgets': self.group_fader_widgets,
            'group_faders_page_combo': self.group_faders_page_combo,
            '_group_faders_page': self._group_faders_page,
            '_group_faders_per_page': self._group_faders_per_page,
        }
        try:
            # Swap in detached window's refs
            self.group_faders_layout = data['layout']
            self.group_fader_widgets = data['widgets']
            self.group_faders_page_combo = data['page_combo']
            self._group_faders_page = data['page']
            self._group_faders_per_page = data['per_page']
            # Re-populate using the standard method
            self._populate_group_faders()
            # Update the data dict with any changes (e.g. page reset)
            data['page'] = self._group_faders_page
            data['widgets'] = self.group_fader_widgets
        finally:
            # Restore main window's refs
            for attr, value in saved.items():
                setattr(self, attr, value)

    def _on_group_selected(self, current, previous):
        """Handle group selection change."""
        try:
            self.group_fixtures_table.setRowCount(0)
            self.move_up_btn.setEnabled(False)
            self.move_down_btn.setEnabled(False)
            
            if not current:
                self.group_detail_header.setText("Select a group")
                self.group_color_btn.setEnabled(False)
                self.edit_group_btn.setEnabled(False)
                self.delete_group_btn.setEnabled(False)
                return
            
            group_id = current.data(Qt.ItemDataRole.UserRole)
            group = self.project.get_group_by_id(group_id)
            
            if not group:
                return
            
            # Update header
            self.group_detail_header.setText(f"📁 {group.name}")
            
            # Update color button
            self.group_color_btn.setEnabled(True)
            self.group_color_btn.setStyleSheet(
                f"background-color: {group.color}; border-radius: 4px; border: 1px solid #555;"
            )
            
            # Populate fixtures table
            self.group_fixtures_table.blockSignals(True)  # Prevent cellChanged during population
            self.group_fixtures_table.setRowCount(len(group.fixture_ids))
            for i, fixture_id in enumerate(group.fixture_ids):
                fixture = self.project.get_fixture_by_id(fixture_id)
                if fixture:
                    # Order number - EDITABLE
                    order_item = QTableWidgetItem(str(i + 1))
                    order_item.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
                    order_item.setData(Qt.ItemDataRole.UserRole, fixture_id)
                    self.group_fixtures_table.setItem(i, 0, order_item)
                    
                    # Fixture name
                    label = fixture.label or fixture.profile.name
                    name_item = QTableWidgetItem(f"💡 {label}")
                    name_item.setFlags(name_item.flags() & ~Qt.ItemFlag.ItemIsEditable)
                    self.group_fixtures_table.setItem(i, 1, name_item)
                    
                    # Category
                    cat_item = QTableWidgetItem(fixture.profile.category)
                    cat_item.setFlags(cat_item.flags() & ~Qt.ItemFlag.ItemIsEditable)
                    self.group_fixtures_table.setItem(i, 2, cat_item)
                    
                    # Address
                    addr_item = QTableWidgetItem(f"U{fixture.universe}:{fixture.address}")
                    addr_item.setFlags(addr_item.flags() & ~Qt.ItemFlag.ItemIsEditable)
                    self.group_fixtures_table.setItem(i, 3, addr_item)
            self.group_fixtures_table.blockSignals(False)
            
            if not group.fixture_ids:
                self.group_fixtures_table.setRowCount(1)
                empty_item = QTableWidgetItem("(No fixtures in this group)")
                empty_item.setForeground(QColor("#808080"))
                empty_item.setFlags(empty_item.flags() & ~Qt.ItemFlag.ItemIsEditable)
                self.group_fixtures_table.setItem(0, 0, empty_item)
                self.group_fixtures_table.setSpan(0, 0, 1, 4)
            
            # Enable action buttons
            self.edit_group_btn.setEnabled(True)
            self.delete_group_btn.setEnabled(True)
        except Exception as e:
            print(f"[Groups] Error in _on_group_selected: {e}")
            import traceback; traceback.print_exc()
    
    def _on_group_fixture_selection_changed(self):
        """Handle fixture selection in group table."""
        selected = self.group_fixtures_table.selectedItems()
        if not selected:
            self.move_up_btn.setEnabled(False)
            self.move_down_btn.setEnabled(False)
            return
        
        row = self.group_fixtures_table.currentRow()
        row_count = self.group_fixtures_table.rowCount()
        
        # Check if this is a valid fixture row (not the "no fixtures" message)
        item = self.group_fixtures_table.item(row, 0)
        if not item or not item.data(Qt.ItemDataRole.UserRole):
            self.move_up_btn.setEnabled(False)
            self.move_down_btn.setEnabled(False)
            return
        
        self.move_up_btn.setEnabled(row > 0)
        self.move_down_btn.setEnabled(row < row_count - 1)
    
    def _move_fixture_up(self):
        """Move selected fixture up in the group order."""
        self._move_fixture_in_group(-1)
    
    def _move_fixture_down(self):
        """Move selected fixture down in the group order."""
        self._move_fixture_in_group(1)
    
    def _move_fixture_in_group(self, direction: int):
        """Move fixture up (-1) or down (+1) in group order."""
        current_group_item = self.groups_list.currentItem()
        if not current_group_item:
            return
        
        group_id = current_group_item.data(Qt.ItemDataRole.UserRole)
        group = self.project.get_group_by_id(group_id)
        if not group:
            return
        
        row = self.group_fixtures_table.currentRow()
        new_row = row + direction
        
        if new_row < 0 or new_row >= len(group.fixture_ids):
            return
        
        # Swap fixture IDs in the group's list
        group.fixture_ids[row], group.fixture_ids[new_row] = group.fixture_ids[new_row], group.fixture_ids[row]
        
        # Mark project dirty
        self._mark_dirty()
        
        # Refresh the table
        self._on_group_selected(current_group_item, None)
        
        # Re-select the moved row
        self.group_fixtures_table.selectRow(new_row)
    
    def _on_group_fixture_order_changed(self, row: int, column: int):
        """Handle when user edits the order number in the table."""
        # Only handle column 0 (order number)
        if column != 0:
            return
        
        current_group_item = self.groups_list.currentItem()
        if not current_group_item:
            return
        
        group_id = current_group_item.data(Qt.ItemDataRole.UserRole)
        group = self.project.get_group_by_id(group_id)
        if not group or not group.fixture_ids:
            return
        
        item = self.group_fixtures_table.item(row, 0)
        if not item:
            return
        
        # Get the fixture ID from this row
        fixture_id = item.data(Qt.ItemDataRole.UserRole)
        if not fixture_id:
            return
        
        # Parse the new order number
        try:
            new_order = int(item.text())
        except ValueError:
            # Invalid number, refresh to restore
            self._on_group_selected(current_group_item, None)
            return
        
        # Clamp to valid range
        num_fixtures = len(group.fixture_ids)
        new_order = max(1, min(new_order, num_fixtures))
        new_index = new_order - 1
        
        # Current index
        current_index = row
        
        if new_index == current_index:
            # No change needed, just refresh to fix display
            self._on_group_selected(current_group_item, None)
            return
        
        # Remove fixture from current position and insert at new position
        group.fixture_ids.pop(current_index)
        group.fixture_ids.insert(new_index, fixture_id)
        
        # Mark project dirty
        self._mark_dirty()
        
        # Refresh the table
        self._on_group_selected(current_group_item, None)
        
        # Re-select the moved row at its new position
        self.group_fixtures_table.selectRow(new_index)
    
    def _change_selected_group_color(self):
        """Change color of currently selected group."""
        current = self.groups_list.currentItem()
        if not current:
            return
        group_id = current.data(Qt.ItemDataRole.UserRole)
        group = self.project.get_group_by_id(group_id)
        if group:
            self._change_group_color(group)
    
    def _edit_selected_group(self):
        """Edit the currently selected group."""
        current = self.groups_list.currentItem()
        if not current:
            return
        group_id = current.data(Qt.ItemDataRole.UserRole)
        group = self.project.get_group_by_id(group_id)
        if group:
            self._edit_group(group)
    
    def _delete_selected_group(self):
        """Delete the currently selected group."""
        current = self.groups_list.currentItem()
        if not current:
            return
        group_id = current.data(Qt.ItemDataRole.UserRole)
        group = self.project.get_group_by_id(group_id)
        if group:
            self._delete_group(group)
    
    def _refresh_groups_table(self):
        """Refresh the groups list from project data."""
        # Remember current selection
        current_id = None
        if self.groups_list.currentItem():
            current_id = self.groups_list.currentItem().data(Qt.ItemDataRole.UserRole)
        
        self.groups_list.clear()
        self.group_fixtures_table.setRowCount(0)
        self.group_detail_header.setText("Select a group")
        self.group_color_btn.setEnabled(False)
        self.edit_group_btn.setEnabled(False)
        self.delete_group_btn.setEnabled(False)
        self.move_up_btn.setEnabled(False)
        self.move_down_btn.setEnabled(False)
        
        if not self.project:
            return
        
        select_item = None
        for group in self.project.groups:
            fixture_count = len(group.fixture_ids)
            item = QListWidgetItem(f"📁 {group.name} ({fixture_count})")
            item.setData(Qt.ItemDataRole.UserRole, group.id)
            # Add color indicator via icon or background
            item.setForeground(QColor(group.color))
            self.groups_list.addItem(item)
            
            # Restore selection
            if group.id == current_id:
                select_item = item
        
        if select_item:
            self.groups_list.setCurrentItem(select_item)
        
        # Update fixture types summary
        self._update_fixture_types_summary()
        
        # Also refresh group faders tab
        self._refresh_group_faders_tab()
    
    def _update_fixture_types_summary(self):
        """Update the fixture types summary label."""
        if not self.project or not self.project.fixtures:
            self.fixture_types_label.setText("No fixtures patched")
            return
        
        # Count fixtures by category
        categories = {}
        for fixture in self.project.fixtures:
            category = fixture.profile.category
            if category not in categories:
                categories[category] = []
            categories[category].append(fixture)
        
        # Build summary text
        lines = []
        for category, fixtures in sorted(categories.items()):
            fixture_names = [f.label or f.profile.name for f in fixtures]
            lines.append(f"• {category}: {len(fixtures)} ({', '.join(fixture_names[:3])}{'...' if len(fixtures) > 3 else ''})")
        
        self.fixture_types_label.setText("\n".join(lines) if lines else "No fixtures patched")
    
    def _add_group(self):
        """Add a new group."""
        if not self.project:
            QMessageBox.warning(self._get_active_window(), "No Project", "Please create or open a project first.")
            return
        
        dialog = GroupEditDialog(self, self.project)
        if dialog.exec() == QDialog.DialogCode.Accepted:
            group = dialog.get_group()
            self.project.groups.append(group)
            self._refresh_groups_table()
            self._rebuild_quick_effect_group_buttons()
            self._mark_dirty()
    
    def _edit_group(self, group: FixtureGroup):
        """Edit an existing group."""
        dialog = GroupEditDialog(self, self.project, group)
        if dialog.exec() == QDialog.DialogCode.Accepted:
            updated = dialog.get_group()
            # Update group in place
            group.name = updated.name
            group.fixture_ids = updated.fixture_ids
            group.color = updated.color
            self._refresh_groups_table()
            self._rebuild_quick_effect_group_buttons()
            self._mark_dirty()
    
    def _delete_group(self, group: FixtureGroup):
        """Delete a group."""
        reply = QMessageBox.question(
            self._get_active_window(), "Delete Group",
            f"Are you sure you want to delete the group '{group.name}'?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
        )
        if reply == QMessageBox.StandardButton.Yes:
            self.project.groups.remove(group)
            self._refresh_groups_table()
            self._rebuild_quick_effect_group_buttons()
            self._mark_dirty()
    
    def _change_group_color(self, group: FixtureGroup):
        """Change a group's display color."""
        color = QColorDialog.getColor(QColor(group.color), self.window(), "Select Group Color")
        if color.isValid():
            group.color = color.name()
            self._refresh_groups_table()
            self._mark_dirty()
    
    def _auto_group_by_type(self):
        """Automatically create groups based on fixture categories."""
        if not self.project:
            QMessageBox.warning(self._get_active_window(), "No Project", "Please create or open a project first.")
            return
        
        if not self.project.fixtures:
            QMessageBox.information(self._get_active_window(), "No Fixtures", "No fixtures are patched. Add fixtures in the Patch tab first.")
            return
        
        # Group fixtures by category
        categories = {}
        for fixture in self.project.fixtures:
            category = fixture.profile.category
            if category not in categories:
                categories[category] = []
            categories[category].append(fixture.id)
        
        # Check for existing auto-groups
        existing_names = {g.name.lower() for g in self.project.groups}
        
        created = 0
        for category, fixture_ids in categories.items():
            group_name = f"All {category}"
            if group_name.lower() in existing_names:
                continue  # Skip if already exists
            
            # Assign color based on category
            colors = {
                "Moving Head": "#d35400",
                "Par": "#3498db",
                "Wash": "#2ecc71",
                "Strobe": "#f39c12",
                "Dimmer": "#9b59b6",
                "Laser": "#1abc9c",
                "Effect": "#e67e22",
            }
            color = colors.get(category, "#c97a50")
            
            import uuid
            group = FixtureGroup(
                id=str(uuid.uuid4()),
                name=group_name,
                fixture_ids=fixture_ids,
                color=color
            )
            self.project.groups.append(group)
            created += 1
        
        if created > 0:
            self._refresh_groups_table()
            self._rebuild_quick_effect_group_buttons()
            self._mark_dirty()
            QMessageBox.information(self._get_active_window(), "Groups Created", f"Created {created} new group{'s' if created != 1 else ''} based on fixture categories.")
        else:
            QMessageBox.information(self._get_active_window(), "No New Groups", "All category groups already exist.")
    
    # ==================== POSITIONS TAB ====================
    
