        popup.setStyleSheet("""
            QDialog {
                background-color: #2b2b2b;
                border: 2px solid #555;
                border-radius: 10px;
            }
            QPushButton {
                font-size: 16px;
                min-height: 52px;
                min-width: 220px;
                padding: 10px 24px;
                border-radius: 8px;
                font-weight: bold;
            }
        """)
