    def _quick_effect(self, effect_type: str, name: str):
        """Apply a quick preset effect."""
        
        if effect_type == "blackout":
            self.effect_engine.stop_effect(blackout=False, send_home=True)
            self.effect_engine.blackout()
            self._current_effect = None
            # NOTE: CREATE tab removed - preview_btn no longer exists
            # if hasattr(self, 'preview_btn'):
            #     self.preview_btn.setChecked(False)
            #     self.preview_btn.setEnabled(False)
            return
        
        # Create effect parameters
        target_groups = self._get_quick_effect_target_groups()
        target_fixtures = self._get_quick_effect_target_fixture_ids()
        effect = EffectParameters(
            target_groups=target_groups,
            target_fixtures=target_fixtures,
            description=name
        )
        
        # === STATIC COLORS ===
        if effect_type == "static_white":
            effect.effect_type = "static"
            effect.color = "#ffffff"
            effect.color_name = "white"
            effect.intensity = 100
        elif effect_type == "static_amber":
            effect.effect_type = "static"
            effect.color = "#ffbf00"
            effect.color_name = "amber"
            effect.intensity = 100
        elif effect_type == "static_red":
            effect.effect_type = "static"
            effect.color = "#ff0000"
            effect.color_name = "red"
            effect.intensity = 100
        elif effect_type == "static_blue":
            effect.effect_type = "static"
            effect.color = "#0066ff"
            effect.color_name = "blue"
            effect.intensity = 100
        elif effect_type == "static_green":
            effect.effect_type = "static"
            effect.color = "#00ff00"
            effect.color_name = "green"
            effect.intensity = 100
            
        # === PULSES ===
        elif effect_type == "pulse_blue":
            effect.effect_type = "pulse"
            effect.color = "#0066ff"
            effect.color_name = "blue"
            effect.intensity_min = 10
            effect.intensity_max = 100
            effect.speed_bpm = 40
            effect.movement_pattern = "sweep"
            effect.cycle_seconds = 12
            effect.pan_min = 40
            effect.pan_max = 215
        elif effect_type == "pulse_red":
            effect.effect_type = "pulse"
            effect.color = "#ff0000"
            effect.color_name = "red"
            effect.intensity_min = 10
            effect.intensity_max = 100
            effect.speed_bpm = 50
            effect.movement_pattern = "nod"
            effect.cycle_seconds = 10
        elif effect_type == "pulse_purple":
            effect.effect_type = "pulse"
            effect.color = "#8000ff"
            effect.color_name = "purple"
            effect.intensity_min = 20
            effect.intensity_max = 100
            effect.speed_bpm = 35
            effect.movement_pattern = "circle"
            effect.cycle_seconds = 15
            
        # === CHASES & RAINBOWS ===
        elif effect_type == "rainbow":
            effect.effect_type = "rainbow"
            effect.intensity = 100
            effect.speed_bpm = 30
            effect.movement_pattern = "sweep"
            effect.cycle_seconds = 20
            effect.pan_min = 30
            effect.pan_max = 225
        elif effect_type == "chase_rainbow":
            effect.effect_type = "chase"
            effect.color = "#ff0000"
            effect.color_palette = ["#ff0000", "#ff8000", "#ffff00", "#00ff00", "#00ffff", "#0000ff", "#ff00ff"]
            effect.intensity = 100
            effect.intensity_min = 0
            effect.intensity_max = 100
            effect.speed_bpm = 60
            effect.movement_pattern = "sweep"
            effect.cycle_seconds = 15
            
        # === FIRE EFFECT ===
        elif effect_type == "fire":
            effect.effect_type = "chase"
            effect.color = "#ff4500"
            effect.color_name = "fire"
            effect.color_palette = ["#ff0000", "#ff4500", "#ff6600", "#ff8c00", "#ffa500", "#ffcc00"]
            effect.intensity = 100
            effect.intensity_min = 40
            effect.intensity_max = 100
            effect.speed_bpm = 120
            effect.direction = "random"
            
        # === STROBES ===
        elif effect_type == "strobe":
            effect.effect_type = "strobe"
            effect.color = "#ffffff"
            effect.color_name = "white"
            effect.intensity = 100
            effect.intensity_min = 0
            effect.intensity_max = 100
            effect.speed_bpm = 240
            
        # === POLICE LIGHTS ===
        elif effect_type == "police":
            effect.effect_type = "chase"
            effect.color = "#ff0000"
            effect.color_name = "police"
            effect.color_palette = ["#ff0000", "#0000ff", "#ff0000", "#0000ff"]
            effect.intensity = 100
            effect.intensity_min = 0
            effect.intensity_max = 100
            effect.speed_bpm = 180
            
        # === PARTY MODE ===
        elif effect_type == "party":
            effect.effect_type = "chase"
            effect.color = "#ff00ff"
            effect.color_name = "party"
            effect.color_palette = ["#ff0000", "#ff00ff", "#00ffff", "#ffff00", "#00ff00", "#ff8000"]
            effect.intensity = 100
            effect.intensity_min = 20
            effect.intensity_max = 100
            effect.speed_bpm = 100
            effect.movement_pattern = "ballyhoo"
            effect.cycle_seconds = 8
            
        # === OCEAN CALM ===
        elif effect_type == "ocean":
            effect.effect_type = "pulse"
            effect.color = "#006994"
            effect.color_name = "ocean blue"
            effect.color_palette = ["#006994", "#00ced1", "#20b2aa", "#5f9ea0"]
            effect.intensity = 80
            effect.intensity_min = 30
            effect.intensity_max = 90
            effect.speed_bpm = 20
            effect.movement_pattern = "nod"
            effect.cycle_seconds = 18
            effect.tilt_min = 80
            effect.tilt_max = 160
            
        # === SUNSET GLOW ===
        elif effect_type == "sunset":
            effect.effect_type = "pulse"
            effect.color = "#ff6347"
            effect.color_name = "sunset"
            effect.color_palette = ["#ff6347", "#ff4500", "#ff8c00", "#ffd700", "#ff69b4"]
            effect.intensity = 85
            effect.intensity_min = 40
            effect.intensity_max = 95
            effect.speed_bpm = 15
            effect.movement_pattern = "sweep"
            effect.cycle_seconds = 25
            effect.pan_min = 50
            effect.pan_max = 205
            
        # === RANDOM ===
        elif effect_type == "random":
            effect.effect_type = "random"
            effect.description = "Randomize all channels"
        
        # === MOVING HEAD SHOWS (movement + color fades) ===
        elif effect_type == "mover_rainbow_sweep":
            # Rainbow colors fading while sweeping side to side
            effect.effect_type = "movement"
            effect.color = "#ff0000"
            effect.color_name = "rainbow"
            effect.intensity = 100
            effect.intensity_min = 60
            effect.intensity_max = 100
            effect.movement_pattern = "sweep"
            effect.cycle_seconds = 10
            effect.pan_min = 20
            effect.pan_max = 235
            effect.tilt_min = 80
            effect.tilt_max = 160
            effect.rainbow_colors = True
            
        elif effect_type == "mover_blue_fade":
            # Blue fading in/out while circling
            effect.effect_type = "movement"
            effect.color = "#0066ff"
            effect.color_name = "blue"
            effect.color_palette = ["#0000ff", "#0066ff", "#00ccff", "#00ffff", "#0066ff"]
