    def _create_refine_effect_subtab(self) -> QWidget:
        """Create the Effect sub-tab with effect type selection."""
        widget = QWidget()
        layout = QVBoxLayout(widget)
        layout.setContentsMargins(12, 12, 12, 12)
        layout.setSpacing(12)
        
        # Enable/Disable toggle for this sub-tab
        self.effect_subtab_toggle = QPushButton("⚙️ Effect Type: OFF")
        self.effect_subtab_toggle.setCheckable(True)
        self.effect_subtab_toggle.setChecked(False)
        self.effect_subtab_toggle.setMinimumHeight(44)
        self.effect_subtab_toggle.setStyleSheet("""
            QPushButton {
                font-weight: bold;
                background-color: #3d3d3d;
                border: 2px solid #555;
                border-radius: 6px;
                padding: 8px;
            }
            QPushButton:hover {
                background-color: #4d4d4d;
            }
            QPushButton:checked {
                background-color: #2d5a3d;
                border: 2px solid #4a9f4a;
            }
        """)
        self.effect_subtab_toggle.toggled.connect(lambda checked: self._on_subtab_toggle('effect', checked))
        layout.addWidget(self.effect_subtab_toggle)
        
        # Effect Type
        type_box = QGroupBox("Effect Type")
        type_layout = QVBoxLayout(type_box)
        type_layout.setContentsMargins(12, 12, 12, 12)
        type_layout.setSpacing(10)
        
        self.effect_type_combo = NoWheelComboBox()
        self.effect_type_combo.setMinimumHeight(44)
        self.effect_type_combo.addItems(['Static', 'Pulse', 'Chase', 'Fade', 'Rainbow', 'Movement', 
                                         '── Pixel Effects ──', 'Pixel Chase', 'Pixel Rainbow', 'Pixel Wipe',
                                         '── Pixel Patterns ──', 'Pixel Snake', 'Pixel Rain Drops',
                                         'Pixel Sine Wave', 'Pixel Clock', 'Pixel Orbits',
                                         'Pixel Starfield', 'Pixel Diamond', 'Pixel Butterfly',
                                         'Pixel Spinner', 'Pixel Ripple Pool'])
        # Make separator items non-selectable
        separator_idx = self.effect_type_combo.findText('── Pixel Effects ──')
        if separator_idx >= 0:
            model = self.effect_type_combo.model()
            item = model.item(separator_idx)
            item.setEnabled(False)
        separator_idx2 = self.effect_type_combo.findText('── Pixel Patterns ──')
        if separator_idx2 >= 0:
            model = self.effect_type_combo.model()
            item = model.item(separator_idx2)
            item.setEnabled(False)
        self.effect_type_combo.currentTextChanged.connect(self._on_effect_type_changed)
        type_layout.addWidget(self.effect_type_combo)
        
        # Effect type description
        self.effect_type_desc = QLabel("Select the type of lighting effect to apply.")
        self.effect_type_desc.setStyleSheet("color: #888; font-style: italic; font-size: 11px;")
        self.effect_type_desc.setWordWrap(True)
        type_layout.addWidget(self.effect_type_desc)
        
        layout.addWidget(type_box)
        layout.addStretch()
        return widget
    
