        main_layout.setSpacing(10)
        
        # Enable/Disable toggle for this sub-tab
        self.patterns_subtab_toggle = QPushButton("🎯 Moving Heads: OFF")
        self.patterns_subtab_toggle.setCheckable(True)
        self.patterns_subtab_toggle.setChecked(False)
        self.patterns_subtab_toggle.setMinimumHeight(44)
        self.patterns_subtab_toggle.setStyleSheet("""
            QPushButton {
                font-weight: bold;
                background-color: #3d3d3d;
                border: 2px solid #555;
                border-radius: 6px;
                padding: 8px;
            }
            QPushButton:hover {
                background-color: #4d4d4d;
            }
            QPushButton:checked {
                background-color: #2d5a3d;
                border: 2px solid #4a9f4a;
            }
        """)
        def _sync_patterns_toggle(checked):
            self._on_subtab_toggle('patterns', checked)
            # Keep movement subtab in sync so preset save/load sees both
            self.movement_subtab_toggle.blockSignals(True)
            self.movement_subtab_toggle.setChecked(checked)
            self.movement_subtab_toggle.blockSignals(False)
            if hasattr(self, '_current_effect') and self._current_effect:
                self._current_effect.movement_subtab_enabled = checked
        self.patterns_subtab_toggle.toggled.connect(_sync_patterns_toggle)
        main_layout.addWidget(self.patterns_subtab_toggle)
        
        # Use a scroll area for this tab since it has a lot of content
        scroll = TouchScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        
