    def _populate_gobo_groups(self):
        """Populate the gobo group combo with fixture groups that have gobo channels."""
        self.gobo_group_combo.blockSignals(True)
        self.gobo_group_combo.clear()
        
        # Find groups with fixtures that have gobo channels
        groups_with_gobos = []
        for group in self.project.groups:
            for fixture_id in group.fixture_ids:
                fixture = self.project.get_fixture_by_id(fixture_id)
                if not fixture:
                    continue
                # Use fixture.mode to get the correct mode's channels
                mode = fixture.mode
                if mode:
                    has_gobo = any(
                        ch.type == "gobo" and ch.gobo_slots
                        for ch in mode.channels
                    )
                    if has_gobo:
                        groups_with_gobos.append(group)
                        break
        
        if not groups_with_gobos:
            self.gobo_group_combo.addItem("No groups with gobos")
            self._clear_gobo_grid()
        else:
            for group in groups_with_gobos:
                self.gobo_group_combo.addItem(group.name, group)
            # Populate gobos for first group
            self._on_gobo_group_changed(0)
        
        self.gobo_group_combo.blockSignals(False)
    
    def _on_gobo_group_changed(self, index: int):
        """Handle gobo group selection change."""
        group = self.gobo_group_combo.currentData()
        if not group:
            self._clear_gobo_grid()
            return
        
        # Find gobo slots from first fixture with gobos
        gobo_slots = []
        for fixture_id in group.fixture_ids:
            fixture = self.project.get_fixture_by_id(fixture_id)
            if not fixture:
                continue
            mode = fixture.mode
            if mode:
                for ch in mode.channels:
                    if ch.type == "gobo" and ch.gobo_slots:
                        gobo_slots = ch.gobo_slots
                        break
            if gobo_slots:
                break
        
        self._populate_gobo_grid(gobo_slots)
    
    def _clear_gobo_grid(self):
        """Clear all gobo buttons from the grid."""
        for btn in self.gobo_buttons:
            btn.deleteLater()
        self.gobo_buttons.clear()
    
    def _populate_gobo_grid(self, gobo_slots: list):
        """Populate the gobo grid with buttons for each gobo slot."""
        self._clear_gobo_grid()
        
        if not gobo_slots:
            return
        
        # Add "Open" button first (value 0)
        open_btn = QPushButton("Open")
        open_btn.setMinimumSize(100, 60)
        open_btn.setCheckable(True)
        open_btn.setStyleSheet("""
            QPushButton {
                font-size: 14px;
                font-weight: bold;
                background-color: #3a3a3a;
                border: 2px solid #555;
                border-radius: 8px;
            }
            QPushButton:checked {
                background-color: #2d5a2d;
                border-color: #4CAF50;
            }
            QPushButton:hover {
                background-color: #4a4a4a;
            }
        """)
        open_btn.clicked.connect(lambda checked, v=0: self._on_gobo_selected(v))
        open_btn._gobo_value = 0  # Store value for later reference
        self.gobo_grid_layout.addWidget(open_btn, 0, 0)
        self.gobo_buttons.append(open_btn)
        
        # Add gobo slot buttons
        cols = 3
        for i, slot in enumerate(gobo_slots):
            row = (i + 1) // cols
            col = (i + 1) % cols
            
            name = slot.get("name", f"Gobo {i+1}")
            value = slot.get("value", i * 10)
            
            btn = QPushButton(name)
            btn.setMinimumSize(100, 60)
            btn.setCheckable(True)
            btn.setStyleSheet("""
                QPushButton {
                    font-size: 14px;
                    font-weight: bold;
                    background-color: #3a3a3a;
                    border: 2px solid #555;
                    border-radius: 8px;
                }
                QPushButton:checked {
                    background-color: #2d5a2d;
                    border-color: #4CAF50;
                }
                QPushButton:hover {
                    background-color: #4a4a4a;
                }
            """)
            btn.clicked.connect(lambda checked, v=value: self._on_gobo_selected(v))
            btn._gobo_value = value  # Store value for later reference
            self.gobo_grid_layout.addWidget(btn, row, col)
            self.gobo_buttons.append(btn)
        
        # Select "Open" by default
        if self.gobo_buttons:
            self.gobo_buttons[0].setChecked(True)
            self.current_gobo_value = 0
    
    def _on_gobo_selected(self, value: int):
        """Handle gobo button selection."""
        # Only apply gobo change if the Gobo subtab is enabled
        if not self._current_effect or not self._current_effect.gobo_subtab_enabled:
            # Gobo subtab is disabled - don't apply the change
            # Restore the previous button state
            for btn in self.gobo_buttons:
                btn.blockSignals(True)
                btn.setChecked(False)
                btn.blockSignals(False)
            return
        
        self.current_gobo_value = value
        
        # Update button states - only one can be selected
        for btn in self.gobo_buttons:
            # Find button's value by checking which one was clicked
            btn.blockSignals(True)
            btn.setChecked(False)
            btn.blockSignals(False)
        
        # Find and check the correct button
        # Open button is value 0, others are from gobo_slots
        group = self.gobo_group_combo.currentData()
        if group:
            gobo_slots = []
            for fixture_id in group.fixture_ids:
                fixture = self.project.get_fixture_by_id(fixture_id)
                if not fixture:
                    continue
                mode = fixture.mode
                if mode:
                    for ch in mode.channels:
                        if ch.type == "gobo" and ch.gobo_slots:
                            gobo_slots = ch.gobo_slots
                            break
                if gobo_slots:
                    break
            
            # Find index: 0 = Open, 1+ = gobo slots
            if value == 0:
                idx = 0
            else:
                idx = next((i + 1 for i, s in enumerate(gobo_slots) if s.get("value") == value), -1)
            
            if 0 <= idx < len(self.gobo_buttons):
                self.gobo_buttons[idx].blockSignals(True)
                self.gobo_buttons[idx].setChecked(True)
                self.gobo_buttons[idx].blockSignals(False)
        
        # Apply gobo to fixtures
        self._apply_gobo_to_fixtures(value)
        
        # Update preset gobo_value
        if hasattr(self, 'refine_gobo_value'):
            self.refine_gobo_value = value
    
    def _apply_gobo_to_fixtures(self, gobo_value: int):
        """Apply gobo value to selected fixture group."""
        group = self.gobo_group_combo.currentData()
        if not group:
            return
        
        # Update current effect's gobo_value for preset saving
        if self._current_effect:
            self._current_effect.gobo_value = gobo_value
        
        artnet = get_artnet_output()
        for fixture_id in group.fixture_ids:
            fixture = self.project.get_fixture_by_id(fixture_id)
            if not fixture:
                continue
            mode = fixture.mode
            if mode:
                for i, ch in enumerate(mode.channels):
                    if ch.type == "gobo":
                        dmx_addr = fixture.address + i
                        if 1 <= dmx_addr <= 512:
                            artnet.set_channel(fixture.universe, dmx_addr, gobo_value)
    
