    def _filter_refine_presets(self, text: str):
        """Filter the preset dropdown based on search text."""
        self._refresh_refine_presets(filter_text=text)

    def _refresh_refine_presets(self, filter_text: str | None = None):
        """Refresh the preset dropdown in refine tab, grouped by category.
        
        Args:
            filter_text: Optional search text to filter presets by name.
        """
        current_id = self._refine_loaded_preset_id
        self.refine_preset_combo.blockSignals(True)
        self.refine_preset_combo.clear()
        self.refine_preset_combo.addItem("-- Select a preset to refine --")
        
        # Get filter text from search field if not provided
        if filter_text is None and hasattr(self, 'refine_preset_search'):
            filter_text = self.refine_preset_search.text()
        search_lower = (filter_text or "").strip().lower()
        
        # Group presets by category, applying filter
        categories = {}
        for preset in self.project.presets:
            # Filter by name if search text is provided
            if search_lower and search_lower not in preset.name.lower():
                continue
            cat = preset.category or "General"
            if cat not in categories:
                categories[cat] = []
            categories[cat].append(preset)
        
        # Add presets grouped by category
        for cat_name in sorted(categories.keys()):
            # Add category header (disabled item)
            self.refine_preset_combo.addItem(f"── {cat_name} ──")
            # Make the category header unselectable
            idx = self.refine_preset_combo.count() - 1
            self.refine_preset_combo.model().item(idx).setEnabled(False)
            
            # Add presets in this category
            for preset in sorted(categories[cat_name], key=lambda p: p.name):
                self.refine_preset_combo.addItem(f"    {preset.name} ({preset.effect_type})", preset.id)
        
        # Restore selection if possible
        if current_id:
            for i in range(self.refine_preset_combo.count()):
                if self.refine_preset_combo.itemData(i) == current_id:
                    self.refine_preset_combo.setCurrentIndex(i)
                    break
        
        self.refine_preset_combo.blockSignals(False)
    
    def _refresh_presets_tab(self):
        """Refresh presets display (stub for future presets tab)."""
        # This is a placeholder for when a dedicated presets tab is added
        pass
    
    def _refresh_refine_target_groups(self):
        """Refresh the target groups checkboxes in refine tab."""
        # Remember currently checked groups
        previously_checked = [name for name, cb in self.target_group_checkboxes.items() if cb.isChecked()]
        
        # Clear existing checkboxes
        for cb in self.target_group_checkboxes.values():
            self.target_groups_layout.removeWidget(cb)
            cb.deleteLater()
        self.target_group_checkboxes.clear()
        
        # Rebuild checkboxes for current groups
        all_checked = self.target_all_checkbox.isChecked()
        for group in self.project.groups:
            cb = QCheckBox(group.name)
            cb.setEnabled(not all_checked)
            cb.setChecked(group.name in previously_checked)
            cb.stateChanged.connect(self._on_refine_param_changed)
            self.target_groups_layout.addWidget(cb)
            self.target_group_checkboxes[group.name] = cb
    
    def _on_target_all_changed(self, state: int):
        """Handle 'All Fixtures' checkbox change."""
        all_checked = state == Qt.CheckState.Checked.value
        for cb in self.target_group_checkboxes.values():
            cb.setEnabled(not all_checked)
            if all_checked:
                cb.setChecked(False)
        self._on_refine_param_changed()
    
    def _load_current_effect_into_refine(self):
        """Load the current effect from CREATE tab into REFINE tab controls.
        
        This allows users to tweak an effect from the CREATE tab before saving.
        """
        if not self._current_effect:
            return
        
        effect = self._current_effect
        
        # Clear any loaded preset reference since we're loading from CREATE tab
        self._refine_loaded_preset_id = None
        # Show the actual effect name/description so it updates as user picks effects
        effect_display_name = getattr(effect, 'description', '') or effect.effect_type or 'Effect'
        self.refine_editing_label.setText(f"Editing: <b>{effect_display_name}</b> (unsaved)")
        self.refine_update_preset_btn.setEnabled(False)
        self.preset_rename_btn.setEnabled(False)
        self.preset_duplicate_btn.setEnabled(False)
        self.preset_delete_btn.setEnabled(False)
        
        # Reset the preset combo to "Select a preset"
        self.refine_preset_combo.blockSignals(True)
        self.refine_preset_combo.setCurrentIndex(0)
        self.refine_preset_combo.blockSignals(False)
        
        # Store original values for speed scaling calculations
        self._refine_original_bpm = effect.speed_bpm if effect.speed_bpm > 0 else 120
        self._refine_original_cycle_seconds = effect.cycle_seconds if effect.cycle_seconds and effect.cycle_seconds > 0 else 0
        
        # Load effect values into controls (block signals to prevent live update during load)
        self.effect_type_combo.blockSignals(True)
        self.intensity_slider.blockSignals(True)
        self.intensity_min_spin.blockSignals(True)
        self.intensity_max_spin.blockSignals(True)
        self.speed_spin.blockSignals(True)
        self.speed_slider.blockSignals(True)
        self.direction_combo.blockSignals(True)
        self.pan_min_spin.blockSignals(True)
        self.pan_max_spin.blockSignals(True)
        self.tilt_min_spin.blockSignals(True)
        self.tilt_max_spin.blockSignals(True)
        self.rainbow_colors_checkbox.blockSignals(True)
        
        # Effect type
        idx = self.effect_type_combo.findText(effect_type_to_display(effect.effect_type))
        if idx >= 0:
            self.effect_type_combo.setCurrentIndex(idx)
        
        # Intensity
        self.intensity_slider.setValue(effect.intensity)
        self.intensity_label.setText(f"{effect.intensity}%")
        self.intensity_min_spin.setValue(effect.intensity_min)
        self.intensity_max_spin.setValue(effect.intensity_max)
        
        # Speed
        self.speed_spin.setValue(effect.speed_bpm)
        self.speed_slider.setValue(effect.speed_bpm)
        
        # Direction
        idx = self.direction_combo.findText(effect.direction.title())
        if idx >= 0:
            self.direction_combo.setCurrentIndex(idx)
        
        # Movement settings - select the appropriate movement button
        self._set_movement_pattern_from_preset(effect.movement_pattern)
        self.pan_min_spin.setValue(effect.pan_min)
        self.pan_max_spin.setValue(effect.pan_max)
        self.tilt_min_spin.setValue(effect.tilt_min)
        self.tilt_max_spin.setValue(effect.tilt_max)
        self.rainbow_colors_checkbox.setChecked(effect.rainbow_colors)
        
        # Color palette - prefer color_palette if present, otherwise use single color
        if hasattr(effect, 'color_palette') and effect.color_palette:
            self.palette_colors = effect.color_palette.copy()
        elif effect.color:
            self.palette_colors = [effect.color]
        else:
            self.palette_colors = []
        self._selected_palette_index = -1
        self._refresh_palette_display()
        
        # Target - handle checkboxes
        self.target_all_checkbox.blockSignals(True)
        for cb in self.target_group_checkboxes.values():
            cb.blockSignals(True)
        
        if effect.target_groups and "all" not in [g.lower() for g in effect.target_groups]:
            self.target_all_checkbox.setChecked(False)
            # Enable and check appropriate group checkboxes
            for name, cb in self.target_group_checkboxes.items():
                cb.setEnabled(True)
                cb.setChecked(name in effect.target_groups)
        else:
            self.target_all_checkbox.setChecked(True)
            # Disable and uncheck all group checkboxes
            for cb in self.target_group_checkboxes.values():
                cb.setEnabled(False)
                cb.setChecked(False)
        
        self.target_all_checkbox.blockSignals(False)
        for cb in self.target_group_checkboxes.values():
            cb.blockSignals(False)
        
        # Load sub-tab toggle states from effect
        self.color_subtab_toggle.blockSignals(True)
        self.effect_subtab_toggle.blockSignals(True)
        self.speed_subtab_toggle.blockSignals(True)
        self.strobe_subtab_toggle.blockSignals(True)
        self.movement_subtab_toggle.blockSignals(True)
        self.patterns_subtab_toggle.blockSignals(True)
        self.position_subtab_toggle.blockSignals(True)
        self.gobo_subtab_toggle.blockSignals(True)
        self.intensity_subtab_toggle.blockSignals(True)
        self.target_subtab_toggle.blockSignals(True)
        
        self.color_subtab_toggle.setChecked(getattr(effect, 'color_subtab_enabled', False))
        self.effect_subtab_toggle.setChecked(getattr(effect, 'effect_subtab_enabled', False))
        self.speed_subtab_toggle.setChecked(getattr(effect, 'speed_subtab_enabled', False))
        self.strobe_subtab_toggle.setChecked(getattr(effect, 'strobe_subtab_enabled', False))
        self.movement_subtab_toggle.setChecked(getattr(effect, 'movement_subtab_enabled', False))
        self.patterns_subtab_toggle.setChecked(getattr(effect, 'patterns_subtab_enabled', False))
        self.position_subtab_toggle.setChecked(getattr(effect, 'position_subtab_enabled', False))
        self.gobo_subtab_toggle.setChecked(getattr(effect, 'gobo_subtab_enabled', False))
        self.intensity_subtab_toggle.setChecked(getattr(effect, 'intensity_subtab_enabled', False))
        self.target_subtab_toggle.setChecked(getattr(effect, 'target_subtab_enabled', False))
        
        self.color_subtab_toggle.blockSignals(False)
        self.effect_subtab_toggle.blockSignals(False)
        self.speed_subtab_toggle.blockSignals(False)
        self.strobe_subtab_toggle.blockSignals(False)
        self.movement_subtab_toggle.blockSignals(False)
        self.patterns_subtab_toggle.blockSignals(False)
        self.position_subtab_toggle.blockSignals(False)
        self.gobo_subtab_toggle.blockSignals(False)
        self.intensity_subtab_toggle.blockSignals(False)
        self.target_subtab_toggle.blockSignals(False)
        
        # Unblock signals
        self.effect_type_combo.blockSignals(False)
        self.intensity_slider.blockSignals(False)
        self.intensity_min_spin.blockSignals(False)
        self.intensity_max_spin.blockSignals(False)
        self.speed_spin.blockSignals(False)
        self.speed_slider.blockSignals(False)
        self.direction_combo.blockSignals(False)
        self.pan_min_spin.blockSignals(False)
        self.pan_max_spin.blockSignals(False)
        self.tilt_min_spin.blockSignals(False)
        self.tilt_max_spin.blockSignals(False)
        self.rainbow_colors_checkbox.blockSignals(False)
        
        # Also sync to detached REFINE window if open
        self._sync_effect_to_detached_refine()
        
        # Do NOT auto-start the effect when loading into REFINE.
        # The user must explicitly click "Play" to start playback.
        # Previously called self._apply_manual_effect() here which auto-played.
    
    def _sync_refine_controls_from_effect(self, effect: EffectParameters):
        """Sync main REFINE tab controls from an effect WITHOUT restarting the effect.
        
        This is called when a preset is executed from the EXECUTE tab to ensure
        the REFINE controls match the running effect. Without this, adjusting
        the intensity slider would read the wrong effect_type from the combo box.
        """
        # Block signals to prevent triggering _update_live_effect during sync
        self.effect_type_combo.blockSignals(True)
        self.intensity_slider.blockSignals(True)
        self.intensity_min_spin.blockSignals(True)
        self.intensity_max_spin.blockSignals(True)
        self.speed_spin.blockSignals(True)
        self.speed_slider.blockSignals(True)
        self.direction_combo.blockSignals(True)
        self.pan_min_spin.blockSignals(True)
        self.pan_max_spin.blockSignals(True)
        self.tilt_min_spin.blockSignals(True)
        self.tilt_max_spin.blockSignals(True)
        self.rainbow_colors_checkbox.blockSignals(True)
        
        # Effect type - CRITICAL for rainbow effects
        idx = self.effect_type_combo.findText(effect_type_to_display(effect.effect_type))
        if idx >= 0:
            self.effect_type_combo.setCurrentIndex(idx)
        
        # Intensity
        self.intensity_slider.setValue(effect.intensity)
        self.intensity_label.setText(f"{effect.intensity}%")
        self.intensity_min_spin.setValue(effect.intensity_min)
        self.intensity_max_spin.setValue(effect.intensity_max)
        
        # Speed
        self.speed_spin.setValue(effect.speed_bpm)
        self.speed_slider.setValue(effect.speed_bpm)

        # Mover speed/offset UI (separate controls used for movement overlay)
        if hasattr(self, 'mover_speed_slider'):
            try:
                self.mover_speed_slider.blockSignals(True)
                self.mover_speed_slider.setValue(max(0, min(120, int(effect.speed_bpm))))
                self.mover_speed_label.setText(f"{max(0, min(120, int(effect.speed_bpm)))} BPM")
            finally:
                self.mover_speed_slider.blockSignals(False)
        if hasattr(self, 'mover_offset_slider'):
            try:
                self.mover_offset_slider.blockSignals(True)
                offset_val = int(round(max(0.0, min(1.0, float(getattr(effect, 'fixture_offset', 0.25)))) * 100.0))
                self.mover_offset_slider.setValue(max(0, min(100, offset_val)))
                self.mover_offset_label.setText(f"{max(0, min(100, offset_val))}%")
            finally:
                self.mover_offset_slider.blockSignals(False)
        
        # Direction
        idx = self.direction_combo.findText(effect.direction.title())
        if idx >= 0:
            self.direction_combo.setCurrentIndex(idx)
        
        # Movement settings
        self._set_movement_pattern_from_preset(effect.movement_pattern)
        self.pan_min_spin.setValue(effect.pan_min)
        self.pan_max_spin.setValue(effect.pan_max)
        self.tilt_min_spin.setValue(effect.tilt_min)
        self.tilt_max_spin.setValue(effect.tilt_max)
        self.rainbow_colors_checkbox.setChecked(effect.rainbow_colors)
        
        # Color palette - sync to self.palette_colors so _update_live_effect uses them
        if hasattr(effect, 'color_palette') and effect.color_palette:
            self.palette_colors = effect.color_palette.copy()
        elif effect.color:
            self.palette_colors = [effect.color]
        else:
            self.palette_colors = []
        self._selected_palette_index = -1
        self._refresh_palette_display()
        
        # Target groups
        self.target_all_checkbox.blockSignals(True)
        for cb in self.target_group_checkboxes.values():
            cb.blockSignals(True)
        
        if effect.target_groups and "all" not in [g.lower() for g in effect.target_groups]:
            self.target_all_checkbox.setChecked(False)
            for name, cb in self.target_group_checkboxes.items():
                cb.setEnabled(True)
                cb.setChecked(name in effect.target_groups)
        else:
            self.target_all_checkbox.setChecked(True)
            for cb in self.target_group_checkboxes.values():
                cb.setEnabled(False)
                cb.setChecked(False)
        
        self.target_all_checkbox.blockSignals(False)
        for cb in self.target_group_checkboxes.values():
            cb.blockSignals(False)
        
        # Unblock all signals
        self.effect_type_combo.blockSignals(False)
        self.intensity_slider.blockSignals(False)
        self.intensity_min_spin.blockSignals(False)
        self.intensity_max_spin.blockSignals(False)
        self.speed_spin.blockSignals(False)
        self.speed_slider.blockSignals(False)
        self.direction_combo.blockSignals(False)
        self.pan_min_spin.blockSignals(False)
        self.pan_max_spin.blockSignals(False)
        self.tilt_min_spin.blockSignals(False)
        self.tilt_max_spin.blockSignals(False)
        self.rainbow_colors_checkbox.blockSignals(False)
        
        # Load sub-tab toggle states
        self.color_subtab_toggle.blockSignals(True)
        self.effect_subtab_toggle.blockSignals(True)
        self.speed_subtab_toggle.blockSignals(True)
        self.strobe_subtab_toggle.blockSignals(True)
        self.movement_subtab_toggle.blockSignals(True)
        self.patterns_subtab_toggle.blockSignals(True)
        self.position_subtab_toggle.blockSignals(True)
        self.gobo_subtab_toggle.blockSignals(True)
        self.intensity_subtab_toggle.blockSignals(True)
        self.target_subtab_toggle.blockSignals(True)
        
        self.color_subtab_toggle.setChecked(getattr(effect, 'color_subtab_enabled', False))
        self.effect_subtab_toggle.setChecked(getattr(effect, 'effect_subtab_enabled', False))
        self.speed_subtab_toggle.setChecked(getattr(effect, 'speed_subtab_enabled', False))
        self.strobe_subtab_toggle.setChecked(getattr(effect, 'strobe_subtab_enabled', False))
        self.movement_subtab_toggle.setChecked(getattr(effect, 'movement_subtab_enabled', False))
        self.patterns_subtab_toggle.setChecked(getattr(effect, 'patterns_subtab_enabled', False))
        self.position_subtab_toggle.setChecked(getattr(effect, 'position_subtab_enabled', False))
        self.gobo_subtab_toggle.setChecked(getattr(effect, 'gobo_subtab_enabled', False))
        self.intensity_subtab_toggle.setChecked(getattr(effect, 'intensity_subtab_enabled', False))
        self.target_subtab_toggle.setChecked(getattr(effect, 'target_subtab_enabled', False))
        
        # Update button text to show ON/OFF status
        label_map = {
            'color': '🎨 Color',
            'effect': '⚙️ Effect Type',
            'speed': '⏱️ Speed',
            'strobe': '💡 Strobe',
            'movement': '🎯 Movement',
            'patterns': '🎯 Moving Heads',
            'position': '📍 Position',
            'gobo': '🎬 Gobo',
            'intensity': '💪 Intensity',
            'target': '🎲 Target'
        }
        subtab_toggles = [
            ('color', self.color_subtab_toggle),
            ('effect', self.effect_subtab_toggle),
            ('speed', self.speed_subtab_toggle),
            ('strobe', self.strobe_subtab_toggle),
            ('movement', self.movement_subtab_toggle),
            ('patterns', self.patterns_subtab_toggle),
            ('position', self.position_subtab_toggle),
            ('gobo', self.gobo_subtab_toggle),
            ('intensity', self.intensity_subtab_toggle),
            ('target', self.target_subtab_toggle)
        ]
        for name, toggle in subtab_toggles:
            is_enabled = toggle.isChecked()
            label = label_map.get(name, name.title())
            status = "ON" if is_enabled else "OFF"
            toggle.setText(f"{label}: {status}")
        
        self.color_subtab_toggle.blockSignals(False)
        self.effect_subtab_toggle.blockSignals(False)
        self.speed_subtab_toggle.blockSignals(False)
        self.strobe_subtab_toggle.blockSignals(False)
        self.movement_subtab_toggle.blockSignals(False)
        self.patterns_subtab_toggle.blockSignals(False)
        self.position_subtab_toggle.blockSignals(False)
        self.gobo_subtab_toggle.blockSignals(False)
        self.intensity_subtab_toggle.blockSignals(False)
        self.target_subtab_toggle.blockSignals(False)
        
        print(f"[Sync] Main REFINE controls synced from effect: type={effect.effect_type}, rainbow={effect.rainbow_colors}")

    def _sync_effect_to_detached_refine(self):
        """Sync the current effect to any detached REFINE windows."""
        if not self._current_effect:
            print("[Sync] No current effect to sync")
            return
        
        print(f"[Sync] Syncing effect to {len(self._detached_refine_widgets)} detached REFINE windows")
        
        effect = self._current_effect
        
        for widgets in self._detached_refine_widgets:
            try:
                print(f"[Sync] Syncing to detached window with {len(widgets)} widgets")
                # Block signals to prevent feedback loops
                for w in widgets.values():
                    if hasattr(w, 'blockSignals'):
                        w.blockSignals(True)
                
                # Effect type
                combo = widgets.get('effect_type_combo')
                if combo:
                    idx = combo.findText(effect_type_to_display(effect.effect_type))
                    if idx >= 0:
                        combo.setCurrentIndex(idx)
                
                # Intensity
                slider = widgets.get('intensity_slider')
                label = widgets.get('intensity_label')
                if slider:
                    slider.setValue(effect.intensity)
                if label:
                    label.setText(f"{effect.intensity}%")
                
                min_spin = widgets.get('intensity_min_spin')
                max_spin = widgets.get('intensity_max_spin')
                if min_spin:
                    min_spin.setValue(effect.intensity_min)
                if max_spin:
                    max_spin.setValue(effect.intensity_max)
                
                # Speed
                speed_spin = widgets.get('speed_spin')
                speed_slider = widgets.get('speed_slider')
                if speed_spin:
                    speed_spin.setValue(effect.speed_bpm)
                if speed_slider:
                    speed_slider.setValue(effect.speed_bpm)

                mover_speed_slider = widgets.get('mover_speed_slider')
                mover_speed_label = widgets.get('mover_speed_label')
                if mover_speed_slider:
                    val = max(0, min(120, int(effect.speed_bpm)))
                    mover_speed_slider.setValue(val)
                    if mover_speed_label:
                        mover_speed_label.setText(f"{val} BPM")

                mover_offset_slider = widgets.get('mover_offset_slider')
                mover_offset_label = widgets.get('mover_offset_label')
                if mover_offset_slider:
                    offset_val = int(round(max(0.0, min(1.0, float(getattr(effect, 'fixture_offset', 0.25)))) * 100.0))
                    offset_val = max(0, min(100, offset_val))
                    mover_offset_slider.setValue(offset_val)
                    if mover_offset_label:
                        mover_offset_label.setText(f"{offset_val}%")
                
                # Direction
                direction_combo = widgets.get('direction_combo')
                if direction_combo:
                    idx = direction_combo.findText(effect.direction.title())
                    if idx >= 0:
                        direction_combo.setCurrentIndex(idx)
                
                # Pan/Tilt settings
                pan_min = widgets.get('pan_min_spin')
                pan_max = widgets.get('pan_max_spin')
                tilt_min = widgets.get('tilt_min_spin')
                tilt_max = widgets.get('tilt_max_spin')
                if pan_min:
                    pan_min.setValue(effect.pan_min)
                if pan_max:
                    pan_max.setValue(effect.pan_max)
                if tilt_min:
                    tilt_min.setValue(effect.tilt_min)
                if tilt_max:
                    tilt_max.setValue(effect.tilt_max)
                
                # Rainbow checkbox
                rainbow_cb = widgets.get('rainbow_colors_checkbox')
                if rainbow_cb:
                    rainbow_cb.setChecked(effect.rainbow_colors)
                
                # Movement pattern buttons - clear all first
                sync_btns = widgets.get('mover_sync_buttons', {})
                wave_btns = widgets.get('mover_wave_buttons', {})
                for btn in list(sync_btns.values()) + list(wave_btns.values()):
                    if btn:
                        btn.blockSignals(True)
                        btn.setChecked(False)
                        btn.blockSignals(False)
                
                # Check the appropriate movement button
                pattern = effect.movement_pattern or ''
                if pattern and pattern.lower() not in ('none', ''):
                    if pattern in sync_btns and sync_btns[pattern]:
                        sync_btns[pattern].setChecked(True)
                    elif pattern in wave_btns and wave_btns[pattern]:
                        wave_btns[pattern].setChecked(True)
                
                # Target checkboxes
                target_all = widgets.get('target_all_checkbox')
                target_cbs = widgets.get('target_group_checkboxes', {})
                
                if effect.target_groups and "all" not in [g.lower() for g in effect.target_groups]:
                    if target_all:
                        target_all.setChecked(False)
                    for name, cb in target_cbs.items():
                        if cb:
                            cb.setEnabled(True)
                            cb.setChecked(name in effect.target_groups)
                else:
                    if target_all:
                        target_all.setChecked(True)
                    for cb in target_cbs.values():
                        if cb:
                            cb.setEnabled(False)
                            cb.setChecked(False)
                
                # Update editing label
                editing_label = widgets.get('refine_editing_label')
                if editing_label:
                    effect_display_name = getattr(effect, 'description', '') or effect.effect_type or 'Effect'
                    editing_label.setText(f"Editing: <b>{effect_display_name}</b> (unsaved)")
                
                # Disable preset buttons since this is from CREATE
                for btn_name in ['refine_update_preset_btn', 'preset_rename_btn', 'preset_duplicate_btn', 'preset_delete_btn']:
                    btn = widgets.get(btn_name)
                    if btn:
                        btn.setEnabled(False)
                
                # Reset preset combo
                preset_combo = widgets.get('refine_preset_combo')
                if preset_combo:
                    preset_combo.setCurrentIndex(0)
                
            except Exception as e:
                print(f"Error syncing effect to detached REFINE: {e}")
            finally:
                # Unblock signals
                for w in widgets.values():
                    if hasattr(w, 'blockSignals'):
                        w.blockSignals(False)
    
