    def _clear_all_execution_midi_mappings(self):
        """Clear all MIDI mappings for execution buttons (presets + OFF + Blackout), but keep master/speed faders."""
        reply = QMessageBox.question(
            self._get_active_window(), 
            "Clear All Execution MIDI Mappings",
            "This will remove MIDI mappings from all execution buttons (effects + OFF + Blackout).\n\n"
            "Master fader and Effect Speed fader mappings will be kept.\n\n"
            "Are you sure?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No
        )
        
        if reply == QMessageBox.StandardButton.Yes:
            midi_mgr = get_midi_manager()
            
            # Clear OFF button mapping
            midi_mgr.clear_mappings_for_preset("__OFF__")
            midi_mgr.unregister_preset_callback("__OFF__")
            
            # Clear Blackout button mapping
            midi_mgr.clear_mappings_for_preset("__BLACKOUT__")
            midi_mgr.unregister_preset_callback("__BLACKOUT__")
            
            # Clear all preset mappings
            for preset in self.project.presets:
                midi_mgr.clear_mappings_for_preset(preset.id)
                midi_mgr.unregister_preset_callback(preset.id)
            
            # Save mappings (this keeps fader mappings intact)
            self.app_settings['midi_mappings'] = midi_mgr.get_mappings_dict()
            self._save_app_settings()
            
            # Refresh buttons to remove borders
            self._refresh_execute_buttons()
            
            print("[MIDI] Cleared all execution button MIDI mappings (kept master/speed faders)")
            
            QMessageBox.information(
                self,
                "MIDI Mappings Cleared",
                "All execution button MIDI mappings have been cleared.\n\n"
                "Master and Effect Speed fader mappings were kept."
            )

    def _rename_execute_preset(self, preset, button):
        """Rename a preset via input dialog."""
        from PyQt6.QtWidgets import QInputDialog
        parent = button.window() if button else self
        new_name, ok = QInputDialog.getText(
            parent,
            "Rename Preset",
            "New name:",
            text=preset.name
        )
        if ok and new_name.strip():
            preset.name = new_name.strip()
            self._mark_dirty()
            self._refresh_execute_buttons()
            # Also refresh the presets list if it exists
            if hasattr(self, 'preset_list'):
                for i in range(self.preset_list.count()):
                    item = self.preset_list.item(i)
                    if item and item.data(Qt.ItemDataRole.UserRole) == preset.id:
                        item.setText(preset.name)
                        break
            print(f"[Preset] Renamed preset to '{preset.name}'")

    def _change_preset_color(self, preset, button):
        """Change the color of a preset via color picker."""
        from PyQt6.QtWidgets import QColorDialog
        
        # Get current color
        current_color = QColor(preset.color) if preset.color else QColor("#c97a50")
        
        # Use the button's window as parent so dialog appears on correct screen
        parent = button.window() if button else self
        
        # Open color dialog
        color = QColorDialog.getColor(
            current_color, 
            parent, 
            f"Choose Color for {preset.name}",
            QColorDialog.ColorDialogOption.ShowAlphaChannel
        )
        
        if color.isValid():
            new_color = color.name()  # Returns hex like #rrggbb
            preset.color = new_color
            self._mark_dirty()
            
            # Update MIDI LED color if this preset has a mapping
            midi_mgr = get_midi_manager()
            midi_mappings = midi_mgr.get_mappings_for_preset(preset.id)
            if midi_mappings and midi_mgr.is_connected:
                # Update the stored color and refresh LED
                midi_mgr.set_preset_color(preset.id, new_color)
                led_color = midi_mgr.get_preset_led_color(preset.id)
                for midi_key in midi_mappings:
                    midi_mgr.update_led_for_mapping(midi_key, True, led_color)
            
            # Refresh buttons to show new stripe color
            self._refresh_execute_buttons()
            
            print(f"[Preset] Changed color of '{preset.name}' to {new_color}")
    
    def _delete_execute_preset(self, preset, button=None):
        """Delete a preset from the execute tab."""
        # Use the button's window as parent so dialog appears on correct screen
        parent = button.window() if button else self
        reply = QMessageBox.question(
            parent, "Delete Preset",
            f"Delete preset '{preset.name}'?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
        )
        if reply == QMessageBox.StandardButton.Yes:
            # Save undo info before deleting
            page_ids = [pg.id for pg in self.project.execute_pages if preset.id in pg.preset_ids]
            self._undo_preset_stack.append({
                'action': 'delete',
                'preset': preset,
                'page_ids': page_ids,
            })
            self.project.presets.remove(preset)
            # Also remove from all execute pages to avoid orphan references
            for pg in self.project.execute_pages:
                if preset.id in pg.preset_ids:
                    pg.preset_ids.remove(preset.id)
            self._mark_dirty()
            self._refresh_execute_buttons()
            self._refresh_presets_list()
            # If we deleted the active preset, clear the selection
            if self._active_execute_preset_id == preset.id:
                self._active_execute_preset_id = None
            self.statusBar().showMessage(f"Deleted '{preset.name}'. Press Ctrl+Z to undo.", 10000)
    
    def _execute_preset(self, preset):
        """Execute a preset - start the effect immediately."""
        print(f"[Execute] Running preset: {preset.name}")
        print(f"[Execute] Preset movement_pattern: {getattr(preset, 'movement_pattern', 'NOT SET')}")

        # If the default look is running, stop its HTP layers first so they
        # don't interfere with the new preset's output.
        self._stop_default_look_if_active()

        # Release any manual fixture-control / trackpad / overlay claims so the
        # preset can take full control of its target fixtures.  Otherwise
        # hand-edited channels would stay stuck and the preset couldn't drive
        # them.
        self._release_overlay_claims_for_effect()

        # ── If the preset has layers, use HTP multi-effect engine ────────
        layers_data = getattr(preset, 'layers', None) or []
        if layers_data:
            print(f"[Execute] Preset has {len(layers_data)} layers — using HTP engine")
            engine = getattr(self, 'effect_engine', None)
            if engine:
                # Stop BOTH engine modes so a previously running non-layered
                # (legacy) preset doesn't keep driving channels underneath the
                # new layered preset.  Blackout stale channels so the
                # transition matches the clean "preset → off → preset" path.
                if engine.is_running():
                    engine.stop_effect(blackout=True, send_home=False)
                engine.stop_all_effects_htp()
                for ld in layers_data:
                    try:
                        layer = EffectLayer.from_dict(ld)
                        if layer.enabled:
                            params = layer.to_effect_params()
                            # Prevent static intensity layers from pulsing
                            # due to leftover default min/max values (0/100).
                            # Look presets should hold a fixed dimmer.
                            if (layer.layer_type == 'intensity'
                                    and layer.effect_type == 'static'
                                    and params.effect_type == 'pulse'):
                                params.effect_type = 'static'
                                params.intensity_min = layer.intensity
                                params.intensity_max = layer.intensity
                            engine.start_effect_htp(layer.id, params)
                    except Exception as exc:
                        print(f"[Execute] Layer error: {exc}")
                # Update execute button selection
                self._update_execute_button_selection(preset.id)
            return
        
        # Detect whether this is a partial preset (only some subtabs enabled).
        # A partial preset should MERGE with the running effect instead of replacing it.
        _subtab_names = ['color', 'effect', 'speed', 'strobe', 'movement', 'patterns',
                         'position', 'gobo', 'intensity', 'target']
        _any_enabled = any(getattr(preset, f'{s}_subtab_enabled', False) for s in _subtab_names)
        _all_enabled = all(getattr(preset, f'{s}_subtab_enabled', False) for s in _subtab_names)
        is_partial = _any_enabled and not _all_enabled
        
        # Apply master speed from preset BEFORE starting effect
        # Skip for partial presets unless the speed subtab is explicitly enabled
        if not is_partial or getattr(preset, 'speed_subtab_enabled', False):
            master_speed = getattr(preset, 'master_speed', 100)
            if hasattr(self, 'effect_speed_slider'):
                self.effect_speed_slider.blockSignals(True)
                self.effect_speed_slider.setValue(master_speed)
                self.effect_speed_slider.blockSignals(False)
                self._on_effect_speed_changed(master_speed)
                print(f"[Execute] Set master speed to {master_speed}% ({master_speed/100.0:.2f}x)")
        
        # Set pan/tilt speed to SLOW for smooth transitions between presets
        # Skip for partial presets that only change movement (they manage their own speed)
        if not is_partial:
            self._set_pan_tilt_speed_slow()
        
        # Store preset info and delay the actual effect start by 100ms
        # For partial presets, apply immediately (no need for speed channel delay)
        from PyQt6.QtCore import QTimer
        if is_partial and self.effect_engine._running:
            self._execute_preset_merge(preset)
        else:
            if not is_partial:
                QTimer.singleShot(100, lambda: self._execute_preset_delayed(preset))
            else:
                self._execute_preset_delayed(preset)
    
    def _execute_preset_delayed(self, preset):
        """Continue executing preset after speed channel delay."""
        # Cancel any existing speed restoration timers to avoid conflicts
        self._cancel_speed_restoration_timers()

        # Ensure the default look's HTP layers are gone before starting
        self._stop_default_look_if_active()

        # Preserve fader level before stopping (stop_effect resets it to 1.0)
        preserved_fader_level = getattr(self.effect_engine, '_fader_level', 1.0)
        
        # Stop any previously running HTP layer-based preset first so its
        # layers don't keep driving channels underneath this non-layered
        # preset.  Blackout stale channels so the transition matches the
        # clean "preset → off → preset" path.
        if self.effect_engine._active_effects:
            print(f"[Execute] Stopping previous HTP layers")
            self.effect_engine.stop_all_effects_htp(blackout=True)
        
        # Stop any currently running effect first (blackout to clear stale
        # channels the new preset may not overwrite).
        if self.effect_engine._running:
            print(f"[Execute] Stopping previous effect")
            self.effect_engine.stop_effect(blackout=True, send_home=False)
        
        # Restore fader level after stop (prevents flash to full brightness)
        self.effect_engine._fader_level = preserved_fader_level
        print(f"[Execute] Preserved fader level: {preserved_fader_level:.2f}")
        
        # Build effect parameters from preset
        # Use 'none' as default movement_pattern to prevent unwanted pan/tilt movement
        movement_pattern_value = getattr(preset, 'movement_pattern', 'none')
        print(f"[Execute] Using movement_pattern: {movement_pattern_value}")
        
        # Resolve target groups: only default to ['all'] when BOTH groups and
        # fixtures are empty.  If individual fixtures are selected the groups
        # list is intentionally empty and must stay that way.
        _tgt_fixtures = list(getattr(preset, 'target_fixtures', []))
        if preset.target_groups:
            _tgt_groups = list(preset.target_groups)
        elif _tgt_fixtures:
            _tgt_groups = []  # individual fixtures — don't default to 'all'
        else:
            _tgt_groups = ['all']
        
        effect = EffectParameters(
            effect_type=preset.effect_type or 'static',
            color=preset.color or '#ffffff',
            intensity=preset.intensity if preset.intensity is not None else 100,
            intensity_min=getattr(preset, 'intensity_min', 0),
            intensity_max=getattr(preset, 'intensity_max', 100),
            speed_bpm=preset.speed_bpm if preset.speed_bpm is not None else 120,
            direction=getattr(preset, 'direction', 'forward'),
            transition=getattr(preset, 'transition', 'instant'),
            transition_time=getattr(preset, 'transition_time', 0.0),
            movement_pattern=movement_pattern_value,
            cycle_seconds=getattr(preset, 'cycle_seconds', 4.0),
            pan_min=getattr(preset, 'pan_min', 0),
            pan_max=getattr(preset, 'pan_max', 255),
            tilt_min=getattr(preset, 'tilt_min', 0),
            tilt_max=getattr(preset, 'tilt_max', 255),
            rainbow_colors=getattr(preset, 'rainbow_colors', False),
            color_palette=getattr(preset, 'color_palette', []),
            target_groups=_tgt_groups,
            target_fixtures=_tgt_fixtures,
            description=preset.name,
            macro_value=getattr(preset, 'macro_value', 0),
            color_wheel_value=getattr(preset, 'color_wheel_value', -1),
            effect_channel_value=getattr(preset, 'effect_channel_value', -1),
            gobo_value=getattr(preset, 'gobo_value', 0),
            gobo_rotation_value=getattr(preset, 'gobo_rotation_value', 0),
            gobo2_value=getattr(preset, 'gobo2_value', 0),
            gobo2_rotation_value=getattr(preset, 'gobo2_rotation_value', 0),
            position_preset=getattr(preset, 'position_preset', ''),
            fixture_offset=getattr(preset, 'fixture_offset', 0.25),
            # Position cycling settings
            position_cycle_enabled=getattr(preset, 'position_cycle_enabled', False),
            position_cycle_presets=getattr(preset, 'position_cycle_presets', []),
            position_cycle_hold_time=getattr(preset, 'position_cycle_hold_time', 4.0),
            position_cycle_speed=getattr(preset, 'position_cycle_speed', 128),
            # Subtab enabled states
            color_subtab_enabled=getattr(preset, 'color_subtab_enabled', False),
            effect_subtab_enabled=getattr(preset, 'effect_subtab_enabled', False),
            speed_subtab_enabled=getattr(preset, 'speed_subtab_enabled', False),
            strobe_subtab_enabled=getattr(preset, 'strobe_subtab_enabled', False),
            movement_subtab_enabled=getattr(preset, 'movement_subtab_enabled', False),
            patterns_subtab_enabled=getattr(preset, 'patterns_subtab_enabled', False),
            position_subtab_enabled=getattr(preset, 'position_subtab_enabled', False),
            gobo_subtab_enabled=getattr(preset, 'gobo_subtab_enabled', False),
            intensity_subtab_enabled=getattr(preset, 'intensity_subtab_enabled', False),
            target_subtab_enabled=getattr(preset, 'target_subtab_enabled', False),
            # Reset movers to home when loading preset without movement pattern
            reset_to_home=(movement_pattern_value in ('none', '', None))
        )
        
        print(f"[Execute] Position cycling: enabled={effect.position_cycle_enabled}, presets={effect.position_cycle_presets}")
        
        # Start the effect (mark as Execute mode so overlay yields)
        self._current_effect = effect
        print(f"[Execute] Starting effect: {effect.effect_type}, color={effect.color}, targets={effect.target_groups}")
        self.effect_engine._execute_mode = True
        self.effect_engine.start_effect(effect)
        print(f"[Execute] Effect started successfully")
        
        # Update selection state on execute buttons
        self._update_execute_button_selection(preset.id)
        
        # Start blinking the MIDI button for this preset
        midi_mgr = get_midi_manager()
        if midi_mgr:
            midi_mgr.start_blink(preset.id)
        
        # Start blinking the GUI execute button
        self._start_gui_blink(preset.id)
        
        # Sync REFINE tab controls to show the preset's saved settings (especially speed)
        # This ensures the speed sliders reflect the actual playback speed
        self._sync_refine_controls_from_effect(effect)
        
        # Update preview button state if visible
        if hasattr(self, 'preview_btn'):
            self.preview_btn.setChecked(True)
    
    def _execute_preset_merge(self, preset):
        """Merge a partial preset into the currently running effect.
        
        Instead of stopping and replacing the running effect, only override
        the parameters from subtabs that are enabled on the preset.  This lets
        a movement-only preset layer on top of a colour effect, for example.
        """
        running = self._current_effect
        if not running:
            # Nothing running – fall back to full start
            self._execute_preset_delayed(preset)
            return
        
        print(f"[Execute] Merging partial preset '{preset.name}' into running effect")
        
        # --- Merge enabled subtabs only ---------------------------------------------------
        if getattr(preset, 'color_subtab_enabled', False):
            running.color = preset.color or running.color
            running.color_name = getattr(preset, 'color_name', running.color_name)
            running.rainbow_colors = getattr(preset, 'rainbow_colors', running.rainbow_colors)
            if preset.color_palette:
                running.color_palette = list(preset.color_palette)
            print(f"[Execute/Merge] Color → {running.color}")
        
        if getattr(preset, 'effect_subtab_enabled', False):
            running.effect_type = preset.effect_type or running.effect_type
            running.rainbow_colors = getattr(preset, 'rainbow_colors', running.rainbow_colors)
            print(f"[Execute/Merge] Effect type → {running.effect_type}")
        
        if getattr(preset, 'intensity_subtab_enabled', False):
            running.intensity = preset.intensity if preset.intensity is not None else running.intensity
            running.intensity_min = getattr(preset, 'intensity_min', running.intensity_min)
            running.intensity_max = getattr(preset, 'intensity_max', running.intensity_max)
            print(f"[Execute/Merge] Intensity → {running.intensity}%")
        
        if getattr(preset, 'speed_subtab_enabled', False):
            running.speed_bpm = preset.speed_bpm if preset.speed_bpm is not None else running.speed_bpm
            running.direction = getattr(preset, 'direction', running.direction)
            print(f"[Execute/Merge] Speed → {running.speed_bpm} BPM")
        
        if getattr(preset, 'movement_subtab_enabled', False):
            running.pan_min = getattr(preset, 'pan_min', running.pan_min)
            running.pan_max = getattr(preset, 'pan_max', running.pan_max)
            running.tilt_min = getattr(preset, 'tilt_min', running.tilt_min)
            running.tilt_max = getattr(preset, 'tilt_max', running.tilt_max)
            print(f"[Execute/Merge] Movement bounds → pan {running.pan_min}-{running.pan_max}, tilt {running.tilt_min}-{running.tilt_max}")
        
        if getattr(preset, 'patterns_subtab_enabled', False):
            mp = getattr(preset, 'movement_pattern', 'none')
            if mp and mp.lower() not in ('none', ''):
                running.movement_pattern = mp
            running.fixture_offset = getattr(preset, 'fixture_offset', running.fixture_offset)
            # Allow patterns preset to carry its own speed
            if preset.speed_bpm and preset.speed_bpm > 0:
                running.speed_bpm = preset.speed_bpm
            # Also merge pan/tilt bounds from pattern preset
            running.pan_min = getattr(preset, 'pan_min', running.pan_min)
            running.pan_max = getattr(preset, 'pan_max', running.pan_max)
            running.tilt_min = getattr(preset, 'tilt_min', running.tilt_min)
            running.tilt_max = getattr(preset, 'tilt_max', running.tilt_max)
            print(f"[Execute/Merge] Pattern → {running.movement_pattern}, offset={running.fixture_offset}")
        
        if getattr(preset, 'position_subtab_enabled', False):
            running.position_cycle_enabled = getattr(preset, 'position_cycle_enabled', running.position_cycle_enabled)
            running.position_cycle_presets = getattr(preset, 'position_cycle_presets', running.position_cycle_presets)
            running.position_cycle_hold_time = getattr(preset, 'position_cycle_hold_time', running.position_cycle_hold_time)
            running.position_cycle_speed = getattr(preset, 'position_cycle_speed', running.position_cycle_speed)
            print(f"[Execute/Merge] Position cycling → {running.position_cycle_enabled}")
        
        if getattr(preset, 'gobo_subtab_enabled', False):
            running.gobo_value = getattr(preset, 'gobo_value', running.gobo_value)
            running.gobo_rotation_value = getattr(preset, 'gobo_rotation_value', getattr(running, 'gobo_rotation_value', 0))
            running.gobo2_value = getattr(preset, 'gobo2_value', getattr(running, 'gobo2_value', 0))
            running.gobo2_rotation_value = getattr(preset, 'gobo2_rotation_value', getattr(running, 'gobo2_rotation_value', 0))
            print(f"[Execute/Merge] Gobo → {running.gobo_value}")
        
        if getattr(preset, 'target_subtab_enabled', False):
            target_fixtures = getattr(preset, 'target_fixtures', [])
            if preset.target_groups:
                running.target_groups = list(preset.target_groups)
            elif target_fixtures:
                running.target_groups = []  # fixtures override groups
            # else: keep running.target_groups unchanged
            running.target_fixtures = list(target_fixtures) if target_fixtures else running.target_fixtures
            print(f"[Execute/Merge] Targets → {running.target_groups}")
        
        # Push merged parameters into the running effect engine
        self.effect_engine.update_effect(running)
        
        # UI updates
        self._update_execute_button_selection(preset.id)
        midi_mgr = get_midi_manager()
        if midi_mgr:
            midi_mgr.start_blink(preset.id)
        self._start_gui_blink(preset.id)
        self._sync_refine_controls_from_effect(running)
        if hasattr(self, 'preview_btn'):
            self.preview_btn.setChecked(True)
        print(f"[Execute] Partial merge complete")

    def _cancel_speed_restoration_timers(self):
        """Cancel any pending pan/tilt speed restoration timers.
        
        Called when starting a new effect to prevent conflicts between
        old speed restoration and new movement patterns.
        """
        if hasattr(self, '_pan_tilt_speed_restore_timer') and self._pan_tilt_speed_restore_timer:
            self._pan_tilt_speed_restore_timer.stop()
            self._pan_tilt_speed_restore_timer.deleteLater()
            self._pan_tilt_speed_restore_timer = None
            print("[Speed] Cancelled pan/tilt speed restoration timer")
        
        if hasattr(self, '_home_position_speed_restore_timer') and self._home_position_speed_restore_timer:
            self._home_position_speed_restore_timer.stop()
            self._home_position_speed_restore_timer.deleteLater()
            self._home_position_speed_restore_timer = None
            print("[Speed] Cancelled home position speed restoration timer")
    
    def _set_pan_tilt_speed_slow(self):
        """Set all moving head pan/tilt speed channels to slow for smooth transitions.
        
        This is called before executing a preset so that when pan/tilt values change,
        the fixtures morph smoothly to the new position instead of snapping instantly.
        The speed will be restored after 6 seconds.
        """
        artnet = get_artnet_output()
        if not artnet:
            return
        
        # Cancel any existing speed restoration timer
        if hasattr(self, '_pan_tilt_speed_restore_timer') and self._pan_tilt_speed_restore_timer:
            self._pan_tilt_speed_restore_timer.stop()
            self._pan_tilt_speed_restore_timer.deleteLater()
            self._pan_tilt_speed_restore_timer = None
        
        speed_restore_info = []  # List of (universe, address, original_value)
        
        for fixture in self.project.fixtures:
            if not fixture.mode:
                continue
            
            # Check if fixture has pan/tilt (it's a moving head)
            has_pan_tilt = any(ch.type.lower() in ('pan', 'tilt') for ch in fixture.mode.channels)
            if not has_pan_tilt:
                continue
            
            # Find and set pan/tilt speed channel
            for i, ch in enumerate(fixture.mode.channels):
                ch_type = ch.type.lower()
                if ch_type in ('pan_tilt_speed', 'pantilt_speed', 'pt_speed', 'speed'):
                    address = fixture.address + i
                    # Get current value to restore later
                    current_value = artnet.get_channel(fixture.universe, address) or 0
                    # Set to 220 for slow movement (higher = slower on most fixtures)
                    artnet.set_channel(fixture.universe, address, 220)
                    speed_restore_info.append((fixture.universe, address, current_value))
                    name = fixture.label or fixture.profile.name
                    print(f"[Execute] Set {name} pan/tilt speed to 220 (slow), was {current_value}")
        
        # Restore speed channels after 6 seconds (enough time for movement to complete)
        if speed_restore_info:
            def restore_speeds():
                artnet = get_artnet_output()
                if artnet:
                    for universe, address, original_value in speed_restore_info:
                        artnet.set_channel(universe, address, original_value)
                    print(f"[Execute] Restored {len(speed_restore_info)} pan/tilt speed channels")
                # Clear timer reference
                if hasattr(self, '_pan_tilt_speed_restore_timer'):
                    self._pan_tilt_speed_restore_timer = None
            
            from PyQt6.QtCore import QTimer
            self._pan_tilt_speed_restore_timer = QTimer()
            self._pan_tilt_speed_restore_timer.setSingleShot(True)
            self._pan_tilt_speed_restore_timer.timeout.connect(restore_speeds)
            self._pan_tilt_speed_restore_timer.start(6000)
            print(f"[Execute] Will restore pan/tilt speeds in 6 seconds")
    
    def _execute_off(self):
        """Stop button-triggered effects. If a fader is up, restart its effect."""
        print("[Execute] OFF - stopping current effect")
        
        # Stop Play All cycling if active (both exec and viz)
        self._exec_stop_play_all()
        try:
            from .visualizer_tab import _stop_play_all
        except ImportError:
            from visualizer_tab import _stop_play_all
        _stop_play_all(self)
        
        # Stop any MIDI button blinking
        midi_mgr = get_midi_manager()
        if midi_mgr:
            midi_mgr.stop_blink()
        
        # Stop GUI button blinking
        self._stop_gui_blink()
        
        # Stop any HTP layer-based effects first
        self.effect_engine.stop_all_effects_htp(blackout=False)
        # Stop the current legacy effect
        self.effect_engine._execute_mode = False
        self.effect_engine.stop_effect(blackout=True, send_home=False)
        self._current_effect = None
        
        # Update selection state on execute buttons to show OFF
        self._update_execute_button_selection("__OFF__")
        
        # Update preview button state
        if hasattr(self, 'preview_btn'):
            self.preview_btn.setChecked(False)
        
        # Check if any fader is up and should restart its effect
        active_fader = None
        active_fader_preset_id = None
        active_fader_value = 0
        
        if hasattr(self, '_fader_exec_states'):
            for fader_id, state in self._fader_exec_states.items():
                preset_id = state.get('preset_id')
                if preset_id and preset_id != "__OFF__":
                    # Check fader position
                    try:
                        fader_num = int(fader_id.split("_")[1]) - 1
                        if hasattr(self, 'prog_faders') and fader_num < len(self.prog_faders):
                            fader_value = self.prog_faders[fader_num].value()
                            if fader_value > 2:  # Above threshold
                                active_fader = fader_id
                                active_fader_preset_id = preset_id
                                active_fader_value = fader_value
                                print(f"[Execute] Found active fader {fader_id} at {fader_value}%")
                                break
                    except (ValueError, IndexError):
                        pass
        
        if active_fader and active_fader_preset_id:
            # Restart the fader's effect
            print(f"[Execute] Restarting fader {active_fader} effect: {active_fader_preset_id}")
            
            # Find the preset
            preset = None
            for p in self.project.presets:
                if p.id == active_fader_preset_id:
                    preset = p
                    break
            
            if preset:
                # Build and start the effect
                effect = self._build_effect_from_preset(preset)
                fader_level = active_fader_value / 100.0
                
                # Get fader mode
                fader_modes = self.app_settings.get('fader_modes', {})
                fader_mode = fader_modes.get(active_fader, 'fade')
                
                # Set fader level based on mode
                if fader_mode == 'speed':
                    self.effect_engine._fader_level = 1.0
                else:
                    self.effect_engine._fader_level = fader_level
                
                self._current_effect = effect
                self.effect_engine._execute_mode = True
                self.effect_engine.start_effect(effect)
                
                # Re-apply fader level after start
                if fader_mode == 'speed':
                    self.effect_engine._fader_level = 1.0
                else:
                    self.effect_engine._fader_level = fader_level
                
                # Mark fader as active
                self._fader_exec_states[active_fader]['active'] = True
                
                print(f"[Execute] Fader effect restarted at {fader_level:.0%}")
        else:
            # No faders up - do full blackout and send home
            self.effect_engine._send_to_home_positions()
            
            # Clear all fader states
            if hasattr(self, '_fader_exec_states'):
                for state in self._fader_exec_states.values():
                    state['active'] = False
            
            if hasattr(self, '_midi_fader_states'):
                for state in self._midi_fader_states.values():
                    state['active'] = False
            
            print("[Execute] Full stop - no active faders")
            # Restore default look if configured
            self._maybe_restore_default_look()
    
    def _build_effect_from_preset(self, preset) -> 'EffectParameters':
        """Build EffectParameters from a preset for HTP execution.
        
        Args:
            preset: The preset object
            
        Returns:
            EffectParameters configured from the preset
        """
        # EffectParameters is already imported at the top of this file (line 73)
        
        movement_pattern_value = getattr(preset, 'movement_pattern', 'none')
        
        _tgt_fixtures = list(getattr(preset, 'target_fixtures', []))
        if preset.target_groups:
            _tgt_groups = list(preset.target_groups)
        elif _tgt_fixtures:
            _tgt_groups = []
        else:
            _tgt_groups = ['all']
        
        return EffectParameters(
            effect_type=preset.effect_type or 'static',
            color=preset.color or '#ffffff',
            intensity=preset.intensity if preset.intensity is not None else 100,
            intensity_min=getattr(preset, 'intensity_min', 0),
            intensity_max=getattr(preset, 'intensity_max', 100),
            speed_bpm=preset.speed_bpm if preset.speed_bpm is not None else 120,
            direction=getattr(preset, 'direction', 'forward'),
            transition=getattr(preset, 'transition', 'instant'),
            transition_time=getattr(preset, 'transition_time', 0.0),
            movement_pattern=movement_pattern_value,
            cycle_seconds=getattr(preset, 'cycle_seconds', 4.0),
            pan_min=getattr(preset, 'pan_min', 0),
            pan_max=getattr(preset, 'pan_max', 255),
            tilt_min=getattr(preset, 'tilt_min', 0),
            tilt_max=getattr(preset, 'tilt_max', 255),
            rainbow_colors=getattr(preset, 'rainbow_colors', False),
            color_palette=getattr(preset, 'color_palette', []),
            target_groups=_tgt_groups,
            target_fixtures=_tgt_fixtures,
            description=preset.name,
            macro_value=getattr(preset, 'macro_value', 0),
            color_wheel_value=getattr(preset, 'color_wheel_value', -1),
            effect_channel_value=getattr(preset, 'effect_channel_value', -1),
            gobo_value=getattr(preset, 'gobo_value', 0),
            gobo_rotation_value=getattr(preset, 'gobo_rotation_value', 0),
            gobo2_value=getattr(preset, 'gobo2_value', 0),
            gobo2_rotation_value=getattr(preset, 'gobo2_rotation_value', 0),
            position_preset=getattr(preset, 'position_preset', ''),
            fixture_offset=getattr(preset, 'fixture_offset', 0.25),
            position_cycle_enabled=getattr(preset, 'position_cycle_enabled', False),
            position_cycle_presets=getattr(preset, 'position_cycle_presets', []),
            position_cycle_hold_time=getattr(preset, 'position_cycle_hold_time', 4.0),
            position_cycle_speed=getattr(preset, 'position_cycle_speed', 128),
            color_subtab_enabled=getattr(preset, 'color_subtab_enabled', False),
            effect_subtab_enabled=getattr(preset, 'effect_subtab_enabled', False),
            speed_subtab_enabled=getattr(preset, 'speed_subtab_enabled', False),
            strobe_subtab_enabled=getattr(preset, 'strobe_subtab_enabled', False),
            movement_subtab_enabled=getattr(preset, 'movement_subtab_enabled', False),
            patterns_subtab_enabled=getattr(preset, 'patterns_subtab_enabled', False),
            position_subtab_enabled=getattr(preset, 'position_subtab_enabled', False),
            gobo_subtab_enabled=getattr(preset, 'gobo_subtab_enabled', False),
            intensity_subtab_enabled=getattr(preset, 'intensity_subtab_enabled', False),
            target_subtab_enabled=getattr(preset, 'target_subtab_enabled', False),
            reset_to_home=(movement_pattern_value in ('none', '', None))
        )
    
    def _all_faders_at_zero(self):
        """Check if all faders (both MIDI and GUI) are at 0 or inactive."""
        # Check MIDI faders
        if hasattr(self, '_midi_fader_states'):
            for state in self._midi_fader_states.values():
                if state['active']:
                    return False
        
        # Check GUI fader execution
        if hasattr(self, '_fader_exec_states'):
            for state in self._fader_exec_states.values():
                if state['active']:
                    return False
        
        return True
    
    def _on_effect_state_change(self, action: str, effect: Optional[EffectParameters]):
        """Handle effect engine state changes to update Execute tab selection.
        
        Args:
            action: "started" or "stopped"
            effect: EffectParameters if started, None if stopped
        """
        print(f"[EffectCallback] Effect {action}")
        if action == "started":
            # Effect started - could update selection if needed, but typically
            # the preset button was already pressed to start it
            pass
        elif action == "stopped":
            # Effect stopped - check if all faders are at 0, if so select OFF
            all_faders_zero = self._are_all_faders_at_zero()
            print(f"[EffectCallback] All faders at zero: {all_faders_zero}")
            if all_faders_zero:
                print(f"[EffectCallback] Setting execute selection to OFF")
                self._active_execute_preset_id = "__OFF__"
                self._update_execute_button_selection("__OFF__")
                # Stop MIDI button blinking
                midi_mgr = get_midi_manager()
                if midi_mgr:
                    midi_mgr.stop_blink()
                # Stop GUI button blinking
                self._stop_gui_blink()
                # Restore default look if configured
                self._maybe_restore_default_look()
    
    def _are_all_faders_at_zero(self) -> bool:
        """Check if all faders (MIDI, GUI exec, and group) are at or near zero."""
        # Check MIDI fader states
        if hasattr(self, '_midi_fader_states'):
            for state in self._midi_fader_states.values():
                if state.get('active', False):
                    return False
        
        # Check GUI fader execution states
        if hasattr(self, '_fader_exec_states'):
            for state in self._fader_exec_states.values():
                if state.get('active', False):
                    return False
        
        # Check group faders
        if not self._are_all_group_faders_at_zero():
            return False
        
        return True
    
    def _are_all_group_faders_at_zero(self) -> bool:
        """Check if all group fader sliders are at 0."""
        if hasattr(self, 'group_fader_widgets'):
            for slider in self.group_fader_widgets.values():
                try:
                    if slider.value() > 0:
                        return False
                except RuntimeError:
                    pass  # Widget deleted
        return True
    
    def _on_midi_fader_intensity(self, midi_key: str, intensity_pct: int):
        """Handle MIDI fader intensity changes for HTP execution.

        Args:
            midi_key: MIDI key like 'pb:1', 'cc:0:7'
            intensity_pct: Intensity percentage 0-100
        """
        print(f"[FaderHandler] Called with {midi_key}, intensity={intensity_pct}%")
        # Get preset mappings for this MIDI key
        midi_mgr = get_midi_manager()
        if not midi_mgr:
            return
        preset_ids = midi_mgr._mappings.get(midi_key, [])
        if not preset_ids:
            print(f"[FaderIntensity] No mappings for {midi_key}")
            return
        
        # Get first preset (typically only one)
        preset_id = preset_ids[0]
        print(f"[FaderIntensity] {midi_key} -> {preset_id}, intensity={intensity_pct}%")
        
        # Track state per MIDI key
        if not hasattr(self, '_midi_fader_states'):
            self._midi_fader_states = {}
        if midi_key not in self._midi_fader_states:
            self._midi_fader_states[midi_key] = {'active': False, 'preset_id': preset_id}
            print(f"[StateInit] Created {midi_key} with active=False")
        
        state = self._midi_fader_states[midi_key]
        fader_level = intensity_pct / 100.0
        
        # If this preset has a callback registered (from execution tab MIDI mapping),
        # trigger it like a button press/release based on fader position
        if preset_id in midi_mgr._preset_callbacks:
            print(f"[FaderIntensity] Using callback path for {preset_id}")
            callback = midi_mgr._preset_callbacks[preset_id]
            if intensity_pct > 5 and not state['active']:
                print(f"[MIDI] Fader {midi_key} triggering preset callback for {preset_id}")
                # Stop default look before starting new effect
                self._stop_default_look_if_active()
                # Set fader level BEFORE triggering callback so effect starts with correct intensity
                self.effect_engine._fader_level = fader_level
                # Call on main thread
                from PyQt6.QtCore import QTimer
                QTimer.singleShot(0, callback)
                state['active'] = True
                # Update active preset selection
                self._active_execute_preset_id = preset_id
                self._update_execute_button_selection(preset_id)
            elif intensity_pct <= 5 and state['active']:
                # Stop the effect when fader goes down
                print(f"[MIDI] Fader {midi_key} stopping effect for {preset_id}")
                self.effect_engine.stop_effect(blackout=True, send_home=False)
                self.effect_engine._fader_level = 1.0  # Reset fader level
                self._current_effect = None
                state['active'] = False
                # Stop MIDI button blinking
                midi_mgr.stop_blink()
                # Stop GUI button blinking
                self._stop_gui_blink()
                # Check if any faders are still active
                active_count = sum(1 for s in self._midi_fader_states.values() if s['active'])
                print(f"[FaderStop] Callback path - Active fader count: {active_count}")
                if active_count == 0:
                    print(f"[FaderStop] Setting execute selection to OFF")
                    self._active_execute_preset_id = "__OFF__"
                    self._update_execute_button_selection("__OFF__")
                    # Restore default look if configured
                    self._maybe_restore_default_look()
            elif state['active'] and intensity_pct > 5:
                # Update fader level while effect is running (callback path)
                self.effect_engine._fader_level = fader_level
                print(f"[FaderIntensity] Callback path - updated fader level to {intensity_pct}%")
            return  # Use preset callback path, not intensity path
        else:
            print(f"[FaderIntensity] {preset_id} not in callbacks, using intensity path")
        
        # Handle OFF button specially
        if preset_id == "__OFF__":
            if intensity_pct > 2 and not state['active']:
                print(f"[FaderIntensity] OFF fader raised - stopping all effects")
                self._execute_off()
                state['active'] = True
            elif intensity_pct <= 2 and state['active']:
                state['active'] = False
                # Check if any faders are still active
                active_count = sum(1 for s in self._midi_fader_states.values() if s['active'])
                if active_count == 0:
                    self._active_execute_preset_id = "__OFF__"
                    self._update_execute_button_selection("__OFF__")
            return
        
        # Look up the preset object from ID
        preset = self.project.get_preset_by_id(preset_id)
        if not preset:
            print(f"[FaderIntensity] Preset {preset_id} not found in project")
            return
        
        # Start effect when fader crosses threshold
        if intensity_pct > 5 and not state['active']:
            # Mark active BEFORE stopping so callbacks see a non-zero fader
            state['active'] = True
            # Stop default look before starting new effect
            self._stop_default_look_if_active()
            # Auto-crossfade: lower all other faders to 0 when starting a new effect
            print(f"[AutoCrossfade] {midi_key} starting, stopping other faders")
            
            # Stop other MIDI-mapped presets
            for other_midi_key, other_state in self._midi_fader_states.items():
                if other_midi_key != midi_key and other_state['active'] and other_state['preset_id'] != "__OFF__":
                    # Stop the other effect
                    other_preset_id = other_state['preset_id']
                    self.effect_engine.stop_effect(blackout=False, send_home=False)
                    self._current_effect = None
                    other_state['active'] = False
                    
                    # Move the motorized fader to 0
                    midi_mgr = get_midi_manager()
                    if midi_mgr and midi_mgr.is_connected:
                        midi_mgr.send_fader_feedback(other_midi_key, 0)

                    # Also update GUI sliders in popup/detached windows
                    # Find the fader_id that corresponds to this MIDI key so we
                    # can update _all_fader_sliders and send dynamic feedback.
                    _mapped_fader_id = None
                    fader_mappings = self.app_settings.get('midi_fader_mappings', {})
                    for _fid, _mkeys in fader_mappings.items():
                        keys_list = [_mkeys] if isinstance(_mkeys, str) else (_mkeys or [])
                        if other_midi_key in keys_list:
                            _mapped_fader_id = _fid
                            break
                    if _mapped_fader_id and _mapped_fader_id in getattr(self, '_all_fader_sliders', {}):
                        for slider in list(self._all_fader_sliders[_mapped_fader_id]):
                            try:
                                slider.blockSignals(True)
                                slider.setValue(0)
                                slider.blockSignals(False)
                            except RuntimeError:
                                pass
                        self._send_dynamic_midi_feedback_for_fader(_mapped_fader_id, 0)

            # Also stop fader execution presets (skip override faders)
            if hasattr(self, '_fader_exec_states'):
                prog_overrides = self.app_settings.get('prog_fader_overrides', {})
                for other_fader_id, other_exec_state in self._fader_exec_states.items():
                    # Skip if no preset_id (safety check for old states)
                    if 'preset_id' not in other_exec_state:
                        continue
                    # Skip override faders — they coexist with other effects
                    if prog_overrides.get(other_fader_id, False):
                        continue
                    if other_exec_state['active'] and other_exec_state['preset_id'] != "__OFF__":
                        other_preset_id = other_exec_state['preset_id']
                        self.effect_engine.stop_effect(blackout=False, send_home=False)
                        self._current_effect = None
                        other_exec_state['active'] = False
                        
                        # Update GUI slider to 0 (prevents value mismatch)
                        try:
                            other_fader_num = int(other_fader_id.split("_")[1]) - 1
                            if 0 <= other_fader_num < len(self.prog_faders):
                                self._updating_from_midi = True
                                self.prog_faders[other_fader_num].setValue(0)
                                self._updating_from_midi = False
                        except (ValueError, IndexError):
                            pass
                        
                        # Set cooldown to ignore incoming MIDI while motor moves to 0
                        import time
                        self._fader_cooldown[other_fader_id] = time.time()
                        
                        # Send feedback to move motorized fader to 0
                        self._send_fader_feedback(other_fader_id, 0, max_val=100)
                        
                        # Also update sliders in popup/detached windows
                        if other_fader_id in getattr(self, '_all_fader_sliders', {}):
                            for slider in list(self._all_fader_sliders[other_fader_id]):
                                try:
                                    slider.blockSignals(True)
                                    slider.setValue(0)
                                    slider.blockSignals(False)
                                except RuntimeError:
                                    pass
                        
                        # Send dynamic MIDI feedback
                        self._send_dynamic_midi_feedback_for_fader(other_fader_id, 0)

            effect = self._build_effect_from_preset(preset)
            print(f"[FaderIntensity] Starting effect: {preset.name}, type={effect.effect_type}, color={effect.color}, targets={effect.target_groups}")
            
            effect.intensity = intensity_pct
            if hasattr(effect, 'intensity_max'):
                effect.intensity_max = intensity_pct
            
            # Use same code path as buttons with fader scaling
            self.effect_engine._fader_level = fader_level
            self._current_effect = effect
            self.effect_engine._execute_mode = True
            self.effect_engine.start_effect(effect)
            self._active_execute_preset_id = preset_id
            # state['active'] already set True above (before stop_default_look)
            
            # Start MIDI button blinking for active preset
            midi_mgr = get_midi_manager()
            if midi_mgr:
                midi_mgr.start_blink(preset_id)
            
            # Start GUI button blinking
            self._start_gui_blink(preset_id)
            
            # Update execute button selection
            self._update_execute_button_selection(preset_id)
            
        elif intensity_pct <= 5 and state['active']:
            # Stop effect and blackout when fader drops
            self.effect_engine.stop_effect(blackout=True, send_home=False)  # Blackout when fader drops
            self.effect_engine._fader_level = 1.0  # Reset fader level
            self._current_effect = None  # Clear effect like buttons
            state['active'] = False
            
            # Stop MIDI button blinking
            midi_mgr = get_midi_manager()
            if midi_mgr:
                midi_mgr.stop_blink()
            
            # Stop GUI button blinking
            self._stop_gui_blink()
            
            # Update active preset ID
            self._active_execute_preset_id = "__OFF__"
            # Update execute button selection
            self._update_execute_button_selection("__OFF__")
            # Check if ALL faders are at 0 before going home
            if self._all_faders_at_zero():
                print("[Home] Sending fixtures to home positions")
                self.effect_engine._send_to_home_positions()
                # Restore default look if configured
                self._maybe_restore_default_look()
                
        elif state['active'] and intensity_pct > 2:
            # Update fader level for running effect
            # But first check if effect is actually running - if not, start it
            if not self.effect_engine._running or not self.effect_engine._current_effect:
                # Effect not actually running - state is out of sync, restart it
                effect = self._build_effect_from_preset(preset)
                print(f"[FaderIntensity] Re-starting effect (was out of sync): {preset.name}, type={effect.effect_type}, color={effect.color}")
                effect.intensity = intensity_pct
                if hasattr(effect, 'intensity_max'):
                    effect.intensity_max = intensity_pct
                self.effect_engine._fader_level = fader_level
                self._current_effect = effect
                self.effect_engine._execute_mode = True
                self.effect_engine.start_effect(effect)
                self._active_execute_preset_id = preset_id
                self._update_execute_button_selection(preset_id)
            else:
                # Update fader level for running effect
                self.effect_engine._fader_level = fader_level
    
    def _pick_color(self):
        """Open color picker dialog - adds to palette."""
        color = QColorDialog.getColor(QColor("#ffffff"), self.window(), "Pick Effect Color")
        if color.isValid():
            hex_color = color.name()
            self.palette_colors.append(hex_color)
            self._refresh_palette_display()
            self._on_refine_param_changed()
    
    def _add_palette_color(self):
        """Add a color to the palette."""
        color = QColorDialog.getColor(QColor("#ffffff"), self.window(), "Add Palette Color")
        if color.isValid():
            hex_color = color.name()
            self.palette_colors.append(hex_color)
            self._refresh_palette_display()
            self._on_refine_param_changed()
    
    def _remove_palette_color(self, index: int):
        """Remove a color from the palette by index."""
        if 0 <= index < len(self.palette_colors):
            self.palette_colors.pop(index)
            self._refresh_palette_display()
            self._on_refine_param_changed()
    
    def _clear_palette(self):
        """Clear all colors from the palette."""
        self.palette_colors.clear()
        self._selected_palette_index = -1
        self._refresh_palette_display()
        self._on_refine_param_changed()
    
    def _new_palette(self):
        """Start a new palette - clears name and colors."""
        self.palette_name_edit.clear()
        self.palette_colors.clear()
        self._selected_palette_index = -1
        self._refresh_palette_display()
        self._on_refine_param_changed()
        self.palette_name_edit.setFocus()
    
