    def _clear_large_fader_assignment(self, fader_id: str, display_label: QLabel, dialog: QDialog):
        """Clear large fader assignment (effect, position, and visualizer)."""
        exec_assignments = self.app_settings.get('fader_execution_assignments', {})
        if fader_id in exec_assignments:
            del exec_assignments[fader_id]
        
        pos_assignments = self.app_settings.get('fader_position_assignments', {})
        if fader_id in pos_assignments:
            del pos_assignments[fader_id]
        
        viz_assignments = self.app_settings.get('fader_visualizer_assignments', {})
        if fader_id in viz_assignments:
            del viz_assignments[fader_id]
        
        # Stop any running visualizer playback from this fader
        if hasattr(self, '_viz_fader_states') and fader_id in self._viz_fader_states:
            self._stop_visualizer_fader(fader_id)
            del self._viz_fader_states[fader_id]
        
        # Clean up position fader state
        if hasattr(self, '_position_fader_states') and fader_id in self._position_fader_states:
            del self._position_fader_states[fader_id]
        
        # Release position override channels
        if hasattr(self, '_position_override_by_fader') and fader_id in self._position_override_by_fader:
            artnet = get_artnet_output()
            if artnet:
                artnet._position_override_channels -= self._position_override_by_fader[fader_id]
            del self._position_override_by_fader[fader_id]
        
        self._save_app_settings()
        
        # Refresh mode label back to F/S
        self._refresh_fader_mode_label(fader_id)
        
        display_label.setText("")  # Blank when unassigned
        
        # Reset the prog_fader visual too
        try:
            fader_num = int(fader_id.split("_")[1]) - 1
            if hasattr(self, 'prog_faders') and 0 <= fader_num < len(self.prog_faders):
                slider = self.prog_faders[fader_num]
                slider.setStyleSheet("""
                    QSlider::groove:horizontal { height: 6px; background: #2a2a2a; border-radius: 3px; }
                    QSlider::handle:horizontal { width: 14px; background: #c97a50; border-radius: 7px; margin: -4px 0; }
                    QSlider::sub-page:horizontal { background: #4a4a4a; border-radius: 3px; }
                """)
                slider.setToolTip("")
        except (ValueError, IndexError):
            pass
        
        self._sync_fader_display_across_windows(fader_id)
        dialog.accept()

    def _sync_fader_display_across_windows(self, fader_id: str):
        """Sync the effect/position/visualizer display label for a fader across all open windows.
        
        This updates every instance of the fader's effect_display label in
        _all_fader_sliders so that all windows show the same assignment name.
        """
        # Determine what the display text should be
        display_text = ""
        exec_assignments = self.app_settings.get('fader_execution_assignments', {})
        pos_assignments = self.app_settings.get('fader_position_assignments', {})
        viz_assignments = self.app_settings.get('fader_visualizer_assignments', {})
        
        assigned_preset_id = exec_assignments.get(fader_id)
        assigned_positions = pos_assignments.get(fader_id, [])
        assigned_viz_id = viz_assignments.get(fader_id)
        
        if assigned_preset_id:
            if assigned_preset_id == "__OFF__":
                display_text = "OFF"
            elif assigned_preset_id.startswith("cuelist:"):
                cid = assigned_preset_id.split(":", 1)[1]
                for cl in self.project.cue_lists:
                    if cl.id == cid:
                        display_text = f"\U0001f3ac {cl.name}"
                        break
                else:
                    display_text = "\U0001f3ac Cue List"
            else:
                for preset in self.project.presets:
                    if preset.id == assigned_preset_id:
                        display_text = preset.name
                        break
                else:
                    display_text = "Unknown"
        elif assigned_positions:
            pos_names = []
            for pid in assigned_positions:
                p = self.project.get_position_preset_by_id(pid)
                if p:
                    pos_names.append(p.name)
            if len(pos_names) == 1:
                display_text = f"\ud83d\udccd {pos_names[0]}"
            elif pos_names:
                display_text = f"\ud83d\udccd {len(pos_names)} Pos"
        elif assigned_viz_id:
            viz_name = "Video Visualizer"
            for vit in getattr(self.project, '_visualizer_items', []):
                if vit.id == assigned_viz_id:
                    viz_name = vit.name
                    break
            display_text = f"\U0001f3a5 {viz_name}"
        
        # Update all slider instances' _effect_display labels
        if fader_id in self._all_fader_sliders:
            for slider in self._all_fader_sliders[fader_id]:
                try:
                    ed = getattr(slider, '_effect_display', None)
                    if ed is not None:
                        ed.setText(display_text)
                except RuntimeError:
                    pass  # Widget deleted

    def _assign_fader_from_dialog(self, fader_config: 'FaderConfig', display_label: QLabel, 
                                 effects_list: QListWidget, dialog: QDialog):
        """Assign selected effect to fader."""
        current_item = effects_list.currentItem()
        if not current_item:
            QMessageBox.warning(dialog, "No Selection", "Please select an effect to assign.")
            return
        
        data = current_item.data(Qt.ItemDataRole.UserRole)
        if data:
            preset_type, preset_id = data
            fader_config.assigned_preset_type = preset_type
            fader_config.assigned_preset_id = preset_id
            
            # Update display
            assigned_name = self._get_assigned_preset_name(fader_config)
            display_label.setText(assigned_name)
            
            dialog.accept()
    
    def _clear_fader_assignment(self, fader_config: 'FaderConfig', display_label: QLabel, dialog: QDialog):
        """Clear fader assignment."""
        fader_config.assigned_preset_id = None
        fader_config.assigned_preset_type = "effect"
        display_label.setText("(Tap to assign)")
        dialog.accept()

    
    def _on_fader_value_changed(self, fader_config: 'FaderConfig', value: int, page_id: str):
        """Handle fader value change - update config and execute if assigned."""
        if self._syncing_fader:
            return  # Prevent feedback loops
        
        fader_config.value = value
        
        # Sync this value to all other slider instances (in detached windows)
        self._syncing_fader = True
        try:
            if fader_config.id in self._all_fader_sliders:
                # Filter out deleted sliders and only update valid ones
                valid_sliders = []
                for slider in self._all_fader_sliders[fader_config.id]:
                    try:
                        # Try to access the slider - if deleted, this will raise
                        if slider.value() != value:
                            slider.blockSignals(True)
                            slider.setValue(value)
                            slider.blockSignals(False)
                        valid_sliders.append(slider)
                    except RuntimeError:
                        # Slider was deleted, skip it
                        pass
                
                # Update the list with only valid sliders
                if valid_sliders:
                    self._all_fader_sliders[fader_config.id] = valid_sliders
                else:
                    del self._all_fader_sliders[fader_config.id]
        finally:
            self._syncing_fader = False
        
        # Send motorized fader feedback (only if not triggered by MIDI input)
        if not getattr(self, '_updating_from_midi', False):
            self._send_fader_feedback(fader_config.id, value, max_val=100)
        
        # If fader is assigned to a preset/effect, execute it
        if fader_config.assigned_preset_id and fader_config.assigned_preset_type == "effect":
            # Find the preset
            preset = self.project.get_preset_by_id(fader_config.assigned_preset_id)
            if preset:
                if value == 0:
                    # Fader at zero → stop the effect instead of running at 0%
                    if hasattr(self, 'effect_engine'):
                        self.effect_engine.stop_effect(blackout=True, send_home=False)
                        if hasattr(self.effect_engine, 'stop_all_effects_htp'):
                            self.effect_engine.stop_all_effects_htp()
                    if self._all_faders_at_zero():
                        self.effect_engine._send_to_home_positions()
                        self._maybe_restore_default_look()
                else:
                    # Adjust intensity based on fader value
                    old_intensity = preset.intensity
                    preset.intensity = value
                    # Execute the preset
                    self._execute_preset(preset)
                    # Restore original intensity
                    preset.intensity = old_intensity
    
    def _on_large_fader_changed(self, fader_id: str, fader_idx: int, value: int):
        """Handle large fader value change - sync to prog_faders and execute assignment."""
        if self._syncing_fader:
            return  # Prevent feedback loops
        
        self._syncing_fader = True
        try:
            # Update the corresponding prog_fader
            if hasattr(self, 'prog_faders') and fader_idx < len(self.prog_faders):
                prog_slider = self.prog_faders[fader_idx]
                if prog_slider.value() != value:
                    prog_slider.blockSignals(True)
                    prog_slider.setValue(value)
                    prog_slider.blockSignals(False)
            
            # Sync to all other instances of this fader in _all_fader_sliders
            if fader_id in self._all_fader_sliders:
                valid_sliders = []
                for slider in self._all_fader_sliders[fader_id]:
                    try:
                        if slider.value() != value:
                            slider.blockSignals(True)
                            slider.setValue(value)
                            slider.blockSignals(False)
                        valid_sliders.append(slider)
                    except RuntimeError:
                        pass  # Slider deleted
                
                if valid_sliders:
                    self._all_fader_sliders[fader_id] = valid_sliders
                else:
                    del self._all_fader_sliders[fader_id]
        finally:
            self._syncing_fader = False
        
        # Send motorized fader feedback (only if not triggered by MIDI input)
        if not getattr(self, '_updating_from_midi', False):
            self._send_fader_feedback(fader_id, value, max_val=100)

        # Update V1-M scribble strip / LCD for this fader slot
        slot_idx = fader_idx - getattr(self, '_fader_page', 0) * 8
        if 0 <= slot_idx < 8:
            slider = None
            if hasattr(self, 'prog_faders') and fader_idx < len(self.prog_faders):
                slider = self.prog_faders[fader_idx]
            if slider is not None:
                self._update_v1m_fader_display(slot_idx, slider)

        # Update the prog_fader value label text directly
        if hasattr(self, 'prog_fader_labels') and fader_idx < len(self.prog_fader_labels):
            self.prog_fader_labels[fader_idx].setText(str(value))

        # Use the fader execution control system (same as prog_faders)
        # This handles state tracking, auto-crossfade, and smooth intensity changes
        exec_assignments = self.app_settings.get('fader_execution_assignments', {})
        assigned_preset_id = exec_assignments.get(fader_id)
        
        # Check for position assignments
        pos_assignments = self.app_settings.get('fader_position_assignments', {})
        assigned_positions = pos_assignments.get(fader_id)
        
        # Check for visualizer assignments
        viz_assignments = self.app_settings.get('fader_visualizer_assignments', {})
        assigned_viz = viz_assignments.get(fader_id)
        
        if assigned_positions:
            self._handle_position_fader(fader_id, assigned_positions, value)
        elif assigned_viz:
            self._handle_visualizer_fader(fader_id, assigned_viz, value)
        elif assigned_preset_id:
            self._handle_fader_execution_control(fader_id, assigned_preset_id, value)

    def _on_fader_moved(self, fader_config: 'FaderConfig', value: int):
        """Handle fader being manually moved."""
        pass  # Real-time update happens via valueChanged
    
    # ── Fader page navigation arrows ──

    def _faders_page_prev(self):
        """Go to previous fader page."""
        # Determine the target index from whichever tab bar is available
        target_idx = None
        if hasattr(self, 'faders_page_tabs') and self.faders_page_tabs is not None:
            try:
                idx = self.faders_page_tabs.currentIndex()
                if idx > 0:
                    target_idx = idx - 1
                    self.faders_page_tabs.setCurrentIndex(target_idx)
            except RuntimeError:
                pass
        # Also switch any detached fader windows
        if hasattr(self, '_fader_windows'):
            for winfo in self._fader_windows.values():
                pt = winfo.get('page_tabs')
                if pt is not None:
                    try:
                        idx = pt.currentIndex()
                        if target_idx is not None:
                            pt.setCurrentIndex(target_idx)
                        elif idx > 0:
                            pt.setCurrentIndex(idx - 1)
                    except RuntimeError:
                        pass

    def _faders_page_next(self):
        """Go to next fader page."""
        target_idx = None
        if hasattr(self, 'faders_page_tabs') and self.faders_page_tabs is not None:
            try:
                idx = self.faders_page_tabs.currentIndex()
                if idx < self.faders_page_tabs.count() - 1:
                    target_idx = idx + 1
                    self.faders_page_tabs.setCurrentIndex(target_idx)
            except RuntimeError:
                pass
        # Also switch any detached fader windows
        if hasattr(self, '_fader_windows'):
            for winfo in self._fader_windows.values():
                pt = winfo.get('page_tabs')
                if pt is not None:
                    try:
                        idx = pt.currentIndex()
                        if target_idx is not None:
                            pt.setCurrentIndex(target_idx)
                        elif idx < pt.count() - 1:
                            pt.setCurrentIndex(idx + 1)
                    except RuntimeError:
                        pass

    def _faders_window_page_prev(self, page_tabs):
        """Go to previous fader page in a detached fader window."""
        if page_tabs is None:
            return
        idx = page_tabs.currentIndex()
        if idx > 0:
            page_tabs.setCurrentIndex(idx - 1)

    def _faders_window_page_next(self, page_tabs):
        """Go to next fader page in a detached fader window."""
        if page_tabs is None:
            return
        idx = page_tabs.currentIndex()
        if idx < page_tabs.count() - 1:
            page_tabs.setCurrentIndex(idx + 1)

    def _show_page_nav_midi_menu(self, pos, btn, nav_id: str):
        """Show right-click MIDI learn/clear context menu for page nav arrows."""
        midi_mgr = get_midi_manager()
        menu = QMenu(self)
        menu.setStyleSheet("""
            QMenu {
                background-color: #2d2d2d;
                border: 1px solid #444;
                border-radius: 4px;
                padding: 4px;
            }
            QMenu::item {
                padding: 8px 16px;
                color: white;
            }
            QMenu::item:selected {
                background-color: #3d3d3d;
            }
        """)

        label = "◀ Prev Page" if nav_id == "page_nav_prev" else "▶ Next Page"

        learn_action = menu.addAction(f"🎹 MIDI Learn ({label})")
        learn_action.triggered.connect(lambda: self._start_page_nav_midi_learn(nav_id, btn))

        # Show clear option if already mapped
        nav_mappings = self.app_settings.get('midi_page_nav_mappings', {})
        if nav_id in nav_mappings:
            midi_key = nav_mappings[nav_id]
            info_action = menu.addAction(f"📋 Mapped to: {midi_key}")
            info_action.setEnabled(False)
            clear_action = menu.addAction("❌ Remove MIDI Mapping")
            clear_action.triggered.connect(lambda: self._clear_page_nav_midi(nav_id))

        menu.exec(btn.mapToGlobal(pos))

    def _start_page_nav_midi_learn(self, nav_id: str, btn):
        """Start MIDI learn for a page navigation arrow."""
        midi_mgr = get_midi_manager()

        parent_window = btn.window() if btn else self
        dialog = QDialog(parent_window)
        dialog.setWindowTitle(f"MIDI Learn: {'Prev Page' if nav_id == 'page_nav_prev' else 'Next Page'}")
        dialog.setFixedSize(300, 150)
        dialog.setStyleSheet("""
            QDialog { background-color: #2d2d2d; }
            QLabel { color: white; font-size: 14px; }
        """)

        layout = QVBoxLayout(dialog)
        label = QLabel("Press a button on your MIDI controller...")
        label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        layout.addWidget(label)

        cancel_btn = QPushButton("Cancel")
        cancel_btn.clicked.connect(dialog.reject)
        layout.addWidget(cancel_btn)

        # Use learn mode to capture any MIDI input
        midi_mgr.set_learn_mode(True)
        learned_key = [None]

        def on_midi_received(midi_key: str):
            if learned_key[0] is None:
                learned_key[0] = midi_key
                label.setText(f"✓ Learned: {midi_key}")
                QTimer.singleShot(400, dialog.accept)

        midi_mgr.midi_received.connect(on_midi_received)

        result = dialog.exec()

        midi_mgr.set_learn_mode(False)
        try:
            midi_mgr.midi_received.disconnect(on_midi_received)
        except (TypeError, RuntimeError):
            pass

        if result == QDialog.DialogCode.Accepted and learned_key[0]:
            midi_key = learned_key[0]

            # Remove any previous mapping for this nav action
            self._clear_page_nav_midi(nav_id, save=False)

            # Save new mapping
            nav_mappings = self.app_settings.get('midi_page_nav_mappings', {})
            nav_mappings[nav_id] = midi_key
            self.app_settings['midi_page_nav_mappings'] = nav_mappings
            self._save_app_settings()

            # Register runtime callback
            self._register_page_nav_midi(nav_id, midi_key)
            print(f"[MIDI] Page nav '{nav_id}' mapped to {midi_key}")

    def _clear_page_nav_midi(self, nav_id: str, save: bool = True):
        """Clear MIDI mapping for a page navigation arrow."""
        midi_mgr = get_midi_manager()
        nav_mappings = self.app_settings.get('midi_page_nav_mappings', {})

        if nav_id in nav_mappings:
            midi_key = nav_mappings.pop(nav_id)
            # Remove from trigger system
            if midi_key in midi_mgr._mappings:
                if nav_id in midi_mgr._mappings[midi_key]:
                    midi_mgr._mappings[midi_key].remove(nav_id)
                    if not midi_mgr._mappings[midi_key]:
                        del midi_mgr._mappings[midi_key]
            if nav_id in midi_mgr._preset_callbacks:
                del midi_mgr._preset_callbacks[nav_id]

            if save:
                self.app_settings['midi_page_nav_mappings'] = nav_mappings
                self._save_app_settings()
            print(f"[MIDI] Page nav '{nav_id}' mapping cleared")

    def _register_page_nav_midi(self, nav_id: str, midi_key: str):
        """Register a MIDI key to trigger page navigation at runtime."""
        midi_mgr = get_midi_manager()

        # Use the preset-trigger system (note-on dispatching)
        if midi_key not in midi_mgr._mappings:
            midi_mgr._mappings[midi_key] = []
        if nav_id not in midi_mgr._mappings[midi_key]:
            midi_mgr._mappings[midi_key].append(nav_id)

        if nav_id == "page_nav_prev":
            midi_mgr._preset_callbacks[nav_id] = self._faders_page_prev
        else:
            midi_mgr._preset_callbacks[nav_id] = self._faders_page_next

    # ── Fader page-tab direct MIDI shortcuts ──

    def _show_page_tab_midi_menu(self, pos, page_tabs: 'QTabBar'):
        """Show right-click MIDI learn/clear context menu for a specific page tab."""
        tab_index = page_tabs.tabAt(pos)
        if tab_index < 0:
            return
        if tab_index >= len(self.project.faders.pages):
            return

        page = self.project.faders.pages[tab_index]
        page_id = page.id
        page_name = page.name

        menu = QMenu(self)
        menu.setStyleSheet("""
            QMenu {
                background-color: #2d2d2d;
                border: 1px solid #444;
                border-radius: 4px;
                padding: 4px;
            }
            QMenu::item {
                padding: 8px 16px;
                color: white;
            }
            QMenu::item:selected {
                background-color: #3d3d3d;
            }
        """)

        learn_action = menu.addAction(f"🎹 MIDI Learn ({page_name})")
        learn_action.triggered.connect(lambda: self._start_page_tab_midi_learn(page_id, page_name, page_tabs))

        tab_mappings = self.app_settings.get('midi_page_tab_mappings', {})
        if page_id in tab_mappings:
            midi_key = tab_mappings[page_id]
            info_action = menu.addAction(f"📋 Mapped to: {midi_key}")
            info_action.setEnabled(False)
            clear_action = menu.addAction("❌ Remove MIDI Mapping")
            clear_action.triggered.connect(lambda: self._clear_page_tab_midi(page_id))

        menu.addSeparator()

        # Set as Default page option
        current_default = self.app_settings.get('default_fader_page_id', '')
        is_default = (page_id == current_default)
        if is_default:
            default_action = menu.addAction(f"⭐ Default Page (current)")
            default_action.setEnabled(False)
        else:
            default_action = menu.addAction(f"⭐ Set as Default Page")
            default_action.triggered.connect(lambda: self._set_default_fader_page(page_id, page_name))

        menu.exec(page_tabs.mapToGlobal(pos))

    def _start_page_tab_midi_learn(self, page_id: str, page_name: str, page_tabs: 'QTabBar'):
        """Start MIDI learn for a specific fader page tab."""
        midi_mgr = get_midi_manager()

        parent_window = page_tabs.window() if page_tabs else self
        dialog = QDialog(parent_window)
        dialog.setWindowTitle(f"MIDI Learn: {page_name}")
        dialog.setFixedSize(300, 150)
        dialog.setStyleSheet("""
            QDialog { background-color: #2d2d2d; }
            QLabel { color: white; font-size: 14px; }
        """)

        layout = QVBoxLayout(dialog)
        label = QLabel("Press a button on your MIDI controller...")
        label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        layout.addWidget(label)

        cancel_btn = QPushButton("Cancel")
        cancel_btn.clicked.connect(dialog.reject)
        layout.addWidget(cancel_btn)

        midi_mgr.set_learn_mode(True)
        learned_key = [None]

        def on_midi_received(midi_key: str):
            if learned_key[0] is None:
                learned_key[0] = midi_key
                label.setText(f"✓ Learned: {midi_key}")
                QTimer.singleShot(400, dialog.accept)

        midi_mgr.midi_received.connect(on_midi_received)

        result = dialog.exec()

        midi_mgr.set_learn_mode(False)
        try:
            midi_mgr.midi_received.disconnect(on_midi_received)
        except (TypeError, RuntimeError):
            pass

        if result == QDialog.DialogCode.Accepted and learned_key[0]:
            midi_key = learned_key[0]

            # Remove any previous mapping for this page
            self._clear_page_tab_midi(page_id, save=False)

            # Save new mapping
            tab_mappings = self.app_settings.get('midi_page_tab_mappings', {})
            tab_mappings[page_id] = midi_key
            self.app_settings['midi_page_tab_mappings'] = tab_mappings
            self._save_app_settings()

            # Register runtime callback
            self._register_page_tab_midi(page_id, midi_key)
            print(f"[MIDI] Page tab '{page_name}' ({page_id}) mapped to {midi_key}")

    def _clear_page_tab_midi(self, page_id: str, save: bool = True):
        """Clear MIDI mapping for a fader page tab."""
        midi_mgr = get_midi_manager()
        tab_mappings = self.app_settings.get('midi_page_tab_mappings', {})
        virtual_id = f"page_tab:{page_id}"

        if page_id in tab_mappings:
            midi_key = tab_mappings.pop(page_id)
            # Remove from trigger system
            if midi_key in midi_mgr._mappings:
                if virtual_id in midi_mgr._mappings[midi_key]:
                    midi_mgr._mappings[midi_key].remove(virtual_id)
                    if not midi_mgr._mappings[midi_key]:
                        del midi_mgr._mappings[midi_key]
            if virtual_id in midi_mgr._preset_callbacks:
                del midi_mgr._preset_callbacks[virtual_id]

            if save:
                self.app_settings['midi_page_tab_mappings'] = tab_mappings
                self._save_app_settings()
            print(f"[MIDI] Page tab '{page_id}' mapping cleared")

    def _set_default_fader_page(self, page_id: str, page_name: str):
        """Set a fader page as the default startup page."""
        self.app_settings['default_fader_page_id'] = page_id
        self._save_app_settings()
        print(f"[Faders] Default page set to '{page_name}' ({page_id})")

    def _register_page_tab_midi(self, page_id: str, midi_key: str):
        """Register a MIDI key to jump to a specific fader page at runtime."""
        midi_mgr = get_midi_manager()
        virtual_id = f"page_tab:{page_id}"

        if midi_key not in midi_mgr._mappings:
            midi_mgr._mappings[midi_key] = []
        if virtual_id not in midi_mgr._mappings[midi_key]:
            midi_mgr._mappings[midi_key].append(virtual_id)

        def _go_to_page(pid=page_id):
            """Switch to the fader page with the given id."""
            if not hasattr(self, 'project') or not self.project.faders.pages:
                return
            for idx, pg in enumerate(self.project.faders.pages):
                if pg.id == pid:
                    # Switch main window tabs
                    if hasattr(self, 'faders_page_tabs') and self.faders_page_tabs is not None:
                        try:
                            self.faders_page_tabs.setCurrentIndex(idx)
                        except RuntimeError:
                            pass
                    # Also switch any detached fader windows
                    if hasattr(self, '_fader_windows'):
                        for winfo in self._fader_windows.values():
                            pt = winfo.get('page_tabs')
                            if pt is not None:
                                try:
                                    pt.setCurrentIndex(idx)
                                except RuntimeError:
                                    pass
                    break

        midi_mgr._preset_callbacks[virtual_id] = _go_to_page

    def _on_faders_page_tab_changed(self, tab_index: int):
        """Handle page tab selection change."""
        if tab_index < 0 or not hasattr(self, 'project') or not self.project.faders.pages:
            return
        
        if tab_index >= len(self.project.faders.pages):
            return
            
        page = self.project.faders.pages[tab_index]
        self.project.faders.current_page_id = page.id
        self._current_faders_page_id = page.id
        
        # Refresh main layout if valid
        if hasattr(self, 'faders_layout') and self.faders_layout is not None:
            try:
                self._populate_faders_layout(self.faders_layout, is_main=True)
            except RuntimeError:
                self.faders_layout = None
        
        # Refresh detached layouts (old style)
        if hasattr(self, '_detached_faders_layouts'):
            valid_layouts = []
            for layout in self._detached_faders_layouts:
                try:
                    self._populate_faders_layout(layout, is_main=False)
                    valid_layouts.append(layout)
                except RuntimeError:
                    pass  # Layout was deleted
            self._detached_faders_layouts = valid_layouts

        # Refresh dynamic MIDI sliders if FADERS tab is active
        if getattr(self, '_last_tab_name', None) == 'FADERS':
            QTimer.singleShot(50, lambda: self._update_dynamic_sliders_for_main_tab('FADERS'))
    
    def _on_faders_page_changed(self, page_name: str):
        """Handle page selection change for main window only (legacy combo box support)."""
        if not page_name:
            return
        
        # Find page by name
        for page in self.project.faders.pages:
            if page.name == page_name:
                self.project.faders.current_page_id = page.id
                self._current_faders_page_id = page.id
                
                # Refresh main layout if valid
                if hasattr(self, 'faders_layout') and self.faders_layout is not None:
                    try:
                        self._populate_faders_layout(self.faders_layout, is_main=True)
                    except RuntimeError:
                        self.faders_layout = None
                
                # Refresh detached layouts (old style)
                if hasattr(self, '_detached_faders_layouts'):
                    valid_layouts = []
                    for layout in self._detached_faders_layouts:
                        try:
                            self._populate_faders_layout(layout, is_main=False)
                            valid_layouts.append(layout)
                        except RuntimeError:
                            pass  # Layout was deleted
                    self._detached_faders_layouts = valid_layouts
                break
    
    def _on_faders_speed_changed(self, value: int):
        """Handle speed fader change from faders board - syncs with main effect speed."""
        if self._syncing_fader:
            return
        self._syncing_fader = True
        try:
            multiplier = value / 100.0
            
            # Sync all faders board speed sliders
            for slider, label in self._all_faders_board_speed_sliders:
                try:
                    if slider and slider.isVisible():
                        slider.blockSignals(True)
                        slider.setValue(value)
                        slider.blockSignals(False)
                    if label:
                        label.setText(f"{multiplier:.1f}x")
                except RuntimeError:
                    pass  # Widget deleted
            
            # Sync to main effect speed slider
            if hasattr(self, 'effect_speed_slider'):
                self.effect_speed_slider.blockSignals(True)
                self.effect_speed_slider.setValue(value)
                self.effect_speed_slider.blockSignals(False)
                self.effect_speed_label.setText(f"{multiplier:.2f}x")
            
            # Apply to effect engine
            if hasattr(self, 'effect_engine'):
                self.effect_engine.global_speed_multiplier = multiplier
        finally:
            self._syncing_fader = False
    
    def _on_faders_master_changed(self, value: int):
        """Handle master fader change from faders board - syncs with main master."""
        if self._syncing_fader:
            return
        self._syncing_fader = True
        try:
            # Sync all faders board master sliders
            for slider, label in self._all_faders_board_master_sliders:
                try:
                    if slider and slider.isVisible():
                        slider.blockSignals(True)
                        slider.setValue(value)
                        slider.blockSignals(False)
                    if label:
                        label.setText(f"{value}%")
                except RuntimeError:
                    pass  # Widget deleted
            
            # Sync to main master slider
            if hasattr(self, 'master_slider'):
                self.master_slider.blockSignals(True)
                self.master_slider.setValue(value)
                self.master_slider.blockSignals(False)
                self.master_label.setText(f"{value}%")
            
            # Apply to project
            self.project.master_intensity = value
            
            # Apply to Art-Net
            if hasattr(self, 'artnet'):
                self.artnet.master_level = value / 100.0
            
            # Re-trigger active group faders so pre-computed DMX reflects the new master cap
            self._refresh_active_group_faders()

            # Send MIDI feedback so motorized fader follows
            if not getattr(self, '_updating_from_midi', False):
                self._send_fader_feedback("master", value, max_val=100)
        finally:
            self._syncing_fader = False
    
    def _sync_faders_board_controls(self):
        """Sync the faders board speed/master sliders with main controls."""
        # Sync speed to all faders board speed sliders
        if hasattr(self, 'effect_speed_slider'):
            value = self.effect_speed_slider.value()
            multiplier = value / 100.0
            for slider, label in self._all_faders_board_speed_sliders:
                try:
                    if slider:
                        slider.blockSignals(True)
                        slider.setValue(value)
                        slider.blockSignals(False)
                    if label:
                        label.setText(f"{multiplier:.1f}x")
                except RuntimeError:
                    pass  # Widget deleted
        
        # Sync master to all faders board master sliders
        if hasattr(self, 'master_slider'):
            value = self.master_slider.value()
            for slider, label in self._all_faders_board_master_sliders:
                try:
                    if slider:
                        slider.blockSignals(True)
                        slider.setValue(value)
                        slider.blockSignals(False)
                    if label:
                        label.setText(f"{value}%")
                except RuntimeError:
                    pass  # Widget deleted
    
    def _on_fader_name_changed(self, fader_config: 'FaderConfig', new_name: str):
        """Handle fader name change."""
        fader_config.name = new_name.strip() if new_name else f"Fader {fader_config.id}"
    
    def _add_faders_page(self):
        """Add a new faders page."""
        new_page_num = len(self.project.faders.pages) + 1
        new_page = self.project.faders.add_page(f"Page {new_page_num}")
        self._refresh_faders_tab()
        # Select new page (it's the last tab)
        if hasattr(self, 'faders_page_tabs') and self.faders_page_tabs:
            new_idx = len(self.project.faders.pages) - 1
            self.faders_page_tabs.setCurrentIndex(new_idx)
    
    def _get_active_faders_page(self):
        """Return the fader page currently selected in whatever fader window
        triggered the action (detached window or main tab)."""
        # Check if the action was triggered from a detached fader window
        # by walking up from the sender (the clicked button).
        sender = self.sender()
        if sender is not None:
            # Walk up to find the top-level window the button lives in
            widget = sender
            parent_win = None
            while widget is not None:
                parent_win = widget
                widget = widget.parentWidget()
            # Check each detached fader window
            for win_data in self._fader_windows.values():
                if win_data.get('window') is parent_win:
                    # Use this window's selected page tab
                    page_tabs = win_data.get('page_tabs')
                    if page_tabs is not None:
                        idx = page_tabs.currentIndex()
                        if 0 <= idx < len(self.project.faders.pages):
                            return self.project.faders.pages[idx]
                    # Fall back to tracked page_id
                    pid = win_data.get('page_id')
                    if pid:
                        for p in self.project.faders.pages:
                            if p.id == pid:
                                return p
        # Main window path: use the main tab bar selection
        if hasattr(self, 'faders_page_tabs') and self.faders_page_tabs is not None:
            try:
                idx = self.faders_page_tabs.currentIndex()
                if 0 <= idx < len(self.project.faders.pages):
                    return self.project.faders.pages[idx]
            except RuntimeError:
                pass
        return self.project.faders.get_current_page()

    def _rename_faders_page(self):
        """Rename the current faders page."""
        current_page = self._get_active_faders_page()
        if not current_page:
            return
        
        text, ok = self._show_input_dialog("Rename Page", f"Enter new name for '{current_page.name}':",
                                       current_page.name)
        if ok and text:
            current_page.name = text.strip()
            self._refresh_faders_tab()
    
    def _delete_faders_page(self):
        """Delete the current faders page."""
        current_page = self._get_active_faders_page()
        if not current_page:
            return
        
        if len(self.project.faders.pages) <= 1:
            self._show_message_box("warning", "Cannot Delete", "You must have at least one fader page.")
            return
        
        reply = self._show_message_box("question", "Confirm Delete", 
                                    f"Delete fader page '{current_page.name}'?\n\nThis cannot be undone.",
                                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        if reply == QMessageBox.StandardButton.Yes:
            self.project.faders.delete_page(current_page.id)
            self._refresh_faders_tab()
    
    def _show_fader_context_menu(self, fader_config: 'FaderConfig'):
        """Show context menu for fader MIDI mapping."""
        menu = QMenu(self)
        menu.setStyleSheet(self._get_touch_menu_stylesheet())
        
        # Assign to MIDI
        assign_action = menu.addAction("🎹 Assign MIDI CC")
        assign_action.triggered.connect(lambda: self._assign_fader_midi(fader_config))
        
        # View/Clear MIDI assignments
        if fader_config.midi_ccs:
            view_action = menu.addAction(f"📋 View MIDI CCs ({len(fader_config.midi_ccs)})")
            view_action.triggered.connect(lambda: self._show_fader_midi_list(fader_config))
            
            clear_action = menu.addAction("❌ Clear All MIDI")
            clear_action.triggered.connect(lambda: self._clear_fader_midi(fader_config))
        
        menu.exec(QCursor.pos())
    
    def _assign_fader_midi(self, fader_config: 'FaderConfig'):
        """Assign a fader to one or more MIDI CCs."""
        midi_mgr = get_midi_manager()
        if not midi_mgr.is_connected:
            QMessageBox.warning(self._get_active_window(), "No MIDI Device", "Connect a MIDI device first in Settings > MIDI.")
            return
        
        # Open MIDI learning dialog - use cursor position to determine parent window
        from PyQt6.QtGui import QCursor
        cursor_pos = QCursor.pos()
        parent_window = self
        # Find the window under the cursor
        for win in [self] + list(self._detached_windows.values()):
            try:
                if win.geometry().contains(cursor_pos):
                    parent_window = win
                    break
            except RuntimeError:
                pass
        dialog = QDialog(parent_window)
        dialog.setWindowTitle(f"Learn MIDI for '{fader_config.name}'")
        dialog.setMinimumWidth(400)
        layout = QVBoxLayout()
        
        label = QLabel("Turn or move a MIDI control on your device...\n\n(Waiting for input)")
        label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        label.setStyleSheet("font-size: 14px; padding: 20px;")
        layout.addWidget(label)
        
        # List of learned CCs
        learned_list = QListWidget()
        learned_list.setMaximumHeight(100)
        layout.addWidget(QLabel("Learned CCs:"))
        layout.addWidget(learned_list)
        
        # Buttons
        button_layout = QHBoxLayout()
        learn_more_button = QPushButton("Learn Another CC")
        ok_button = QPushButton("OK")
        cancel_button = QPushButton("Cancel")
        learn_more_button.setMinimumHeight(40)
        ok_button.setMinimumHeight(40)
        cancel_button.setMinimumHeight(40)
        button_layout.addWidget(learn_more_button)
        button_layout.addWidget(ok_button)
        button_layout.addWidget(cancel_button)
        layout.addLayout(button_layout)
        
        dialog.setLayout(layout)
        
        # Enable MIDI learn mode
        midi_mgr.set_learn_mode(True)
        learned_ccs = []
        
        def on_midi_received(midi_key):
            nonlocal learned_ccs
            # Extract CC number from midi_key (e.g., "cc:1" -> 1)
            if midi_key.startswith("cc:"):
                try:
                    cc_num = int(midi_key.split(":")[1])
                    if cc_num not in learned_ccs:
                        learned_ccs.append(cc_num)
                        # Store the device name that sent this message
                        device_name = getattr(midi_mgr, '_last_received_device', None)
                        if device_name:
                            midi_mgr._mapping_devices[midi_key] = device_name
                        learned_list.addItem(f"CC {cc_num}")
                        label.setText(f"✓ Learned CC {cc_num}\n\nLearn another or click OK")
                except:
                    pass
        
        # Connect signal temporarily
        midi_mgr.midi_received.connect(on_midi_received)
        
        # Connect button signals
        ok_button.clicked.connect(dialog.accept)
        cancel_button.clicked.connect(dialog.reject)
        learn_more_button.clicked.connect(lambda: label.setText("Waiting for next MIDI input..."))
        
        # Wait with timeout
        result = dialog.exec()
        
        # Disable learn mode
        midi_mgr.set_learn_mode(False)
        midi_mgr.midi_received.disconnect(on_midi_received)
        
        if result == QDialog.DialogCode.Accepted and learned_ccs:
            # Add learned CCs to the fader config
            for cc_num in learned_ccs:
                if cc_num not in fader_config.midi_ccs:
                    fader_config.midi_ccs.append(cc_num)
            
            # Register ALL MIDI mappings for this fader directly in midi_manager
            for cc_num in fader_config.midi_ccs:
                cc_key = f"cc:{cc_num}"
                # Directly update the internal mapping dict
                midi_mgr._fader_mappings[cc_key] = fader_config.id
            
            # Register callback once (handles all mapped CCs)
            midi_mgr.register_fader_callback(fader_config.id, 
                lambda val, max_val, fc=fader_config: self._on_midi_large_fader(fc, val, max_val))
            
            # Save mapping to settings
            fader_mappings = self.app_settings.get('midi_fader_mappings', {})
            # Store as list of CC keys for each fader
            fader_mappings[fader_config.id] = [f"cc:{cc}" for cc in fader_config.midi_ccs]
            self.app_settings['midi_fader_mappings'] = fader_mappings
            # Also save the device mappings so controller names persist
            self.app_settings['midi_mapping_devices'] = midi_mgr.get_mapping_devices_dict()
            self._save_app_settings()
            
            cc_list = ", ".join([f"CC {cc}" for cc in learned_ccs])
            QMessageBox.information(self._get_active_window(), "Success", f"Fader '{fader_config.name}' assigned to {cc_list}")
            self._mark_dirty()
            self._refresh_faders_tab()
    
    def _show_fader_midi_list(self, fader_config: 'FaderConfig'):
        """Show dialog listing all MIDI CCs assigned to a fader."""
        if not fader_config.midi_ccs:
            QMessageBox.information(self._get_active_window(), "No MIDI Assignments", f"Fader '{fader_config.name}' has no MIDI assignments.")
            return
        
        cc_list = ", ".join([f"CC {cc}" for cc in fader_config.midi_ccs])
        
        dialog = QDialog(self._get_active_window())
        dialog.setWindowTitle(f"MIDI Assignments for '{fader_config.name}'")
        dialog.setMinimumWidth(300)
        layout = QVBoxLayout()
        
        label = QLabel(f"Assigned MIDI Controls:\n\n{cc_list}")
        label.setStyleSheet("font-size: 14px; padding: 20px;")
        layout.addWidget(label)
        
        button_layout = QHBoxLayout()
        add_button = QPushButton("Add Another CC")
        remove_button = QPushButton("Remove CC")
        close_button = QPushButton("Close")
        add_button.setMinimumHeight(40)
        remove_button.setMinimumHeight(40)
        close_button.setMinimumHeight(40)
        button_layout.addWidget(add_button)
        button_layout.addWidget(remove_button)
        button_layout.addWidget(close_button)
        layout.addLayout(button_layout)
        
        dialog.setLayout(layout)
        
        def add_cc():
            # Re-open assignment dialog to add more CCs
            dialog.accept()
            self._assign_fader_midi(fader_config)
        
        def remove_cc():
            # Simple dialog to select which CC to remove
            items = [f"CC {cc}" for cc in fader_config.midi_ccs]
            item, ok = QInputDialog.getItem(self._get_active_window(), "Remove MIDI CC", "Select CC to remove:", items)
            if ok and item:
                try:
                    cc_num = int(item.split()[1])
                    fader_config.midi_ccs.remove(cc_num)
                    
                    # Update MIDI mappings
                    midi_mgr = get_midi_manager()
                    for cc in fader_config.midi_ccs:
                        cc_key = f"cc:{cc}"
                        midi_mgr._fader_mappings[cc_key] = fader_config.id
                    
                    # Save settings
                    fader_mappings = self.app_settings.get('midi_fader_mappings', {})
                    fader_mappings[fader_config.id] = [f"cc:{cc}" for cc in fader_config.midi_ccs]
                    self.app_settings['midi_fader_mappings'] = fader_mappings
                    self._save_app_settings()
                    
                    self._mark_dirty()
                    dialog.accept()
                    self._refresh_faders_tab()
                except:
                    pass
        
        add_button.clicked.connect(add_cc)
        remove_button.clicked.connect(remove_cc)
        close_button.clicked.connect(dialog.accept)
        
        dialog.exec()

    
    def _clear_fader_midi(self, fader_config: 'FaderConfig'):
        """Clear all MIDI assignments from a fader."""
        if not fader_config.midi_ccs:
            return
        
        reply = QMessageBox.question(self._get_active_window(), "Clear MIDI Assignments",
            f"Remove all MIDI CC assignments from '{fader_config.name}'?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        
        if reply == QMessageBox.StandardButton.Yes:
            midi_mgr = get_midi_manager()
            
            # Clear all CC mappings for this fader
            for cc_num in fader_config.midi_ccs:
                cc_key = f"cc:{cc_num}"
                # Unregister from MIDI manager
                if cc_key in midi_mgr._fader_mappings:
                    del midi_mgr._fader_mappings[cc_key]
            
            # Clear from config
            fader_config.midi_ccs = []
            
            # Update settings
            fader_mappings = self.app_settings.get('midi_fader_mappings', {})
            if fader_config.id in fader_mappings:
                del fader_mappings[fader_config.id]
            self.app_settings['midi_fader_mappings'] = fader_mappings
            self._save_app_settings()
            
            self._mark_dirty()
            self._refresh_faders_tab()
    
    def _on_midi_large_fader(self, fader_config: 'FaderConfig', value: int, max_value: int):
        """Handle MIDI CC input for large fader controls."""
        # Map 0-127 (CC range) or 0-max_value to 0-100 (fader range)
        if max_value > 0:
            fader_value = int((value / max_value) * 100)
        else:
            fader_value = value
        
        # Clamp to 0-100
        fader_value = max(0, min(100, fader_value))
        
        print(f"[MIDI Fader] {fader_config.name} (ID: {fader_config.id}): MIDI value={value} max={max_value} -> fader_value={fader_value}")
        
        # Update fader config value
        fader_config.value = fader_value
        
        # Update all slider instances (main window + detached windows)
        if fader_config.id in self._all_fader_sliders:
            sliders = self._all_fader_sliders[fader_config.id]
            print(f"[MIDI Fader] Found {len(sliders)} slider(s) for {fader_config.name}")
            self._syncing_fader = True
            try:
                valid_sliders = []
                for slider in sliders:
                    try:
                        # Try to access the slider - if deleted, this will raise
                        if slider.value() != fader_value:
                            print(f"[MIDI Fader] Updating slider from {slider.value()} to {fader_value}")
                            slider.blockSignals(True)
                            slider.setValue(fader_value)
                            slider.blockSignals(False)
                        valid_sliders.append(slider)
                    except RuntimeError:
                        # Slider was deleted, skip it
                        print(f"[MIDI Fader] Skipping deleted slider")
                        pass
                
                # Update the list with only valid sliders
                if valid_sliders:
                    self._all_fader_sliders[fader_config.id] = valid_sliders
                else:
                    del self._all_fader_sliders[fader_config.id]
            finally:
                self._syncing_fader = False
        else:
            print(f"[MIDI Fader] WARNING: No sliders registered for {fader_config.id}")
        
        # If fader is assigned to a preset/effect, execute it
        if fader_config.assigned_preset_id and fader_config.assigned_preset_type == "effect":
            preset = self.project.get_preset_by_id(fader_config.assigned_preset_id)
            if preset:
                # Adjust intensity based on fader value
                old_intensity = preset.intensity
                preset.intensity = fader_value
                # Execute the preset
                self._execute_preset(preset)
                # Restore original intensity
                preset.intensity = old_intensity
    
    # SHORTCUTS TAB - OSC/MIDI Shortcut Buttons
    # =========================================================================
    
    def _create_shortcuts_tab(self) -> QWidget:
        """Create the Shortcuts tab with paged OSC/MIDI shortcut buttons."""
        widget = QWidget()
        layout = QVBoxLayout(widget)
        layout.setContentsMargins(20, 20, 20, 20)
        layout.setSpacing(15)
        
        # Header row with Create New Shortcut button
        header_row = QHBoxLayout()
        header = QLabel("OSC/MIDI Shortcuts")
        header.setStyleSheet("font-size: 24px; font-weight: bold; color: #c97a50;")
        header_row.addWidget(header)
        header_row.addStretch()
        create_shortcut_btn = QPushButton("➕ Create New Shortcut")
        create_shortcut_btn.setStyleSheet("""
            QPushButton {
                background-color: #2a5a2a;
                color: white;
                border: 1px solid #4caf50;
                border-radius: 6px;
                font-size: 13px;
                padding: 8px 16px;
            }
            QPushButton:hover { background-color: #3a6a3a; }
            QPushButton:pressed { background-color: #1a4a1a; }
        """)
        create_shortcut_btn.clicked.connect(lambda: self._add_shortcut(
            self.project.shortcut_pages[self.shortcut_page_tabs.currentIndex()]
            if self.shortcut_page_tabs.currentIndex() >= 0 and self.project.shortcut_pages else None
        ))
        header_row.addWidget(create_shortcut_btn)
        layout.addLayout(header_row)
        
        # Page tabs (sub-tabs within the Shortcuts tab)
        self.shortcut_page_tabs = QTabWidget()
        self.shortcut_page_tabs.setTabPosition(QTabWidget.TabPosition.North)
        self.shortcut_page_tabs.setDocumentMode(True)
        self.shortcut_page_tabs.setTabsClosable(False)
        self.shortcut_page_tabs.setMovable(True)
        self.shortcut_page_tabs.setStyleSheet("""
            QTabWidget::pane { border: none; background-color: #1e1e1e; }
            QTabBar::tab { 
                background: #2d2d2d; 
                color: white; 
                padding: 8px 16px; 
                margin-right: 2px;
                border-top-left-radius: 4px;
                border-top-right-radius: 4px;
            }
            QTabBar::tab:selected { background: #3d3d3d; }
            QTabBar::tab:hover { background: #454545; }
        """)
        
        # Context menu for tabs
        self.shortcut_page_tabs.tabBar().setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.shortcut_page_tabs.tabBar().customContextMenuRequested.connect(self._show_shortcut_page_context_menu)
        
        layout.addWidget(self.shortcut_page_tabs, 1)
        
        # Bottom toolbar - compact
        toolbar = QHBoxLayout()
        toolbar.setSpacing(5)
        toolbar.setContentsMargins(0, 5, 0, 0)
        
        add_page_btn = QPushButton("+ Add Page")
        add_page_btn.clicked.connect(self._add_shortcut_page)
        add_page_btn.setStyleSheet("""
            QPushButton {
                background-color: #3d3d3d;
                color: white;
                border: 1px solid #555;
                border-radius: 4px;
                font-size: 11px;
                padding: 4px 10px;
            }
            QPushButton:hover { background-color: #4d4d4d; }
            QPushButton:pressed { background-color: #2d2d2d; }
        """)
        toolbar.addWidget(add_page_btn)
        
        toolbar.addStretch()
        
        layout.addLayout(toolbar)
        
        # Populate pages
        self._refresh_shortcut_pages()
        
        return widget
    
    def _refresh_all_shortcut_tabs(self):
        """Refresh all open Shortcuts tabs (main and detached) to keep them in sync."""
        if hasattr(self, 'shortcut_page_tabs'):
            self._refresh_shortcut_pages()
        if hasattr(self, '_detached_windows') and 'MIDI AND\nOSC TRIGGERS' in self._detached_windows:
            win = self._detached_windows['MIDI AND\nOSC TRIGGERS']
            # Recreate the detached window content
            win.setCentralWidget(self._create_shortcuts_tab())
    
    def _refresh_shortcut_pages(self):
        """Refresh the shortcut page tabs with current data."""
        if not hasattr(self, 'shortcut_page_tabs'):
            return
        
        # Remember current tab
        current_idx = self.shortcut_page_tabs.currentIndex()
        
        # Clear existing tabs
        self.shortcut_page_tabs.clear()
        
        # Ensure at least one page exists
        if not self.project.shortcut_pages:
            try:
                from .models import ShortcutPage
            except ImportError:
                from models import ShortcutPage
            import uuid
            self.project.shortcut_pages.append(ShortcutPage(
                id=str(uuid.uuid4()),
                name="Page 1",
                shortcuts=[]
            ))
        
        # Create tabs for each page
        for page in self.project.shortcut_pages:
            page_widget = self._create_shortcut_page_widget(page)
            self.shortcut_page_tabs.addTab(page_widget, page.name)
        
        # Restore tab selection
        if 0 <= current_idx < self.shortcut_page_tabs.count():
            self.shortcut_page_tabs.setCurrentIndex(current_idx)
    
    def _create_shortcut_page_widget(self, page) -> QWidget:
        """Create the widget for a single shortcut page."""
        widget = QWidget()
        widget.setProperty("page_id", page.id)
        
        layout = QVBoxLayout(widget)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(10)
        
        # Scroll area for buttons
        scroll = TouchScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setStyleSheet("""
            QScrollArea { border: none; background-color: #1e1e1e; }
            QScrollBar:vertical { width: 20px; }
            QScrollBar:horizontal { height: 20px; }
        """)
        
        # Create a custom droppable container
        class DroppableContainer(QWidget):
            def __init__(self, parent, page_ref, gui_ref):
                super().__init__(parent)
                self.page_ref = page_ref
                self.gui_ref = gui_ref
                self.setAcceptDrops(True)
            
            def dragEnterEvent(self, event):
                if event.mimeData().hasText():
                    event.acceptProposedAction()
            
            def dragMoveEvent(self, event):
                if event.mimeData().hasText():
                    event.acceptProposedAction()
            
            def dropEvent(self, event):
                if event.mimeData().hasText():
                    shortcut_id = event.mimeData().text()
                    # Find the shortcut being dragged
                    dragged_shortcut = None
                    for s in self.page_ref.shortcuts:
                        if s.id == shortcut_id:
                            dragged_shortcut = s
                            break
                    
                    if dragged_shortcut:
                        # Find the widget at drop position (convert QPointF to QPoint)
                        from PyQt6.QtCore import QPoint
                        drop_pos = QPoint(int(event.position().x()), int(event.position().y()))
                        target_widget = self.childAt(drop_pos)
                        
                        if target_widget and hasattr(target_widget, 'shortcut'):
                            target_shortcut = target_widget.shortcut
                            # Find indices
                            from_idx = self.page_ref.shortcuts.index(dragged_shortcut)
                            to_idx = self.page_ref.shortcuts.index(target_shortcut)
                            
                            # Swap if different
                            if from_idx != to_idx:
                                self.page_ref.shortcuts[from_idx], self.page_ref.shortcuts[to_idx] = \
                                    self.page_ref.shortcuts[to_idx], self.page_ref.shortcuts[from_idx]
                                self.gui_ref._mark_dirty()
                                # Defer refresh so drag source widget isn't destroyed
                                # while QDrag.exec() is still running (prevents segfault)
                                QTimer.singleShot(0, self.gui_ref._refresh_all_shortcut_tabs)
                        
                        event.acceptProposedAction()
        
        # Container for button flow layout
        container = DroppableContainer(self, page, self)
        container.setProperty("page_id", page.id)
        flow_layout = FlowLayout(container, margin=10, h_spacing=15, v_spacing=15)
        
        # Set context menu on container for right-click to add shortcuts
        container.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        container.customContextMenuRequested.connect(
            lambda pos, p=page: self._show_shortcut_container_context_menu(pos, p)
        )
        
        scroll.setWidget(container)
        layout.addWidget(scroll, 1)
        
        # Store reference for refresh
        if not hasattr(self, '_shortcut_page_layouts'):
            self._shortcut_page_layouts = {}
        self._shortcut_page_layouts[page.id] = flow_layout
        
        # Populate buttons
        self._populate_shortcut_buttons(page, flow_layout)
        
        return widget
    
    def _populate_shortcut_buttons(self, page, layout: 'FlowLayout'):
        """Populate a shortcut page with buttons."""
        # Clear existing buttons
        while layout.count():
            item = layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
        
        # Enable drop support on the layout's parent
        layout.parentWidget().setAcceptDrops(True)
        
        # Button size (same as execute tab)
        tile_width = 160
        tile_height = 120
        
        # Custom draggable button class
        class DraggableButton(_WordWrapButtonMixin, QPushButton):
            def __init__(self, *args, **kwargs):
                super().__init__(*args, **kwargs)
                self.drag_start_pos = None
                self.shortcut = None
                self.page = None
            
            def mousePressEvent(self, event):
                if event.button() == Qt.MouseButton.LeftButton:
                    self.drag_start_pos = event.pos()
                    super().mousePressEvent(event)
                elif event.button() == Qt.MouseButton.RightButton:
                    event.ignore()
                    return
                else:
                    super().mousePressEvent(event)
            
            def mouseMoveEvent(self, event):
                if (event.buttons() == Qt.MouseButton.LeftButton and 
                    self.drag_start_pos is not None):
                    distance = (event.pos() - self.drag_start_pos).manhattanLength()
                    if distance > 10:  # Threshold before drag starts
                        self._start_drag()
                        return
                super().mouseMoveEvent(event)
            
            def mouseReleaseEvent(self, event):
                if event.button() == Qt.MouseButton.RightButton:
                    event.ignore()
                    return
                self.drag_start_pos = None
                super().mouseReleaseEvent(event)
            
            def _start_drag(self):
                """Start a drag operation."""
                drag = QDrag(self)
                mime_data = QMimeData()
                mime_data.setText(self.shortcut.id)
                drag.setMimeData(mime_data)
                
                # Visual feedback: create a semi-transparent pixmap
                pixmap = self.grab()
                drag.setPixmap(pixmap)
                drag.setHotSpot(self.drag_start_pos)
                
                drag.exec(Qt.DropAction.MoveAction)
        
        def create_tile_button(shortcut) -> QPushButton:
            """Create a shortcut button with OSC/MIDI indicators."""
            btn = DraggableButton(shortcut.name)
            btn.setFixedSize(tile_width, tile_height)
            btn.shortcut = shortcut
            btn.page = page
            
            # Font size based on text measurement
            font_size = _calc_tile_font_size(shortcut.name, tile_width, tile_height)
            
            bg_medium = "#3d3d3d"
            stripe_color = shortcut.color if shortcut.color else "#c97a50"
            
            # Check for MIDI mapping (trigger via MIDI button)
            midi_mgr = get_midi_manager()
            shortcut_midi_id = f"shortcut_{shortcut.id}"
            has_midi = bool(midi_mgr.get_mappings_for_preset(shortcut_midi_id))
            
            # Check if this shortcut is currently selected (last triggered)
            is_selected = getattr(self, '_active_shortcut_id', None) == shortcut.id
            
            # Border style - green for selected, gray for MIDI mapped, default otherwise
            if is_selected:
                border_style = "border: 3px solid #00ff00;"
                hover_border = "border: 3px solid #00ff00;"
            elif has_midi:
                border_style = "border: 2px solid #888888;"
                hover_border = "border: 2px solid #c97a50;"
            else:
                border_style = "border: 1px solid #4d4d4d;"
                hover_border = "border: 2px solid #c97a50;"
            
            btn.setStyleSheet(f"""
                QPushButton {{
                    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                        stop:0 {bg_medium},
                        stop:0.85 {bg_medium},
                        stop:0.86 {stripe_color},
                        stop:1 {stripe_color});
                    color: white;
                    font-size: {font_size}px;
                    font-weight: 600;
                    {border_style}
                    border-radius: 6px;
                    padding: 12px 8px 20px 8px;
                }}
                QPushButton:hover {{
                    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                        stop:0 #454545,
                        stop:0.85 #454545,
                        stop:0.86 #c97a50,
                        stop:1 #c97a50);
                    {hover_border}
                }}
                QPushButton:pressed {{
                    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                        stop:0 #555555,
                        stop:0.85 #555555,
                        stop:0.86 #ff8844,
                        stop:1 #ff8844);
                }}
            """)
            
            # Tooltip showing OSC/MIDI config
            tooltip_parts = []
            if shortcut.osc_enabled:
                tooltip_parts.append(f"OSC: {shortcut.osc_ip}:{shortcut.osc_port} {shortcut.osc_address}")
            if shortcut.midi_enabled:
                tooltip_parts.append(f"MIDI: {shortcut.midi_type} Ch{shortcut.midi_channel} Note{shortcut.midi_note}")
            if tooltip_parts:
                btn.setToolTip("\n".join(tooltip_parts))
            
            btn._setup_tile_font(font_size)
            return btn
        
        # Create buttons for each shortcut
        for shortcut in page.shortcuts:
            btn = create_tile_button(shortcut)
            btn.clicked.connect(lambda checked=False, s=shortcut: self._trigger_shortcut(s))
            btn.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
            btn.customContextMenuRequested.connect(
                lambda pos, s=shortcut, b=btn, p=page: self._show_shortcut_button_context_menu(pos, s, b, p)
            )
            layout.addWidget(btn)
    
    def _show_shortcut_page_context_menu(self, pos):
        """Show context menu for shortcut page tab."""
        # Use sender() to get the actual tab bar that was clicked (works for detached windows)
        tab_bar = self.sender()
        if tab_bar is None:
            tab_bar = self.shortcut_page_tabs.tabBar()
        tab_idx = tab_bar.tabAt(pos)
        
        # Use tab_bar as parent so menu appears on correct monitor
        menu = QMenu(tab_bar)
        menu.setStyleSheet(self._get_touch_menu_stylesheet())
        
        if tab_idx >= 0:
            rename_action = menu.addAction("✏️ Rename Page")
            rename_action.triggered.connect(lambda: self._rename_shortcut_page(tab_idx))
            
            if len(self.project.shortcut_pages) > 1:
                delete_action = menu.addAction("🗑️ Delete Page")
                delete_action.triggered.connect(lambda: self._delete_shortcut_page(tab_idx))
        
        menu.addSeparator()
        add_action = menu.addAction("➕ Add Page")
        add_action.triggered.connect(self._add_shortcut_page)
        
        menu.exec(tab_bar.mapToGlobal(pos))
    
    def _show_shortcut_container_context_menu(self, pos, page):
        """Show context menu when right-clicking on empty area of shortcut page."""
        menu = QMenu(self)
        
        add_action = menu.addAction("➕ New Shortcut")
        add_action.triggered.connect(lambda: self._add_shortcut(page))
        
        # Find the widget that was clicked to get global position
        sender = self.sender()
        if sender:
            menu.exec(sender.mapToGlobal(pos))
    
    def _show_shortcut_button_context_menu(self, pos, shortcut, button, page):
        """Show context menu for a shortcut button."""
        # Use button as parent so menu appears on correct monitor
        menu = QMenu(button)
        menu.setStyleSheet(self._get_touch_menu_stylesheet())
        
        # MIDI Learn section (trigger this shortcut via MIDI button press)
        midi_mgr = get_midi_manager()
        # Use "shortcut_" prefix to distinguish from execute preset IDs
        shortcut_midi_id = f"shortcut_{shortcut.id}"
        midi_mappings = midi_mgr.get_mappings_for_preset(shortcut_midi_id)
        
        if midi_mgr.is_available:
            learn_action = menu.addAction("🎹 Learn MIDI...")
            learn_action.triggered.connect(lambda: self._start_midi_learn_shortcut(shortcut, button))
            
            if midi_mappings:
                # Show current mappings
                mappings_menu = menu.addMenu("🎹 MIDI Mappings")
                mappings_menu.setStyleSheet(self._get_touch_menu_stylesheet())
                for midi_key in midi_mappings:
                    display = MIDIManager.format_midi_key(midi_key)
                    mapping_action = mappings_menu.addAction(f"  {display}")
                    mapping_action.setEnabled(False)
                
                mappings_menu.addSeparator()
                clear_action = mappings_menu.addAction("❌ Clear All Mappings")
                clear_action.triggered.connect(lambda: self._clear_midi_mappings_shortcut(shortcut))
            
            menu.addSeparator()
        
        trigger_action = menu.addAction("▶ Trigger Now")
        trigger_action.triggered.connect(lambda: self._trigger_shortcut(shortcut))
        
        menu.addSeparator()
        
        edit_action = menu.addAction("✏️ Edit Shortcut")
        edit_action.triggered.connect(lambda: self._edit_shortcut(shortcut, page))
        
        color_action = menu.addAction("🎨 Change Color")
        color_action.triggered.connect(lambda: self._change_shortcut_color(shortcut, page))
        
        duplicate_action = menu.addAction("📋 Duplicate")
        duplicate_action.triggered.connect(lambda: self._duplicate_shortcut(shortcut, page))
        
        menu.addSeparator()
        
        # Add Move Up/Down options
        try:
            idx = page.shortcuts.index(shortcut)
            if idx > 0:
                move_up_action = menu.addAction("⬆️ Move Up")
                move_up_action.triggered.connect(lambda: self._move_shortcut(shortcut, page, -1))
            
            if idx < len(page.shortcuts) - 1:
                move_down_action = menu.addAction("⬇️ Move Down")
                move_down_action.triggered.connect(lambda: self._move_shortcut(shortcut, page, 1))
        except ValueError:
            pass
        
        # Move to Page / Copy to Page (only if multiple pages exist)
        if len(self.project.shortcut_pages) > 1:
            move_page_menu = menu.addMenu("📋 Move to Page")
            move_page_menu.setStyleSheet(self._get_touch_menu_stylesheet())
            for other_page in self.project.shortcut_pages:
                if other_page.id != page.id:
                    move_action = move_page_menu.addAction(other_page.name)
                    move_action.triggered.connect(lambda checked=False, op=other_page: self._move_shortcut_to_page(shortcut, page, op))
        
        copy_page_menu = menu.addMenu("📑 Copy to Page")
        copy_page_menu.setStyleSheet(self._get_touch_menu_stylesheet())
        for other_page in self.project.shortcut_pages:
            if other_page.id != page.id:
                copy_action = copy_page_menu.addAction(other_page.name)
                copy_action.triggered.connect(lambda checked=False, op=other_page: self._copy_shortcut_to_page(shortcut, op))
        
        menu.addSeparator()
        
        delete_action = menu.addAction("🗑️ Delete Shortcut")
        delete_action.triggered.connect(lambda: self._delete_shortcut(shortcut, page))
        
        menu.exec(button.mapToGlobal(pos))
    
    def _start_midi_learn_shortcut(self, shortcut, button):
        """Start MIDI learn mode for a shortcut button."""
        midi_mgr = get_midi_manager()
        
        if not midi_mgr.is_connected:
            # Check if we have a configured port
            port = self.app_settings.get('midi_input_port', '')
            if port and port in midi_mgr.get_input_ports():
                midi_mgr.connect(port)
            else:
                QMessageBox.warning(
                    self, "MIDI Not Connected",
                    "Please configure a MIDI input device in Settings first.\n\n"
                    "Go to menu: Tools → MIDI Settings..."
                )
                return
        
        # Create learn dialog
        dialog = QDialog(self._get_active_window())
        dialog.setWindowTitle(f"MIDI Learn - {shortcut.name}")
        dialog.setMinimumWidth(400)
        dialog.setMinimumHeight(200)
        dialog.setStyleSheet(DARK_STYLESHEET)
        
        layout = QVBoxLayout(dialog)
        layout.setSpacing(16)
        
        label = QLabel("Press a button/key on your MIDI controller...")
        label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        label.setStyleSheet("font-size: 16px; padding: 20px;")
        layout.addWidget(label)
        
        status_label = QLabel("Waiting for MIDI input...")
        status_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        status_label.setStyleSheet("font-size: 12px; color: #888;")
        layout.addWidget(status_label)
        
        # Button bar
        btn_layout = QHBoxLayout()
        cancel_btn = QPushButton("Cancel")
        cancel_btn.clicked.connect(dialog.reject)
        btn_layout.addWidget(cancel_btn)
        layout.addLayout(btn_layout)
        
        # Clear any previous received key
        midi_mgr._last_received_key = None
        midi_mgr.set_learn_mode(True)
        
        shortcut_midi_id = f"shortcut_{shortcut.id}"
        
        # Handle MIDI input
        def complete_learn(midi_key):
            midi_mgr.set_learn_mode(False)
            # Clear any existing mappings for this shortcut first
            midi_mgr.clear_mappings_for_preset(shortcut_midi_id)
            # Get shortcut color for LED feedback
            shortcut_color = shortcut.color if shortcut.color else "#c97a50"
            midi_mgr.add_mapping(midi_key, shortcut_midi_id, shortcut_color)
            # Record which device made this mapping
            device_name = midi_mgr.get_last_received_device()
            midi_mgr.set_mapping_device(midi_key, device_name)
            # Register callback for this shortcut
            midi_mgr.register_preset_callback(shortcut_midi_id, lambda s=shortcut: self._trigger_shortcut(s))
            # Save mappings
            self.app_settings['midi_mappings'] = midi_mgr.get_mappings_dict()
            self.app_settings['midi_mapping_devices'] = midi_mgr.get_mapping_devices_dict()
            self._save_app_settings()
            # Refresh shortcut buttons to show gray outline
            self._refresh_all_shortcut_tabs()
            
            display = MIDIManager.format_midi_key(midi_key)
            status_label.setText(f"✓ Learned: {display}")
            status_label.setStyleSheet("font-size: 12px; color: #27ae60;")
            QTimer.singleShot(800, dialog.accept)
        
        # Poll for received key
        poll_timer = QTimer()
        def check_for_midi():
            if midi_mgr._last_received_key:
                key = midi_mgr._last_received_key
                midi_mgr._last_received_key = None
                poll_timer.stop()
                complete_learn(key)
        poll_timer.timeout.connect(check_for_midi)
        poll_timer.start(50)  # Check every 50ms
        
        # Clean up on close
        def on_close():
            poll_timer.stop()
            midi_mgr.set_learn_mode(False)
            midi_mgr._last_received_key = None
        
        dialog.finished.connect(on_close)
        dialog.exec()
    
    def _clear_midi_mappings_shortcut(self, shortcut):
        """Clear all MIDI mappings for a shortcut."""
        midi_mgr = get_midi_manager()
        shortcut_midi_id = f"shortcut_{shortcut.id}"
        midi_mgr.clear_mappings_for_preset(shortcut_midi_id)
        midi_mgr.unregister_preset_callback(shortcut_midi_id)
        # Save mappings
        self.app_settings['midi_mappings'] = midi_mgr.get_mappings_dict()
        self._save_app_settings()
        # Refresh buttons to remove border
        self._refresh_all_shortcut_tabs()
        print(f"[MIDI] Cleared mappings for shortcut: {shortcut.name}")
    
    def _update_shortcut_button_selection(self, shortcut_id: str):
        """Update the visual selection state of shortcut buttons without recreating them."""
        self._active_shortcut_id = shortcut_id
        
        # Update button styles in-place
        accent_color = "#c97a50"
        
        def update_button_style(btn):
            """Update a single button's selection style."""
            if btn is None or not hasattr(btn, 'shortcut'):
                return
            try:
                if not btn.isVisible():
                    return
            except RuntimeError:
                return  # Button was deleted
            
            shortcut = btn.shortcut
            # Verify it's an actual shortcut object with an 'id' attribute, not a method
            if not hasattr(shortcut, 'id') or callable(shortcut):
                return
            
            is_selected = (shortcut.id == shortcut_id)
            
            # Check for MIDI mapping
            midi_mgr = get_midi_manager()
            shortcut_midi_id = f"shortcut_{shortcut.id}"
            has_midi = bool(midi_mgr.get_mappings_for_preset(shortcut_midi_id))
            
            # Border style - green for selected, gray for MIDI mapped, default otherwise
            if is_selected:
                border_style = "border: 3px solid #00ff00;"
                hover_border = "border: 3px solid #00ff00;"
            elif has_midi:
                border_style = "border: 2px solid #888888;"
                hover_border = "border: 2px solid #c97a50;"
            else:
                border_style = "border: 1px solid #4d4d4d;"
                hover_border = "border: 2px solid #c97a50;"
            
            bg_medium = "#3d3d3d"
            stripe_color = shortcut.color if shortcut.color else accent_color
            
            # Get font size based on text length
            text_len = len(btn.text())
            if text_len <= 6:
                font_size = 16
            elif text_len <= 10:
                font_size = 14
            elif text_len <= 14:
                font_size = 12
            elif text_len <= 18:
                font_size = 11
            elif text_len <= 22:
                font_size = 10
            else:
                font_size = 9
            
            btn.setStyleSheet(f"""
                QPushButton {{
                    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                        stop:0 {bg_medium},
                        stop:0.85 {bg_medium},
                        stop:0.86 {stripe_color},
                        stop:1 {stripe_color});
                    color: white;
                    font-size: {font_size}px;
                    font-weight: 600;
                    {border_style}
                    border-radius: 6px;
                    padding: 12px 8px 20px 8px;
                }}
                QPushButton:hover {{
                    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                        stop:0 #454545,
                        stop:0.85 #454545,
                        stop:0.86 #c97a50,
                        stop:1 #c97a50);
                    {hover_border}
                }}
                QPushButton:pressed {{
                    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                        stop:0 #555555,
                        stop:0.85 #555555,
                        stop:0.86 #ff8844,
                        stop:1 #ff8844);
                }}
            """)
        
        # Update buttons in main shortcuts tab
        if hasattr(self, 'shortcut_page_tabs'):
            for page_idx in range(self.shortcut_page_tabs.count()):
                page_widget = self.shortcut_page_tabs.widget(page_idx)
                if page_widget:
                    # Find the scroll area and container
                    for child in page_widget.findChildren(QPushButton):
                        if hasattr(child, 'shortcut'):
                            update_button_style(child)
        
        # Update buttons in detached window if any
        if hasattr(self, '_detached_windows') and 'MIDI AND\nOSC TRIGGERS' in self._detached_windows:
            win = self._detached_windows['MIDI AND\nOSC TRIGGERS']
            central = win.centralWidget()
            if central:
                for child in central.findChildren(QPushButton):
                    if hasattr(child, 'shortcut'):
                        update_button_style(child)

    def _add_shortcut_page(self):
        """Add a new shortcut page."""
        try:
            from .models import ShortcutPage
        except ImportError:
            from models import ShortcutPage
        import uuid
        
        # Get name from user
        name, ok = self._show_input_dialog(
            "Add Page",
            "Page name:",
            f"Page {len(self.project.shortcut_pages) + 1}"
        )
        
        if ok and name.strip():
            page = ShortcutPage(
                id=str(uuid.uuid4()),
                name=name.strip(),
                shortcuts=[]
            )
            self.project.shortcut_pages.append(page)
            self._mark_dirty()
            self._refresh_all_shortcut_tabs()
            # Switch to new page (main tab only)
            if hasattr(self, 'shortcut_page_tabs'):
                self.shortcut_page_tabs.setCurrentIndex(len(self.project.shortcut_pages) - 1)
    
    def _rename_shortcut_page(self, tab_idx: int):
        """Rename a shortcut page."""
        if tab_idx < 0 or tab_idx >= len(self.project.shortcut_pages):
            return
        
        page = self.project.shortcut_pages[tab_idx]
        name, ok = self._show_input_dialog(
            "Rename Page",
            "Page name:",
            page.name
        )
        
        if ok and name.strip():
            page.name = name.strip()
            self._mark_dirty()
            self._refresh_all_shortcut_tabs()
    
    def _delete_shortcut_page(self, tab_idx: int):
        """Delete a shortcut page."""
        if tab_idx < 0 or tab_idx >= len(self.project.shortcut_pages):
            return
        
        if len(self.project.shortcut_pages) <= 1:
            self._show_message_box("warning", "Cannot Delete", "You must have at least one page.")
            return
        
        page = self.project.shortcut_pages[tab_idx]
        reply = self._show_message_box(
            "question", "Delete Page",
            f"Delete page '{page.name}' and all its shortcuts?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
        )
        
        if reply == QMessageBox.StandardButton.Yes:
            self.project.shortcut_pages.pop(tab_idx)
            self._mark_dirty()
            self._refresh_all_shortcut_tabs()
    
    def _add_shortcut(self, page):
        """Add a new shortcut to a page."""
        self._show_shortcut_dialog(None, page)
    
    def _edit_shortcut(self, shortcut, page):
        """Edit an existing shortcut."""
        self._show_shortcut_dialog(shortcut, page)
    
    def _show_shortcut_dialog(self, shortcut, page):
        """Show dialog to create or edit a shortcut."""
        from models import Shortcut
        import uuid
        
        is_new = shortcut is None
        if is_new:
            # Use last entered OSC IP/port as defaults, or fall back to defaults
            last_osc_ip = self.app_settings.get('last_osc_ip', '127.0.0.1')
            last_osc_port = self.app_settings.get('last_osc_port', 8000)
            
            shortcut = Shortcut(
                id=str(uuid.uuid4()),
                name="New Shortcut",
                osc_ip=last_osc_ip,
                osc_port=last_osc_port
            )
        
        dialog = QDialog(self._get_active_window())
        dialog.setWindowTitle("Edit Shortcut" if not is_new else "New Shortcut")
        dialog.setMinimumWidth(560)
        dialog.setMinimumHeight(720)
        dialog.setStyleSheet(DARK_STYLESHEET + """
            QGroupBox { padding-top: 28px; margin-top: 18px; }
            QGroupBox::title { padding: 4px 10px; }
            QLabel { min-height: 26px; font-size: 14px; }
            QLineEdit, QSpinBox, QDoubleSpinBox, QComboBox {
                min-height: 34px; min-width: 200px; padding: 6px 12px; font-size: 14px;
            }
            QCheckBox { min-height: 30px; font-size: 14px; spacing: 10px; }
            QCheckBox::indicator { width: 22px; height: 22px; }
        """)
        
        # Use a scroll area so content never overlaps
        scroll = QScrollArea(dialog)
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QScrollArea.Shape.NoFrame)
        scroll_content = QWidget()
        layout = QVBoxLayout(scroll_content)
        layout.setSpacing(16)
        layout.setContentsMargins(16, 16, 16, 16)
        scroll.setWidget(scroll_content)
        
        outer_layout = QVBoxLayout(dialog)
        outer_layout.setContentsMargins(0, 0, 0, 0)
        outer_layout.addWidget(scroll, 1)
        
        # Name
        name_layout = QHBoxLayout()
        name_layout.addWidget(QLabel("Name:"))
        name_edit = QLineEdit(shortcut.name)
        name_edit.setPlaceholderText("Shortcut name")
        name_layout.addWidget(name_edit)
        layout.addLayout(name_layout)
        
        # Color button
        color_layout = QHBoxLayout()
        color_layout.addWidget(QLabel("Color:"))
        color_btn = QPushButton()
        color_btn.setFixedSize(50, 30)
        color_btn.setStyleSheet(f"background-color: {shortcut.color}; border: 1px solid #666;")
        current_color = [shortcut.color]  # Use list to allow modification in closure
        
        def pick_color():
            color = QColorDialog.getColor(QColor(current_color[0]), dialog)
            if color.isValid():
                current_color[0] = color.name()
                color_btn.setStyleSheet(f"background-color: {current_color[0]}; border: 1px solid #666;")
        
        color_btn.clicked.connect(pick_color)
        color_layout.addWidget(color_btn)
        color_layout.addStretch()
        layout.addLayout(color_layout)
        
        # OSC Section
        osc_group = QGroupBox("OSC Configuration")
        osc_layout = QFormLayout(osc_group)
        osc_layout.setVerticalSpacing(12)
        osc_layout.setHorizontalSpacing(16)
        osc_layout.setContentsMargins(14, 32, 14, 14)
        osc_layout.setFieldGrowthPolicy(QFormLayout.FieldGrowthPolicy.ExpandingFieldsGrow)
        
        osc_enabled = QCheckBox("Enable OSC")
        osc_enabled.setChecked(shortcut.osc_enabled)
        osc_layout.addRow(osc_enabled)
        
        osc_ip = QLineEdit(shortcut.osc_ip)
        osc_ip.setPlaceholderText("127.0.0.1")
        osc_layout.addRow("IP Address:", osc_ip)
        
        osc_port = QSpinBox()
        osc_port.setRange(1, 65535)
        osc_port.setValue(shortcut.osc_port)
        osc_layout.addRow("Port:", osc_port)
        
        osc_address = QLineEdit(shortcut.osc_address)
        osc_address.setPlaceholderText("/cue/1/go")
        osc_layout.addRow("Address:", osc_address)
        
        osc_args = QLineEdit(", ".join(str(a) for a in shortcut.osc_args))
        osc_args.setPlaceholderText("arg1, arg2, ... (optional)")
        osc_layout.addRow("Arguments:", osc_args)
        
        # "Change all OSC IPs" button
        change_all_ip_btn = QPushButton("🌐 Change All OSC Shortcut IPs")
        change_all_ip_btn.setToolTip("Update the IP address on every OSC shortcut across all pages to the IP entered above")
        change_all_ip_btn.clicked.connect(lambda: self._change_all_osc_shortcut_ips(osc_ip.text()))
        osc_layout.addRow(change_all_ip_btn)
        
        layout.addWidget(osc_group)
        
        # MIDI Section
        midi_group = QGroupBox("MIDI Configuration")
        midi_layout = QFormLayout(midi_group)
        midi_layout.setVerticalSpacing(12)
        midi_layout.setHorizontalSpacing(16)
        midi_layout.setContentsMargins(14, 32, 14, 14)
        midi_layout.setFieldGrowthPolicy(QFormLayout.FieldGrowthPolicy.ExpandingFieldsGrow)
        
        midi_enabled = QCheckBox("Enable MIDI")
        midi_enabled.setChecked(shortcut.midi_enabled)
        midi_layout.addRow(midi_enabled)
        
        midi_type = QComboBox()
        midi_type.addItems(["note_on", "note_off", "cc", "program_change"])
        midi_type.setCurrentText(shortcut.midi_type)
        midi_layout.addRow("Message Type:", midi_type)
        
        midi_channel = QSpinBox()
        midi_channel.setRange(1, 16)
        midi_channel.setValue(shortcut.midi_channel)
        midi_layout.addRow("Channel:", midi_channel)
        
        midi_note = QSpinBox()
        midi_note.setRange(0, 127)
        midi_note.setValue(shortcut.midi_note)
        midi_layout.addRow("Note/CC Number:", midi_note)
        
        midi_velocity = QSpinBox()
        midi_velocity.setRange(0, 127)
        midi_velocity.setValue(shortcut.midi_velocity)
        midi_layout.addRow("Velocity/Value:", midi_velocity)
        
        midi_duration = QDoubleSpinBox()
        midi_duration.setRange(0.01, 10.0)
        midi_duration.setSingleStep(0.1)
        midi_duration.setValue(shortcut.midi_duration)
        midi_duration.setSuffix(" sec")
        midi_layout.addRow("Duration:", midi_duration)
        
        layout.addWidget(midi_group)
        
        # Test button
        test_btn = QPushButton("🔊 Test Shortcut")
        test_btn.clicked.connect(lambda: self._test_shortcut_from_dialog(
            osc_enabled.isChecked(), osc_ip.text(), osc_port.value(), osc_address.text(), osc_args.text(),
            midi_enabled.isChecked(), midi_type.currentText(), midi_channel.value(), 
            midi_note.value(), midi_velocity.value(), midi_duration.value()
        ))
        layout.addWidget(test_btn)
        
        # Buttons outside scroll area so they're always visible
        buttons = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel
        )
        buttons.accepted.connect(dialog.accept)
        buttons.rejected.connect(dialog.reject)
        outer_layout.addWidget(buttons)
        
        if dialog.exec() == QDialog.DialogCode.Accepted:
            # Update shortcut
            shortcut.name = name_edit.text().strip() or "Shortcut"
            shortcut.color = current_color[0]
            shortcut.osc_enabled = osc_enabled.isChecked()
            shortcut.osc_ip = osc_ip.text().strip() or "127.0.0.1"
            shortcut.osc_port = osc_port.value()
            shortcut.osc_address = osc_address.text().strip() or "/"
            
            # Save OSC defaults for next shortcut
            self.app_settings['last_osc_ip'] = shortcut.osc_ip
            self.app_settings['last_osc_port'] = shortcut.osc_port
            
            # Parse args
            args_text = osc_args.text().strip()
            if args_text:
                parsed_args = []
                for arg in args_text.split(","):
                    arg = arg.strip()
                    if not arg:
                        continue
                    # Try to parse as number
                    try:
                        if "." in arg:
                            parsed_args.append(float(arg))
                        else:
                            parsed_args.append(int(arg))
                    except ValueError:
                        parsed_args.append(arg)
                shortcut.osc_args = parsed_args
            else:
                shortcut.osc_args = []
            
            shortcut.midi_enabled = midi_enabled.isChecked()
            shortcut.midi_type = midi_type.currentText()
            shortcut.midi_channel = midi_channel.value()
            shortcut.midi_note = midi_note.value()
            shortcut.midi_velocity = midi_velocity.value()
            shortcut.midi_duration = midi_duration.value()
            
            if is_new:
                page.shortcuts.append(shortcut)
            self._mark_dirty()
            self._refresh_all_shortcut_tabs()
    
    def _change_all_osc_shortcut_ips(self, new_ip: str):
        """Update the OSC IP address on every shortcut across all pages."""
        new_ip = new_ip.strip() or "127.0.0.1"
        count = 0
        for page in self.project.shortcut_pages:
            for sc in page.shortcuts:
                if sc.osc_ip != new_ip:
                    sc.osc_ip = new_ip
                    count += 1
        self.app_settings['last_osc_ip'] = new_ip
        self._save_settings()
        if count:
            self._mark_dirty()
        QMessageBox.information(
            None, "OSC IP Updated",
            f"Updated {count} shortcut(s) to IP address {new_ip}."
        )
    
    def _test_shortcut_from_dialog(self, osc_enabled, osc_ip, osc_port, osc_address, osc_args_text,
                                    midi_enabled, midi_type, midi_channel, midi_note, midi_velocity, midi_duration):
        """Test a shortcut configuration from the dialog."""
        # Parse OSC args
        osc_args = []
        if osc_args_text:
            for arg in osc_args_text.split(","):
                arg = arg.strip()
                if not arg:
                    continue
                try:
                    if "." in arg:
                        osc_args.append(float(arg))
                    else:
                        osc_args.append(int(arg))
                except ValueError:
                    osc_args.append(arg)
        
        # Send OSC if enabled
        if osc_enabled:
            self._send_osc_message(osc_ip, osc_port, osc_address, osc_args)
        
        # Send MIDI if enabled
        if midi_enabled:
            self._send_midi_message(midi_type, midi_channel, midi_note, midi_velocity, midi_duration)
    
    def _change_shortcut_color(self, shortcut, page):
        """Change the color of a shortcut."""
        color = QColorDialog.getColor(QColor(shortcut.color), self.window())
        if color.isValid():
            shortcut.color = color.name()
            self._mark_dirty()
            self._refresh_all_shortcut_tabs()
    
    def _delete_shortcut(self, shortcut, page):
        """Delete a shortcut from a page."""
        reply = QMessageBox.question(
            self._get_active_window(), "Delete Shortcut",
            f"Delete shortcut '{shortcut.name}'?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
        )
        
        if reply == QMessageBox.StandardButton.Yes:
            page.shortcuts.remove(shortcut)
            self._mark_dirty()
            self._refresh_all_shortcut_tabs()
    
    def _duplicate_shortcut(self, shortcut, page):
        """Duplicate a shortcut in the same page."""
        from models import Shortcut
        import uuid
        
        # Create a new shortcut with the same properties
        new_shortcut = Shortcut(
            id=str(uuid.uuid4()),
            name=f"{shortcut.name} (copy)",
            color=shortcut.color,
            osc_enabled=shortcut.osc_enabled,
            osc_ip=shortcut.osc_ip,
            osc_port=shortcut.osc_port,
            osc_address=shortcut.osc_address,
            osc_args=shortcut.osc_args.copy(),  # Copy the list
            midi_enabled=shortcut.midi_enabled,
            midi_type=shortcut.midi_type,
            midi_channel=shortcut.midi_channel,
            midi_note=shortcut.midi_note,
            midi_velocity=shortcut.midi_velocity,
            midi_duration=shortcut.midi_duration
        )
        
        # Add to the same page
        page.shortcuts.append(new_shortcut)
        self._mark_dirty()
        self._refresh_all_shortcut_tabs()
    
    def _move_shortcut_to_page(self, shortcut, from_page, to_page):
        """Move a shortcut from one page to another."""
        if shortcut in from_page.shortcuts:
            from_page.shortcuts.remove(shortcut)
        if shortcut not in to_page.shortcuts:
            to_page.shortcuts.append(shortcut)
        self._mark_dirty()
        self._refresh_all_shortcut_tabs()
    
    def _copy_shortcut_to_page(self, shortcut, to_page):
        """Copy a shortcut to another page."""
        from models import Shortcut
        import uuid
        
        new_shortcut = Shortcut(
            id=str(uuid.uuid4()),
            name=shortcut.name,
            color=shortcut.color,
            osc_enabled=shortcut.osc_enabled,
            osc_ip=shortcut.osc_ip,
            osc_port=shortcut.osc_port,
            osc_address=shortcut.osc_address,
            osc_args=shortcut.osc_args.copy(),
            midi_enabled=shortcut.midi_enabled,
            midi_type=shortcut.midi_type,
            midi_channel=shortcut.midi_channel,
            midi_note=shortcut.midi_note,
            midi_velocity=shortcut.midi_velocity,
            midi_duration=shortcut.midi_duration
        )
        to_page.shortcuts.append(new_shortcut)
        self._mark_dirty()
        self._refresh_all_shortcut_tabs()
    
    def _move_shortcut(self, shortcut, page, direction):
        """Move a shortcut up or down in the page. direction: -1 for up, 1 for down."""
        try:
            idx = page.shortcuts.index(shortcut)
            new_idx = idx + direction
            
            # Validate new index
            if 0 <= new_idx < len(page.shortcuts):
                # Swap positions
                page.shortcuts[idx], page.shortcuts[new_idx] = page.shortcuts[new_idx], page.shortcuts[idx]
                self._mark_dirty()
                self._refresh_all_shortcut_tabs()
        except ValueError:
            pass
    
    def _trigger_shortcut(self, shortcut):
        """Trigger a shortcut - send its OSC and/or MIDI messages."""
        print(f"\n[Shortcut] ===== TRIGGERED: {shortcut.name} =====")
        print(f"[Shortcut] OSC enabled: {shortcut.osc_enabled}")
        print(f"[Shortcut] MIDI enabled: {shortcut.midi_enabled}")
        
        # Update the active shortcut and refresh button styling
        self._active_shortcut_id = shortcut.id
        self._update_shortcut_button_selection(shortcut.id)
        
        if shortcut.osc_enabled:
            print(f"[Shortcut] Sending OSC to {shortcut.osc_ip}:{shortcut.osc_port} {shortcut.osc_address} args={shortcut.osc_args}")
            self._send_osc_message(shortcut.osc_ip, shortcut.osc_port, 
                                   shortcut.osc_address, shortcut.osc_args)
        else:
            print(f"[Shortcut] OSC is DISABLED")
        
        if shortcut.midi_enabled:
            print(f"[Shortcut] Sending MIDI: {shortcut.midi_type} ch={shortcut.midi_channel} note={shortcut.midi_note} vel={shortcut.midi_velocity}")
            self._send_midi_message(shortcut.midi_type, shortcut.midi_channel,
                                    shortcut.midi_note, shortcut.midi_velocity, 
                                    shortcut.midi_duration)
        else:
            print(f"[Shortcut] MIDI is DISABLED")
        
        print(f"[Shortcut] ===== TRIGGER COMPLETE =====\n")

    def _trigger_viz_item(self, viz_item):
        """Trigger a visualizer item from MIDI — play the video or effect."""
        try:
            try:
                from .visualizer_tab import _play_item
            except ImportError:
                from visualizer_tab import _play_item
            _play_item(self, viz_item)
            print(f"[Visualizer MIDI] Triggered: {viz_item.name} ({viz_item.source_type})")
        except Exception as e:
            print(f"[Visualizer MIDI] Error triggering {viz_item.name}: {e}")
    
    # ── Fader → Shortcut assignment helpers ──────────────────────────
    
    def _get_fader_shortcut_entry(self, fader_id: str) -> dict:
        """Return the {rise: id, off: id} dict for a fader, migrating legacy format."""
        assignments = self.app_settings.get('fader_shortcut_assignments', {})
        entry = assignments.get(fader_id)
        if entry is None:
            return {}
        if isinstance(entry, str):
            # Migrate old single-string format → rise
            entry = {'rise': entry}
            assignments[fader_id] = entry
        return entry
    
    def _build_fader_shortcut_submenu(self, parent_menu, fader_id: str):
        """Add an 'Assign OSC/MIDI Shortcut' submenu to a fader context menu."""
        from PyQt6.QtWidgets import QMenu
        
        shortcut_menu = QMenu("📡 OSC/MIDI Shortcut Output", parent_menu)
        
        entry = self._get_fader_shortcut_entry(fader_id)
        rise_id = entry.get('rise')
        off_id = entry.get('off')
        
        # Show current assignments as headers
        if rise_id:
            sc = self._find_shortcut_by_id(rise_id)
            label = sc.name if sc else "(deleted)"
            h = shortcut_menu.addAction(f"⬆️ Rise: {label}")
            h.setEnabled(False)
        if off_id:
            sc = self._find_shortcut_by_id(off_id)
            label = sc.name if sc else "(deleted)"
            h = shortcut_menu.addAction(f"⬇️ Off: {label}")
            h.setEnabled(False)
        if rise_id or off_id:
            shortcut_menu.addSeparator()
        
        # Build the two sub-submenus: On Rise / On Off
        for trigger_type, emoji, current_id in [('rise', '⬆️', rise_id), ('off', '⬇️', off_id)]:
            trigger_menu = QMenu(f"{emoji} On Fader {'Rise' if trigger_type == 'rise' else 'Off'}", shortcut_menu)
            
            # Clear option if assigned
            if current_id:
                clear_action = trigger_menu.addAction("❌ Clear")
                clear_action.triggered.connect(
                    lambda checked, tt=trigger_type: self._clear_fader_shortcut(fader_id, tt))
                trigger_menu.addSeparator()
            
            any_shortcuts = False
            for page in getattr(self.project, 'shortcut_pages', []):
                if not page.shortcuts:
                    continue
                page_menu = QMenu(page.name, trigger_menu)
                for sc in page.shortcuts:
                    has_output = sc.osc_enabled or sc.midi_enabled
                    if not has_output:
                        continue
                    any_shortcuts = True
                    parts = []
                    if sc.osc_enabled:
                        parts.append(f"OSC {sc.osc_address}")
                    if sc.midi_enabled:
                        parts.append(f"MIDI ch{sc.midi_channel}")
                    suffix = f"  ({', '.join(parts)})" if parts else ""
                    is_current = (sc.id == current_id)
                    action = page_menu.addAction(f"{'✓ ' if is_current else ''}{sc.name}{suffix}")
                    if is_current:
                        action.setEnabled(False)
                    else:
                        action.triggered.connect(
                            lambda checked, sid=sc.id, tt=trigger_type: self._assign_fader_shortcut(fader_id, sid, tt))
                if page_menu.actions():
                    trigger_menu.addMenu(page_menu)
            
            if not any_shortcuts:
                empty = trigger_menu.addAction("(no shortcuts with outputs)")
                empty.setEnabled(False)
            
            shortcut_menu.addMenu(trigger_menu)
        
        # Clear all option
        if rise_id or off_id:
            shortcut_menu.addSeparator()
            clear_all = shortcut_menu.addAction("❌ Clear All Shortcuts")
            clear_all.triggered.connect(lambda: self._clear_fader_shortcut(fader_id, None))
        
        parent_menu.addMenu(shortcut_menu)
    
    def _find_shortcut_by_id(self, shortcut_id: str):
        """Find a Shortcut object by its id across all pages."""
        for page in getattr(self.project, 'shortcut_pages', []):
            for sc in page.shortcuts:
                if sc.id == shortcut_id:
                    return sc
        return None
    
    def _assign_fader_shortcut(self, fader_id: str, shortcut_id: str, trigger_type: str = 'rise'):
        """Assign a shortcut to fire on fader rise or off."""
        assignments = self.app_settings.setdefault('fader_shortcut_assignments', {})
        entry = self._get_fader_shortcut_entry(fader_id)
        entry[trigger_type] = shortcut_id
        assignments[fader_id] = entry
        self._save_app_settings()
        sc = self._find_shortcut_by_id(shortcut_id)
        name = sc.name if sc else shortcut_id
        print(f"[FaderShortcut] Assigned shortcut '{name}' to fader '{fader_id}' on {trigger_type}")
        self._refresh_fader_output_visuals(fader_id)
    
    def _clear_fader_shortcut(self, fader_id: str, trigger_type: str | None = None):
        """Remove shortcut assignment(s) from a fader. None = clear both."""
        assignments = self.app_settings.get('fader_shortcut_assignments', {})
        if fader_id not in assignments:
            return
        if trigger_type is None:
            del assignments[fader_id]
            print(f"[FaderShortcut] Cleared all shortcuts from fader '{fader_id}'")
        else:
            entry = self._get_fader_shortcut_entry(fader_id)
            entry.pop(trigger_type, None)
            if not entry:
                assignments.pop(fader_id, None)
            else:
                assignments[fader_id] = entry
            print(f"[FaderShortcut] Cleared {trigger_type} shortcut from fader '{fader_id}'")
        self._save_app_settings()
        self._refresh_fader_output_visuals(fader_id)
    
    def _fire_fader_shortcut_if_assigned(self, fader_id: str, trigger_type: str = 'rise'):
        """If a shortcut is assigned to this fader for the given trigger, fire it."""
        entry = self._get_fader_shortcut_entry(fader_id)
        shortcut_id = entry.get(trigger_type)
        if not shortcut_id:
            return
        sc = self._find_shortcut_by_id(shortcut_id)
        if sc:
            print(f"[FaderShortcut] Fader '{fader_id}' {trigger_type} -> firing shortcut '{sc.name}'")
            self._trigger_shortcut(sc)
        else:
            print(f"[FaderShortcut] Shortcut '{shortcut_id}' no longer exists, skipping")
    
    def _send_osc_message(self, ip: str, port: int, address: str, args: list):
        """Send an OSC message from the selected network interface."""
        try:
            from pythonosc.osc_message_builder import OscMessageBuilder
            import socket
            
            # Validate inputs
            if not ip or not port or not address:
                print(f"[OSC] ERROR - Invalid OSC config: ip={ip}, port={port}, address={address}")
                return
            
            if args is None:
                args = []
            
            # Get selected network interface
            network_interface = self.app_settings.get('osc_network_interface', 'auto')
            
            # Build the OSC message
            print(f"[OSC] Building message at address: {address}")
            builder = OscMessageBuilder(address=address)
            for arg in args:
                builder.add_arg(arg)
                print(f"[OSC]   Added arg: {arg}")
            msg = builder.build()
            
            # Create socket with proper interface binding
            try:
                sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
                
                if network_interface != 'auto' and network_interface != '127.0.0.1':
                    try:
                        # Bind to specific interface
                        sock.bind((network_interface, 0))
                        print(f"[OSC] Bound to interface: {network_interface}")
                    except OSError as e:
                        print(f"[OSC] Warning: Could not bind to interface {network_interface}: {e}")
                        print(f"[OSC] Falling back to default interface")
                        sock.bind(('', 0))
                else:
                    sock.bind(('', 0))
                    if network_interface == 'auto':
                        print(f"[OSC] Using default network interface (auto)")
                    else:
                        print(f"[OSC] Using localhost interface")
                
                # Send the message
                print(f"[OSC] Sending OSC message to {ip}:{port}")
                sock.sendto(msg.dgram, (ip, port))
                sock.close()
                
                print(f"[OSC] OK - Successfully sent to {ip}:{port} {address} with args={args}")
                
            except socket.error as e:
                print(f"[OSC] FAIL - Socket error: {e}")
                # Fallback: try with SimpleUDPClient
                print(f"[OSC] Attempting fallback with SimpleUDPClient...")
                from pythonosc import udp_client
                client = udp_client.SimpleUDPClient(ip, port)
                client.send(msg)
                print(f"[OSC] OK - Sent via fallback method")
            
        except ImportError as e:
            print(f"[OSC] FAIL - Import error: {e}")
            print(f"[OSC] Make sure 'python-osc' is installed: pip install python-osc")
        except Exception as e:
            print(f"[OSC] FAIL - Error sending OSC message: {e}")
            import traceback
            traceback.print_exc()
    
    def _send_midi_message(self, msg_type: str, channel: int, note: int, velocity: int, duration: float):
        """Send a MIDI message."""
        try:
            import ctypes
            
            # Get configured MIDI output device
            midi_device = self.app_settings.get('midi_output_device', '')
            
            # Use Windows MIDI API (midiOutShortMsg)
            winmm = ctypes.windll.winmm
            
            # Find device by name or use default
            device_id = 0  # Default to first device
            if midi_device:
                # Try to find matching device
                num_devs = winmm.midiOutGetNumDevs()
                class MIDIOUTCAPS(ctypes.Structure):
                    _fields_ = [
                        ("wMid", ctypes.wintypes.WORD),
                        ("wPid", ctypes.wintypes.WORD),
                        ("vDriverVersion", ctypes.wintypes.DWORD),
                        ("szPname", ctypes.c_wchar * 32),
                        ("wTechnology", ctypes.wintypes.WORD),
                        ("wVoices", ctypes.wintypes.WORD),
                        ("wNotes", ctypes.wintypes.WORD),
                        ("wChannelMask", ctypes.wintypes.WORD),
                        ("dwSupport", ctypes.wintypes.DWORD),
                    ]
                for i in range(num_devs):
                    caps = MIDIOUTCAPS()
                    if winmm.midiOutGetDevCapsW(i, ctypes.byref(caps), ctypes.sizeof(caps)) == 0:
                        if midi_device in caps.szPname:
                            device_id = i
                            break
            
            # Open MIDI device
            midi_handle = ctypes.wintypes.HANDLE()
            result = winmm.midiOutOpen(ctypes.byref(midi_handle), device_id, 0, 0, 0)
            if result != 0:
                raise Exception(f"Failed to open MIDI device (error {result})")
            
            try:
                # Construct MIDI message
                ch = (channel - 1) & 0x0F  # 0-15
                
                if msg_type == "note_on":
                    status = 0x90 | ch
                    msg = status | (note << 8) | (velocity << 16)
                    winmm.midiOutShortMsg(midi_handle, msg)
                    print(f"[MIDI] Note On: Ch{channel} Note{note} Vel{velocity}")
                    
                    # Schedule note off
                    if duration > 0:
                        from PyQt6.QtCore import QTimer
                        def send_note_off():
                            try:
                                status_off = 0x80 | ch
                                msg_off = status_off | (note << 8) | (0 << 16)
                                winmm.midiOutShortMsg(midi_handle, msg_off)
                                winmm.midiOutClose(midi_handle)
                            except:
                                pass
                        QTimer.singleShot(int(duration * 1000), send_note_off)
                        return  # Don't close handle yet
                    
                elif msg_type == "note_off":
                    status = 0x80 | ch
                    msg = status | (note << 8) | (velocity << 16)
                    winmm.midiOutShortMsg(midi_handle, msg)
                    print(f"[MIDI] Note Off: Ch{channel} Note{note}")
                    
                elif msg_type == "cc":
                    status = 0xB0 | ch
                    msg = status | (note << 8) | (velocity << 16)
                    winmm.midiOutShortMsg(midi_handle, msg)
                    print(f"[MIDI] CC: Ch{channel} CC{note} Val{velocity}")
                    
                elif msg_type == "program_change":
                    status = 0xC0 | ch
                    msg = status | (note << 8)
                    winmm.midiOutShortMsg(midi_handle, msg)
                    print(f"[MIDI] Program Change: Ch{channel} Prog{note}")
                
                # Close handle
                winmm.midiOutClose(midi_handle)
                
            except Exception as e:
                winmm.midiOutClose(midi_handle)
                raise e
                
        except Exception as e:
            print(f"[MIDI] Error sending: {e}")
            QMessageBox.warning(self._get_active_window(), "MIDI Error", f"Failed to send MIDI message:\n{e}")
    
