    def _refresh_palette_display(self):
        """Refresh the visual display of palette colors."""
        # Clear existing swatches
        while self.palette_preview_layout.count():
            item = self.palette_preview_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
        
        if not self.palette_colors:
            # Show placeholder
            placeholder = QLabel("No colors - click Add Color to build palette")
            placeholder.setStyleSheet("color: #808080; font-style: italic; font-size: 11px;")
            self.palette_preview_layout.addWidget(placeholder)
            self._selected_palette_index = -1
        else:
            # Add color swatches
            for i, color in enumerate(self.palette_colors):
                swatch = QPushButton()
                swatch.setFixedSize(40, 40)
                # Check if this swatch is selected
                is_selected = (i == self._selected_palette_index)
                border_color = "#00aaff" if is_selected else "#3d3d3d"
                border_width = "3px" if is_selected else "2px"
                swatch.setStyleSheet(f"""
                    QPushButton {{
                        background-color: {color};
                        border-radius: 4px;
                        border: {border_width} solid {border_color};
                    }}
                    QPushButton:hover {{
                        border: 3px solid #ffaa00;
                    }}
                """)
                swatch.setToolTip(f"{color}\nClick to select • Double-click to edit")
                swatch.clicked.connect(lambda checked, idx=i: self._select_palette_color(idx))
                swatch.installEventFilter(self)  # For double-click handling
                swatch.setProperty("palette_index", i)
                self.palette_preview_layout.addWidget(swatch)
        
        self.palette_preview_layout.addStretch()
        
        # Update remove button state
        if hasattr(self, 'palette_remove_btn'):
            self.palette_remove_btn.setEnabled(self._selected_palette_index >= 0)
    
    def _select_palette_color(self, index: int):
        """Select a palette color swatch."""
        if self._selected_palette_index == index:
            # Deselect if clicking same one
            self._selected_palette_index = -1
        else:
            self._selected_palette_index = index
        self._refresh_palette_display()
    
    def _remove_selected_palette_color(self):
        """Remove the currently selected palette color."""
        if 0 <= self._selected_palette_index < len(self.palette_colors):
            del self.palette_colors[self._selected_palette_index]
            self._selected_palette_index = -1
            self._refresh_palette_display()
            self._on_refine_param_changed()
    
    def _load_quick_palette(self, colors: list):
        """Load a quick preset palette."""
        self.palette_colors = colors.copy()
        self._selected_palette_index = -1
        self._refresh_palette_display()
        self._on_refine_param_changed()
    
    def eventFilter(self, obj, event):
        """Handle events for palette swatches (double-click to edit)."""
        from PyQt6.QtCore import QEvent
        if event.type() == QEvent.Type.MouseButtonDblClick:
            idx = obj.property("palette_index")
            if idx is not None and 0 <= idx < len(self.palette_colors):
                self._edit_palette_color(idx)
                return True
        return super().eventFilter(obj, event)
    
    def _edit_palette_color(self, index: int):
        """Edit a palette color at the given index."""
        from PyQt6.QtWidgets import QColorDialog
        current_color = QColor(self.palette_colors[index])
        color = QColorDialog.getColor(current_color, self.window(), "Edit Palette Color")
        if color.isValid():
            self.palette_colors[index] = color.name()
            self._refresh_palette_display()
            self._on_refine_param_changed()

    def _refresh_saved_palettes(self):
        """Refresh the saved palettes as buttons."""
        if not hasattr(self, 'saved_palettes_btn_layout'):
            return
        
        # Clear existing buttons
        while self.saved_palettes_btn_layout.count():
            item = self.saved_palettes_btn_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
        
        # Create buttons for each saved palette
        for palette in self.project.color_palettes:
            btn = QPushButton(palette.name)
            btn.setToolTip(f"Load '{palette.name}' ({len(palette.colors)} colors)\nRight-click to delete")
            btn.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
            btn.customContextMenuRequested.connect(lambda pos, p=palette: self._show_palette_context_menu(p, pos))
            btn.clicked.connect(lambda checked, p=palette: self._load_saved_palette(p))
            self.saved_palettes_btn_layout.addWidget(btn)
        
        self.saved_palettes_btn_layout.addStretch()
        
        # Update label visibility
        if hasattr(self, 'saved_palettes_label'):
            self.saved_palettes_label.setVisible(len(self.project.color_palettes) > 0)
            self.saved_palettes_btn_container.setVisible(len(self.project.color_palettes) > 0)
    
    def _load_saved_palette(self, palette):
        """Load a saved palette."""
        self.palette_colors = palette.colors.copy()
        self.palette_name_edit.setText(palette.name)
        self._refresh_palette_display()
        self._on_refine_param_changed()
        self.statusBar().showMessage(f"Loaded palette '{palette.name}'", 2000)
    
    def _show_palette_context_menu(self, palette, pos):
        """Show context menu for palette button."""
        from PyQt6.QtWidgets import QMenu
        menu = QMenu(self)
        menu.setStyleSheet(self._get_touch_menu_stylesheet())
        delete_action = menu.addAction("🗑️ Delete")
        action = menu.exec(self.sender().mapToGlobal(pos))
        if action == delete_action:
            self._delete_palette_by_id(palette.id, palette.name)
    
    def _delete_palette_by_id(self, palette_id: str, palette_name: str):
        """Delete a palette by its ID."""
        reply = QMessageBox.question(
            self._get_active_window(), "Delete Palette?",
            f"Are you sure you want to delete the palette '{palette_name}'?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
        )
        if reply == QMessageBox.StandardButton.Yes:
            self.project.color_palettes = [p for p in self.project.color_palettes if p.id != palette_id]
            self._mark_dirty()
            self._refresh_saved_palettes()
            self.statusBar().showMessage(f"Deleted palette '{palette_name}'", 2000)
    
    def _on_saved_palette_selected(self, index: int):
        """Legacy - kept for compatibility but no longer used."""
        pass
    
    def _refresh_position_cycle_checkboxes(self):
        """Refresh the position preset checkboxes for position cycle effect."""
        if not hasattr(self, 'position_cycle_checkboxes_layout'):
            return
        
        # Clear existing checkboxes
        while self.position_cycle_checkboxes_layout.count():
            item = self.position_cycle_checkboxes_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
        
        self.position_cycle_preset_checkboxes.clear()
        
        if not self.project.position_presets:
            # Show placeholder
            placeholder = QLabel("No position presets defined.\nCreate some in the POSITION tab first.")
            placeholder.setStyleSheet("color: #888; font-style: italic; padding: 10px;")
            self.position_cycle_checkboxes_layout.addWidget(placeholder)
            return
        
        # Add toggle button for each position preset - TOUCH FRIENDLY
        for preset in self.project.position_presets:
            btn = QPushButton(f"📍 {preset.name}")
            btn.setCheckable(True)
            btn.setChecked(False)  # Default to unselected
            btn.setMinimumHeight(50)
            btn.setToolTip(f"Include '{preset.name}' in the position cycle\n{len(preset.fixture_positions)} fixtures defined")
            btn.setStyleSheet("""
                QPushButton {
                    font-size: 15px;
                    font-weight: bold;
                    text-align: left;
                    padding: 10px 15px;
                    border: 2px solid #444;
                    border-radius: 8px;
                    background-color: #2d2d2d;
                }
                QPushButton:hover {
                    background-color: #3d3d3d;
                    border-color: #666;
                }
                QPushButton:checked {
                    background-color: #2d5a3d;
                    border-color: #4a9;
                }
                QPushButton:checked:hover {
                    background-color: #3d6a4d;
                }
            """)
            btn.toggled.connect(self._on_position_preset_checkbox_changed)
            self.position_cycle_checkboxes_layout.addWidget(btn)
            self.position_cycle_preset_checkboxes[preset.id] = btn
        
        self.position_cycle_checkboxes_layout.addStretch()
    
    def _on_position_preset_checkbox_changed(self, state):
        """Called when a position preset checkbox is toggled."""
        # If any position preset is checked, auto-enable position cycling
        any_checked = any(cb.isChecked() for cb in self.position_cycle_preset_checkboxes.values())
        
        if any_checked and not self.position_cycle_box.isChecked():
            # Auto-enable position cycling when user checks a position preset
            self.position_cycle_box.blockSignals(True)
            self.position_cycle_box.setChecked(True)
            self.position_cycle_box.blockSignals(False)
            print(f"[GUI] Auto-enabled position cycling (preset checked)")
        
        # Trigger the normal param changed handler
        self._on_refine_param_changed()
    
    def _on_position_cycle_speed_changed(self, value: int):
        """Called when position cycle speed slider changes."""
        self.position_cycle_speed_label.setText(str(value))
        self._on_refine_param_changed()
    
    def _on_mover_offset_changed(self, value: int):
        """Called when the mover offset slider changes."""
        self.mover_offset_label.setText(f"{value}%")
        # If a movement is active, update the offset without restarting
        if self._active_mover_movement:
            if self._current_effect and self.effect_engine._running:
                self._current_effect.fixture_offset = value / 100.0
                self.effect_engine.update_effect(self._current_effect)
            else:
                # Fallback: restart the movement
                self._start_mover_movement(self._active_mover_movement)
    
    def _on_patterns_bounds_changed(self, _value=None):
        """Called when the patterns-tab pan/tilt bounds spinboxes change."""
        if not self._active_mover_movement:
            return
        if self._current_effect and self.effect_engine._running:
            self._current_effect.pan_min = self.patterns_pan_min_spin.value()
            self._current_effect.pan_max = self.patterns_pan_max_spin.value()
            self._current_effect.tilt_min = self.patterns_tilt_min_spin.value()
            self._current_effect.tilt_max = self.patterns_tilt_max_spin.value()
            self.effect_engine.update_effect(self._current_effect)

    def _on_mover_speed_changed(self, value: int):
        """Called when the mover speed slider changes."""
        self.mover_speed_label.setText(f"{value} BPM")
        # If a movement is active, update the speed without restarting
        if self._active_mover_movement:
            if self._current_effect and self.effect_engine._running:
                self._current_effect.speed_bpm = value
                self.effect_engine.update_effect(self._current_effect)
            else:
                # Fallback: restart the movement
                self._start_mover_movement(self._active_mover_movement)
    
    def _get_active_movement_pattern(self) -> str:
        """Get the movement pattern from the active movement button."""
        if self._active_mover_movement:
            # Map button key to pattern name
            key_to_pattern = {
                'circle_sync': 'circle',
                'figure8_sync': 'figure8',
                'sweep_sync': 'sweep',
                'nod_sync': 'nod',
                'ballyhoo_sync': 'ballyhoo',
                'drift_sync': 'drift',
                # Use canonical names that the engine understands (and that we display in UI)
                # Keep backward-compat mapping in _set_movement_pattern_from_preset.
                'wave_sweep': 'wave_sweep',
                'tilt_wave': 'tilt_wave',
                'spiral': 'spiral',
                'waterfall': 'waterfall',
                'converge': 'converge',
                'diverge': 'diverge',
                'mirror': 'mirror',
                'fan_out': 'fan_out',
                'fan_in': 'fan_in',
                'chase_pan': 'chase_pan',
                'random_wave': 'random_wave',
                'bounce_wave': 'bounce_wave',
                'cross_sync': 'cross',
                'pendulum_sync': 'pendulum',
                'zigzag_sync': 'zigzag',
                'stagger': 'stagger',
                'crossover': 'crossover',
                'figure8_wide': 'figure8_wide',
            }
            return key_to_pattern.get(self._active_mover_movement, 'none')
        return 'none'
    
    def _set_movement_pattern_from_preset(self, pattern: str):
        """Set the appropriate movement button based on a preset's pattern."""
        # Don't stop movement - just update the button state to match
        if not pattern or pattern.lower() == 'none':
            # Clear all movement buttons without triggering stop
            for btn in self.mover_sync_buttons.values():
                btn.blockSignals(True)
                btn.setChecked(False)
                btn.blockSignals(False)
            for btn in self.mover_wave_buttons.values():
                btn.blockSignals(True)
                btn.setChecked(False)
                btn.blockSignals(False)
            self._active_mover_movement = None
            return
        
        # Map pattern name to button key
        pattern_to_key = {
            'circle': 'circle_sync',
            'figure8': 'figure8_sync',
            'sweep': 'sweep_sync',
            'nod': 'nod_sync',
            'ballyhoo': 'ballyhoo_sync',
            'drift': 'drift_sync',
            # Backward compat (older projects saved 'wave'/'chase'/'random'/'bounce')
            'wave': 'wave_sweep',
            'wave_sweep': 'wave_sweep',
            'tilt_wave': 'tilt_wave',
            'spiral': 'spiral',
            'waterfall': 'waterfall',
            'converge': 'converge',
            'diverge': 'diverge',
            'mirror': 'mirror',
            'fan_out': 'fan_out',
            'fan_in': 'fan_in',
            'chase': 'chase_pan',
            'chase_pan': 'chase_pan',
            'random': 'random_wave',
            'random_wave': 'random_wave',
            'bounce': 'bounce_wave',
            'bounce_wave': 'bounce_wave',
            'cross': 'cross_sync',
            'pendulum': 'pendulum_sync',
            'zigzag': 'zigzag_sync',
            'stagger': 'stagger',
            'crossover': 'crossover',
            'figure8_wide': 'figure8_wide',
        }
        
        key = pattern_to_key.get(pattern.lower())
        if key:
            # Check the appropriate button WITHOUT triggering signal handlers
            # We just want to update the UI state, not restart the movement
            if key in self.mover_sync_buttons:
                self.mover_sync_buttons[key].blockSignals(True)
                self.mover_sync_buttons[key].setChecked(True)
                self.mover_sync_buttons[key].blockSignals(False)
                self._active_mover_movement = key
            elif key in self.mover_wave_buttons:
                self.mover_wave_buttons[key].blockSignals(True)
                self.mover_wave_buttons[key].setChecked(True)
                self.mover_wave_buttons[key].blockSignals(False)
                self._active_mover_movement = key

    def _on_mover_movement_toggled(self, movement_key: str, checked: bool):
        """Called when a mover movement button is toggled."""
        if checked:
            # Uncheck all other movement buttons
            for key, btn in self.mover_sync_buttons.items():
                if key != movement_key:
                    btn.blockSignals(True)
                    btn.setChecked(False)
                    btn.blockSignals(False)
            for key, btn in self.mover_wave_buttons.items():
                if key != movement_key:
                    btn.blockSignals(True)
                    btn.setChecked(False)
                    btn.blockSignals(False)
            
            # Track the active movement
            self._active_mover_movement = movement_key
            
            # If an effect is already running, just update the movement pattern
            # Otherwise, start a new movement effect
            if self.effect_engine.is_running() and self._current_effect:
                # Update current effect with new movement parameters.
                # Previously we only changed movement_pattern, which meant movement would inherit
                # whatever speed/cycle_seconds the underlying effect was using. That often looks
                # jerky until the mover speed slider is touched.

                effect = self._current_effect

                # CRITICAL: If there's no color_palette, add a themed or default palette for visual variety
                if not hasattr(effect, 'color_palette') or not effect.color_palette:
                    if hasattr(self, 'movement_color_schemes') and movement_key in self.movement_color_schemes:
                        effect.color_palette = self.movement_color_schemes[movement_key]['palette']
                        print(f"[_on_mover_movement_toggled] Added themed palette for {movement_key}: {effect.color_palette}")
                    else:
                        effect.color_palette = ['#ff0000', '#ff8000', '#ffff00', '#00ff00', '#00ffff', '#0000ff', '#ff00ff', '#ffffff']
                        print(f"[_on_mover_movement_toggled] Added default palette to effect: {effect.color_palette}")

                # Enable rainbow_colors (color cycling) if this movement pattern has color_cycle enabled
                color_cycle_enabled = False
                if hasattr(self, 'movement_color_schemes') and movement_key in self.movement_color_schemes:
                    color_cycle_enabled = self.movement_color_schemes[movement_key].get('color_cycle', False)
                if color_cycle_enabled:
                    effect.rainbow_colors = True
                    print(f"[_on_mover_movement_toggled] Enabled color cycling for {movement_key}")

                # Apply mover speed/offset immediately
                speed_bpm = self.mover_speed_slider.value() if hasattr(self, 'mover_speed_slider') else effect.speed_bpm
                if speed_bpm <= 0:
                    speed_bpm = 60
                effect.speed_bpm = speed_bpm

                offset_pct = self.mover_offset_slider.value() / 100.0 if hasattr(self, 'mover_offset_slider') else getattr(effect, 'fixture_offset', 0.0)
                effect.fixture_offset = offset_pct

                # Read user-defined bounds from the Patterns subtab spinboxes.
                # These let the user limit how far the lights move.
                _pmin = self.patterns_pan_min_spin.value() if hasattr(self, 'patterns_pan_min_spin') else 0
                _pmax = self.patterns_pan_max_spin.value() if hasattr(self, 'patterns_pan_max_spin') else 255
                _tmin = self.patterns_tilt_min_spin.value() if hasattr(self, 'patterns_tilt_min_spin') else 0
                _tmax = self.patterns_tilt_max_spin.value() if hasattr(self, 'patterns_tilt_max_spin') else 255

                # Map movement key → engine pattern name
                _key_to_engine = {
                    'circle_sync': 'circle', 'figure8_sync': 'figure8',
                    'sweep_sync': 'sweep', 'nod_sync': 'nod',
                    'ballyhoo_sync': 'ballyhoo', 'drift_sync': 'drift',
                    'cross_sync': 'cross', 'pendulum_sync': 'pendulum',
                    'zigzag_sync': 'zigzag',
                    'wave_sweep': 'wave_sweep', 'tilt_wave': 'tilt_wave',
                    'spiral': 'spiral', 'waterfall': 'waterfall',
                    'converge': 'converge', 'diverge': 'diverge',
                    'mirror': 'mirror', 'fan_out': 'fan_out', 'fan_in': 'fan_in',
                    'chase_pan': 'chase_pan', 'random_wave': 'random_wave',
                    'bounce_wave': 'bounce_wave', 'stagger': 'stagger',
                    'crossover': 'crossover', 'figure8_wide': 'figure8_wide',
                }
                effect.movement_pattern = _key_to_engine.get(movement_key, 'sweep')

                # Use the user-defined bounds for all patterns
                effect.pan_min = _pmin
                effect.pan_max = _pmax
                effect.tilt_min = _tmin
                effect.tilt_max = _tmax

                # Pattern-specific cycle_seconds
                if movement_key in ("circle_sync",):
                    effect.cycle_seconds = 60.0 / speed_bpm * 2
                elif movement_key in ("figure8_sync", "figure8_wide"):
                    effect.cycle_seconds = 60.0 / speed_bpm * 4
                elif movement_key == "drift_sync":
                    effect.cycle_seconds = 60.0 / max(5, speed_bpm) * 8
                else:
                    effect.cycle_seconds = 0

                self._current_effect = effect
                # IMPORTANT: Don't route through _update_live_effect() here.
                # That method applies REFINE subtab gating and can restore speed_bpm/cycle_seconds
                # from the original effect when the Speed subtab is OFF, which re-introduces
                # the jerk until the mover speed slider is touched.
                self.effect_engine.update_effect(effect)
                
                # CRITICAL: Also update _original_effect to preserve the new movement pattern
                # This prevents _update_live_effect from restoring the old pattern when subtabs are disabled
                if hasattr(self, '_original_effect') and self._original_effect:
                    self._original_effect.movement_pattern = effect.movement_pattern
                    self._original_effect.cycle_seconds = effect.cycle_seconds
                    self._original_effect.pan_min = effect.pan_min
                    self._original_effect.pan_max = effect.pan_max
                    self._original_effect.tilt_min = effect.tilt_min
                    self._original_effect.tilt_max = effect.tilt_max
                    # Also preserve color_palette so it doesn't get lost on subtab resets
                    self._original_effect.color_palette = getattr(effect, 'color_palette', [])
                    # Preserve rainbow_colors (color cycling) setting
                    self._original_effect.rainbow_colors = getattr(effect, 'rainbow_colors', False)
                
                print(f"[Mover] Updated movement: {movement_key} pattern={effect.movement_pattern} speed={effect.speed_bpm} offset={effect.fixture_offset}")
            else:
                # No effect running - start a new movement effect
                self._start_mover_movement(movement_key)
        else:
            # Stop movement if unchecked
            if self._active_mover_movement == movement_key:
                self._stop_mover_movement()
    
    def _stop_mover_movement(self):
        """Stop the current mover movement WITHOUT stopping other effects."""
        import traceback
        print("[Mover] _stop_mover_movement called from:")
        traceback.print_stack(limit=8)
        
        self._active_mover_movement = None
        
        # Uncheck all movement buttons (silently, without triggering callbacks)
        for btn in self.mover_sync_buttons.values():
            btn.blockSignals(True)
            btn.setChecked(False)
            btn.blockSignals(False)
        for btn in self.mover_wave_buttons.values():
            btn.blockSignals(True)
            btn.setChecked(False)
            btn.blockSignals(False)
        
        # IMPORTANT: Don't stop the entire effect!
        # Just clear the movement pattern so the effect loop will skip movement overlay
        # This keeps color/intensity effects running while disabling pan/tilt animation
        if self._current_effect:
            # Set movement_pattern to None/empty to disable movement overlay
            self._current_effect.movement_pattern = None
            # Update running effect to apply the change immediately
            self._update_live_effect()
            print("[Mover] Movement overlay disabled (effect continues running)")
        else:
            print("[Mover] No effect running")
    
    def _start_mover_movement(self, movement_key: str):
        """Start a moving head movement pattern."""
        from effect_engine import EffectParameters
        
        # Get settings
        offset_pct = self.mover_offset_slider.value() / 100.0
        speed_bpm = self.mover_speed_slider.value()
        
        # Ensure speed_bpm is at least 1 to avoid division by zero
        if speed_bpm <= 0:
            speed_bpm = 60  # Default to 60 BPM (1 Hz) if slider is at 0
        
        # PRESERVE current color palette and intensity
        # First check palette_colors (from refine UI), then fall back to current running effect
        if self.palette_colors:
            current_color = self.palette_colors[0]
            current_palette = self.palette_colors.copy()
            print(f"[GUI _start_mover_movement] Using refine palette: {current_palette}")
        elif self._current_effect and getattr(self._current_effect, 'color_palette', []):
            # Use palette from the currently running effect if it has one
            current_palette = self._current_effect.color_palette.copy()
            current_color = current_palette[0]
            print(f"[GUI _start_mover_movement] Using effect palette: {current_palette}")
        else:
            # Use themed palette if available for this movement pattern
            if hasattr(self, 'movement_color_schemes') and movement_key in self.movement_color_schemes:
                current_palette = self.movement_color_schemes[movement_key]['palette']
                current_color = current_palette[0]
                print(f"[GUI _start_mover_movement] Using themed palette for {movement_key}: {current_palette}")
            else:
                # Fallback: Use colors that map well to moving head color wheels for maximum variety
                current_palette = ['#ff0000', '#ff8000', '#ffff00', '#00ff00', '#00ffff', '#0000ff', '#ff00ff', '#ffffff']
                current_color = current_palette[0]
                print(f"[GUI _start_mover_movement] Using default palette: {current_palette}")
        
        current_intensity = self.intensity_slider.value()
        current_intensity_min = self.intensity_min_spin.value()
        current_intensity_max = self.intensity_max_spin.value()
        
        # Check if this movement pattern has color cycling enabled
        color_cycle_enabled = False
        if hasattr(self, 'movement_color_schemes') and movement_key in self.movement_color_schemes:
            color_cycle_enabled = self.movement_color_schemes[movement_key].get('color_cycle', False)
        
        # Rainbow colors: use checkbox OR color_cycle from scheme OR previous effect setting
        rainbow_colors = (
            self.rainbow_colors_checkbox.isChecked() or 
            color_cycle_enabled or
            (self._current_effect and getattr(self._current_effect, 'rainbow_colors', False))
        )
        print(f"[GUI _start_mover_movement] rainbow_colors={rainbow_colors} (checkbox={self.rainbow_colors_checkbox.isChecked()}, color_cycle={color_cycle_enabled})")
        
        # Create effect parameters
        effect = EffectParameters(
            target_groups=["all"],
            description=f"Mover: {movement_key}"
        )
        
        # CRITICAL FIX: Preserve current effect_type instead of forcing "movement"
        # This allows movement patterns to work with rainbow, pulse, chase, etc. effects
        # Movement patterns should be overlays, not replacement effect types
        if self._current_effect and hasattr(self._current_effect, 'effect_type'):
            effect.effect_type = self._current_effect.effect_type
        else:
            effect.effect_type = "movement"
        
        effect.speed_bpm = speed_bpm
        effect.color = current_color
        effect.color_palette = current_palette
        effect.intensity = current_intensity
        
        print(f"[GUI _start_mover_movement] Effect created:")
        print(f"  - color = {effect.color}")
        print(f"  - color_palette = {effect.color_palette}")
        print(f"  - effect_type = {effect.effect_type}")
        # For pure movement effects, keep intensity CONSTANT (no chase/dimming)
        # Set min = max = current intensity so there's no flickering
        effect.intensity_min = current_intensity
        effect.intensity_max = current_intensity
        effect.rainbow_colors = rainbow_colors
        
        # Default pan/tilt ranges (can be overridden)
        effect.pan_min = 20
        effect.pan_max = 235
        effect.tilt_min = 40
        effect.tilt_max = 200
        
        # Always use the slider value for fixture offset
        effect.fixture_offset = offset_pct
        
        # Configure based on movement type
        if movement_key == "circle_sync":
            effect.movement_pattern = "circle"
            effect.cycle_seconds = 60.0 / speed_bpm * 2  # 2 beats per circle
            
        elif movement_key == "figure8_sync":
            effect.movement_pattern = "figure8"
            effect.cycle_seconds = 60.0 / speed_bpm * 4  # 4 beats per figure-8
            
        elif movement_key == "sweep_sync":
            effect.movement_pattern = "sweep"
            effect.pan_min = 10
            effect.pan_max = 245
            effect.tilt_min = 100
            effect.tilt_max = 140
            
        elif movement_key == "nod_sync":
            effect.movement_pattern = "nod"
            effect.pan_min = 120
            effect.pan_max = 135
            effect.tilt_min = 60
            effect.tilt_max = 200
            
        elif movement_key == "ballyhoo_sync":
            effect.movement_pattern = "ballyhoo"
            
        elif movement_key == "drift_sync":
            effect.movement_pattern = "circle"
            effect.cycle_seconds = 60.0 / max(5, speed_bpm) * 8  # Very slow
            effect.pan_min = 80
            effect.pan_max = 175
            effect.tilt_min = 90
            effect.tilt_max = 165
            
        # Position-based effects
        elif movement_key == "wave_sweep":
            effect.movement_pattern = "wave_sweep"
            effect.direction = "forward"
            
        elif movement_key == "tilt_wave":
            effect.movement_pattern = "tilt_wave"
            effect.direction = "forward"
            effect.pan_min = 120
            effect.pan_max = 135
            
        elif movement_key == "spiral":
            effect.movement_pattern = "spiral"
            
        elif movement_key == "waterfall":
            effect.movement_pattern = "waterfall"
            effect.direction = "top_down"
            
        elif movement_key == "converge":
            effect.movement_pattern = "converge"
            
        elif movement_key == "diverge":
            effect.movement_pattern = "diverge"
            
        elif movement_key == "mirror":
            effect.movement_pattern = "mirror"
            
        elif movement_key == "fan_out":
            effect.movement_pattern = "fan_out"
            effect.tilt_min = 80
            effect.tilt_max = 180
            
        elif movement_key == "fan_in":
            effect.movement_pattern = "fan_in"
            effect.tilt_min = 80
            effect.tilt_max = 180
            
        elif movement_key == "chase_pan":
            effect.movement_pattern = "chase_pan"
            effect.direction = "forward"
            
        elif movement_key == "random_wave":
            effect.movement_pattern = "random_wave"
            effect.direction = "random"
            
        elif movement_key == "bounce_wave":
            effect.movement_pattern = "bounce_wave"
            effect.direction = "bounce"
        
        # Note: fixture_offset was set earlier based on sync vs position-based
        
        # Set current effect and start
        self._current_effect = effect
        # CRITICAL: Also set _original_effect so palette isn't lost on subtab resets
        self._original_effect = effect
        
        print(f"[GUI _start_mover_movement] Set _original_effect.color_palette = {effect.color_palette}")
        
        # DEBUG
        print(f"\n[GUI _start_mover_movement] {movement_key}")
        print(f"  - effect.movement_pattern = '{effect.movement_pattern}'")
        print(f"  - effect.effect_type = '{effect.effect_type}'")
        print(f"  - effect.speed_bpm = {effect.speed_bpm}")
        print(f"  - effect.color = {effect.color}")
        print(f"  - Calling effect_engine.start_effect()...\n")
        
        self.effect_engine.start_effect(effect)
        
        print(f"[Mover] Started movement: {movement_key}, speed={speed_bpm}BPM, offset={effect.fixture_offset*100:.0f}%")

    def _get_selected_position_preset_ids(self) -> list:
        """Get list of position preset IDs that are checked for position cycle."""
        selected_ids = []
        for preset_id, checkbox in self.position_cycle_preset_checkboxes.items():
            if checkbox.isChecked():
                selected_ids.append(preset_id)
        return selected_ids
    
    def _save_palette(self):
        """Save the current palette colors as a named palette."""
        if not self.palette_colors:
            QMessageBox.warning(self._get_active_window(), "No Colors", "Add some colors to the palette first.")
            return
        
        # Get name from the text field
        name = self.palette_name_edit.text().strip()
        
        if not name:
            QMessageBox.warning(self._get_active_window(), "No Name", "Enter a name for the palette.")
            self.palette_name_edit.setFocus()
            return
        
        # Check if name already exists
        for palette in self.project.color_palettes:
            if palette.name.lower() == name.lower():
                reply = QMessageBox.question(
                    self._get_active_window(), "Replace Palette?",
                    f"A palette named '{palette.name}' already exists. Replace it?",
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
                )
                if reply == QMessageBox.StandardButton.Yes:
                    palette.colors = self.palette_colors.copy()
                    self._mark_dirty()
                    self._refresh_saved_palettes()
                    self.statusBar().showMessage(f"Palette '{name}' updated", 3000)
                return
        
        # Create new palette
        import uuid
        new_palette = ColorPalette(
            id=str(uuid.uuid4()),
            name=name,
            colors=self.palette_colors.copy()
        )
        self.project.color_palettes.append(new_palette)
        self._mark_dirty()
        self._refresh_saved_palettes()
        
        # Clear the name field and show confirmation
        self.palette_name_edit.clear()
        self.statusBar().showMessage(f"Palette '{name}' saved with {len(self.palette_colors)} colors", 3000)
    
    def _delete_palette(self):
        """Legacy delete method - now using context menu on buttons."""
        # Show info about new way to delete
        QMessageBox.information(self._get_active_window(), "Delete Palette", 
            "To delete a palette, right-click on its button in the Saved Palettes section.")

    def _on_intensity_changed(self, value: int):
        """Handle intensity slider change."""
        logger.debug(f"_on_intensity_changed: value={value}")
        self.intensity_label.setText(f"{value}%")
        
        # If strobe is active, just update the strobe intensity without restarting
        if hasattr(self, '_strobe_active') and self._strobe_active:
            if self._current_effect:
                self._current_effect.intensity = value
                # Use update_effect to change intensity without restarting
                self.effect_engine.update_effect(self._current_effect)
            return
        
        self._on_refine_param_changed()
    
    def _on_strobe_changed(self):
        """Handle strobe speed change."""
        speed = self.strobe_speed_slider.value()
        self.strobe_speed_label.setText(str(speed))
        
        # Check if strobe is enabled via the toggle button (not the hidden checkbox)
        is_enabled = self.strobe_subtab_toggle.isChecked()
        print(f"[Strobe] _on_strobe_changed: enabled={is_enabled}, speed={speed}")
        
        # Update strobe speed whenever the slider moves (if strobe is enabled)
        if is_enabled:
            self._start_strobe_effect()
    
    def _set_strobe_speed(self, speed: int):
        """Set strobe speed from quick preset button."""
        print(f"[Strobe] Quick preset clicked: speed={speed}")
        self.strobe_speed_slider.setValue(speed)
        # Enable strobe via sub-tab toggle
        self.strobe_subtab_toggle.setChecked(True)
        self._on_subtab_toggle('strobe', True)
    
    def _start_strobe_effect(self):
        """Start strobe by switching effect type to 'strobe' in effect engine."""
        print(f"[Strobe] Starting strobe effect")
        print(f"[LIGHTING DESIGNER DEBUG] ===== STROBE EFFECT START =====")
        
        # Track if strobe was already active
        already_active = hasattr(self, '_strobe_active') and self._strobe_active
        
        # Save current effect if not already in strobe mode
        if not already_active:
            self._pre_strobe_effect_type = self.effect_type_combo.currentText()
            # Save the complete effect parameters so we can restore it
            if hasattr(self, '_current_effect') and self._current_effect:
                self._pre_strobe_effect = self._current_effect
                print(f"[Strobe] Saved previous effect: {self._current_effect.effect_type}")
                print(f"[LIGHTING DESIGNER DEBUG] Previous effect_type: {self._current_effect.effect_type}")
            else:
                self._pre_strobe_effect = None
        
        self._strobe_active = True
        
        # Map strobe speed slider (1-255) to BPM for strobe effect
        # Slider 1 = 60 BPM (1 flash/sec), Slider 255 = 900 BPM (15 flashes/sec)
        speed = self.strobe_speed_slider.value()
        strobe_bpm = int(60 + (speed / 255.0) * 840)
        
        print(f"[Strobe] Strobe speed={speed} -> BPM={strobe_bpm}")
        print(f"[LIGHTING DESIGNER DEBUG] Strobe speed: {speed} -> BPM: {strobe_bpm}")
        
        # Get color from current effect, NOT from palette selector
        # This preserves the color from the quick effect
        if hasattr(self, '_current_effect') and self._current_effect:
            strobe_color = self._current_effect.color
            strobe_palette = self._current_effect.color_palette.copy() if self._current_effect.color_palette else []
            # PRESERVE movement pattern and position cycling from current effect
            movement_pattern = self._current_effect.movement_pattern
            position_cycle_enabled = getattr(self._current_effect, 'position_cycle_enabled', False)
            position_cycle_presets = getattr(self._current_effect, 'position_cycle_presets', [])
            position_cycle_hold_time = getattr(self._current_effect, 'position_cycle_hold_time', 4.0)
            position_cycle_speed = getattr(self._current_effect, 'position_cycle_speed', 128)
            cycle_seconds = self._current_effect.cycle_seconds
            # PRESERVE color wheel and gobo settings
            color_wheel_value = getattr(self._current_effect, 'color_wheel_value', -1)
            gobo_value = getattr(self._current_effect, 'gobo_value', 0)
            effect_channel_value = getattr(self._current_effect, 'effect_channel_value', -1)
            
            print(f"[LIGHTING DESIGNER DEBUG] Preserved from current effect:")
            print(f"[LIGHTING DESIGNER DEBUG]   color: {strobe_color}")
            print(f"[LIGHTING DESIGNER DEBUG]   movement_pattern: {movement_pattern}")
            print(f"[LIGHTING DESIGNER DEBUG]   position_cycle_enabled: {position_cycle_enabled}")
            print(f"[LIGHTING DESIGNER DEBUG]   color_wheel_value: {color_wheel_value}")
            print(f"[LIGHTING DESIGNER DEBUG]   gobo_value: {gobo_value}")
        else:
            # No current effect - use palette if available
            strobe_color = self.palette_colors[0] if self.palette_colors else "#ffffff"
            strobe_palette = self.palette_colors.copy() if self.palette_colors else []
            movement_pattern = ''
            position_cycle_enabled = False
            position_cycle_presets = []
            position_cycle_hold_time = 4.0
            position_cycle_speed = 128
            cycle_seconds = 0
            color_wheel_value = -1
            gobo_value = 0
            effect_channel_value = -1
            print(f"[LIGHTING DESIGNER DEBUG] No current effect - using defaults")
        
        # Get target groups
        if self.target_all_checkbox.isChecked():
            target_groups = ["all"]
        else:
            selected = [name for name, cb in self.target_group_checkboxes.items() if cb.isChecked()]
            target_groups = selected if selected else ["all"]
        
        print(f"[LIGHTING DESIGNER DEBUG] target_groups: {target_groups}")
        print(f"[LIGHTING DESIGNER DEBUG] intensity: {self.intensity_slider.value()}")
        print(f"[LIGHTING DESIGNER DEBUG] intensity_min: 0, intensity_max: 100")
        
        # Create strobe effect - preserve movement patterns
        effect = EffectParameters(
            effect_type='strobe',
            color=strobe_color,
            intensity=self.intensity_slider.value(),
            intensity_min=0,  # Full off
            intensity_max=100,  # Full on
            speed_bpm=strobe_bpm,
            direction='forward',
            movement_pattern=movement_pattern,  # PRESERVE movement
            cycle_seconds=cycle_seconds,  # PRESERVE cycle timing
            pan_min=self.pan_min_spin.value(),
            pan_max=self.pan_max_spin.value(),
            tilt_min=self.tilt_min_spin.value(),
            tilt_max=self.tilt_max_spin.value(),
            rainbow_colors=False,
            color_palette=strobe_palette,
            color_wheel_value=color_wheel_value,  # PRESERVE color wheel
            gobo_value=gobo_value,  # PRESERVE gobo
            effect_channel_value=effect_channel_value,  # PRESERVE effect channel
            position_cycle_enabled=position_cycle_enabled,  # PRESERVE position cycling
            position_cycle_presets=position_cycle_presets,
            position_cycle_hold_time=position_cycle_hold_time,
            position_cycle_speed=position_cycle_speed,
            # CRITICAL: Set strobe_subtab_enabled=True so Timeline/Player know to use strobe mode
            strobe_subtab_enabled=True,
        )
        
        # Set target groups
        effect.target_groups = target_groups
        
        effect.description = "Strobe effect"
        
        self._current_effect = effect
        
        print(f"[LIGHTING DESIGNER DEBUG] Created EffectParameters:")
        print(f"[LIGHTING DESIGNER DEBUG]   effect_type: {effect.effect_type}")
        print(f"[LIGHTING DESIGNER DEBUG]   target_groups: {effect.target_groups}")
        print(f"[LIGHTING DESIGNER DEBUG]   intensity: {effect.intensity}, min: {effect.intensity_min}, max: {effect.intensity_max}")
        print(f"[LIGHTING DESIGNER DEBUG]   speed_bpm: {effect.speed_bpm}")
        print(f"[LIGHTING DESIGNER DEBUG] Fader level: {getattr(self.effect_engine, '_fader_level', 'NOT SET')}")
        
        # If strobe was already active, use update_effect to preserve timing
        if already_active:
            print(f"[Strobe] Updating strobe speed to {strobe_bpm} BPM")
            print(f"[LIGHTING DESIGNER DEBUG] Calling effect_engine.update_effect()")
            self.effect_engine.update_effect(effect)
        else:
            print(f"[Strobe] Starting new strobe effect at {strobe_bpm} BPM")
            print(f"[LIGHTING DESIGNER DEBUG] Calling effect_engine.start_effect()")
            self.effect_engine.start_effect(effect)
        
        print(f"[Strobe] Effect applied with movement={movement_pattern}, position_cycling={position_cycle_enabled}")
        print(f"[LIGHTING DESIGNER DEBUG] ===== STROBE EFFECT START COMPLETE =====")
    
    def _stop_strobe_effect(self):
        """Stop strobe and restore previous effect."""
        print(f"[Strobe] Stopping strobe effect")
        self._strobe_active = False
        
        # Restore previous effect if we had one saved before strobe started
        if hasattr(self, '_pre_strobe_effect') and self._pre_strobe_effect:
            print(f"[Strobe] Restoring previous effect: {self._pre_strobe_effect.effect_type}")
            self._current_effect = self._pre_strobe_effect
            self.effect_engine.start_effect(self._pre_strobe_effect)
        else:
            # No previous effect - just stop and restore intensity
            print(f"[Strobe] No previous effect to restore, stopping")
            self.effect_engine.stop_effect(blackout=False, send_home=False)
            
            # Restore intensity to current slider setting
            intensity = int(self.intensity_slider.value() * 2.55)
            self._set_all_dimmers(intensity)
    
    def _set_all_dimmers(self, value: int):
        """Set all target fixture dimmers to a value."""
        artnet = get_artnet_output()
        if not artnet:
            return
        
        # Get target fixtures
        target_fixtures = []
        if self.target_all_checkbox.isChecked():
            target_fixtures = list(self.project.fixtures)
        else:
            for group in self.project.groups:
                cb = self.target_group_checkboxes.get(group.name)
                if cb and cb.isChecked():
                    for fid in group.fixture_ids:
                        fixture = next((f for f in self.project.fixtures if f.id == fid), None)
                        if fixture and fixture not in target_fixtures:
                            target_fixtures.append(fixture)
        
        # Set dimmer channel on each fixture
        for fixture in target_fixtures:
            if not fixture.mode:
                continue
            
            for i, ch in enumerate(fixture.mode.channels):
                ch_type = ch.type.lower() if ch.type else ''
                ch_name = ch.name.lower() if ch.name else ''
                
                is_dimmer = (
                    ch_type in ('dimmer', 'intensity', 'master', 'master dimmer') or
                    'dimmer' in ch_name or 'intensity' in ch_name or ch_name == 'dim'
                )
                
                if is_dimmer:
                    dmx_addr = fixture.address + i
                    artnet.set_channel(fixture.universe, dmx_addr, value)
                    break

    def _on_speed_changed(self, value: int):
        """Handle speed change - update current effect if running."""
        if self._current_effect and self.effect_engine.is_running():
            self._current_effect.speed_bpm = value
            # Restart effect with new speed
            self.effect_engine.start_effect(self._current_effect)
    
    def _apply_manual_effect(self, from_preset: bool = False):
        """Apply manual effect from Refine tab controls.
        
        Args:
            from_preset: If True, loading from a saved preset - will reset movers to home
                        if no movement pattern is set. If False, this is a live parameter
                        change and movers stay where they are.
        """
        # Cancel any existing speed restoration timers to avoid conflicts
        self._cancel_speed_restoration_timers()
        
        # Get color from palette, default to white if empty
        color = self.palette_colors[0] if self.palette_colors else "#ffffff"
        
        # Get effect type (convert spaces to underscores for pixel effects like "Pixel Chase" -> "pixel_chase")
        effect_type = self.effect_type_combo.currentText().lower().replace(' ', '_')
        
        # DEBUG: Log what we're reading
        print(f"[_apply_manual_effect] effect_type from combo: '{effect_type}', color: '{color}', from_preset={from_preset}")
        print(f"[_apply_manual_effect] palette_colors: {self.palette_colors[:3] if self.palette_colors else 'empty'}...")
        
        # Check if position cycling is enabled (independent of effect type)
        position_cycling_enabled = self.position_cycle_box.isChecked()
        selected_position_ids = self._get_selected_position_preset_ids()
        
        print(f"[GUI] _apply_manual_effect: position_cycling_enabled={position_cycling_enabled}, selected_positions={selected_position_ids}")
        
        # Get movement pattern from active button and rainbow setting
        movement_pattern = self._get_active_movement_pattern()
        rainbow_colors = self.rainbow_colors_checkbox.isChecked()
        
        # Determine if we should reset movers to home position
        # Only reset if loading from preset AND there's no movement pattern
        should_reset_home = from_preset and (not movement_pattern or movement_pattern.lower() in ('none', ''))
        
        effect = EffectParameters(
            effect_type=effect_type,
            color=color,
            intensity=self.intensity_slider.value(),
            intensity_min=self.intensity_min_spin.value(),
            intensity_max=self.intensity_max_spin.value(),
            speed_bpm=self.speed_spin.value(),
            direction=self.direction_combo.currentText().lower(),
            movement_pattern=movement_pattern,
            cycle_seconds=0,  # Use BPM-based timing
            pan_min=self.pan_min_spin.value(),
            pan_max=self.pan_max_spin.value(),
            tilt_min=self.tilt_min_spin.value(),
            tilt_max=self.tilt_max_spin.value(),
            rainbow_colors=rainbow_colors,
            color_palette=self.palette_colors.copy() if self.palette_colors else [],
            # Position cycling settings (independent feature)
            position_cycle_presets=self._get_selected_position_preset_ids() if position_cycling_enabled else [],
            position_cycle_enabled=position_cycling_enabled,
            position_cycle_hold_time=self.position_cycle_hold_spin.value() if position_cycling_enabled else 4.0,
            position_cycle_speed=self.position_cycle_speed_slider.value() if position_cycling_enabled else 128,
            # Reset movers to home when loading preset without movement
            reset_to_home=should_reset_home,
            # Gobo and other channel values
            gobo_value=getattr(self, 'current_gobo_value', 0),
            macro_value=self.macro_spin.value() if hasattr(self, 'macro_spin') else 0,
            color_wheel_value=self.color_wheel_spin.value() if hasattr(self, 'color_wheel_spin') else -1,
            effect_channel_value=self.effect_channel_spin.value() if hasattr(self, 'effect_channel_spin') else -1,
            # Subtab enabled states - capture from UI toggles
            gobo_subtab_enabled=self.gobo_subtab_toggle.isChecked() if hasattr(self, 'gobo_subtab_toggle') else False,
            color_subtab_enabled=self.color_subtab_toggle.isChecked() if hasattr(self, 'color_subtab_toggle') else False,
            effect_subtab_enabled=self.effect_subtab_toggle.isChecked() if hasattr(self, 'effect_subtab_toggle') else False,
            speed_subtab_enabled=self.speed_subtab_toggle.isChecked() if hasattr(self, 'speed_subtab_toggle') else False,
            strobe_subtab_enabled=self.strobe_subtab_toggle.isChecked() if hasattr(self, 'strobe_subtab_toggle') else False,
            movement_subtab_enabled=self.movement_subtab_toggle.isChecked() if hasattr(self, 'movement_subtab_toggle') else False,
            patterns_subtab_enabled=self.patterns_subtab_toggle.isChecked() if hasattr(self, 'patterns_subtab_toggle') else False,
            position_subtab_enabled=self.position_subtab_toggle.isChecked() if hasattr(self, 'position_subtab_toggle') else False,
            intensity_subtab_enabled=self.intensity_subtab_toggle.isChecked() if hasattr(self, 'intensity_subtab_toggle') else False,
            target_subtab_enabled=self.target_subtab_toggle.isChecked() if hasattr(self, 'target_subtab_toggle') else False,
        )

        # If movement is active, the dedicated mover speed/offset controls are the user's source of truth.
        if movement_pattern and movement_pattern.lower() not in ('none', ''):
            if hasattr(self, 'mover_speed_slider'):
                effect.speed_bpm = int(self.mover_speed_slider.value())
            if hasattr(self, 'mover_offset_slider'):
                offset_pct = float(self.mover_offset_slider.value()) / 100.0
                effect.fixture_offset = offset_pct
        
        # Set target - get selected groups from checkboxes
        if self.target_all_checkbox.isChecked():
            effect.target_groups = ["all"]
        else:
            selected = [name for name, cb in self.target_group_checkboxes.items() if cb.isChecked()]
            effect.target_groups = selected if selected else ["all"]
        
        effect.description = f"Manual {effect.effect_type} effect"
        
        self._current_effect = effect
        self.effect_engine.start_effect(effect)
        
        # Update CREATE tab preview button state
        if hasattr(self, 'preview_btn'):
            self.preview_btn.setChecked(True)
            self.preview_btn.setEnabled(True)
            self.save_preset_btn.setEnabled(True)
            self.effect_description.setText(
                f"<b>{effect.effect_type.title()}</b><br>"
                f"<span style='color: {effect.color}'>●</span> {effect.color} | "
                f"{effect.intensity}% | {effect.speed_bpm} BPM"
            )
    
    def _update_live_effect(self):
        """Update running effect parameters without restarting the animation cycle.
        
        Core behavior - DISABLED SUBTABS PRESERVE QUICK EFFECT VALUES:
        - Start with a copy of current effect (preserves ALL values)
        - For each ENABLED subtab: read UI controls and override effect parameters
        - For each DISABLED subtab: do NOT read UI, keep preserved values from quick effect
        - Result: Moving sliders on disabled subtabs has NO effect on the running effect
        
        Example flow:
        1. User selects "Red Static" quick effect → all subtabs OFF
        2. User enables Intensity subtab → can adjust intensity
        3. User disables Intensity subtab → moving slider does NOTHING
        4. Intensity returns to quick effect value when next enabled
        
        This preserves where fixtures are in their pan/tilt movement cycle
        while updating only the parameters from ENABLED subtabs.
        """
        # Only update if an effect is currently defined
        if not hasattr(self, '_current_effect') or self._current_effect is None:
            # No effect loaded - nothing to update
            return
        
        # Start with a copy of current effect values (preserves disabled sub-tabs)
        effect = EffectParameters(
            effect_type=self._current_effect.effect_type,
            color=self._current_effect.color,
            color_name=getattr(self._current_effect, 'color_name', ''),
            intensity=self._current_effect.intensity,
            intensity_min=self._current_effect.intensity_min,
            intensity_max=self._current_effect.intensity_max,
            speed_bpm=self._current_effect.speed_bpm,
            direction=self._current_effect.direction,
            transition=getattr(self._current_effect, 'transition', 'instant'),
            transition_time=getattr(self._current_effect, 'transition_time', 0.0),
            movement_pattern=self._current_effect.movement_pattern,
            cycle_seconds=self._current_effect.cycle_seconds,
            pan_min=self._current_effect.pan_min,
            pan_max=self._current_effect.pan_max,
            tilt_min=self._current_effect.tilt_min,
            tilt_max=self._current_effect.tilt_max,
            rainbow_colors=self._current_effect.rainbow_colors,
            color_palette=self._current_effect.color_palette.copy() if self._current_effect.color_palette else [],
            macro_value=getattr(self._current_effect, 'macro_value', 0),
            color_wheel_value=getattr(self._current_effect, 'color_wheel_value', -1),
            effect_channel_value=getattr(self._current_effect, 'effect_channel_value', -1),
            gobo_value=getattr(self._current_effect, 'gobo_value', 0),
            position_preset=getattr(self._current_effect, 'position_preset', ''),
            fixture_offset=getattr(self._current_effect, 'fixture_offset', 0.25),
            position_cycle_presets=self._current_effect.position_cycle_presets,
            position_cycle_enabled=self._current_effect.position_cycle_enabled,
            position_cycle_hold_time=self._current_effect.position_cycle_hold_time,
            position_cycle_speed=self._current_effect.position_cycle_speed,
            # Preserve toggle states
            color_subtab_enabled=self._current_effect.color_subtab_enabled,
            effect_subtab_enabled=self._current_effect.effect_subtab_enabled,
            speed_subtab_enabled=self._current_effect.speed_subtab_enabled,
            strobe_subtab_enabled=self._current_effect.strobe_subtab_enabled,
            movement_subtab_enabled=self._current_effect.movement_subtab_enabled,
            patterns_subtab_enabled=self._current_effect.patterns_subtab_enabled,
            position_subtab_enabled=self._current_effect.position_subtab_enabled,
            gobo_subtab_enabled=self._current_effect.gobo_subtab_enabled,
            intensity_subtab_enabled=self._current_effect.intensity_subtab_enabled,
            target_subtab_enabled=self._current_effect.target_subtab_enabled,
        )
        
        print(f"[_update_live_effect] Copied color_palette from _current_effect: {effect.color_palette}")

        # Preserve explicit fixture targeting if present
        effect.target_fixtures = getattr(self._current_effect, 'target_fixtures', [])
        effect.target_groups = getattr(self._current_effect, 'target_groups', ['all'])
        
        # === EFFECT SUB-TAB (controls effect_type and rainbow_colors) ===
        if self._current_effect.effect_subtab_enabled:
            combo_effect_type = self.effect_type_combo.currentText().lower().replace(' ', '_')
            # Only change effect type if it's different from current
            if combo_effect_type != effect.effect_type:
                effect.effect_type = combo_effect_type
            effect.rainbow_colors = self.rainbow_colors_checkbox.isChecked()
        else:
            # When disabled, restore effect_type and rainbow_colors from ORIGINAL
            if hasattr(self, '_original_effect') and self._original_effect:
                effect.effect_type = self._original_effect.effect_type if hasattr(self._original_effect, 'effect_type') else effect.effect_type
                effect.rainbow_colors = self._original_effect.rainbow_colors if hasattr(self._original_effect, 'rainbow_colors') else effect.rainbow_colors
        
        # === COLOR SUB-TAB (controls color and color_palette) ===
        if self._current_effect.color_subtab_enabled:
            color_palette = self.palette_colors.copy() if self.palette_colors else []
            if effect.effect_type == "rainbow" and not color_palette:
                # Rainbow effect with no palette - keep current palette
                pass
            elif color_palette:
                effect.color_palette = color_palette
                effect.color = color_palette[0]
            else:
                effect.color = "#ffffff"
        else:
            # When disabled, restore color and color_palette from ORIGINAL
            if hasattr(self, '_original_effect') and self._original_effect:
                effect.color = self._original_effect.color if hasattr(self._original_effect, 'color') else effect.color
                effect.color_palette = self._original_effect.color_palette.copy() if hasattr(self._original_effect, 'color_palette') and self._original_effect.color_palette else effect.color_palette
        
        # === INTENSITY SUB-TAB (controls intensity, intensity_min, intensity_max) ===
        if self._current_effect.intensity_subtab_enabled:
            current_intensity = self.intensity_slider.value()
            effect.intensity = current_intensity
            
            # Check if movement pattern is active
            movement_pattern = self._get_active_movement_pattern()
            if movement_pattern and movement_pattern.lower() not in ('none', ''):
                # Movement is active - keep brightness constant
                effect.intensity_min = current_intensity
                effect.intensity_max = current_intensity
            else:
                # No movement - use the spinbox values for chase/pulse effects
                effect.intensity_min = self.intensity_min_spin.value()
                effect.intensity_max = self.intensity_max_spin.value()
        else:
            # When disabled, restore intensity from ORIGINAL
            if hasattr(self, '_original_effect') and self._original_effect:
                effect.intensity = self._original_effect.intensity if hasattr(self._original_effect, 'intensity') else effect.intensity
                effect.intensity_min = self._original_effect.intensity_min if hasattr(self._original_effect, 'intensity_min') else effect.intensity_min
                effect.intensity_max = self._original_effect.intensity_max if hasattr(self._original_effect, 'intensity_max') else effect.intensity_max
        
        # === SPEED SUB-TAB (controls speed_bpm and direction) ===
        if self._current_effect.speed_subtab_enabled:
            effect.speed_bpm = self.speed_spin.value()
            effect.direction = self.direction_combo.currentText().lower()
        else:
            # When disabled, restore speed_bpm and direction from ORIGINAL
            if hasattr(self, '_original_effect') and self._original_effect:
                effect.speed_bpm = self._original_effect.speed_bpm if hasattr(self._original_effect, 'speed_bpm') else effect.speed_bpm
                effect.direction = self._original_effect.direction if hasattr(self._original_effect, 'direction') else effect.direction
        
        # === STROBE SUB-TAB ===
        # Strobe is handled specially via _on_subtab_toggle -> _start_strobe_effect
        # Do not implement strobe updates here
        
        # === MOVEMENT SUB-TAB (controls movement_pattern and pan/tilt) ===
        # When movement subtab is ENABLED: Allow buttons to update the pattern
        # When movement subtab is DISABLED: Preserve the current movement pattern
        # This prevents accidentally stopping movement when you disable the subtab
        if self._current_effect.movement_subtab_enabled:
            # Subtab is ENABLED - read active pattern from movement buttons
            # User can click buttons to change movement
            active_pattern = self._get_active_movement_pattern()
            # If no movement button is active, do NOT overwrite an existing pattern.
            # This avoids stopping movement just by toggling the subtab ON.
            if active_pattern and active_pattern.lower() not in ('none', ''):
                effect.movement_pattern = active_pattern
            effect.pan_min = self.pan_min_spin.value()
            effect.pan_max = self.pan_max_spin.value()
            effect.tilt_min = self.tilt_min_spin.value()
            effect.tilt_max = self.tilt_max_spin.value()
        else:
            # Subtab is DISABLED - preserve current movement pattern and ranges
            # Don't change anything - keep the movement running smoothly
            # This prevents jerking/twitching when toggling the subtab off
            pass
        
        # === PATTERNS SUB-TAB (controls movement pattern + mover speed/offset + bounds) ===
        if self._current_effect.patterns_subtab_enabled:
            active_pattern = self._get_active_movement_pattern()
            if active_pattern and active_pattern.lower() not in ('none', ''):
                effect.movement_pattern = active_pattern
                # Prefer dedicated mover controls when a movement overlay is active.
                if hasattr(self, 'mover_speed_slider'):
                    effect.speed_bpm = int(self.mover_speed_slider.value())
                if hasattr(self, 'mover_offset_slider'):
                    offset_pct = float(self.mover_offset_slider.value()) / 100.0
                    effect.fixture_offset = offset_pct
            # Read movement bounds from patterns subtab spinboxes
            if hasattr(self, 'patterns_pan_min_spin'):
                effect.pan_min = self.patterns_pan_min_spin.value()
                effect.pan_max = self.patterns_pan_max_spin.value()
                effect.tilt_min = self.patterns_tilt_min_spin.value()
                effect.tilt_max = self.patterns_tilt_max_spin.value()
        else:
            # When disabled, restore movement pattern + offset from ORIGINAL (not whatever UI shows)
            if hasattr(self, '_original_effect') and self._original_effect:
                effect.movement_pattern = getattr(self._original_effect, 'movement_pattern', effect.movement_pattern)
                effect.fixture_offset = getattr(self._original_effect, 'fixture_offset', effect.fixture_offset)

        # === POSITION SUB-TAB (controls position cycling overlay) ===
        if self._current_effect.position_subtab_enabled:
            position_cycling_enabled = self.position_cycle_box.isChecked()
            effect.position_cycle_enabled = position_cycling_enabled
            if position_cycling_enabled:
                effect.position_cycle_presets = self._get_selected_position_preset_ids()
                effect.position_cycle_hold_time = self.position_cycle_hold_spin.value()
                effect.position_cycle_speed = self.position_cycle_speed_slider.value()
        else:
            # When disabled, restore position cycling from ORIGINAL
            if hasattr(self, '_original_effect') and self._original_effect:
                effect.position_cycle_enabled = getattr(self._original_effect, 'position_cycle_enabled', effect.position_cycle_enabled)
                effect.position_cycle_presets = getattr(self._original_effect, 'position_cycle_presets', effect.position_cycle_presets)
                effect.position_cycle_hold_time = getattr(self._original_effect, 'position_cycle_hold_time', effect.position_cycle_hold_time)
                effect.position_cycle_speed = getattr(self._original_effect, 'position_cycle_speed', effect.position_cycle_speed)
        
        # === GOBO SUB-TAB (controls gobo_value, gobo2_value, rotation values) ===
        if self._current_effect.gobo_subtab_enabled:
            # When enabled, use the current gobo value from the UI buttons
            effect.gobo_value = getattr(self, 'current_gobo_value', 0)
            # gobo2 and rotation values don't have dedicated UI controls yet,
            # so preserve them from the current running effect
            effect.gobo_rotation_value = getattr(self._current_effect, 'gobo_rotation_value', 0)
            effect.gobo2_value = getattr(self._current_effect, 'gobo2_value', 0)
            effect.gobo2_rotation_value = getattr(self._current_effect, 'gobo2_rotation_value', 0)
        else:
            # When disabled, restore gobo values from ORIGINAL quick effect (not current)
            # This ensures gobos return to original settings when subtab disabled
            if hasattr(self, '_original_effect') and self._original_effect:
                effect.gobo_value = self._original_effect.gobo_value if hasattr(self._original_effect, 'gobo_value') else 0
                effect.gobo_rotation_value = getattr(self._original_effect, 'gobo_rotation_value', 0)
                effect.gobo2_value = getattr(self._original_effect, 'gobo2_value', 0)
                effect.gobo2_rotation_value = getattr(self._original_effect, 'gobo2_rotation_value', 0)
            # else: preserve current_effect value (backward compat if no original)
        
        # === TARGET SUB-TAB (controls target_groups) ===
        if self._current_effect.target_subtab_enabled:
            if self.target_all_checkbox.isChecked():
                effect.target_groups = ["all"]
            else:
                selected = [name for name, cb in self.target_group_checkboxes.items() if cb.isChecked()]
                effect.target_groups = selected if selected else ["all"]
        else:
            # When disabled, restore target_groups from ORIGINAL
            if hasattr(self, '_original_effect') and self._original_effect:
                effect.target_groups = self._original_effect.target_groups if hasattr(self._original_effect, 'target_groups') else effect.target_groups
        
        effect.description = f"Manual {effect.effect_type} effect"
        
        self._current_effect = effect
        
        # Update parameters in place without restarting
        logger.debug(f"_update_live_effect calling update_effect with intensity={effect.intensity}, color={effect.color}, type={effect.effect_type}")
        self.effect_engine.update_effect(effect)
    
    def _stop_effect(self):
        """Stop the current effect and return fixtures to home positions."""
        # Stop effect and send fixtures home (handled by effect engine)
        self.effect_engine.stop_effect(blackout=False, send_home=True)
        if hasattr(self, 'preview_btn'):
            self.preview_btn.setChecked(False)
    
