    def _ensure_viz_overlay_rect(self):
        """Make sure the draggable overlay positioning rect exists on the stage.
        
        Always uses the main location scene, not a detached copy.
        """
        # Prefer the pinned main-scene reference set by _update_viz_stage_overlay
        scene = getattr(self, '_main_location_scene', None) or getattr(self, 'location_scene', None)
        view = getattr(self, '_main_location_view', None) or getattr(self, 'location_view', None)
        if scene is None or view is None:
            return
        if hasattr(self, '_viz_overlay_rect') and self._viz_overlay_rect is not None:
            return  # already exists
        from PyQt6.QtWidgets import QGraphicsRectItem, QGraphicsItem
        from PyQt6.QtCore import QRectF

        _avail_w = max(600, view.viewport().width() - 40)
        _avail_h = max(400, view.viewport().height() - 40)
        _target_ratio = 16.0 / 9.0
        if _avail_w / _avail_h > _target_ratio:
            view_height = _avail_h
            view_width = int(_avail_h * _target_ratio)
        else:
            view_width = _avail_w
            view_height = int(_avail_w / _target_ratio)

        # One-time migration: clear old saved overlay geometry so the new
        # full-stage default kicks in and fixtures align 1:1 with the frame.
        if hasattr(self, 'app_settings') and not self.app_settings.get('_overlay_v2_migrated'):
            self.app_settings.pop('viz_overlay_rect_geom', None)
            self.app_settings.pop('viz_overlay_rect_geom_rel', None)
            self._viz_overlay_rect_geom = None
            self._viz_overlay_rect_geom_rel = None
            self.app_settings['_overlay_v2_migrated'] = True
            self._save_app_settings()

        # Restore saved rect or default to **full stage** so the
        # visualizer frame maps 1:1 with the fixture layout.
        # Prefer proportional (0-1) geometry so the overlay scales with the
        # view when the window is resized.  Fall back to absolute coords
        # (clamped) for backward compatibility.
        saved_rel = getattr(self, '_viz_overlay_rect_geom_rel', None)
        if not saved_rel and hasattr(self, 'app_settings'):
            saved_rel_list = self.app_settings.get('viz_overlay_rect_geom_rel')
            if saved_rel_list and len(saved_rel_list) == 4:
                saved_rel = tuple(saved_rel_list)
                self._viz_overlay_rect_geom_rel = saved_rel

        if saved_rel:
            rx = saved_rel[0] * view_width
            ry = saved_rel[1] * view_height
            rw = saved_rel[2] * view_width
            rh = saved_rel[3] * view_height
        else:
            saved = getattr(self, '_viz_overlay_rect_geom', None)
            if not saved and hasattr(self, 'app_settings'):
                saved_list = self.app_settings.get('viz_overlay_rect_geom')
                if saved_list and len(saved_list) == 4:
                    saved = tuple(saved_list)
                    self._viz_overlay_rect_geom = saved
            if saved:
                rx, ry, rw, rh = saved
            else:
                # Default: full stage so fixture positions match the
                # visualizer render frame exactly.
                rw = float(view_width)
                rh = float(view_height)
                rx = 0.0
                ry = 0.0

        # Clamp so the overlay never extends beyond the current view bounds
        rw = max(60, min(rw, view_width))
        rh = max(40, min(rh, view_height))
        rx = max(0, min(rx, view_width - rw))
        ry = max(0, min(ry, view_height - rh))

        rect_item = _VizOverlayRectItem(QRectF(0, 0, rw, rh), self)
        rect_item.setPos(rx, ry)
        rect_item.setZValue(100)  # On top of everything so it's easy to grab
        scene.addItem(rect_item)
        self._viz_overlay_rect = rect_item
        # Honour the current overlay-lock state
        if getattr(self, '_viz_overlay_locked', False):
            rect_item.set_interactive(False)

    def _remove_viz_overlay_rect(self):
        """Remove the draggable overlay positioning rect from the stage."""
        if hasattr(self, '_viz_overlay_rect') and self._viz_overlay_rect is not None:
            # Save geometry before removing
            r = self._viz_overlay_rect
            geom = (r.pos().x(), r.pos().y(),
                    r.rect().width(), r.rect().height())
            self._viz_overlay_rect_geom = geom
            # Persist to app settings (absolute + proportional)
            if hasattr(self, 'app_settings'):
                self.app_settings['viz_overlay_rect_geom'] = list(geom)
                view = (getattr(self, '_main_location_view', None)
                        or getattr(self, 'location_view', None))
                if view is not None:
                    _aw = max(1, view.viewport().width() - 40)
                    _ah = max(1, view.viewport().height() - 40)
                    _tr = 16.0 / 9.0
                    if _aw / _ah > _tr:
                        vh = _ah; vw = int(_ah * _tr)
                    else:
                        vw = _aw; vh = int(_aw / _tr)
                    rel = [geom[0] / vw, geom[1] / vh,
                           geom[2] / vw, geom[3] / vh]
                    self.app_settings['viz_overlay_rect_geom_rel'] = rel
                    self._viz_overlay_rect_geom_rel = tuple(rel)
                self._save_app_settings()
            scene = getattr(self, '_main_location_scene', None) or getattr(self, 'location_scene', None)
            if scene:
                try:
                    scene.removeItem(self._viz_overlay_rect)
                except Exception:
                    pass
            self._viz_overlay_rect = None

    def _update_viz_stage_overlay(self, frame: 'QImage'):
        """Paint the visualizer frame inside the draggable overlay box on the Stage Layout.
        
        Updates both the main location scene and any detached LIGHTING PREVIEW windows.
        Always uses the main location_scene reference stored at init time, so that a
        popped-out VISUALIZER window can never redirect the overlay to a different scene.

        Throttled to ~10 fps to avoid saturating the GUI event loop when
        videos play at 30 fps — the visual overlay updates are not
        perceptibly smoother above 10 fps anyway.
        """
        import time as _time
        _now = _time.monotonic()
        _last = getattr(self, '_viz_overlay_last_t', 0.0)
        if (_now - _last) < 0.1:          # 100 ms → ~10 fps cap
            # Still store the raw frame so fixture-colour sampling (which
            # runs on its own timer) always sees the latest frame.
            self._viz_overlay_frame = frame
            return
        self._viz_overlay_last_t = _now

        # Use the master location scene reference.  During tab detach/reattach
        # self.location_scene may momentarily point to a detached scene, so we
        # fall back to the init-time reference stored on first call.
        main_scene = getattr(self, '_main_location_scene', None)
        main_view = getattr(self, '_main_location_view', None)
        if main_scene is None:
            main_scene = getattr(self, 'location_scene', None)
            main_view = getattr(self, 'location_view', None)
            if main_scene is not None:
                self._main_location_scene = main_scene
                self._main_location_view = main_view
        if main_scene is None or main_view is None:
            return

        # Get target rect from the draggable box (main scene only)
        rect_item = getattr(self, '_viz_overlay_rect', None)
        if rect_item is not None:
            # Check if rect was orphaned by scene.clear()
            try:
                import sip as _sip
            except ImportError:
                from PyQt6 import sip as _sip
            if _sip.isdeleted(rect_item) or rect_item.scene() is not main_scene:
                self._viz_overlay_rect = None
                rect_item = None
        if rect_item is None:
            self._ensure_viz_overlay_rect()
            rect_item = getattr(self, '_viz_overlay_rect', None)
            if rect_item is None:
                return

        target_w = max(1, int(rect_item.rect().width()))
        target_h = max(1, int(rect_item.rect().height()))
        target_x = rect_item.pos().x()
        target_y = rect_item.pos().y()

        # Store raw frame + overlay bounds for fixture color sampling
        self._viz_overlay_frame = frame
        self._viz_overlay_bounds = (target_x, target_y, target_w, target_h)

        from PyQt6.QtGui import QPixmap
        from PyQt6.QtCore import Qt as _Qt
        scaled = frame.scaled(target_w, target_h,
                              _Qt.AspectRatioMode.IgnoreAspectRatio,
                              _Qt.TransformationMode.FastTransformation)
        pixmap = QPixmap.fromImage(scaled)

        # --- Update main scene ---
        self._update_overlay_pixmap_on_scene(
            main_scene, pixmap, target_x, target_y,
            '_viz_overlay_item'
        )

        # --- Update detached LIGHTING PREVIEW scenes ---
        # Each detached view may have a different viewport size and therefore
        # different scene-coordinate stage dimensions.  Compute the scale
        # factor between the main stage and each detached stage and rescale
        # the overlay pixmap + position accordingly.
        for idx, view_data in enumerate(getattr(self, '_detached_location_views', [])):
            det_scene = view_data.get('scene')
            det_view = view_data.get('view')
            if det_scene is None:
                continue
            attr_name = f'_viz_overlay_item_detached_{idx}'

            if det_view is not None:
                # Compute this detached view's stage dimensions (same formula
                # as _refresh_location_view / _ensure_viz_overlay_rect).
                _daw = max(600, det_view.viewport().width() - 40)
                _dah = max(400, det_view.viewport().height() - 40)
                _tr = 16.0 / 9.0
                if _daw / _dah > _tr:
                    det_stage_w = int(_dah * _tr)
                    det_stage_h = _dah
                else:
                    det_stage_w = _daw
                    det_stage_h = int(_daw / _tr)

                # Compute main view's stage dimensions for the ratio.
                _maw = max(600, main_view.viewport().width() - 40)
                _mah = max(400, main_view.viewport().height() - 40)
                if _maw / _mah > _tr:
                    main_stage_w = int(_mah * _tr)
                    main_stage_h = _mah
                else:
                    main_stage_w = _maw
                    main_stage_h = int(_maw / _tr)

                sx = det_stage_w / max(1, main_stage_w)
                sy = det_stage_h / max(1, main_stage_h)

                det_w = max(1, int(target_w * sx))
                det_h = max(1, int(target_h * sy))
                det_x = target_x * sx
                det_y = target_y * sy

                det_scaled = frame.scaled(det_w, det_h,
                                          _Qt.AspectRatioMode.IgnoreAspectRatio,
                                          _Qt.TransformationMode.FastTransformation)
                det_pixmap = QPixmap.fromImage(det_scaled)
                self._update_overlay_pixmap_on_scene(
                    det_scene, det_pixmap, det_x, det_y, attr_name
                )
            else:
                # No view reference — fall back to unscaled
                self._update_overlay_pixmap_on_scene(
                    det_scene, pixmap, target_x, target_y, attr_name
                )

    def _update_overlay_pixmap_on_scene(self, scene, pixmap, x, y, attr_name):
        """Add or update a pixmap overlay item on the given QGraphicsScene."""
        from PyQt6.QtWidgets import QGraphicsPixmapItem
        item = getattr(self, attr_name, None)
        needs_create = False
        if item is None:
            needs_create = True
        else:
            # Safety: check the item still belongs to the expected scene.
            # scene.clear() destroys all child items; if the Python wrapper
            # survives (not sip-deleted) the item is orphaned (scene()==None)
            # and setPixmap/setPos would draw nothing.
            try:
                import sip
            except ImportError:
                from PyQt6 import sip
            if sip.isdeleted(item):
                needs_create = True
            elif item.scene() is not scene:
                # Item was removed from the scene (e.g. scene.clear())
                needs_create = True

        if needs_create:
            item = QGraphicsPixmapItem(pixmap)
            item.setPos(x, y)
            item.setZValue(-8)
            overlay_pct = self.app_settings.get('video_overlay_master', 100) / 100.0
            item.setOpacity(overlay_pct * 0.6)
            item.setAcceptedMouseButtons(Qt.MouseButton.NoButton)
            item.setAcceptHoverEvents(False)
            scene.addItem(item)
            setattr(self, attr_name, item)
        else:
            item.setPixmap(pixmap)
            item.setPos(x, y)
            overlay_pct = self.app_settings.get('video_overlay_master', 100) / 100.0
            item.setOpacity(overlay_pct * 0.6)

    def _clear_viz_stage_overlay(self):
        """Remove the visualizer overlay and positioning rect from the Stage Layout."""
        self._viz_overlay_frame = None
        self._viz_overlay_bounds = None
        # Blackout any fixtures that were being driven by the overlay
        prev_driven = getattr(self, '_viz_overlay_active_fixtures', set())
        if prev_driven:
            self._blackout_overlay_fixtures(prev_driven)
            self._viz_overlay_active_fixtures = set()
        # Release effect engine channels so effects can resume control
        self._release_viz_overlay_channels()
        scene = getattr(self, '_main_location_scene', None) or getattr(self, 'location_scene', None)
        for attr in ('_viz_overlay_item', '_viz_overlay_rect'):
            obj = getattr(self, attr, None)
            if obj is not None:
                if scene:
                    try:
                        scene.removeItem(obj)
                    except Exception:
                        pass
                setattr(self, attr, None)
        # Also clean up detached overlay items
        for idx, view_data in enumerate(getattr(self, '_detached_location_views', [])):
            attr_name = f'_viz_overlay_item_detached_{idx}'
            obj = getattr(self, attr_name, None)
            if obj is not None:
                det_scene = view_data.get('scene')
                if det_scene:
                    try:
                        det_scene.removeItem(obj)
                    except Exception:
                        pass
                setattr(self, attr_name, None)

