    def _on_master_changed(self, value: int):
        """Handle master fader change."""
        self.master_label.setText(f"{value}%")
        # Apply master to Art-Net output (0-100 -> 0.0-1.0)
        self.artnet.master_level = value / 100.0
        print(f"[Master] Slider changed to {value}% (master_level={self.artnet.master_level:.2f})")
        
        # Sync to all faders board master sliders
        for slider, label in self._all_faders_board_master_sliders:
            try:
                if slider:
                    slider.blockSignals(True)
                    slider.setValue(value)
                    slider.blockSignals(False)
                if label:
                    label.setText(f"{value}%")
            except RuntimeError:
                pass  # Widget deleted
        
        # Sync to fixtures tab master slider
        if hasattr(self, '_fixtures_tab_master_slider') and self._fixtures_tab_master_slider:
            try:
                self._fixtures_tab_master_slider.blockSignals(True)
                self._fixtures_tab_master_slider.setValue(value)
                self._fixtures_tab_master_slider.blockSignals(False)
                if hasattr(self._fixtures_tab_master_slider, '_value_label'):
                    self._fixtures_tab_master_slider._value_label.setText(f"{value}%")
            except RuntimeError:
                pass  # Widget deleted

        # Re-trigger active group faders so their pre-computed DMX reflects the new master cap
        self._refresh_active_group_faders()
        
        # Send motorized fader feedback (only if not triggered by MIDI input)
        if not getattr(self, '_updating_from_midi', False):
            self._send_fader_feedback("master", value, max_val=100)
    
    def _on_effect_speed_changed(self, value: int):
        """Handle effect speed fader change."""
        # Convert slider value (25-300) to multiplier (0.25x - 3.0x)
        multiplier = value / 100.0
        self.effect_speed_label.setText(f"{multiplier:.2f}x")
        # Apply to effect engine
        self.effect_engine.global_speed_multiplier = multiplier
        
        # Sync to all faders board speed sliders
        for slider, label in self._all_faders_board_speed_sliders:
            try:
                if slider:
                    slider.blockSignals(True)
                    slider.setValue(value)
                    slider.blockSignals(False)
                if label:
                    label.setText(f"{multiplier:.1f}x")
            except RuntimeError:
                pass  # Widget deleted
        
        # Send motorized fader feedback (only if not triggered by MIDI input)
        if not getattr(self, '_updating_from_midi', False):
            self._send_fader_feedback("effect_speed", value, max_val=400)

    def _get_video_volume_multiplier(self) -> float:
        """Return the global video audio multiplier from the Live Output slider."""
        if hasattr(self, 'video_volume_slider') and self.video_volume_slider:
            return self.video_volume_slider.value() / 100.0
        return 1.0

    def _apply_visualizer_audio_volume(self, fader_level: float | None = None):
        """Apply the combined fader/global/per-item audio volume to the visualizer audio player."""
        engine = getattr(self, '_viz_engine', None)
        if not engine or not getattr(engine, '_audio_player', None):
            return

        if fader_level is None:
            fader_level = getattr(engine, '_fader_level', 1.0)

        # Per-item volume stored on VisualizerItem (0-100, default 100)
        active_item = getattr(engine, '_active_item', None)
        item_volume = getattr(active_item, 'volume', 100) / 100.0 if active_item else 1.0

        effective_volume = max(0.0, min(1.0,
            fader_level * self._get_video_volume_multiplier() * item_volume))
        engine._audio_player.set_volume(effective_volume)

    def _on_video_volume_changed(self, value: int):
        """Handle global video volume changes."""
        self.video_volume_label.setText(f"{value}%")
        self.app_settings['video_volume'] = value
        self._apply_visualizer_audio_volume()

        if not getattr(self, '_updating_from_midi', False):
            self._send_fader_feedback("video_volume", value, max_val=100)

    def _on_video_overlay_master_changed(self, value: int):
        """Handle Video Overlay Master slider changes.
        
        Scales the video overlay brightness sent to fixtures (0=black, 100=full).
        """
        self.video_overlay_label.setText(f"{value}%")
        self.app_settings['video_overlay_master'] = value
        self._save_app_settings()

        # Also update the overlay pixmap opacity for the stage preview
        opacity = value / 100.0 * 0.6  # Scale within 0..0.6 range
        overlay_item = getattr(self, '_viz_overlay_item', None)
        if overlay_item is not None:
            try:
                overlay_item.setOpacity(opacity)
            except RuntimeError:
                pass
        # Update detached preview overlays too
        for idx in range(len(getattr(self, '_detached_location_views', []))):
            det_item = getattr(self, f'_viz_overlay_item_detached_{idx}', None)
            if det_item is not None:
                try:
                    det_item.setOpacity(opacity)
                except RuntimeError:
                    pass

        if not getattr(self, '_updating_from_midi', False):
            self._send_fader_feedback("video_overlay_master", value, max_val=100)
    
    def _set_effect_speed(self, value: int):
        """Set effect speed from quick preset button."""
        self.effect_speed_slider.setValue(value)
    
    def _on_midi_master_fader(self, midi_value: int, max_value: int = 127):
        """Handle MIDI fader input for master.
        
        Args:
            midi_value: The raw MIDI value, or direction (-1, 1) for encoders
            max_value: Maximum value (127 for CC, 16383 for pitch bend, 0 for encoder)
        """
        if max_value == 0:
            # Encoder mode: midi_value is direction (-1 or 1)
            # Step by 5% per click
            step = 5
            current = self.master_slider.value()
            slider_value = max(0, min(100, current + (midi_value * step)))
            print(f"[MIDI] Master encoder: direction={midi_value}, current={current} -> {slider_value}")
        else:
            # Absolute mode: Map MIDI value to slider 0-100
            slider_value = int(midi_value * 100 / max_value)
        
        # Block feedback while updating from MIDI
        self._updating_from_midi = True
        try:
            self.master_slider.setValue(slider_value)
        finally:
            self._updating_from_midi = False

    def _on_midi_video_volume_fader(self, midi_value: int, max_value: int = 127):
        """Handle MIDI fader input for global video volume."""
        if max_value == 0:
            step = 5
            current = self.video_volume_slider.value()
            slider_value = max(0, min(100, current + (midi_value * step)))
            print(f"[MIDI] Video volume encoder: direction={midi_value}, current={current} -> {slider_value}")
        else:
            slider_value = int(midi_value * 100 / max_value)

        self._updating_from_midi = True
        try:
            self.video_volume_slider.setValue(slider_value)
        finally:
            self._updating_from_midi = False

    def _on_midi_video_overlay_fader(self, midi_value: int, max_value: int = 127):
        """Handle MIDI fader input for Video Overlay Master."""
        if max_value == 0:
            step = 5
            current = self.video_overlay_slider.value()
            slider_value = max(0, min(100, current + (midi_value * step)))
        else:
            slider_value = int(midi_value * 100 / max_value)

        self._updating_from_midi = True
        try:
            self.video_overlay_slider.setValue(slider_value)
        finally:
            self._updating_from_midi = False
    
    def _on_midi_speed_fader(self, midi_value: int, max_value: int = 127):
        """Handle MIDI fader input for effect speed.
        
        Args:
            midi_value: The raw MIDI value, or direction (-1, 1) for encoders
            max_value: Maximum value (127 for CC, 16383 for pitch bend, 0 for encoder)
        """
        slider_min = self.effect_speed_slider.minimum()
        slider_max = self.effect_speed_slider.maximum()
        
        if max_value == 0:
            # Encoder mode: midi_value is the direction (-1 or 1) from the encoder note mapping
            direction = midi_value  # This is +1 or -1 based on which note was pressed
            
            step = max(1, (slider_max - slider_min) // 20)
            current = self.effect_speed_slider.value()
            slider_value = max(slider_min, min(slider_max, current + (direction * step)))
            print(f"[MIDI] Speed encoder: dir={direction}, step={step}, current={current} -> {slider_value}")
        else:
            # Absolute mode: Map MIDI value to slider 10-300 (0.1x to 3.0x)
            slider_value = int(slider_min + (midi_value / max_value) * (slider_max - slider_min))
        
        self._updating_from_midi = True
        try:
            self.effect_speed_slider.setValue(slider_value)
        finally:
            self._updating_from_midi = False
    
    def _show_fader_execution_assignment_dialog(self, fader_id: str, fader_name: str):
        """Show dialog to assign a fader to an execution button."""
        dialog = QDialog(self._get_active_window())
        dialog.setWindowTitle(f"Assign {fader_name} to Execution")
        dialog.setMinimumWidth(400)
        dialog.setMinimumHeight(300)
        dialog.setStyleSheet(DARK_STYLESHEET)
        
        layout = QVBoxLayout(dialog)
        layout.setSpacing(12)
        
        label = QLabel("Select an execution button to control with this fader:")
        label.setWordWrap(True)
        layout.addWidget(label)
        
        info_label = QLabel("The fader will start the effect when moved above 0 and control dimmer/shutter intensity.")
        info_label.setStyleSheet("color: #888; font-size: 11px;")
        info_label.setWordWrap(True)
        layout.addWidget(info_label)
        
        # List widget for presets
        preset_list = QListWidget()
        preset_list.setStyleSheet("""
            QListWidget {
                background: #2d2d2d;
                border: 1px solid #555;
                padding: 4px;
            }
            QListWidget::item {
                padding: 8px;
                border-radius: 3px;
            }
            QListWidget::item:hover {
                background: #3d3d3d;
            }
            QListWidget::item:selected {
                background: #c97a50;
            }
        """)
        
        # Add OFF button
        off_item = QListWidgetItem("⬛ OFF")
        off_item.setData(Qt.ItemDataRole.UserRole, "__OFF__")
        preset_list.addItem(off_item)
        
        # Add all presets (sorted alphabetically by name)
        sorted_presets = sorted(self.project.presets, key=lambda p: p.name.lower())
        for preset in sorted_presets:
            item = QListWidgetItem(f"⚡ {preset.name}")
            item.setData(Qt.ItemDataRole.UserRole, preset.id)
            preset_list.addItem(item)
        
        layout.addWidget(preset_list)
        
        # Buttons
        btn_layout = QHBoxLayout()
        cancel_btn = QPushButton("Cancel")
        cancel_btn.clicked.connect(dialog.reject)
        assign_btn = QPushButton("Assign")
        assign_btn.setDefault(True)
        assign_btn.clicked.connect(dialog.accept)
        btn_layout.addWidget(cancel_btn)
        btn_layout.addWidget(assign_btn)
        layout.addLayout(btn_layout)
        
        if dialog.exec() == QDialog.DialogCode.Accepted:
            selected_items = preset_list.selectedItems()
            if selected_items:
                preset_id = selected_items[0].data(Qt.ItemDataRole.UserRole)
                self._assign_fader_to_execution(fader_id, preset_id)
    
    def _assign_fader_to_execution(self, fader_id: str, preset_id: str):
        """Assign a fader to control an execution button."""
        if 'fader_execution_assignments' not in self.app_settings:
            self.app_settings['fader_execution_assignments'] = {}
        
        self.app_settings['fader_execution_assignments'][fader_id] = preset_id
        self._save_app_settings()
        
        # Get preset name for display
        fader_num = int(fader_id.split("_")[1]) - 1
        preset_name = "OFF" if preset_id == "__OFF__" else None
        for preset in self.project.presets:
            if preset.id == preset_id:
                preset_name = preset.name
                break
        
        # Update fader styling to show it's assigned (orange glow on slider)
        if fader_num < len(self.prog_faders):
            slider = self.prog_faders[fader_num]
            slider.setStyleSheet("""
                QSlider::groove:horizontal { height: 6px; background: #2a2a2a; border-radius: 3px; }
                QSlider::handle:horizontal { width: 14px; background: #ff8844; border-radius: 7px; margin: -4px 0; }
                QSlider::sub-page:horizontal { background: #c97a50; border-radius: 3px; }
            """)
            slider.setToolTip(f"⚡ Controls: {preset_name}")
        
        print(f"[Fader Execute] Assigned {fader_id} to preset: {preset_name}")
        
        # Initialize tracking for this fader
        if not hasattr(self, '_fader_exec_states'):
            self._fader_exec_states = {}
        self._fader_exec_states[fader_id] = {'active': False, 'last_value': 0, 'preset_id': preset_id}
    
    def _clear_fader_execution_assignment(self, fader_id: str):
        """Clear execution assignment for a fader."""
        exec_assignments = self.app_settings.get('fader_execution_assignments', {})
        if fader_id in exec_assignments:
            del exec_assignments[fader_id]
            self._save_app_settings()
            
            # Reset fader styling
            fader_num = int(fader_id.split("_")[1]) - 1
            if fader_num < len(self.prog_faders):
                slider = self.prog_faders[fader_num]
                slider.setStyleSheet("""
                    QSlider::groove:horizontal { height: 6px; background: #2a2a2a; border-radius: 3px; }
                    QSlider::handle:horizontal { width: 14px; background: #c97a50; border-radius: 7px; margin: -4px 0; }
                    QSlider::sub-page:horizontal { background: #4a4a4a; border-radius: 3px; }
                """)
                slider.setToolTip("")
            
            print(f"[Fader Execute] Cleared assignment for {fader_id}")
    
    def _clear_fader_position_assignment(self, fader_id: str):
        """Clear position assignment for a fader."""
        pos_assignments = self.app_settings.get('fader_position_assignments', {})
        if fader_id in pos_assignments:
            del pos_assignments[fader_id]
            self._save_app_settings()
            
            # Clean up position fader state
            if hasattr(self, '_position_fader_states') and fader_id in self._position_fader_states:
                del self._position_fader_states[fader_id]
            
            # Reset fader styling
            try:
                fader_num = int(fader_id.split("_")[1]) - 1
                if fader_num < len(self.prog_faders):
                    slider = self.prog_faders[fader_num]
                    slider.setStyleSheet("""
                        QSlider::groove:horizontal { height: 6px; background: #2a2a2a; border-radius: 3px; }
                        QSlider::handle:horizontal { width: 14px; background: #c97a50; border-radius: 7px; margin: -4px 0; }
                        QSlider::sub-page:horizontal { background: #4a4a4a; border-radius: 3px; }
                    """)
                    slider.setToolTip("")
            except (ValueError, IndexError):
                pass
            
            # Refresh the faders tab display if open
            if hasattr(self, 'faders_layout') and self.faders_layout is not None:
                try:
                    self._populate_faders_layout(self.faders_layout, is_main=True)
                except RuntimeError:
                    pass
            
            print(f"[Position Fader] Cleared position assignment for {fader_id}")
    
    def _fader_page_prev(self):
        """Go to previous fader page."""
        if self._fader_page > 0:
            self._fader_page -= 1
            self._update_fader_page_visibility()
    
    def _fader_page_next(self):
        """Go to next fader page."""
        max_page = (self._total_faders - 1) // self._faders_per_page
        if self._fader_page < max_page:
            self._fader_page += 1
            self._update_fader_page_visibility()
    
    def _update_fader_page_visibility(self):
        """Update which faders are visible based on current page."""
        start_idx = self._fader_page * self._faders_per_page
        end_idx = start_idx + self._faders_per_page
        
        for i, container in enumerate(self.prog_fader_containers):
            visible = start_idx <= i < end_idx
            container.setVisible(visible)
        
        # Update page label
        start_num = start_idx + 1
        end_num = min(end_idx, self._total_faders)
        self.fader_page_label.setText(f"{start_num}-{end_num}")
        
        # Update button states
        self.fader_prev_btn.setEnabled(self._fader_page > 0)
        max_page = (self._total_faders - 1) // self._faders_per_page
        self.fader_next_btn.setEnabled(self._fader_page < max_page)
        
        # Send MIDI feedback for all faders now visible on this page
        # This moves motorized faders to match the new page's fader positions
        for i in range(start_idx, min(end_idx, len(self.prog_faders))):
            fader_id = f"fader_{i + 1}"
            value = self.prog_faders[i].value()
            self._send_fader_feedback(fader_id, value, max_val=100)

        # Update V1-M meters for the new page
        midi_mgr = get_midi_manager()
        if midi_mgr.has_v1m_connection:
            for slot in range(min(8, len(self.prog_faders) - start_idx)):
                pct = self.prog_faders[start_idx + slot].value()
                midi_mgr.send_v1m_meter(slot, int(pct * 12 / 100))

    def _on_prog_fader_changed(self, fader_id: str, value: int):
        """Handle programmable fader change."""
        # Update value label
        fader_num = int(fader_id.split("_")[1]) - 1  # 0-indexed
        self.prog_fader_labels[fader_num].setText(str(value))
        
        # Send motorized fader feedback (only if not triggered by MIDI input)
        # This prevents motor jiggling during manual fader movement
        if not getattr(self, '_updating_from_midi', False):
            self._send_fader_feedback(fader_id, value, max_val=100)
        
        # Update V1-M scribble strip / LCD for this fader
        slot_idx = fader_num - getattr(self, '_fader_page', 0) * 8
        if 0 <= slot_idx < 8 and hasattr(self, 'prog_faders') and fader_num < len(self.prog_faders):
            self._update_v1m_fader_display(slot_idx, self.prog_faders[fader_num])
        
        # Sync to large faders tab if they are linked to this fader
        if not getattr(self, '_syncing_fader', False):
            self._sync_large_fader_from_prog(fader_id, fader_num, value)
        
        # Check if fader is assigned to an execution button
        exec_assignments = self.app_settings.get('fader_execution_assignments', {})
        assigned_preset_id = exec_assignments.get(fader_id)
        
        # Check if fader is assigned to positions
        pos_assignments = self.app_settings.get('fader_position_assignments', {})
        assigned_positions = pos_assignments.get(fader_id)
        
        # Check if fader is assigned to a visualizer item
        viz_assignments = self.app_settings.get('fader_visualizer_assignments', {})
        assigned_viz = viz_assignments.get(fader_id)
        
        # Debug: show if fader has assignment
        if value % 10 == 0 or value == 0:  # Only log at key positions to reduce spam
            if assigned_preset_id:
                print(f"[Fader] {fader_id}={value}% -> Assigned to preset: {assigned_preset_id}")
            elif assigned_positions:
                print(f"[Fader] {fader_id}={value}% -> Assigned to {len(assigned_positions)} positions")
            elif assigned_viz:
                print(f"[Fader] {fader_id}={value}% -> Assigned to visualizer: {assigned_viz}")
            else:
                print(f"[Fader] {fader_id}={value}% -> NOT ASSIGNED (right-click to assign)")
        
        if assigned_positions:
            self._handle_position_fader(fader_id, assigned_positions, value)
        elif assigned_viz:
            self._handle_visualizer_fader(fader_id, assigned_viz, value)
        elif assigned_preset_id:
            self._handle_fader_execution_control(fader_id, assigned_preset_id, value)
    
    def _sync_large_fader_from_prog(self, fader_id: str, fader_idx: int, value: int):
        """Sync large faders tab when prog_fader changes."""
        if fader_id in self._all_fader_sliders:
            self._syncing_fader = True
            try:
                valid_sliders = []
                for slider in self._all_fader_sliders[fader_id]:
                    try:
                        if slider.value() != value:
                            slider.blockSignals(True)
                            slider.setValue(value)
                            slider.blockSignals(False)
                        valid_sliders.append(slider)
                    except RuntimeError:
                        pass  # Slider deleted
                
                if valid_sliders:
                    self._all_fader_sliders[fader_id] = valid_sliders
                else:
                    del self._all_fader_sliders[fader_id]
            finally:
                self._syncing_fader = False

    def _handle_fader_execution_control(self, fader_id: str, preset_id: str, value: int):
        """Handle fader-based execution control with HTP blending.
        
        Multiple effects can run simultaneously. Their outputs are merged using:
        - HTP (Highest Takes Precedence) for intensity/dimmer channels
        - Highest fader level wins for discrete channels (gobo, color wheel, position)
        
        Args:
            fader_id: The fader ID
            preset_id: The assigned preset ID
            value: Fader position (0-100)
        """
        # ── Cue list fader: fader controls master level of current cue ──
        if preset_id.startswith("cuelist:"):
            cuelist_id = preset_id.split(":", 1)[1]
            self._handle_cuelist_fader(fader_id, cuelist_id, value)
            return

        # Release overlay channel claims when a fader starts driving an effect
        if value > 2:
            self._release_overlay_claims_for_effect()

        import time
        
        # Check if this fader is in cooldown (just moved to 0 by auto-crossfade)
        # During cooldown, we still process the fader value but DON'T trigger auto-crossfade
        in_cooldown = False
        if fader_id in self._fader_cooldown:
            cooldown_time = self._fader_cooldown[fader_id]
            elapsed = time.time() - cooldown_time
            if elapsed < 0.3:  # 300ms cooldown
                in_cooldown = True
            else:
                # Cooldown expired
                del self._fader_cooldown[fader_id]
        
        # Initialize state tracking if needed
        if not hasattr(self, '_fader_exec_states'):
            self._fader_exec_states = {}
        if fader_id not in self._fader_exec_states:
            self._fader_exec_states[fader_id] = {'active': False, 'last_value': 0, 'preset_id': preset_id}
        
        state = self._fader_exec_states[fader_id]
        threshold = 2  # Start effect when fader moves above 2%
        fader_level = value / 100.0  # Convert to 0.0-1.0
        
        # Handle OFF button specially
        if preset_id == "__OFF__":
            if value > threshold and not state['active']:
                # OFF fader raised - stop all effects
                print(f"[Fader Execute] {fader_id} OFF raised - stopping all effects")
                self.effect_engine._execute_mode = False
                self.effect_engine.stop_effect(blackout=True, send_home=False)
                self._current_effect = None
                state['active'] = True
            elif value <= threshold and state['active']:
                state['active'] = False
            state['last_value'] = value
            return
        
        # Find the preset
        preset = None
        for p in self.project.presets:
            if p.id == preset_id:
                preset = p
                break
        
        if not preset:
            return
        
        # Check if another fader's effect is currently active
        # Skip override faders — they coexist independently and should not
        # trigger auto-crossfade logic on normal faders.
        another_effect_active = False
        active_other_fader = None
        prog_overrides = self.app_settings.get('prog_fader_overrides', {})
        is_override = prog_overrides.get(fader_id, False)
        if is_override:
            print(f"[Override] {fader_id} detected as OVERRIDE fader (value={value})")
        elif value > threshold:
            print(f"[Fader] {fader_id} is a NORMAL fader (value={value})")
        for other_fader_id, other_state in self._fader_exec_states.items():
            if other_fader_id != fader_id and other_state['active'] and other_state['preset_id'] != "__OFF__":
                # Skip override faders — they don't count as "another_effect_active"
                if prog_overrides.get(other_fader_id, False):
                    continue
                another_effect_active = True
                active_other_fader = other_fader_id
                break
        
        # Detect significant movement on this fader (snap threshold)
        last_value = state.get('last_value', 0)
        significant_movement = abs(value - last_value) >= 5  # 5% change is significant
        
        # Start/snap to effect when:
        # 1. Fader crosses threshold from below (normal case), OR
        # 2. Another effect is active AND this fader moved significantly AND is above threshold
        #    (but NOT for override faders that are already running — they just update level)
        should_start_effect = (
            (value > threshold and not state['active']) or
            (value > threshold and another_effect_active and significant_movement and not in_cooldown
             and not (is_override and state['active']))
        )
        
        if should_start_effect:
            # Fire assigned OSC/MIDI shortcut on fader rise
            self._fire_fader_shortcut_if_assigned(fader_id, 'rise')
            
            if is_override:
                # ── Override fader: run full effect dispatch on dedicated thread ──
                effect = self._build_effect_from_preset(preset)
                print(f"[Override Fader] {fader_id} starting override effect: {preset.name} at {value}%")
                
                fader_modes = self.app_settings.get('fader_modes', {})
                fader_mode = fader_modes.get(fader_id, 'fade')
                
                override_fader_level = 1.0 if fader_mode == 'speed' else fader_level
                
                # Mark execute mode so the overlay yields to the effect
                self.effect_engine._execute_mode = True
                # Start dedicated override effect loop (full dispatch, separate thread)
                # start_override_effect() also registers fixtures as overridden so the
                # main effect loop and HTP merge skip them (prevents flashing).
                self.effect_engine.start_override_effect(fader_id, effect, override_fader_level)
                
                # NOTE: Override faders must NOT change the global speed slider — that
                # would alter the main effect's speed.  The override loop already
                # reads global_speed_multiplier like any other loop, so leaving
                # the slider alone means the override runs at whatever global
                # speed is currently set (typically 1.0x).
                
                # Don't overwrite _active_execute_preset_id — that tracks the main effect.
                state['active'] = True
            elif not is_override:
                # ── Normal fader: auto-crossfade, replaces current effect ──
                # Safety guard: double-check this is NOT an override fader.
                # If somehow is_override was wrong above, we must NOT auto-crossfade.
                # SKIP auto-crossfade if this fader is in cooldown (prevents feedback loop)
                if not in_cooldown:
                    print(f"[AutoCrossfade] {fader_id} starting, stopping other faders")
                    
                    # Stop other fader execution presets (skip override faders)
                    for other_fader_id, other_state in self._fader_exec_states.items():
                        if other_fader_id != fader_id and other_state['active'] and other_state['preset_id'] != "__OFF__":
                            # Skip override faders - they coexist with other effects
                            if prog_overrides.get(other_fader_id, False):
                                continue
                            other_preset_id = other_state['preset_id']
                            self.effect_engine.stop_effect(blackout=False, send_home=False)
                            self._current_effect = None
                            other_state['active'] = False
                            
                            # Update GUI slider to 0 (prevents value mismatch)
                            try:
                                other_fader_num = int(other_fader_id.split("_")[1]) - 1
                                if 0 <= other_fader_num < len(self.prog_faders):
                                    self._updating_from_midi = True
                                    self.prog_faders[other_fader_num].setValue(0)
                                    self._updating_from_midi = False
                                    
                                    # Also update in _all_fader_sliders (for detached windows)
                                    if other_fader_id in self._all_fader_sliders:
                                        for slider in self._all_fader_sliders[other_fader_id]:
                                            try:
                                                slider.blockSignals(True)
                                                slider.setValue(0)
                                                slider.blockSignals(False)
                                            except RuntimeError:
                                                pass
                            except (ValueError, IndexError):
                                pass
                            
                            # Set cooldown to ignore auto-crossfade while motor moves to 0
                            import time
                            self._fader_cooldown[other_fader_id] = time.time()
                            
                            # Move the motorized fader to 0 (regular mapping)
                            self._send_fader_feedback(other_fader_id, 0, max_val=100)
                            
                            # Also send dynamic MIDI feedback if enabled
                            self._send_dynamic_midi_feedback_for_fader(other_fader_id, 0)
                    
                    # Also stop MIDI-mapped presets (from other state tracking)
                    if hasattr(self, '_midi_fader_states'):
                        for other_midi_key, other_midi_state in self._midi_fader_states.items():
                            if other_midi_state['active'] and other_midi_state['preset_id'] != "__OFF__":
                                other_preset_id = other_midi_state['preset_id']
                                self.effect_engine.stop_effect(blackout=False, send_home=False)
                                other_midi_state['active'] = False
                                
                                # Send MIDI feedback to move fader to 0
                                midi_mgr = get_midi_manager()
                                if midi_mgr and midi_mgr.is_connected:
                                    midi_mgr.send_fader_feedback(other_midi_key, 0)
                
                # Mark this fader active BEFORE stopping the default look so
                # that any 'stopped' callbacks see a non-zero fader and don't
                # schedule a spurious default-look restore.
                state['active'] = True

                # ── Stop the default look so it doesn't fight ──
                self._stop_default_look_if_active()

                # ── Check if preset has layers (dimmer layers, etc.) ──
                layers_data = getattr(preset, 'layers', None) or []
                if layers_data:
                    # Layered preset — use HTP multi-effect engine (same as _execute_preset)
                    print(f"[Fader Execute] {fader_id} starting layered preset: {preset.name} ({len(layers_data)} layers) at {value}%")
                    engine = getattr(self, 'effect_engine', None)
                    if engine:
                        # Get fader mode
                        fader_modes = self.app_settings.get('fader_modes', {})
                        fader_mode = fader_modes.get(fader_id, 'fade')
                        
                        # HTP merge loop scales via active.fader_level, so keep
                        # engine._fader_level at 1.0 to avoid double-scaling in
                        # the buffer methods (_buffer_static etc.). Pass the
                        # actual fader level to each start_effect_htp call.
                        htp_fader_level = 1.0 if fader_mode == 'speed' else fader_level
                        engine._fader_level = 1.0
                        
                        engine._execute_mode = True
                        engine.stop_all_effects_htp()
                        for ld in layers_data:
                            try:
                                layer = EffectLayer.from_dict(ld)
                                if layer.enabled:
                                    params = layer.to_effect_params()
                                    engine.start_effect_htp(layer.id, params, fader_level=htp_fader_level)
                            except Exception as exc:
                                print(f"[Fader Execute] Layer error: {exc}")
                        
                        print(f"[Fader Execute] HTP fader level set to {htp_fader_level:.2f} (mode={fader_mode})")
                else:
                    # Flat (non-layered) preset — original single-effect path
                    # Build effect parameters from preset
                    effect = self._build_effect_from_preset(preset)
                    print(f"[Fader Execute] {fader_id} starting effect: {preset.name} at {value}%, type={effect.effect_type}, color={effect.color}, targets={effect.target_groups}")
                    
                    # Get fader mode: 'fade' (default), 'speed', or 'fade_and_speed'
                    fader_modes = self.app_settings.get('fader_modes', {})
                    fader_mode = fader_modes.get(fader_id, 'fade')
                    
                    # Set fader level based on mode
                    if fader_mode == 'speed':
                        self.effect_engine._fader_level = 1.0
                    else:
                        self.effect_engine._fader_level = fader_level
                    
                    # Set initial speed if mode includes speed control
                    if fader_mode in ('speed', 'fade_and_speed'):
                        min_speed = self.effect_speed_slider.minimum()
                        # Map fader 100% → 1.0x so the preset runs at its saved speed
                        target_max_speed = 100  # 1.0x multiplier
                        speed_value = int(min_speed + (value / 100.0) * (target_max_speed - min_speed))
                        self.effect_speed_slider.setValue(speed_value)
                        print(f"[Fader Execute] Initial speed set to {speed_value/100:.2f}x (mode={fader_mode})")
                    
                    self._current_effect = effect
                    # Mark execute mode so the overlay yields to the effect
                    self.effect_engine._execute_mode = True
                    self.effect_engine.start_effect(effect)
                    
                    # Re-apply fader level AFTER start_effect to ensure thread sees it
                    if fader_mode == 'speed':
                        self.effect_engine._fader_level = 1.0
                    else:
                        self.effect_engine._fader_level = fader_level
                    print(f"[Fader Execute] Fader level confirmed at {self.effect_engine._fader_level:.2f} (mode={fader_mode})")
                
                self._active_execute_preset_id = preset_id
                # state['active'] already set True above (before stop_default_look)
                
                # Update execute button selection
                self._update_execute_button_selection(preset_id)
            
        elif value <= threshold and state['active']:
            # Fader dropped - stop effect
            # Fire assigned OSC/MIDI shortcut on fader off
            self._fire_fader_shortcut_if_assigned(fader_id, 'off')
            
            prog_overrides = self.app_settings.get('prog_fader_overrides', {})
            is_override = prog_overrides.get(fader_id, False)
            
            if is_override:
                # Override fader: stop its dedicated effect loop, leave others running
                print(f"[Override Fader] {fader_id} stopping override effect: {preset.name}")
                if hasattr(self, 'effect_engine') and self.effect_engine:
                    # Get the fixture IDs this override actually CLAIMED before stopping
                    claimed_ids = [
                        fid for fid, owner in self.effect_engine._override_fixtures.items()
                        if owner == fader_id
                    ]
                    self.effect_engine.stop_override_effect(fader_id)
                    # Only blackout the override's fixtures if no main effect is
                    # still running — when a main effect IS running, it will
                    # immediately resume rendering those fixtures on the next
                    # frame, so a blackout would just cause a visible flash.
                    main_running = (self.effect_engine._running
                                    and self.effect_engine._current_effect is not None)
                    if claimed_ids and not main_running:
                        override_fixtures = [f for f in self.project.fixtures if f.id in claimed_ids]
                        if override_fixtures:
                            self.effect_engine._blackout_fixtures(override_fixtures)
            else:
                # Normal fader: stop all and blackout
                print(f"[Fader Execute] {fader_id} stopping effect: {preset.name}")
                self.effect_engine._execute_mode = False
                self.effect_engine.stop_effect(blackout=True, send_home=False)
                # Also stop HTP layer effects (for layered presets)
                if hasattr(self.effect_engine, 'stop_all_effects_htp'):
                    self.effect_engine.stop_all_effects_htp()
            
            state['active'] = False
            
            if not is_override:
                # Only reset main-effect state for normal faders
                self.effect_engine._fader_level = 1.0  # Reset fader level
                self._current_effect = None
                self._active_execute_preset_id = None
            
            # Check if ALL faders are at 0 before going home
            if self._all_faders_at_zero():
                print("[Home] Sending fixtures to home positions")
                self.effect_engine._send_to_home_positions()
                # Restore default look if configured
                self._maybe_restore_default_look()
            
            # Reset effect speed if mode includes speed control (but NOT for override faders
            # — they must not touch the global speed that the main effect is using)
            if not is_override:
                fader_modes = self.app_settings.get('fader_modes', {})
                fader_mode = fader_modes.get(fader_id, 'fade')
                if fader_mode in ('speed', 'fade_and_speed'):
                    # Reset speed to 1.0x (100 on slider which is 25-400 range)
                    self.effect_speed_slider.setValue(100)
        
        # Update fader level for running effect
        elif state['active'] and value > threshold:
            # Get fader mode
            fader_modes = self.app_settings.get('fader_modes', {})
            fader_mode = fader_modes.get(fader_id, 'fade')
            
            # Check if this is an override fader
            prog_overrides = self.app_settings.get('prog_fader_overrides', {})
            is_override = prog_overrides.get(fader_id, False)
            
            if is_override:
                # Override fader: update its dedicated fader level
                override_fader_level = 1.0 if fader_mode == 'speed' else fader_level
                self.effect_engine.set_override_fader_level(fader_id, override_fader_level)
            else:
                target_level = 1.0 if fader_mode == 'speed' else fader_level
                # HTP layered effects: update via active.fader_level (merge
                # loop applies it each frame).  Keep _fader_level at 1.0 so
                # buffer methods don't double-scale with the merge multiplier.
                if self.effect_engine._active_effects:
                    for eid in list(self.effect_engine._active_effects.keys()):
                        self.effect_engine.set_effect_fader_level(eid, target_level)
                else:
                    # Old-API flat effects: update _fader_level (monitored by
                    # the static fader thread / effect loop).
                    self.effect_engine._fader_level = target_level
            
            # Update speed if mode includes speed control
            # Override faders must NOT change the global speed slider — it would
            # alter the main effect's speed.
            if not is_override and fader_mode in ('speed', 'fade_and_speed'):
                min_speed = self.effect_speed_slider.minimum()  # 25
                # Map fader 100% → 1.0x so the preset runs at its saved speed
                target_max_speed = 100  # 1.0x multiplier
                speed_value = int(min_speed + (value / 100.0) * (target_max_speed - min_speed))
                self.effect_speed_slider.setValue(speed_value)
            # Reduce log spam - only log at 10% intervals
            # (Frequent logging while moving fader can cause jitter)
        
        state['last_value'] = value
    
    # ── Visualizer fader control ──

    def _handle_visualizer_fader(self, fader_id: str, viz_item_id: str, value: int):
        """Handle a fader assigned to a visualizer item.

        When the fader rises above a small threshold the visualizer item starts
        playing.  The fader level (0-100 %) is forwarded to the engine as a
        brightness multiplier so the video / effect fades up smoothly with the
        fader.  Dropping the fader to 0 stops playback.
        """
        threshold = 2
        fader_level = value / 100.0

        if not hasattr(self, '_viz_fader_states'):
            self._viz_fader_states = {}
        if fader_id not in self._viz_fader_states:
            self._viz_fader_states[fader_id] = {'active': False, 'item_id': viz_item_id}

        state = self._viz_fader_states[fader_id]

        if value > threshold and not state['active']:
            # ── Crossfade: bring down any other active visualizer fader ──
            self._crossfade_down_other_viz_faders(fader_id)

            # Fader raised — start playing the assigned visualizer item
            viz_item = self._find_viz_item(viz_item_id)
            if viz_item is None:
                print(f"[Visualizer Fader] {fader_id}: item {viz_item_id} not found")
                return

            # Ensure engine exists
            try:
                from .visualizer_tab import _play_item
            except ImportError:
                from visualizer_tab import _play_item

            # Fader-triggered videos: only honour 'repeat' mode (loop).
            # Never use continuous mode — fader videos play once then stop,
            # unless the user explicitly set repeat mode.
            mode = getattr(self, '_viz_playback_mode', 'stop')
            viz_item.loop = (mode == 'repeat')

            # Set initial brightness level BEFORE play so first frames are dimmed
            engine = getattr(self, '_viz_engine', None)
            if engine:
                engine._fader_level = fader_level

            _play_item(self, viz_item)

            # Set initial audio volume using both the fader and global video volume.
            self._apply_visualizer_audio_volume(fader_level)

            state['active'] = True
            print(f"[Visualizer Fader] {fader_id} started: {viz_item.name} at {value}%")

        elif value <= threshold and state['active']:
            # Fader dropped — stop visualizer playback
            self._stop_visualizer_fader(fader_id)
            state['active'] = False
            print(f"[Visualizer Fader] {fader_id} stopped")

        elif state['active'] and value > threshold:
            # Fader moving while active — update brightness level and audio volume
            engine = getattr(self, '_viz_engine', None)
            if engine:
                engine._fader_level = fader_level
                # Fade audio volume with the fader
                self._apply_visualizer_audio_volume(fader_level)

    def _crossfade_down_other_viz_faders(self, active_fader_id: str):
        """Bring all other active visualizer faders to 0 so only one video plays."""
        if not hasattr(self, '_viz_fader_states'):
            return
        for other_id, other_state in list(self._viz_fader_states.items()):
            if other_id == active_fader_id or not other_state.get('active'):
                continue
            # Stop playback for the displaced fader
            self._stop_visualizer_fader(other_id)
            other_state['active'] = False
            # Bring the physical slider(s) to 0
            self._set_fader_to_zero(other_id)
            print(f"[Visualizer Fader] {other_id} crossfaded down (displaced by {active_fader_id})")

    def _set_fader_to_zero(self, fader_id: str):
        """Programmatically set a fader's slider(s) to 0 and update its label."""
        # Update all slider instances (main + detached windows)
        if fader_id in self._all_fader_sliders:
            for slider in list(self._all_fader_sliders[fader_id]):
                try:
                    slider.blockSignals(True)
                    slider.setValue(0)
                    slider.blockSignals(False)
                except RuntimeError:
                    pass
        # Update prog_fader slider and label
        try:
            fader_num = int(fader_id.split("_")[1]) - 1
            if hasattr(self, 'prog_faders') and fader_num < len(self.prog_faders):
                sl = self.prog_faders[fader_num]
                sl.blockSignals(True)
                sl.setValue(0)
                sl.blockSignals(False)
            if hasattr(self, 'prog_fader_labels') and fader_num < len(self.prog_fader_labels):
                self.prog_fader_labels[fader_num].setText("0")
        except (ValueError, IndexError):
            pass
        # Send MIDI motorized-fader feedback (static + dynamic mappings)
        self._send_fader_feedback(fader_id, 0, max_val=100)
        self._send_dynamic_midi_feedback_for_fader(fader_id, 0)

        # Set cooldown to prevent incoming MIDI echo while motor moves to 0
        import time as _time
        if not hasattr(self, '_fader_cooldown'):
            self._fader_cooldown = {}
        self._fader_cooldown[fader_id] = _time.time()

    def _stop_visualizer_fader(self, fader_id: str):
        """Stop visualizer playback triggered by a fader and restore default look."""
        try:
            from .visualizer_tab import _stop_visualizer
        except ImportError:
            from visualizer_tab import _stop_visualizer
        _stop_visualizer(self)

        # Reset engine fader level
        engine = getattr(self, '_viz_engine', None)
        if engine:
            engine._fader_level = 1.0

    def _find_viz_item(self, viz_item_id: str):
        """Find a VisualizerItem by ID from the project."""
        for vit in getattr(self.project, '_visualizer_items', []):
            if vit.id == viz_item_id:
                return vit
        return None

    def _handle_position_fader(self, fader_id: str, position_ids: list, value: int):
        """Handle position fader movement — interpolate fixtures across position presets.
        
        With N positions assigned, the fader is divided into N equal segments:
        - Segment 1: 0% → (100/N)% → interpolate from home to Position 1
        - Segment 2: (100/N)% → (200/N)% → interpolate from Position 1 to Position 2
        - etc.
        
        Interpolated channels: pan, tilt, dimmer, shutter, and RGB color.
        At 0%: all values at home (dimmer=0, shutter=0, pan/tilt=home or center).
        At 100%: fully at the last position.
        
        Args:
            fader_id: The fader ID
            position_ids: List of position preset IDs assigned to this fader
            value: Fader position (0-100)
        """
        artnet = get_artnet_output()
        if not artnet:
            return
        
        # Initialize per-fader override tracking
        if not hasattr(self, '_position_override_by_fader'):
            self._position_override_by_fader = {}
        
        # Track which (universe, channel) pairs this fader is overriding
        override_channels = set()
        
        # Load position presets
        presets = []
        for pid in position_ids:
            p = self.project.get_position_preset_by_id(pid)
            if p:
                presets.append(p)
        
        if not presets:
            return
        
        num_positions = len(presets)
        fader_fraction = value / 100.0  # 0.0 to 1.0
        
        # Determine which segment we're in and the local progress within that segment
        if value >= 100:
            segment_index = num_positions - 1
            local_progress = 1.0
        else:
            # Each segment spans (1/num_positions) of the fader range
            segment_size = 1.0 / num_positions
            segment_index = min(int(fader_fraction / segment_size), num_positions - 1)
            local_progress = (fader_fraction - (segment_index * segment_size)) / segment_size
            local_progress = max(0.0, min(1.0, local_progress))
        
        # Gather all fixture IDs involved across all presets
        all_fixture_ids = set()
        for p in presets:
            all_fixture_ids.update(p.fixture_positions.keys())
        
        # For each fixture, compute interpolated values
        for fixture_id in all_fixture_ids:
            fixture = self.project.get_fixture_by_id(fixture_id)
            if not fixture or not fixture.mode:
                continue
            
            # Home values: dimmer=0, shutter=0, pan/tilt from fixture home or center (128)
            home_pan = 128
            home_tilt = 128
            if hasattr(fixture, 'home_pan') and fixture.home_pan is not None:
                home_pan = fixture.home_pan
            if hasattr(fixture, 'home_tilt') and fixture.home_tilt is not None:
                home_tilt = fixture.home_tilt
            home_dimmer = 0
            home_shutter = 0
            home_color = (0, 0, 0)  # RGB off at home
            
            # Continuous channels that should be interpolated smoothly
            continuous_keys = ('prism', 'frost', 'focus', 'zoom', 'iris')
            # Discrete channels that snap to target once we enter the segment
            discrete_keys = ('color_wheel', 'gobo', 'effect')
            
            # Build "from" values (the position we're coming from)
            if segment_index == 0:
                # Coming from home
                from_pan = home_pan
                from_tilt = home_tilt
                from_dimmer = home_dimmer
                from_shutter = home_shutter
                from_color = home_color
                from_continuous = {k: 0 for k in continuous_keys}
                from_discrete = {k: 0 for k in discrete_keys}
            else:
                # Coming from previous position
                prev_preset = presets[segment_index - 1]
                prev_pos = prev_preset.fixture_positions.get(fixture_id, {})
                from_pan = prev_pos.get('pan', home_pan)
                from_tilt = prev_pos.get('tilt', home_tilt)
                from_dimmer = prev_pos.get('dimmer', 255)
                from_shutter = prev_pos.get('shutter', 255)
                prev_color_hex = prev_pos.get('color', '#ffffff')
                from_color = self._hex_to_rgb(prev_color_hex)
                from_continuous = {k: prev_pos.get(k, 0) for k in continuous_keys}
                from_discrete = {k: prev_pos.get(k, 0) for k in discrete_keys}
            
            # Build "to" values (the position we're going to)
            target_preset = presets[segment_index]
            target_pos = target_preset.fixture_positions.get(fixture_id, {})
            to_pan = target_pos.get('pan', home_pan)
            to_tilt = target_pos.get('tilt', home_tilt)
            to_dimmer = target_pos.get('dimmer', 255)
            to_shutter = target_pos.get('shutter', 255)
            to_color_hex = target_pos.get('color', '#ffffff')
            to_color = self._hex_to_rgb(to_color_hex)
            to_continuous = {k: target_pos.get(k, 0) for k in continuous_keys}
            to_discrete = {k: target_pos.get(k, 0) for k in discrete_keys}
            
            # Interpolate
            t = local_progress
            int_pan = int(from_pan + (to_pan - from_pan) * t)
            int_tilt = int(from_tilt + (to_tilt - from_tilt) * t)
            int_dimmer = int(from_dimmer + (to_dimmer - from_dimmer) * t)
            int_shutter = int(from_shutter + (to_shutter - from_shutter) * t)
            int_r = int(from_color[0] + (to_color[0] - from_color[0]) * t)
            int_g = int(from_color[1] + (to_color[1] - from_color[1]) * t)
            int_b = int(from_color[2] + (to_color[2] - from_color[2]) * t)
            
            # Interpolate continuous beam channels
            int_continuous = {}
            for k in continuous_keys:
                int_continuous[k] = int(from_continuous[k] + (to_continuous[k] - from_continuous[k]) * t)
            
            # Discrete channels snap to target as soon as we enter the segment
            int_discrete = {}
            for k in discrete_keys:
                int_discrete[k] = to_discrete[k] if t > 0 else from_discrete[k]
            
            # Clamp values
            int_pan = max(0, min(255, int_pan))
            int_tilt = max(0, min(255, int_tilt))
            int_dimmer = max(0, min(255, int_dimmer))
            int_shutter = max(0, min(255, int_shutter))
            int_r = max(0, min(255, int_r))
            int_g = max(0, min(255, int_g))
            int_b = max(0, min(255, int_b))
            for k in int_continuous:
                int_continuous[k] = max(0, min(255, int_continuous[k]))
            for k in int_discrete:
                int_discrete[k] = max(0, min(255, int_discrete[k]))
            
            # White follows the minimum of RGB for a natural look
            int_w = min(int_r, int_g, int_b)
            
            # Build a channel type -> value map for easy lookup
            channel_value_map = {
                'pan': int_pan,
                'tilt': int_tilt,
                'dimmer': int_dimmer, 'intensity': int_dimmer,
                'master': int_dimmer, 'master dimmer': int_dimmer,
                'shutter': int_shutter,
                'red': int_r, 'green': int_g, 'blue': int_b,
                'white': int_w, 'cool_white': int_w, 'warm_white': int_w,
                'amber': min(int_r, int_g) // 2,
                'uv': 0,
                'color_wheel': int_discrete.get('color_wheel', 0),
                'gobo': int_discrete.get('gobo', 0),
                'effect': int_discrete.get('effect', 0),
                'prism': int_continuous.get('prism', 0),
                'frost': int_continuous.get('frost', 0),
                'focus': int_continuous.get('focus', 0),
                'zoom': int_continuous.get('zoom', 0),
                'iris': int_continuous.get('iris', 0),
            }
            
            # Apply to fixture channels via Art-Net and track overridden channels
            for i, ch in enumerate(fixture.mode.channels):
                ch_type = ch.type.lower()
                address = fixture.address + i
                
                if ch_type in channel_value_map:
                    artnet.force_set_channel(fixture.universe, address, channel_value_map[ch_type])
                    # Register this channel as position-overridden so the effect engine skips it
                    override_channels.add((fixture.universe, address))
        
        # Update the ArtNet output's override set (blocks effect engine writes at the ArtNet level)
        if value == 0:
            # Fader at 0: release all overrides for this fader so effects resume
            prev = self._position_override_by_fader.get(fader_id, set())
            artnet._position_override_channels -= prev
            self._position_override_by_fader.pop(fader_id, None)
        else:
            # Replace this fader's overrides with the current set
            prev = self._position_override_by_fader.get(fader_id, set())
            artnet._position_override_channels -= prev
            artnet._position_override_channels |= override_channels
            self._position_override_by_fader[fader_id] = override_channels
        
        # Log at key positions
        if value % 10 == 0 or value == 0 or value == 100:
            if num_positions == 1:
                print(f"[Position Fader] {fader_id}={value}% -> {presets[0].name} (progress={local_progress:.0%})")
            else:
                target_name = presets[segment_index].name
                print(f"[Position Fader] {fader_id}={value}% -> Segment {segment_index+1}/{num_positions} '{target_name}' (progress={local_progress:.0%})")
    
    @staticmethod
    def _hex_to_rgb(hex_color: str) -> tuple:
        """Convert hex color string to (r, g, b) tuple."""
        hex_color = hex_color.lstrip('#')
        if len(hex_color) != 6:
            return (255, 255, 255)
        try:
            return (int(hex_color[0:2], 16), int(hex_color[2:4], 16), int(hex_color[4:6], 16))
        except ValueError:
            return (255, 255, 255)

    def _on_midi_prog_fader(self, fader_id: str, midi_value: int, max_value: int):
        """Handle MIDI fader input for programmable fader.
        
        Args:
            fader_id: The fader ID (e.g., "fader_1")
            midi_value: The raw MIDI value
            max_value: Maximum value (127 for CC, 16383 for pitch bend)
        """
        # Map MIDI value to slider 0-100 with proper rounding
        slider_value = round(midi_value * 100.0 / max_value)
        
        # Apply small dead zone at bottom to ensure clean 0
        if slider_value <= 2:
            slider_value = 0
        
        # Log at 5% intervals for reasonable feedback
        if slider_value % 5 == 0 or slider_value == 0:
            print(f"[MIDI_PROG_FADER] {fader_id}: {slider_value}%")
        
        fader_num = int(fader_id.split("_")[1]) - 1  # 0-indexed
        
        # Block feedback while updating from MIDI
        self._updating_from_midi = True
        try:
            self.prog_faders[fader_num].setValue(slider_value)
        finally:
            self._updating_from_midi = False
    
    def _show_prog_fader_context_menu(self, pos, fader_id: str, fader_name: str, slider: QSlider):
        """Show context menu for programmable fader MIDI learn."""
        midi_mgr = get_midi_manager()
        menu = QMenu(self)
        menu.setStyleSheet(self._get_touch_menu_stylesheet())
        
        # Check for execution assignment
        exec_assignments = self.app_settings.get('fader_execution_assignments', {})
        assigned_preset_id = exec_assignments.get(fader_id)
        
        if assigned_preset_id:
            # Show currently assigned preset
            preset_name = "Unknown"
            for preset in self.project.presets:
                if preset.id == assigned_preset_id:
                    preset_name = preset.name
                    break
            if assigned_preset_id == "__OFF__":
                preset_name = "OFF"
            
            assigned_action = menu.addAction(f"⚡ Assigned to: {preset_name}")
            assigned_action.setEnabled(False)
            menu.addSeparator()
            
            # Fader mode options (only shown when assigned to an execution button)
            # Modes: 'fade' (default), 'speed', 'fade_and_speed'
            fader_modes = self.app_settings.get('fader_modes', {})
            current_mode = fader_modes.get(fader_id, 'fade')  # Default to 'fade'
            
            fade_action = menu.addAction(f"{'✓' if current_mode == 'fade' else '○'} Fade (brightness)")
            fade_action.triggered.connect(lambda: self._set_fader_mode(fader_id, 'fade'))
            
            speed_action = menu.addAction(f"{'✓' if current_mode == 'speed' else '○'} Speed (full brightness)")
            speed_action.triggered.connect(lambda: self._set_fader_mode(fader_id, 'speed'))
            
            fade_speed_action = menu.addAction(f"{'✓' if current_mode == 'fade_and_speed' else '○'} Fade and Speed")
            fade_speed_action.triggered.connect(lambda: self._set_fader_mode(fader_id, 'fade_and_speed'))
        else:
            # Check for position assignment
            pos_assignments = self.app_settings.get('fader_position_assignments', {})
            assigned_positions = pos_assignments.get(fader_id, [])
            
            if assigned_positions:
                pos_names = []
                for pid in assigned_positions:
                    p = self.project.get_position_preset_by_id(pid)
                    if p:
                        pos_names.append(p.name)
                assigned_action = menu.addAction(f"📍 Positions: {', '.join(pos_names)}")
                assigned_action.setEnabled(False)
                menu.addSeparator()
                clear_pos_action = menu.addAction("❌ Clear Position Assignment")
                clear_pos_action.triggered.connect(lambda: self._clear_fader_position_assignment(fader_id))
            else:
                assign_action = menu.addAction("⚡ Assign to Execution Button...")
                assign_action.triggered.connect(lambda: self._show_fader_execution_assignment_dialog(fader_id, fader_name))
        
        menu.addSeparator()
        
        # Check if dynamic MIDI mode is enabled
        dynamic_mode = midi_mgr.is_dynamic_mode_enabled()
        
        # Check if already mapped to MIDI
        existing_mapping = midi_mgr.get_fader_mapping(fader_id)
        if existing_mapping and not dynamic_mode:
            display = MIDIManager.format_midi_key(existing_mapping)
            mapped_action = menu.addAction(f"✓ MIDI: {display}")
            mapped_action.setEnabled(False)
            menu.addSeparator()
            clear_action = menu.addAction("❌ Clear MIDI Mapping")
            clear_action.triggered.connect(lambda: self._clear_fader_midi_mapping(fader_id))
        else:
            learn_action = menu.addAction("🎹 Learn MIDI Fader...")
            if dynamic_mode:
                learn_action.setEnabled(False)
                learn_action.setText("🎹 Learn MIDI Fader... (Dynamic Mode Active)")
            else:
                learn_action.triggered.connect(lambda: self._start_fader_midi_learn(fader_id, fader_name, slider))
        
        menu.addSeparator()
        
        # Override mode toggle
        override_faders = self.app_settings.get('prog_fader_overrides', {})
        is_override = override_faders.get(fader_id, False)
        override_action = menu.addAction(f"{'✅' if is_override else '⬜'} Override Mode")
        override_action.setToolTip("When enabled, this fader's effect can run alongside other effects.\nIts target fixtures are excluded from other effects.")
        override_action.triggered.connect(lambda: self._toggle_prog_fader_override(fader_id, slider))
        
        menu.addSeparator()
        
        # OSC/MIDI Shortcut output assignment
        self._build_fader_shortcut_submenu(menu, fader_id)
        
        menu.addSeparator()
        clear_all_action = menu.addAction("🗑️ Clear All Fader MIDI...")
        clear_all_action.triggered.connect(self._clear_all_fader_midi_mappings)
        
        menu.exec(slider.mapToGlobal(pos))
    
    def _toggle_prog_fader_override(self, fader_id: str, slider: QSlider):
        """Toggle override mode for a programmable fader.
        
        When override is ON, this fader's effect can coexist with other effects.
        Its target fixtures are excluded from other effects' output.
        Auto-crossfade will skip this fader.
        """
        override_faders = self.app_settings.get('prog_fader_overrides', {})
        is_override = override_faders.get(fader_id, False)
        
        # Toggle
        new_state = not is_override
        override_faders[fader_id] = new_state
        self.app_settings['prog_fader_overrides'] = override_faders
        self._save_app_settings()
        
        if new_state:
            print(f"[Override] Enabled override mode for prog fader '{fader_id}'")
            self._update_prog_fader_override_indicator(fader_id, slider, True)
        else:
            print(f"[Override] Disabled override mode for prog fader '{fader_id}'")
            self._update_prog_fader_override_indicator(fader_id, slider, False)
    
    def _resolve_fader_preset_fixture_ids(self, preset_id: str) -> list:
        """Resolve fixture IDs from a preset's target groups."""
        preset = None
        for p in self.project.presets:
            if p.id == preset_id:
                preset = p
                break
        if not preset:
            return []
        
        fixture_ids = []
        _tgt_fixtures = getattr(preset, 'target_fixtures', []) or []
        if preset.target_groups:
            target_groups = list(preset.target_groups)
        elif _tgt_fixtures:
            target_groups = []  # individual fixtures — don't default to 'all'
        else:
            target_groups = ['all']
        
        if 'all' in [g.lower() for g in target_groups]:
            fixture_ids = [f.id for f in self.project.fixtures]
        else:
            for group_name in target_groups:
                for group in self.project.groups:
                    if group.name == group_name or group.id == group_name:
                        for fid in group.fixture_ids:
                            if fid not in fixture_ids:
                                fixture_ids.append(fid)
                        break
        
        # Also include target_fixtures if specified
        if hasattr(preset, 'target_fixtures') and preset.target_fixtures:
            for fid in preset.target_fixtures:
                if fid not in fixture_ids:
                    fixture_ids.append(fid)
        
        return fixture_ids
    
    def _update_prog_fader_override_indicator(self, fader_id: str, slider: QSlider, is_override: bool):
        """Update the visual indicator on a programmable fader to show override state."""
        if is_override:
            # Red slider handle to visually distinguish override faders
            slider.setStyleSheet("""
                QSlider::groove:vertical {
                    background-color: #2a2020;
                    width: 40px;
                    border-radius: 20px;
                    margin: 0px 0px 40px 0px;
                    border: 3px solid #3a1515;
                }
                QSlider::handle:vertical {
                    background-color: #e04050;
                    border-radius: 15px;
                    width: 50px;
                    height: 30px;
                    margin: -15px -25px;
                    border: 3px solid #b03040;
                }
                QSlider::handle:vertical:hover {
                    background-color: #ff5565;
                    border: 3px solid #e04050;
                }
                QSlider::handle:vertical:pressed {
                    background-color: #ff7080;
                }
            """)
        else:
            # Restore normal amber slider handle
            accent_color = "#c97a50"
            slider.setStyleSheet(f"""
                QSlider::groove:vertical {{
                    background-color: #2a2a2a;
                    width: 40px;
                    border-radius: 20px;
                    margin: 0px 0px 40px 0px;
                    border: 3px solid #1a1a1a;
                }}
                QSlider::handle:vertical {{
                    background-color: {accent_color};
                    border-radius: 15px;
                    width: 50px;
                    height: 30px;
                    margin: -15px -25px;
                    border: 3px solid #a05a30;
                }}
                QSlider::handle:vertical:hover {{
                    background-color: #ff9955;
                    border: 3px solid #c97a50;
                }}
                QSlider::handle:vertical:pressed {{
                    background-color: #ffaa66;
                }}
            """)

        if hasattr(slider, '_midi_label'):
            label = slider._midi_label
            if is_override:
                current_text = label.text()
                if '🔒' not in current_text:
                    if current_text:
                        label.setText(f"🔒 OVR | {current_text}")
                    else:
                        label.setText("🔒 OVR")
                    label.setStyleSheet("color: #ff9944; font-size: 9px; font-weight: bold;")
            else:
                current_text = label.text().replace("🔒 OVR | ", "").replace("🔒 OVR", "").strip()
                label.setText(current_text)
                if current_text:
                    label.setStyleSheet("color: #50c9a0; font-size: 9px;")
                else:
                    label.setStyleSheet("color: #666; font-size: 9px;")
    
    def _clear_fader_midi_mapping(self, fader_id: str):
        """Clear MIDI mapping for a programmable fader."""
        midi_mgr = get_midi_manager()
        
        # Get current mapping
        fader_mappings = self.app_settings.get('midi_fader_mappings', {})
        if fader_id in fader_mappings:
            old_mapping = fader_mappings[fader_id]
            
            # Remove from MIDI manager
            if isinstance(old_mapping, list):
                for cc_key in old_mapping:
                    if cc_key in midi_mgr._fader_mappings:
                        del midi_mgr._fader_mappings[cc_key]
            elif isinstance(old_mapping, str):
                if old_mapping in midi_mgr._fader_mappings:
                    del midi_mgr._fader_mappings[old_mapping]
            
            # Remove callback
            if fader_id in midi_mgr._fader_callbacks:
                del midi_mgr._fader_callbacks[fader_id]
            
            # Remove from settings
            del fader_mappings[fader_id]
            self._save_app_settings()
            
            print(f"[MIDI] Cleared mapping for {fader_id}")
            
            # Update MIDI label on all slider instances for this fader
            self._refresh_fader_midi_label(fader_id, has_mapping=False)
            
            # Refresh appropriate faders tab based on fader type
            if fader_id.startswith('fader_'):
                if hasattr(self, 'faders_layout'):
                    self._refresh_faders_tab()
            elif fader_id.startswith('group_'):
                if hasattr(self, 'group_faders_layout'):
                    self._populate_group_faders()
            elif fader_id.startswith('fixture_type_'):
                if hasattr(self, 'fixture_type_faders_layout'):
                    self._populate_fixture_type_faders()
            elif fader_id == "master":
                self._refresh_all_master_midi_labels()
            elif fader_id == "effect_speed":
                self._refresh_all_speed_midi_labels()
    
    def _clear_all_fader_midi_mappings(self):
        """Clear MIDI mappings from all programmable faders (fader_1 through fader_20).
        
        Does NOT clear master or effect_speed MIDI mappings.
        """
        midi_mgr = get_midi_manager()
        fader_mappings = self.app_settings.get('midi_fader_mappings', {})
        
        # Find all fader_N mappings to clear
        faders_to_clear = [fid for fid in fader_mappings.keys() 
                          if fid.startswith('fader_') and fid not in ('master', 'effect_speed')]
        
        if not faders_to_clear:
            QMessageBox.information(self._get_active_window(), "No Mappings", "No fader MIDI mappings to clear.")
            return
        
        # Confirm
        result = QMessageBox.question(
            self._get_active_window(), "Clear All Fader MIDI",
            f"Clear MIDI mappings from {len(faders_to_clear)} faders?\n\n"
            "(Master and Effect Speed will not be affected)",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
        )
        
        if result != QMessageBox.StandardButton.Yes:
            return
        
        # Clear each fader
        for fader_id in faders_to_clear:
            old_mapping = fader_mappings.get(fader_id)
            if old_mapping:
                # Remove from MIDI manager
                if isinstance(old_mapping, list):
                    for cc_key in old_mapping:
                        if cc_key in midi_mgr._fader_mappings:
                            del midi_mgr._fader_mappings[cc_key]
                elif isinstance(old_mapping, str):
                    if old_mapping in midi_mgr._fader_mappings:
                        del midi_mgr._fader_mappings[old_mapping]
                
                # Remove callback
                if fader_id in midi_mgr._fader_callbacks:
                    del midi_mgr._fader_callbacks[fader_id]
                
                # Remove from settings
                del fader_mappings[fader_id]
        
        self._save_app_settings()
        print(f"[MIDI] Cleared {len(faders_to_clear)} fader MIDI mappings")
        
        # Update MIDI labels on all slider instances
        for fader_id in faders_to_clear:
            self._refresh_fader_midi_label(fader_id, has_mapping=False)
        
        # Refresh faders tab to update MIDI label displays
        if hasattr(self, 'faders_layout'):
            self._refresh_faders_tab()
    
    def _refresh_fader_midi_label(self, fader_id: str, has_mapping: bool):
        """Refresh the MIDI label on all slider instances for a specific fader_id.
        
        Args:
            fader_id: The fader identifier (e.g., 'fader_1', 'group_drums', 'fixture_type_LED')
            has_mapping: Whether the fader has a MIDI mapping
        """
        # Get the mapping count for better display
        fader_mappings = self.app_settings.get('midi_fader_mappings', {})
        mappings = fader_mappings.get(fader_id)
        if mappings:
            if isinstance(mappings, str):
                mappings = [mappings]
            count = len(mappings)
            midi_text = f"🎹 MIDI ({count})" if count > 1 else "🎹 MIDI"
            midi_style = "color: #50c9a0; font-size: 9px;"
        else:
            midi_text = ""
            midi_style = "color: #666; font-size: 9px;"
        
        # Update all slider instances in _all_fader_sliders
        if fader_id in self._all_fader_sliders:
            valid_sliders = []
            for slider in self._all_fader_sliders[fader_id]:
                try:
                    if hasattr(slider, '_midi_label'):
                        slider._midi_label.setText(midi_text)
                        slider._midi_label.setStyleSheet(midi_style)
                    valid_sliders.append(slider)
                except RuntimeError:
                    pass  # Slider was deleted
            if valid_sliders:
                self._all_fader_sliders[fader_id] = valid_sliders
            else:
                del self._all_fader_sliders[fader_id]
        
        # Also check for group faders tracked separately
        if fader_id.startswith('group_'):
            group_name = fader_id[6:]  # Remove 'group_' prefix
            if hasattr(self, 'group_fader_widgets') and group_name in self.group_fader_widgets:
                slider = self.group_fader_widgets[group_name]
                try:
                    if hasattr(slider, '_midi_label'):
                        slider._midi_label.setText(midi_text)
                        slider._midi_label.setStyleSheet(midi_style)
                except RuntimeError:
                    pass
        
        # Also check for fixture type faders tracked in multi-slider tracking
        if fader_id.startswith('fixture_type_'):
            profile_name = fader_id[13:]  # Remove 'fixture_type_' prefix
            if profile_name in self._all_fixture_type_fader_sliders:
                valid_sliders = []
                for slider in self._all_fixture_type_fader_sliders[profile_name]:
                    try:
                        if hasattr(slider, '_midi_label'):
                            slider._midi_label.setText(midi_text)
                            slider._midi_label.setStyleSheet(midi_style)
                        valid_sliders.append(slider)
                    except RuntimeError:
                        pass  # Slider was deleted
                if valid_sliders:
                    self._all_fixture_type_fader_sliders[profile_name] = valid_sliders
                else:
                    del self._all_fixture_type_fader_sliders[profile_name]

    # ── Flash-on-click-hold + MIDI flash methods ───────────────────────

    def _on_flash_label_pressed(self, event, label, slider, fader_id, fader_idx):
        """Mouse press on value label: flash, cycle positions, or advance cue."""
        from PyQt6.QtCore import Qt
        if event.button() != Qt.MouseButton.LeftButton:
            return

        # Check if this fader is assigned to a cue list — act as "Next Cue"
        exec_assignments = self.app_settings.get('fader_execution_assignments', {})
        assigned = exec_assignments.get(fader_id, '')
        if assigned and assigned.startswith('cuelist:'):
            cuelist_id = assigned.split(':', 1)[1]
            # Select this cue list in the combo
            for i in range(self._cue_list_combo.count()):
                if self._cue_list_combo.itemData(i) == cuelist_id:
                    self._cue_list_combo.setCurrentIndex(i)
                    break
            self._cue_next()
            # Brief visual feedback
            accent = getattr(label, '_flash_accent', '#c97a50')
            label.setStyleSheet(f"""
                QLabel {{
                    font-size: 11px; font-weight: bold;
                    color: #fff; background-color: {accent};
                    border-radius: 3px; padding: 4px 2px;
                }}
            """)
            return

        # Check if this fader is a position fader (multiple positions assigned)
        pos_assignments = self.app_settings.get('fader_position_assignments', {})
        assigned_positions = pos_assignments.get(fader_id, [])

        if assigned_positions and len(assigned_positions) >= 1:
            # ── Position cycling mode ──
            self._cycle_position_fader(fader_id, slider, label)
        else:
            # ── Normal flash mode (hold-to-max) ──
            accent = getattr(label, '_flash_accent', '#c97a50')
            label._flash_pre_value = slider.value()
            slider.setValue(100)
            label.setStyleSheet(f"""
                QLabel {{
                    font-size: 11px; font-weight: bold;
                    color: #fff; background-color: {accent};
                    border-radius: 3px; padding: 4px 2px;
                }}
            """)

    def _on_flash_label_released(self, event, label, slider, fader_id, fader_idx):
        """Mouse release on value label: restore fader (no-op for position cycling and cuelists)."""
        from PyQt6.QtCore import Qt
        if event.button() != Qt.MouseButton.LeftButton:
            return

        # Cuelist faders — restore label style only, don't change fader value
        exec_assignments = self.app_settings.get('fader_execution_assignments', {})
        assigned = exec_assignments.get(fader_id, '')
        if assigned and assigned.startswith('cuelist:'):
            accent = getattr(label, '_flash_accent', '#c97a50')
            label.setStyleSheet(f"""
                QLabel {{
                    font-size: 11px; font-weight: bold;
                    color: {accent}; text-align: center;
                    background-color: #2d2d2d;
                    border-radius: 3px; padding: 4px 2px;
                }}
                QLabel:hover {{
                    background-color: #4a3520;
                    border: 1px solid {accent};
                }}
            """)
            return

        # Position faders stay on their cycled value — only restore for normal flash
        pos_assignments = self.app_settings.get('fader_position_assignments', {})
        assigned_positions = pos_assignments.get(fader_id, [])
        if assigned_positions and len(assigned_positions) >= 1:
            return  # Position cycling — do nothing on release

        accent = getattr(label, '_flash_accent', '#c97a50')
        slider.setValue(label._flash_pre_value)
        label.setStyleSheet(f"""
            QLabel {{
                font-size: 11px; font-weight: bold;
                color: {accent}; text-align: center;
                background-color: #2d2d2d;
                border-radius: 3px; padding: 4px 2px;
            }}
            QLabel:hover {{
                background-color: #4a3520;
                border: 1px solid {accent};
            }}
        """)

    def _cycle_position_fader(self, fader_id: str, slider, label=None):
        """Advance a position fader to the next position in its assignment list.

        Cycle: pos1 → pos2 → … → posN → 0 (off) → pos1 → …
        Slider value is proportional: step k of N positions → round(k/N * 100).
        """
        if not hasattr(self, '_position_cycle_state'):
            self._position_cycle_state = {}  # fader_id -> current step index

        pos_assignments = self.app_settings.get('fader_position_assignments', {})
        positions = pos_assignments.get(fader_id, [])
        n = len(positions)
        if n == 0:
            return

        # Current step: 0..n-1 = position, n = off
        current_step = self._position_cycle_state.get(fader_id, -1)
        next_step = current_step + 1
        if next_step > n:
            next_step = 0  # wrap around back to position 1

        self._position_cycle_state[fader_id] = next_step

        if next_step == n:
            # Off step
            slider.setValue(0)
            accent = getattr(label, '_flash_accent', '#c97a50') if label else '#c97a50'
            if label:
                label.setStyleSheet(f"""
                    QLabel {{
                        font-size: 11px; font-weight: bold;
                        color: {accent}; text-align: center;
                        background-color: #2d2d2d;
                        border-radius: 3px; padding: 4px 2px;
                    }}
                    QLabel:hover {{
                        background-color: #4a3520;
                        border: 1px solid {accent};
                    }}
                """)
        else:
            # Position step: proportional slider value
            value = round((next_step + 1) / n * 100)
            slider.setValue(value)
            # Get position name for tooltip feedback
            pos_name = ""
            pid = positions[next_step]
            p = self.project.get_position_preset_by_id(pid)
            if p:
                pos_name = p.name
            accent = getattr(label, '_flash_accent', '#c97a50') if label else '#c97a50'
            if label:
                label.setStyleSheet(f"""
                    QLabel {{
                        font-size: 11px; font-weight: bold;
                        color: #fff; background-color: {accent};
                        border-radius: 3px; padding: 4px 2px;
                    }}
                """)
                label.setToolTip(f"Position {next_step + 1}/{n}: {pos_name}\nClick to advance")

    def _show_flash_midi_context_menu(self, pos, fader_id, fader_name, label):
        """Right-click context menu on value label for MIDI flash learn/clear."""
        midi_mgr = get_midi_manager()
        menu = QMenu(self)
        menu.setStyleSheet(self._get_touch_menu_stylesheet())

        # Check if a flash mapping already exists for this fader
        existing_key = None
        for note_key, mapped_fid in midi_mgr._flash_mappings.items():
            if mapped_fid == fader_id:
                existing_key = note_key
                break

        if existing_key:
            display = MIDIManager.format_midi_key(existing_key)
            info_action = menu.addAction(f"⚡ Flash MIDI: {display}")
            info_action.setEnabled(False)
            menu.addSeparator()
            clear_action = menu.addAction("❌ Clear Flash MIDI")
            clear_action.triggered.connect(lambda: self._clear_flash_midi_mapping(fader_id, label))
        else:
            learn_action = menu.addAction("🎹 Learn MIDI Flash Button...")
            learn_action.triggered.connect(
                lambda: self._start_flash_midi_learn(fader_id, fader_name, label))

        menu.exec(label.mapToGlobal(pos))

    def _start_flash_midi_learn(self, fader_id: str, fader_name: str, label):
        """Open MIDI learn dialog for a flash button (note-only)."""
        midi_mgr = get_midi_manager()
        if not midi_mgr.is_connected:
            QMessageBox.warning(self._get_active_window(), "No MIDI Device",
                                "Connect a MIDI device first in Settings > MIDI.")
            return

        parent_window = label.window() if label else self
        dialog = QDialog(parent_window)
        dialog.setWindowTitle(f"Learn Flash Button for '{fader_name}'")
        dialog.setMinimumWidth(380)
        layout = QVBoxLayout()

        info = QLabel("Press a MIDI note button...\n\n(Waiting for input)")
        info.setAlignment(Qt.AlignmentFlag.AlignCenter)
        info.setStyleSheet("font-size: 14px; padding: 20px;")
        layout.addWidget(info)

        btn_layout = QHBoxLayout()
        ok_btn = QPushButton("OK")
        cancel_btn = QPushButton("Cancel")
        ok_btn.setMinimumHeight(40)
        cancel_btn.setMinimumHeight(40)
        ok_btn.setEnabled(False)
        btn_layout.addWidget(ok_btn)
        btn_layout.addWidget(cancel_btn)
        layout.addLayout(btn_layout)
        dialog.setLayout(layout)

        midi_mgr.set_learn_mode(True)
        learned_key = [None]

        def on_midi_received(midi_key):
            if midi_key.startswith("note:"):
                learned_key[0] = midi_key
                display = MIDIManager.format_midi_key(midi_key)
                info.setText(f"✓ Learned: {display}\n\nClick OK to confirm")
                ok_btn.setEnabled(True)

        midi_mgr.midi_received.connect(on_midi_received)
        ok_btn.clicked.connect(dialog.accept)
        cancel_btn.clicked.connect(dialog.reject)

        result = dialog.exec()

        midi_mgr.set_learn_mode(False)
        midi_mgr.midi_received.disconnect(on_midi_received)

        if result == QDialog.DialogCode.Accepted and learned_key[0]:
            note_key = learned_key[0]
            # Remove any previous flash mapping for this fader
            for k in list(midi_mgr._flash_mappings.keys()):
                if midi_mgr._flash_mappings[k] == fader_id:
                    del midi_mgr._flash_mappings[k]
            # Register new mapping
            midi_mgr._flash_mappings[note_key] = fader_id

            # Persist
            flash_maps = self.app_settings.get('midi_flash_mappings', {})
            # Remove any old key that points to this fader
            flash_maps = {k: v for k, v in flash_maps.items() if v != fader_id}
            flash_maps[note_key] = fader_id
            self.app_settings['midi_flash_mappings'] = flash_maps
            self._save_app_settings()

            display = MIDIManager.format_midi_key(note_key)
            print(f"[MIDI] Flash for {fader_name} assigned to {display}")

    def _clear_flash_midi_mapping(self, fader_id: str, label):
        """Remove the MIDI flash mapping for a fader."""
        midi_mgr = get_midi_manager()
        for k in list(midi_mgr._flash_mappings.keys()):
            if midi_mgr._flash_mappings[k] == fader_id:
                del midi_mgr._flash_mappings[k]

        flash_maps = self.app_settings.get('midi_flash_mappings', {})
        flash_maps = {k: v for k, v in flash_maps.items() if v != fader_id}
        self.app_settings['midi_flash_mappings'] = flash_maps
        self._save_app_settings()
        print(f"[MIDI] Flash mapping cleared for {fader_id}")

    def _on_midi_flash_event(self, fader_id: str, is_pressed: bool):
        """Handle MIDI flash event: flash or cycle positions depending on fader type."""
        # Only act on press for position faders (cycling); for normal flash act on both
        pos_assignments = self.app_settings.get('fader_position_assignments', {})
        assigned_positions = pos_assignments.get(fader_id, [])

        if assigned_positions and len(assigned_positions) >= 1:
            # ── Position cycling: advance on press only, ignore release ──
            if not is_pressed:
                return
            # Find the slider and label for this fader
            for slider in list(self._all_fader_sliders.get(fader_id, [])):
                try:
                    lbl = getattr(slider, '_value_label', None)
                    self._cycle_position_fader(fader_id, slider, lbl)
                except RuntimeError:
                    pass
            return

        # ── Normal flash: max on press, 0 on release ──
        if fader_id in self._all_fader_sliders:
            target_value = 100 if is_pressed else 0
            for slider in list(self._all_fader_sliders.get(fader_id, [])):
                try:
                    slider.setValue(target_value)
                    if hasattr(slider, '_value_label'):
                        lbl = slider._value_label
                        accent = getattr(lbl, '_flash_accent', '#c97a50')
                        if is_pressed:
                            lbl.setStyleSheet(f"""
                                QLabel {{
                                    font-size: 11px; font-weight: bold;
                                    color: #fff; background-color: {accent};
                                    border-radius: 3px; padding: 4px 2px;
                                }}
                            """)
                        else:
                            lbl.setStyleSheet(f"""
                                QLabel {{
                                    font-size: 11px; font-weight: bold;
                                    color: {accent}; text-align: center;
                                    background-color: #2d2d2d;
                                    border-radius: 3px; padding: 4px 2px;
                                }}
                                QLabel:hover {{
                                    background-color: #4a3520;
                                    border: 1px solid {accent};
                                }}
                            """)
                except RuntimeError:
                    pass  # Slider was deleted

        # Also handle group faders (they are tracked in group_fader_widgets, not _all_fader_sliders)
        if fader_id.startswith('group_'):
            group_id = fader_id[6:]
            if hasattr(self, 'group_fader_widgets') and group_id in self.group_fader_widgets:
                slider = self.group_fader_widgets[group_id]
                try:
                    target_value = 100 if is_pressed else 0
                    slider.setValue(target_value)
                    if hasattr(slider, '_value_label'):
                        lbl = slider._value_label
                        accent = getattr(lbl, '_flash_accent', '#50a0c9')
                        if is_pressed:
                            lbl.setStyleSheet(f"""
                                QLabel {{
                                    font-size: 11px; font-weight: bold;
                                    color: #fff; background-color: {accent};
                                    border-radius: 3px; padding: 4px 2px;
                                }}
                            """)
                        else:
                            lbl.setStyleSheet(f"""
                                QLabel {{
                                    font-size: 11px; font-weight: bold;
                                    color: {accent}; text-align: center;
                                    background-color: #2d2d2d;
                                    border-radius: 3px; padding: 4px 2px;
                                }}
                                QLabel:hover {{
                                    background-color: #1a3548;
                                    border: 1px solid {accent};
                                }}
                            """)
                except RuntimeError:
                    pass

    def _fader_has_shortcut_output(self, fader_id: str) -> bool:
        """Check if a fader has any shortcut output assigned (rise or off)."""
        entry = self._get_fader_shortcut_entry(fader_id)
        return bool(entry.get('rise') or entry.get('off'))
    
    def _get_fader_mode_indicator(self, mode: str, fader_id: str = None) -> str:
        """Get the display indicator for a fader mode.
        
        Args:
            mode: 'fade', 'speed', or 'fade_and_speed'
            fader_id: Optional fader ID to check for position/visualizer assignment
            
        Returns:
            'V' for visualizer, 'P' for position fader, 'F' for fade,
            'S' for speed, 'F,S' for both, with ',O' appended if output shortcut.
        """
        # Check if this fader has a visualizer item assigned
        if fader_id:
            viz_assignments = self.app_settings.get('fader_visualizer_assignments', {})
            if viz_assignments.get(fader_id):
                base = "V"
                if self._fader_has_shortcut_output(fader_id):
                    base += ",O"
                return base
        
        # Check if this fader has positions assigned
        if fader_id:
            pos_assignments = self.app_settings.get('fader_position_assignments', {})
            if pos_assignments.get(fader_id):
                base = "P"
                if self._fader_has_shortcut_output(fader_id):
                    base += ",O"
                return base
        
        if mode == 'speed':
            base = "S"
        elif mode == 'fade_and_speed':
            base = "F,S"
        else:  # 'fade' or default
            base = "F"
        
        if fader_id and self._fader_has_shortcut_output(fader_id):
            base += ",O"
        
        return base

    def _set_fader_mode(self, fader_id: str, mode: str):
        """Set the fader mode for an execution fader.
        
        Modes:
            'fade' - Fader controls brightness only (default)
            'speed' - Fader controls effect speed only, runs at full brightness
            'fade_and_speed' - Fader controls both brightness and speed
        """
        if 'fader_modes' not in self.app_settings:
            self.app_settings['fader_modes'] = {}
        
        self.app_settings['fader_modes'][fader_id] = mode
        self._save_app_settings()
        
        # Update mode indicator labels on all slider instances
        self._refresh_fader_mode_label(fader_id, mode)
        
        mode_names = {
            'fade': 'Fade (brightness)',
            'speed': 'Speed (full brightness)',
            'fade_and_speed': 'Fade and Speed'
        }
        print(f"[Fader] {fader_id} mode set to: {mode_names.get(mode, mode)}")
    
    def _refresh_fader_mode_label(self, fader_id: str, mode: str = None):
        """Refresh the mode indicator label on all slider instances for a fader.
        
        Args:
            fader_id: The fader identifier (e.g., 'fader_1')
            mode: The fader mode ('fade', 'speed', or 'fade_and_speed'). If None, reads from settings.
        """
        if mode is None:
            fader_modes = self.app_settings.get('fader_modes', {})
            mode = fader_modes.get(fader_id, 'fade')
        mode_text = self._get_fader_mode_indicator(mode, fader_id)
        
        # Update all slider instances in _all_fader_sliders
        if fader_id in self._all_fader_sliders:
            valid_sliders = []
            for slider in self._all_fader_sliders[fader_id]:
                try:
                    if hasattr(slider, '_mode_label'):
                        slider._mode_label.setText(mode_text)
                    valid_sliders.append(slider)
                except RuntimeError:
                    pass  # Slider was deleted
            if valid_sliders:
                self._all_fader_sliders[fader_id] = valid_sliders
            else:
                del self._all_fader_sliders[fader_id]
    
    def _refresh_fader_output_visuals(self, fader_id: str):
        """Update slider handle color and mode/output label when output assignment changes."""
        has_output = self._fader_has_shortcut_output(fader_id)
        
        # Determine fader type
        is_group = fader_id.startswith('group_')
        is_prog = fader_id.startswith('fader_')
        
        if is_prog:
            # ── Programmable fader ──
            # Refresh mode label (includes O indicator)
            self._refresh_fader_mode_label(fader_id)
            
            # Update slider handle color on all instances
            prog_overrides = self.app_settings.get('prog_fader_overrides', {})
            is_override = prog_overrides.get(fader_id, False)
            
            if fader_id in self._all_fader_sliders:
                for slider in list(self._all_fader_sliders[fader_id]):
                    try:
                        if is_override:
                            # Override takes priority for styling — don't change
                            pass
                        elif has_output:
                            self._apply_output_fader_style(slider, 'prog')
                        else:
                            self._apply_normal_fader_style(slider, 'prog')
                    except RuntimeError:
                        pass
        
        elif is_group:
            # ── Group fader ──
            group_id = fader_id.replace('group_', '', 1)
            override_faders = self.app_settings.get('group_fader_overrides', {})
            is_override = override_faders.get(group_id, False)
            
            if group_id in self.group_fader_widgets:
                slider = self.group_fader_widgets[group_id]
                try:
                    # Update output label
                    if hasattr(slider, '_output_label'):
                        if has_output:
                            slider._output_label.setText("📡 O")
                            slider._output_label.setStyleSheet("color: #50e8a0; font-size: 9px; font-weight: bold;")
                        else:
                            slider._output_label.setText("")
                            slider._output_label.setStyleSheet("color: #666; font-size: 9px;")
                    
                    # Update handle color (skip if override)
                    if is_override:
                        pass
                    elif has_output:
                        self._apply_output_fader_style(slider, 'group')
                    else:
                        self._apply_normal_fader_style(slider, 'group')
                except RuntimeError:
                    pass
    
