    def _show_special_fader_context_menu(self, pos, fader_id: str, fader_name: str, slider: QSlider):
        """Show simplified context menu for special faders without execution assignment."""
        midi_mgr = get_midi_manager()
        menu = QMenu(self)
        menu.setStyleSheet(self._get_touch_menu_stylesheet())
        
        # Master/effect_speed are special faders — always mappable, even in dynamic mode
        fader_mappings = self.app_settings.get('midi_fader_mappings', {})
        existing_mappings = fader_mappings.get(fader_id)
        
        if existing_mappings:
            if isinstance(existing_mappings, str):
                existing_mappings = [existing_mappings]
            for midi_key in existing_mappings:
                display = MIDIManager.format_midi_key(midi_key)
                mapped_action = menu.addAction(f"✓ MIDI: {display}")
                mapped_action.setEnabled(False)
            menu.addSeparator()
            add_action = menu.addAction("➕ Add Another MIDI...")
            add_action.triggered.connect(lambda: self._start_fader_midi_learn(fader_id, fader_name, slider))
            clear_action = menu.addAction("❌ Clear All MIDI Mappings")
            if fader_id == "effect_speed":
                clear_action.triggered.connect(lambda: self._clear_speed_midi_mapping())
            else:
                clear_action.triggered.connect(lambda: self._clear_fader_midi_mapping(fader_id))
        else:
            learn_action = menu.addAction("🎹 Learn MIDI Fader...")
            learn_action.triggered.connect(lambda: self._start_fader_midi_learn(fader_id, fader_name, slider))
        
        menu.exec(slider.mapToGlobal(pos))
    
    def _start_fader_midi_learn(self, fader_id: str, fader_name: str, slider: QSlider):
        """Start MIDI learn mode for a programmable fader (by ID, not FaderConfig).
        
        Supports learning multiple MIDI controls for a single fader.
        """
        midi_mgr = get_midi_manager()
        if not midi_mgr.is_connected:
            QMessageBox.warning(self._get_active_window(), "No MIDI Device", "Connect a MIDI device first in Settings > MIDI.")
            return
        
        # Open MIDI learning dialog - parent to slider's window for correct monitor
        parent_window = slider.window() if slider else self
        dialog = QDialog(parent_window)
        dialog.setWindowTitle(f"Learn MIDI for '{fader_name}'")
        dialog.setMinimumWidth(400)
        layout = QVBoxLayout()
        
        label = QLabel("Turn or move a MIDI fader/knob...\n\n(Waiting for input)")
        label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        label.setStyleSheet("font-size: 14px; padding: 20px;")
        layout.addWidget(label)
        
        # List of learned MIDI controls
        learned_list = QListWidget()
        learned_list.setMaximumHeight(100)
        layout.addWidget(QLabel("Learned MIDI controls:"))
        layout.addWidget(learned_list)
        
        # Encoder direction hint
        encoder_hint = QLabel("For encoders: turn RIGHT for UP note, then turn LEFT for DOWN note")
        encoder_hint.setStyleSheet("color: #888; font-size: 10px;")
        encoder_hint.setWordWrap(True)
        layout.addWidget(encoder_hint)
        
        # Buttons
        button_layout = QHBoxLayout()
        learn_more_button = QPushButton("Learn Another")
        ok_button = QPushButton("OK")
        cancel_button = QPushButton("Cancel")
        learn_more_button.setMinimumHeight(40)
        ok_button.setMinimumHeight(40)
        cancel_button.setMinimumHeight(40)
        ok_button.setEnabled(False)  # Disabled until MIDI received
        button_layout.addWidget(learn_more_button)
        button_layout.addWidget(ok_button)
        button_layout.addWidget(cancel_button)
        layout.addLayout(button_layout)
        
        dialog.setLayout(layout)
        
        # Enable MIDI learn mode
        midi_mgr.set_learn_mode(True)
        learned_keys = []  # List of learned MIDI keys (in order: first=up, second=down)
        encoder_directions = {}  # Map note_key -> direction
        cc_value_samples: dict[str, list[int]] = {}  # Track CC values for relative detection
        detected_relative_ccs: set[str] = set()  # CC keys detected as relative jog/encoder
        
        def _is_relative_cc(samples: list[int]) -> bool:
            """Detect if CC value samples look like a relative jog wheel / encoder.
            
            Relative CCs send values clustered near 0 (1-3 for CW),
            near 64 (63/65 for CW/CCW), or near 127 (125-127 for CCW).
            Absolute faders sweep the full 0-127 range.
            """
            if len(samples) < 2:
                return False
            for v in samples:
                near_zero = v <= 10
                near_64 = 54 <= v <= 74
                near_127 = v >= 117
                if not (near_zero or near_64 or near_127):
                    return False  # Value in the middle range → absolute fader
            return True
        
        def on_cc_value_sampled(cc_key: str, value: int):
            """Track CC values during learn to detect relative encoding."""
            if cc_key not in cc_value_samples:
                cc_value_samples[cc_key] = []
            cc_value_samples[cc_key].append(value)
            # Re-check after each sample
            if _is_relative_cc(cc_value_samples[cc_key]):
                if cc_key not in detected_relative_ccs:
                    detected_relative_ccs.add(cc_key)
                    # Update the list item to show jog/encoder detection
                    for i in range(learned_list.count()):
                        item = learned_list.item(i)
                        if item and cc_key in learned_keys:
                            idx = learned_keys.index(cc_key)
                            if i == idx and "(jog wheel" not in item.text():
                                item.setText(item.text() + " (jog wheel detected)")
                                label.setText(f"✓ Jog wheel detected for {MIDIManager.format_midi_key(cc_key)}\n\nClick OK to confirm")
        
        def on_midi_received(midi_key):
            nonlocal learned_keys
            # Accept CC, pitch bend, or note (for encoders that send note messages)
            if midi_key.startswith("cc:") or midi_key.startswith("pb:") or midi_key.startswith("note:"):
                if midi_key not in learned_keys:
                    learned_keys.append(midi_key)
                    # Store the device name that sent this message
                    device_name = getattr(midi_mgr, '_last_received_device', None)
                    if device_name:
                        midi_mgr._mapping_devices[midi_key] = device_name
                        print(f"[DEBUG] Stored device '{device_name}' for midi_key '{midi_key}'")
                    display = MIDIManager.format_midi_key(midi_key)
                    # For notes used as encoders, track direction based on order learned
                    if midi_key.startswith("note:"):
                        # First note learned = UP (+1), second note = DOWN (-1)
                        note_count = sum(1 for k in learned_keys if k.startswith("note:"))
                        if note_count == 1:
                            display += " (encoder UP ↑)"
                            encoder_directions[midi_key] = 1
                        else:
                            display += " (encoder DOWN ↓)"
                            encoder_directions[midi_key] = -1
                    elif midi_key.startswith("cc:") and midi_key in detected_relative_ccs:
                        display += " (jog wheel detected)"
                    learned_list.addItem(display)
                    label.setText(f"✓ Learned: {display}\n\nLearn another or click OK")
                    ok_button.setEnabled(True)
        
        # Connect signals temporarily
        midi_mgr.midi_received.connect(on_midi_received)
        midi_mgr.midi_cc_value.connect(on_cc_value_sampled)
        
        # Connect button signals
        ok_button.clicked.connect(dialog.accept)
        cancel_button.clicked.connect(dialog.reject)
        learn_more_button.clicked.connect(lambda: label.setText("Waiting for next MIDI input..."))
        
        # Wait with timeout
        result = dialog.exec()
        
        # Disable learn mode
        midi_mgr.set_learn_mode(False)
        midi_mgr.midi_received.disconnect(on_midi_received)
        try:
            midi_mgr.midi_cc_value.disconnect(on_cc_value_sampled)
        except (TypeError, RuntimeError):
            pass
        
        if result == QDialog.DialogCode.Accepted and learned_keys:
            # Get existing mappings for this fader
            fader_mappings = self.app_settings.get('midi_fader_mappings', {})
            existing_mappings = fader_mappings.get(fader_id, [])
            if isinstance(existing_mappings, str):
                existing_mappings = [existing_mappings]
            
            # Combine existing and new mappings (avoid duplicates)
            all_keys = list(existing_mappings)
            for key in learned_keys:
                if key not in all_keys:
                    all_keys.append(key)
            
            # Register MIDI mappings for all keys
            for cc_key in all_keys:
                midi_mgr._fader_mappings[cc_key] = fader_id
            
            # Set encoder directions for note-based encoders
            for note_key, direction in encoder_directions.items():
                midi_mgr.set_encoder_direction(note_key, direction)
            
            # Save encoder directions to settings
            saved_encoder_dirs = self.app_settings.get('midi_encoder_directions', {})
            saved_encoder_dirs.update(encoder_directions)
            self.app_settings['midi_encoder_directions'] = saved_encoder_dirs
            
            # Register detected relative CCs (jog wheels)
            for cc_key in detected_relative_ccs:
                if cc_key in all_keys:
                    midi_mgr._relative_ccs.add(cc_key)
            
            # Save relative CCs to settings
            saved_relative = self.app_settings.get('midi_relative_ccs', [])
            for cc_key in detected_relative_ccs:
                if cc_key not in saved_relative:
                    saved_relative.append(cc_key)
            self.app_settings['midi_relative_ccs'] = saved_relative
            
            # Register callback based on fader type (once, handles all mapped keys)
            if fader_id == "master":
                midi_mgr.register_fader_callback(fader_id, self._on_midi_master_fader)
            elif fader_id == "effect_speed":
                midi_mgr.register_fader_callback(fader_id, self._on_midi_speed_fader)
            elif fader_id == "video_volume":
                midi_mgr.register_fader_callback(fader_id, self._on_midi_video_volume_fader)
            elif fader_id == "video_overlay_master":
                midi_mgr.register_fader_callback(fader_id, self._on_midi_video_overlay_fader)
            else:
                # Regular prog_fader
                midi_mgr.register_fader_callback(fader_id, 
                    lambda val, max_val, fid=fader_id: self._on_midi_prog_fader(fid, val, max_val))
            
            # Save mapping to settings - store as list for multiple mappings
            fader_mappings[fader_id] = all_keys if len(all_keys) > 1 else all_keys[0]
            self.app_settings['midi_fader_mappings'] = fader_mappings
            # Also save the device mappings so controller names persist
            self.app_settings['midi_mapping_devices'] = midi_mgr.get_mapping_devices_dict()
            self._save_app_settings()
            
            display_list = ", ".join([MIDIManager.format_midi_key(k) for k in learned_keys])
            print(f"[MIDI] {fader_name} assigned to {display_list}")
            
            # Update MIDI label on all slider instances for this fader
            self._refresh_fader_midi_label(fader_id, has_mapping=True)
            
            # Refresh appropriate faders based on fader type to update MIDI label display
            if fader_id.startswith('fader_'):
                if hasattr(self, 'faders_layout'):
                    self._refresh_faders_tab()
            elif fader_id.startswith('group_'):
                if hasattr(self, 'group_faders_layout'):
                    self._populate_group_faders()
            elif fader_id.startswith('fixture_type_'):
                if hasattr(self, 'fixture_type_faders_layout'):
                    self._populate_fixture_type_faders()
            elif fader_id == "master":
                # If this was the master fader, refresh all master MIDI labels
                self._refresh_all_master_midi_labels()
            elif fader_id == "effect_speed":
                # If this was the speed fader, refresh all speed MIDI labels
                self._refresh_all_speed_midi_labels()
    
    def _send_fader_feedback(self, fader_id: str, value: int, max_val: int = 255):
        """Send motorized fader feedback when GUI fader changes.
        
        Args:
            fader_id: Fader identifier (e.g., "master_fader", "prog_fader_1")
            value: Current fader value
            max_val: Maximum value for this fader (100 for master, 255 for fixtures)
        """
        midi_mgr = get_midi_manager()
        
        # Get the MIDI key(s) for this fader
        fader_mappings = self.app_settings.get('midi_fader_mappings', {})
        midi_keys = fader_mappings.get(fader_id)
        
        if midi_keys:
            # Scale value to MIDI range (0-127)
            midi_value = int((value / max_val) * 127)
            midi_value = max(0, min(127, midi_value))  # Clamp to 0-127
            
            # Support both single key (string) and multiple keys (list)
            if isinstance(midi_keys, str):
                midi_keys = [midi_keys]
            
            # Send feedback to all mapped MIDI controls
            for midi_key in midi_keys:
                midi_mgr.send_fader_feedback(midi_key, midi_value)
    
    def _update_v1m_lcd_for_fader(self, midi_key: str, fader_name: str):
        """Update Icon V1-M scribble-strip LCD for a learned fader.

        Maps the MIDI key (pb:N or cc:ch:num) to a physical fader number
        and writes the name to the upper row of that fader's LCD strip.

        Args:
            midi_key: MIDI key like "cc:8:0" or "pb:1"
            fader_name: Name to display (e.g., "Master", "Dimmer", "Red")
        """
        midi_mgr = get_midi_manager()
        if not midi_mgr.is_connected or not midi_mgr.has_v1m_connection:
            return

        fader_num = None
        if midi_key.startswith('pb:'):
            # Format: pb:fader_num  (1-indexed)
            parts = midi_key.split(':')
            if len(parts) >= 2:
                try:
                    fader_num = int(parts[1])
                except ValueError:
                    pass
        elif midi_key.startswith('cc:'):
            # Format: cc:cc_number:channel  — channel maps to fader
            parts = midi_key.split(':')
            if len(parts) >= 3:
                try:
                    channel = int(parts[2])
                    fader_num = channel + 1
                except ValueError:
                    pass

        if fader_num and 1 <= fader_num <= 9:
            midi_mgr.update_v1m_lcd(fader_num, fader_name, row=0)
    
    def _setup_midi_fader_callbacks(self):
        """Set up MIDI fader callbacks on startup."""
        midi_mgr = get_midi_manager()
        
        # Load saved fader mappings (handles both old single-CC and new multi-CC formats)
        fader_mappings = self.app_settings.get('midi_fader_mappings', {})
        
        # Load all fader mappings directly (supports single key, list of keys)
        # The load_fader_mappings method handles both formats
        midi_mgr.load_fader_mappings(fader_mappings)
        
        # Load saved encoder directions for note-based encoders
        encoder_directions = self.app_settings.get('midi_encoder_directions', {})
        for note_key, direction in encoder_directions.items():
            midi_mgr.set_encoder_direction(note_key, direction)
        
        # Load saved relative CC keys (jog wheels / encoders)
        relative_ccs = self.app_settings.get('midi_relative_ccs', [])
        for cc_key in relative_ccs:
            midi_mgr._relative_ccs.add(cc_key)
        if relative_ccs:
            print(f"[MIDI] Loaded {len(relative_ccs)} relative CC mappings (jog wheels)")
        
        # Register callbacks for mapped faders
        if midi_mgr.get_fader_mapping("master"):
            midi_mgr.register_fader_callback("master", self._on_midi_master_fader)
        if midi_mgr.get_fader_mapping("video_volume"):
            midi_mgr.register_fader_callback("video_volume", self._on_midi_video_volume_fader)
        if midi_mgr.get_fader_mapping("video_overlay_master"):
            midi_mgr.register_fader_callback("video_overlay_master", self._on_midi_video_overlay_fader)
        if midi_mgr.get_fader_mapping("effect_speed"):
            midi_mgr.register_fader_callback("effect_speed", self._on_midi_speed_fader)
        
        # Register callbacks for programmable faders (supports up to 20 faders)
        total_faders = getattr(self, '_total_faders', 20)
        for i in range(1, total_faders + 1):
            fader_id = f"fader_{i}"
            if midi_mgr.get_fader_mapping(fader_id):
                midi_mgr.register_fader_callback(fader_id, lambda val, max_val, fid=fader_id: self._on_midi_prog_fader(fid, val, max_val))
        
        # Register callbacks for group faders
        for fader_id, cc_keys in fader_mappings.items():
            if fader_id.startswith("group_"):
                group_id = fader_id.replace("group_", "")
                midi_mgr.register_fader_callback(fader_id, 
                    lambda val, max_val, gid=group_id: self._on_midi_group_fader(gid, val, max_val))
        
        # Register callbacks for fixture type faders (master dimmers tab)
        for fader_id, cc_keys in fader_mappings.items():
            if fader_id.startswith("fixture_type_"):
                profile_name = fader_id.replace("fixture_type_", "")
                midi_mgr.register_fader_callback(fader_id,
                    lambda val, max_val, pn=profile_name: self._on_fixture_type_midi_fader(pn, val, max_val))
        
        # Register callbacks for large fader controls in faders tab
        # Find all fader configs in all pages and register MIDI callbacks if they have CC assignments
        if hasattr(self, 'project') and hasattr(self.project, 'faders_project') and self.project.faders_project:
            for page in self.project.faders_project.pages:
                for fader_config in page.faders:
                    # Support both old single-CC and new multi-CC formats
                    if fader_config.midi_ccs:
                        for cc_num in fader_config.midi_ccs:
                            cc_key = f"cc:{cc_num}"
                            midi_mgr._fader_mappings[cc_key] = fader_config.id
                        
                        # Register callback (handles all mapped CCs)
                        midi_mgr.register_fader_callback(fader_config.id,
                            lambda val, max_val, fc=fader_config: self._on_midi_large_fader(fc, val, max_val))

        # ── Flash MIDI mappings ──────────────────────────────────────
        # Load saved flash mappings (note_key -> fader_id)
        flash_maps = self.app_settings.get('midi_flash_mappings', {})
        for note_key, fader_id in flash_maps.items():
            midi_mgr._flash_mappings[note_key] = fader_id

        # Connect the flash event signal (only once)
        if not getattr(self, '_flash_signal_connected', False):
            midi_mgr.midi_flash_event.connect(self._on_midi_flash_event)
            self._flash_signal_connected = True

        # ── Page navigation MIDI mappings ────────────────────────────
        nav_mappings = self.app_settings.get('midi_page_nav_mappings', {})
        for nav_id, midi_key in nav_mappings.items():
            self._register_page_nav_midi(nav_id, midi_key)
        if nav_mappings:
            print(f"[MIDI] Loaded {len(nav_mappings)} page-nav mapping(s): {nav_mappings}")

        # ── Page tab direct MIDI mappings ─────────────────────────────
        tab_mappings = self.app_settings.get('midi_page_tab_mappings', {})
        for page_id, midi_key in tab_mappings.items():
            self._register_page_tab_midi(page_id, midi_key)
        if tab_mappings:
            print(f"[MIDI] Loaded {len(tab_mappings)} page-tab mapping(s): {tab_mappings}")


    def _sync_faders_to_gui_on_startup(self):
        """Sync motorized faders to GUI values when the program loads.

        - Master and Effect Speed faders move to their current GUI values.
        - All programmable faders (fader_1..fader_20) are forced to 0.
        """
        midi_mgr = get_midi_manager()
        if not midi_mgr.is_available or not midi_mgr.is_connected:
            print("[FaderSync] MIDI not available or not connected, skipping sync")
            return

        print("[FaderSync] Syncing faders to GUI on startup...")
        fader_mappings = self.app_settings.get('midi_fader_mappings', {})
        print(f"[FaderSync] Fader mappings from settings: {fader_mappings}")

        # Master fader: keep project/master slider value
        if fader_mappings.get("master") and hasattr(self, "master_slider"):
            master_val = self.master_slider.value()
            print(f"[FaderSync] Sending master fader to {master_val}")
            self._send_fader_feedback("master", master_val, max_val=self.master_slider.maximum())

        # Video volume fader: keep current global video volume slider value
        if fader_mappings.get("video_volume") and hasattr(self, "video_volume_slider"):
            video_volume_val = self.video_volume_slider.value()
            print(f"[FaderSync] Sending video_volume fader to {video_volume_val}")
            self._send_fader_feedback("video_volume", video_volume_val, max_val=self.video_volume_slider.maximum())

        # Effect speed fader: keep current speed slider value
        if fader_mappings.get("effect_speed") and hasattr(self, "effect_speed_slider"):
            speed_val = self.effect_speed_slider.value()
            print(f"[FaderSync] Sending effect_speed fader to {speed_val}")
            self._send_fader_feedback("effect_speed", speed_val, max_val=self.effect_speed_slider.maximum())

        # Programmable faders: always start at 0 on load
        if hasattr(self, "prog_faders"):
            for i, slider in enumerate(self.prog_faders, start=1):
                fader_id = f"fader_{i}"

                # Force GUI value to 0 for every programmable fader
                slider.setValue(0)

                # If this fader is mapped, send feedback so the motorized
                # fader on the controller also moves to 0
                if fader_mappings.get(fader_id):
                    print(f"[FaderSync] Sending {fader_id} to 0")
                    self._send_fader_feedback(fader_id, 0, max_val=100)
        
        # Push fader labels to V1-M scribble strips (delayed so MCU is ready)
        QTimer.singleShot(500, self._refresh_v1m_lcd_labels)
    
    def _refresh_v1m_lcd_labels(self):
        """Push current fader labels to the V1-M scribble-strip LCDs.

        Sends large LCD upper-row, small per-channel strip text, and
        backlight colours for the current page.
        Called on startup and when the fader page changes.
        """
        midi_mgr = get_midi_manager()
        if not midi_mgr.is_connected or not midi_mgr.has_v1m_connection:
            return

        # Determine the current page index
        page_idx = 0
        if hasattr(self, 'project') and hasattr(self.project, 'faders'):
            current_page = self.project.faders.get_current_page()
            if current_page:
                for i, page in enumerate(self.project.faders.pages):
                    if page.id == current_page.id:
                        page_idx = i
                        break
        start_fader = page_idx * 8
        exec_assignments = self.app_settings.get('fader_execution_assignments', {})

        strip_colors = []
        for slot in range(8):
            fader_num = start_fader + slot + 1
            fader_id = f"fader_{fader_num}"
            lcd_text = self._get_fader_lcd_label(fader_id, exec_assignments)
            strip_colors.append(self._get_fader_strip_color(fader_id, exec_assignments))
            # Large LCD: name on top row, value on bottom row
            display = lcd_text.ljust(7) + '  0%'.ljust(7)
            midi_mgr.update_v1m_lcd(slot + 1, display, row=0)
            # Small per-channel scribble strip
            midi_mgr.update_v1m_strip(slot + 1, upper=lcd_text[:7], lower='  0%')

        # Batch backlight colours
        midi_mgr.update_v1m_strip_colors(strip_colors)

    def _rebuild_universe_meters(self):
        """Rebuild universe meter rows to match project.universe_count."""
        # Clear existing
        while self._universe_box_layout.count():
            child = self._universe_box_layout.takeAt(0)
            if child.layout():
                while child.layout().count():
                    sub = child.layout().takeAt(0)
                    if sub.widget():
                        sub.widget().deleteLater()
            elif child.widget():
                child.widget().deleteLater()
        self.universe_meters = {}
        count = getattr(self.project, 'universe_count', 4)
        for uni in range(1, count + 1):
            row = QHBoxLayout()
            row.setSpacing(4)
            label = QLabel(f"U{uni}")
            label.setFixedWidth(25)
            meter = QProgressBar()
            meter.setMaximum(512)
            meter.setValue(0)
            meter.setTextVisible(False)
            meter.setMaximumHeight(10)
            self.universe_meters[uni] = meter
            row.addWidget(label)
            row.addWidget(meter)
            self._universe_box_layout.addLayout(row)

    def _update_stats(self):
        """Update Art-Net statistics display."""
        if self.artnet_running:
            self.artnet_packets_label.setText(f"Packets: {self.artnet.packets_sent:,}")
            
            # Update universe meters based on activity
            # Universe numbers in UI (1-4) match the keys in self.artnet.universes
            for uni_num, meter in self.universe_meters.items():
                uni = self.artnet.universes.get(uni_num)
                if uni:
                    # Count non-zero channels
                    active = sum(1 for v in uni.data if v > 0)
                    meter.setValue(active)
                else:
                    meter.setValue(0)
    
    # ==================== Project Management ====================

    # ── Licensing helpers ──

    def _check_license_on_startup(self):
        """Check license on startup; show dialog and start countdown if unlicensed."""
        try:
            from shared.licensing import check_is_licensed
            self._is_licensed = check_is_licensed(self._LD_API_KEY)
            if not self._is_licensed:
                self._start_unlicensed_timer()
                self._update_title()
                self._show_license_dialog()
                # Re-check after dialog (user may have activated)
                self._is_licensed = check_is_licensed(self._LD_API_KEY)
                if self._is_licensed:
                    self._stop_unlicensed_timer()
            self._update_title()
        except Exception as e:
            print(f"[License] startup check error: {e}", flush=True)
            self._is_licensed = True  # graceful fallback

        # Background update check (non-blocking, silent if no update)
        try:
            from PyQt6.QtCore import QTimer
            QTimer.singleShot(2000, lambda: self._check_for_updates(silent=True))
        except Exception:
            pass

    def _check_for_updates(self, silent: bool = True):
        """Check Appertini for a newer version. Runs on a background thread.

        Args:
            silent: If True, only show a banner when an update is available
                    and never show an error. If False (Help menu), always
                    show a result dialog.
        """
        import threading
        from PyQt6.QtCore import QTimer

        print(f"[Update] check_for_updates(silent={silent}) starting…", flush=True)

        # When invoked from the menu, give the user immediate visual feedback
        # so they know the click registered (the network call can take a few
        # seconds, especially on first launch).
        if not silent:
            try:
                self.statusBar().showMessage("Checking for updates…", 4000)
            except Exception:
                pass

        def _worker():
            info = {"error": "", "available": False}
            try:
                from shared.licensing import check_for_update
                info = check_for_update(self._LD_API_KEY)
                print(f"[Update] result: available={info.get('available')} "
                      f"current={info.get('current')!r} "
                      f"latest={info.get('latest')!r}", flush=True)
            except Exception as e:
                info = {"error": str(e), "available": False}
                print(f"[Update] worker error: {e}", flush=True)
            # Marshal back to the GUI thread via a Qt signal — QTimer.singleShot
            # called from a non-GUI thread silently does nothing because the
            # timer is created in a thread that has no event loop.
            try:
                self._update_result_signal.emit(info, silent)
            except Exception as e:
                print(f"[Update] emit error: {e}", flush=True)

        try:
            threading.Thread(target=_worker, name="update-check", daemon=True).start()
        except Exception as e:
            # Thread creation can fail under resource exhaustion; surface it
            # instead of leaving the status bar stuck on “Checking…” forever.
            print(f"[Update] failed to start worker thread: {e}", flush=True)
            try:
                self._update_result_signal.emit(
                    {"error": f"Could not start update check: {e}", "available": False},
                    silent,
                )
            except Exception:
                pass

    def _on_update_check_result(self, info: dict, silent: bool):
        """Show update result on the UI thread."""
        try:
            import webbrowser
            if info.get("error") and not silent:
                QMessageBox.warning(self, "Check for Updates",
                                    f"Could not check for updates:\n{info['error']}")
                return
            if not info.get("available"):
                if not silent:
                    cur = info.get("current") or "unknown"
                    QMessageBox.information(
                        self, "Check for Updates",
                        f"You are running the latest version.\n\nInstalled: {cur}")
                return
            current = info.get("current") or "unknown"
            latest = info.get("latest") or "?"
            url = info.get("download_url") or ""
            notes_url = info.get("release_notes_url") or ""
            notes_text = info.get("release_notes") or ""
            size_bytes = int(info.get("file_size_bytes") or 0)
            required = info.get("required", False)

            title = "Update Required" if required else "Update Available"
            size_str = ""
            if size_bytes:
                size_str = f"\nDownload size: {size_bytes / (1024*1024):.1f} MB"
            msg = (f"A {'required ' if required else 'new '}version is available.\n\n"
                   f"Installed: {current}\n"
                   f"Latest:     {latest}"
                   f"{size_str}")
            if notes_text:
                msg += f"\n\nWhat's new:\n{notes_text}"
            box = QMessageBox(self)
            box.setWindowTitle(title)
            box.setText(msg)
            box.setIcon(QMessageBox.Icon.Warning if required else QMessageBox.Icon.Information)
            dl_btn = box.addButton("Download && Install", QMessageBox.ButtonRole.AcceptRole)
            notes_btn = None
            if notes_url:
                notes_btn = box.addButton("Release Notes", QMessageBox.ButtonRole.HelpRole)
            box.addButton("Later", QMessageBox.ButtonRole.RejectRole)
            box.exec()
            clicked = box.clickedButton()
            if clicked is dl_btn and url:
                self._download_and_install_update(info)
            elif notes_btn is not None and clicked is notes_btn and notes_url:
                webbrowser.open(notes_url)
        except Exception as e:
            print(f"[Update] result error: {e}", flush=True)

    def _download_and_install_update(self, info: dict):
        """Download the installer with a progress dialog, verify it, then
        launch it detached and quit so the new version can replace this one."""
        import os
        import sys
        import tempfile
        import threading
        import subprocess
        from PyQt6.QtCore import Qt, QTimer
        from PyQt6.QtWidgets import QProgressDialog, QApplication

        url = info.get("download_url") or ""
        if not url:
            QMessageBox.warning(self, "Update", "No download URL was provided.")
            return

        file_name = info.get("file_name") or "LightingDesignSuite-Setup.exe"
        # Strip any path components from the server-supplied name.
        file_name = os.path.basename(file_name) or "LightingDesignSuite-Setup.exe"
        dest_path = os.path.join(tempfile.gettempdir(), file_name)
        expected_sha = info.get("file_sha256") or ""
        expected_size = int(info.get("file_size_bytes") or 0)

        dlg = QProgressDialog(
            f"Downloading {file_name}…", "Cancel", 0,
            max(100, expected_size // 1024 if expected_size else 100), self,
        )
        dlg.setWindowTitle("Downloading Update")
        dlg.setWindowModality(Qt.WindowModality.WindowModal)
        dlg.setAutoClose(False)
        dlg.setAutoReset(False)
        dlg.setMinimumDuration(0)
        dlg.setValue(0)

        # Track user-initiated cancel separately from programmatic dlg.cancel()
        # so that closing the progress dialog after a SUCCESSFUL download does not
        # set state["cancelled"] (which would silently skip launching the installer).
        state = {"cancelled": False, "error": None, "path": None, "finished": False}

        def _cancel():
            # Only honor as a user cancel if the worker hasn't already finished.
            if state["finished"]:
                return
            state["cancelled"] = True
        dlg.canceled.connect(_cancel)

        # Use a small QObject with signals so progress/finish callbacks from
        # the worker thread are marshalled to the GUI thread safely.
        # (QTimer.singleShot from a non-GUI thread silently does nothing.)
        from PyQt6.QtCore import QObject, pyqtSignal as _pyqtSignal

        class _DLSignals(QObject):
            progress = _pyqtSignal(int, int)
            finished = _pyqtSignal()

        sigs = _DLSignals(self)

        def _apply_progress(done_bytes: int, total_bytes: int):
            if state["cancelled"]:
                return
            if total_bytes:
                dlg.setMaximum(max(1, total_bytes // 1024))
            dlg.setValue(done_bytes // 1024)
            if total_bytes:
                pct = (done_bytes / total_bytes) * 100.0
                dlg.setLabelText(
                    f"Downloading {file_name}…\n"
                    f"{done_bytes/(1024*1024):.1f} MB of "
                    f"{total_bytes/(1024*1024):.1f} MB  ({pct:.0f}%)"
                )
            else:
                dlg.setLabelText(
                    f"Downloading {file_name}…\n"
                    f"{done_bytes/(1024*1024):.1f} MB"
                )
        sigs.progress.connect(_apply_progress)

        def _on_progress(done_bytes, total_bytes):
            try:
                sigs.progress.emit(int(done_bytes), int(total_bytes))
            except Exception:
                pass

        def _worker():
            try:
                from shared.licensing import download_update
                path = download_update(
                    url, dest_path,
                    expected_sha256=expected_sha,
                    expected_size=expected_size,
                    api_key=self._LD_API_KEY,
                    progress_cb=_on_progress,
                    cancel_cb=lambda: state["cancelled"],
                )
                state["path"] = path
            except Exception as e:
                state["error"] = str(e)
            try:
                sigs.finished.emit()
            except Exception:
                pass

        def _finish():
            # Mark download finished BEFORE closing the dialog.  QProgressDialog.cancel()
            # emits the `canceled` signal which previously set state["cancelled"] = True
            # and made _do_install silently return — the classic "download finishes,
            # then nothing happens" symptom.  The `finished` flag tells _cancel to
            # ignore the programmatic close.
            state["finished"] = True
            try:
                # Disconnect the user-cancel handler defensively so even a
                # racing emit can't flip state["cancelled"].
                dlg.canceled.disconnect(_cancel)
            except (TypeError, RuntimeError):
                pass
            try:
                dlg.hide()
            except Exception:
                pass
            try:
                dlg.done(0)  # exits exec() without re-emitting canceled
            except Exception:
                pass
            try:
                dlg.close()
            except Exception:
                pass
            QTimer.singleShot(0, _do_install)

        def _do_install():
            if state["cancelled"]:
                return
            if state["error"]:
                QMessageBox.critical(
                    self, "Update Failed",
                    f"Could not download the update:\n\n{state['error']}",
                )
                return
            path = state["path"]
            print(f"[Update] _do_install: path={path!r} exists={os.path.exists(path) if path else False}",
                  flush=True)
            if not path or not os.path.exists(path):
                msg = f"Installer file not found after download: {path!r}"
                print(f"[Update] {msg}", flush=True)
                QMessageBox.critical(self, "Update Failed",
                                     "Installer not found after download.")
                return
            # ── Windows: remove the Zone.Identifier alternate data stream ─────
            # Files downloaded via urllib get an ADS that marks them as
            # "from the internet" (Zone 3).  Windows SmartScreen silently
            # blocks os.startfile() on such files without raising a Python
            # exception, so the installer never appears.  Removing the ADS
            # is the programmatic equivalent of Properties → "Unblock".
            if sys.platform.startswith("win"):
                try:
                    import ctypes
                    ctypes.windll.kernel32.DeleteFileW(path + ":Zone.Identifier")
                    print("[Update] Removed Zone.Identifier ADS", flush=True)
                except Exception as _ze:
                    print(f"[Update] Zone.Identifier removal skipped: {_ze}", flush=True)

            # Prompt the user to save any unsaved changes before the app quits.
            if getattr(self, '_dirty', False) or getattr(self, '_project_dirty', False):
                from PyQt6.QtWidgets import QMessageBox as _MB
                reply = _MB.question(
                    self, "Save before update?",
                    "You have unsaved changes.\n\nSave the project before installing the update?",
                    _MB.StandardButton.Save | _MB.StandardButton.Discard | _MB.StandardButton.Cancel,
                    _MB.StandardButton.Save,
                )
                if reply == _MB.StandardButton.Cancel:
                    return
                if reply == _MB.StandardButton.Save:
                    try:
                        self._save_project()
                    except Exception as _se:
                        print(f"[Update] save before update failed: {_se}", flush=True)

            # No second confirmation prompt: the user already chose to
            # download AND install on the previous dialog.  Launching here
            # is the natural continuation of that click.
            launched = False
            launch_err = None
            try:
                if sys.platform.startswith("win"):
                    # Use "runas" verb so Windows prompts for UAC elevation
                    # (the installer requires admin rights for desktop shortcuts
                    # and Program Files installation).
                    try:
                        import ctypes as _ct
                        ret = _ct.windll.shell32.ShellExecuteW(
                            None, "runas", path, None, None, 1  # SW_SHOWNORMAL
                        )
                        print(f"[Update] ShellExecuteW(runas) returned {ret}", flush=True)
                        if ret > 32:
                            launched = True
                        else:
                            raise OSError(f"ShellExecuteW error code {ret}")
                    except Exception as _se:
                        print(f"[Update] ShellExecuteW failed ({_se}), trying Popen", flush=True)
                        # Fallback: detached Popen
                        DETACHED_PROCESS = 0x00000008
                        CREATE_NEW_PROCESS_GROUP = 0x00000200
                        proc = subprocess.Popen(
                            [path],
                            creationflags=DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP,
                            close_fds=True,
                        )
                        print(f"[Update] Popen pid={proc.pid}", flush=True)
                        launched = True
                else:
                    subprocess.Popen([path], close_fds=True)
                    launched = True
            except Exception as e:
                launch_err = e
                print(f"[Update] launch error: {e}", flush=True)

            if not launched:
                QMessageBox.critical(self, "Update Failed",
                                     f"Could not launch installer:\n\n{launch_err}")
                return

            print("[Update] Installer launched — quitting app in 1 s", flush=True)
            # Give the spawned installer 1 s to attach to Explorer / show the
            # UAC prompt before we tear down the Qt event loop.
            QTimer.singleShot(1000, QApplication.instance().quit)

        sigs.finished.connect(_finish)
        threading.Thread(target=_worker, name="update-download", daemon=True).start()
        dlg.exec()

    def _show_license_dialog(self):
        """Show the license information / activation dialog."""
        try:
            from shared.licensing import show_license_dialog_qt
            def _on_activated():
                self._is_licensed = True
                self._stop_unlicensed_timer()
                self._update_title()
            result = show_license_dialog_qt(
                self._LD_API_KEY, parent=self,
                app_label="Lighting Designer", on_activated=_on_activated,
                unlicensed_message="The application will close after 15 minutes.\nRegister to remove this limit.",
            )
            if result:
                self._is_licensed = True
                self._stop_unlicensed_timer()
                self._update_title()
        except Exception as e:
            print(f"[License] dialog error: {e}", flush=True)
            import traceback; traceback.print_exc()
            QMessageBox.warning(self, "License", f"Could not open license dialog:\n{e}")

    def _start_unlicensed_timer(self):
        """Start the 15-minute countdown timer for unlicensed use."""
        self._unlicensed_seconds_remaining = 15 * 60  # 15 minutes
        self._unlicensed_warned = False
        self._unlicensed_timer = QTimer(self)
        self._unlicensed_timer.timeout.connect(self._unlicensed_tick)
        self._unlicensed_timer.start(1000)  # every second
        self._update_title()

    def _stop_unlicensed_timer(self):
        """Stop the countdown timer (e.g. after activation)."""
        if self._unlicensed_timer is not None:
            self._unlicensed_timer.stop()
            self._unlicensed_timer = None
        self._unlicensed_seconds_remaining = 0

    def _unlicensed_tick(self):
        """Called every second while the unlicensed countdown is active."""
        self._unlicensed_seconds_remaining -= 1
        self._update_title()

        # 3-minute warning
        if self._unlicensed_seconds_remaining == 3 * 60 and not self._unlicensed_warned:
            self._unlicensed_warned = True
            QMessageBox.warning(
                self,
                "Lighting Designer — Unregistered",
                "This copy of Lighting Designer is not registered.\n\n"
                "The application will close in 3 minutes.\n\n"
                "Please register to continue using the software.",
            )

        # Time's up
        if self._unlicensed_seconds_remaining <= 0:
            self._stop_unlicensed_timer()
            QMessageBox.critical(
                self,
                "Lighting Designer — Session Expired",
                "The 15-minute unregistered session has expired.\n\n"
                "Please register your copy to continue using Lighting Designer.",
            )
            QApplication.instance().quit()

    def _update_title(self):
        """Update window title with project name and dirty state."""
        modified = " *" if self._dirty else ""
        path_info = f" - {self.project_path}" if self.project_path else ""
        base = f"Lighting Designer - {self.project.name}{path_info}{modified}"
        if not self._is_licensed:
            if self._unlicensed_seconds_remaining > 0:
                mins = self._unlicensed_seconds_remaining // 60
                secs = self._unlicensed_seconds_remaining % 60
                base += f"  [UNREGISTERED — {mins:02d}:{secs:02d} remaining]"
            else:
                base += "  [UNREGISTERED]"
        self.setWindowTitle(base)
    
    def _on_tab_changed(self, index: int):
        """Handle tab changes - refresh data as needed."""
        tab_name = self.tabs.tabText(index)
        logger.debug(f"_on_tab_changed: tab_name={tab_name}")

        # ── Cleanup when LEAVING the previous tab ──
        prev_tab = getattr(self, '_last_tab_name', None)

        if prev_tab == "CREATE\nPRESETS" and tab_name != "CREATE\nPRESETS":
            # Stop any effects / cues that were playing on the CREATE tab
            self._refine_stop_clicked()
            self._refine_loaded_preset_id = None
            self._current_effect = None
            if hasattr(self, 'refine_preset_combo'):
                self.refine_preset_combo.blockSignals(True)
                self.refine_preset_combo.setCurrentIndex(0)
                self.refine_preset_combo.blockSignals(False)
            if hasattr(self, 'refine_editing_label'):
                self.refine_editing_label.setText("")

        if prev_tab in ("LOCATION", "LIGHTING PREVIEW") and tab_name not in ("LOCATION", "LIGHTING PREVIEW"):
            # Clear only if the user actually set something on the preview tab
            has_claimed = bool(getattr(self, '_preview_claimed_channels', None))
            if has_claimed:
                self._clear_look()

        # ── Entering the new tab ──
        if tab_name == "GROUPS":
            self._refresh_groups_table()
        elif tab_name == "POSITIONS":
            self._refresh_position_presets_list()
            self._refresh_position_sliders()
        elif tab_name in ("LOCATION", "LIGHTING PREVIEW"):
            self._refresh_location_view()
            # Force overlay re-render after scene rebuild if overlay is active
            if getattr(self, '_viz_stage_overlay', False):
                frame = getattr(self, '_viz_overlay_frame', None)
                if frame is not None:
                    def _reapply_overlay():
                        self._viz_overlay_last_t = 0.0
                        self._update_viz_stage_overlay(frame)
                    QTimer.singleShot(100, _reapply_overlay)
        elif tab_name == "CREATE\nPRESETS":
            self._refresh_refine_presets()
            self._refresh_refine_target_groups()
            self._refresh_saved_palettes()
            self._refresh_position_cycle_checkboxes()  # Refresh position presets for cycling
            self._rebuild_quick_effect_group_buttons()  # Refresh group buttons for Quick Effects
            # Load current effect from CREATE tab if one is active and no preset is loaded
            logger.debug(f"REFINE tab: _current_effect={self._current_effect is not None}, _refine_loaded_preset_id={self._refine_loaded_preset_id}")
            if self._current_effect and not self._refine_loaded_preset_id:
                logger.debug("Calling _load_current_effect_into_refine()")
                self._load_current_effect_into_refine()
        elif tab_name == "PRESET\nSHORTCUTS":
            # Only trigger OFF when coming from a different tab (not from within PRESET SHORTCUTS tab)
            # This prevents double-clicking when selecting presets
            if not hasattr(self, '_last_tab_name') or self._last_tab_name != "PRESET\nSHORTCUTS":
                print(f"[Execute] Switching to PRESET SHORTCUTS tab from {getattr(self, '_last_tab_name', 'unknown')} - triggering OFF")
                self._execute_off()
            self._refresh_execute_buttons()
        
        elif tab_name == "VIDEO\nVISUALIZER":
            try:
                try:
                    from .visualizer_tab import refresh_visualizer_tab
                except ImportError:
                    from visualizer_tab import refresh_visualizer_tab
                refresh_visualizer_tab(self)
            except Exception:
                pass

        # Track last tab for execute tab logic
        self._last_tab_name = tab_name

        # If the user navigated away from the CREATE screen and the default
        # look was suppressed (via Clear Look), lift the suppression and
        # restore the default look so the rig returns to its baseline state.
        # However, do NOT lift the suppression while the visualizer is
        # actively playing — it sets the same flag to keep its overlay in
        # control of the fixtures.
        viz_playing = getattr(self, '_viz_active_item_id', None) is not None
        if getattr(self, '_default_look_suppressed', False) and tab_name != 'CREATE\nPRESETS' and not viz_playing:
            self._default_look_suppressed = False
            self._maybe_restore_default_look()

        # Update dynamic MIDI fader mapping for tabs that contain faders
        if tab_name in ('MASTER DIMMERS', 'GROUPS', 'PRESET\nSHORTCUTS', 'FADERS'):
            self._update_dynamic_sliders_for_main_tab(tab_name)
    
    def _get_active_window(self) -> QWidget:
        """Get the active window for dialog parenting.
        
        Returns the currently active detached window if one is active,
        otherwise returns self (main window). This ensures dialogs appear
        on top of the window the user is interacting with.
        """
        active_window = QApplication.activeWindow()
        # Check if active window is one of our detached windows
        if hasattr(self, '_detached_windows'):
            for window in self._detached_windows.values():
                if window == active_window:
                    return window
        # Fall back to main window
        return self
    
    def _show_input_dialog(self, title: str, label: str, text: str = "") -> tuple[str, bool]:
        """Show an input dialog that stays on top of all windows.
        
        Args:
            title: Dialog window title
            label: Label text for the input field
            text: Default text in the input field
            
        Returns:
            Tuple of (entered_text, ok_pressed)
        """
        parent = self._get_active_window()
        dialog = QDialog(parent)
        dialog.setWindowTitle(title)
        dialog.setMinimumWidth(350)
        
        layout = QVBoxLayout(dialog)
        layout.setSpacing(12)
        
        label_widget = QLabel(label)
        layout.addWidget(label_widget)
        
        line_edit = QLineEdit(text)
        line_edit.setMinimumHeight(36)
        line_edit.setStyleSheet("font-size: 14px; padding: 4px;")
        layout.addWidget(line_edit)
        
        buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        buttons.accepted.connect(dialog.accept)
        buttons.rejected.connect(dialog.reject)
        layout.addWidget(buttons)
        
        # Focus the line edit
        line_edit.setFocus()
        line_edit.selectAll()
        
        if dialog.exec() == QDialog.DialogCode.Accepted:
            return line_edit.text(), True
        return "", False
    
    def _show_message_box(self, msg_type: str, title: str, text: str, 
                          buttons=None) -> QMessageBox.StandardButton:
        """Show a message box that stays on top of all windows.
        
        Args:
            msg_type: "warning", "question", "information", or "critical"
            title: Dialog window title
            text: Message text
            buttons: QMessageBox.StandardButton flags (optional)
            
        Returns:
            The button that was clicked
        """
        parent = self._get_active_window()
        
        if msg_type == "warning":
            if buttons is None:
                buttons = QMessageBox.StandardButton.Ok
            box = QMessageBox(QMessageBox.Icon.Warning, title, text, buttons, parent)
        elif msg_type == "question":
            if buttons is None:
                buttons = QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
            box = QMessageBox(QMessageBox.Icon.Question, title, text, buttons, parent)
        elif msg_type == "critical":
            if buttons is None:
                buttons = QMessageBox.StandardButton.Ok
            box = QMessageBox(QMessageBox.Icon.Critical, title, text, buttons, parent)
        else:  # information
            if buttons is None:
                buttons = QMessageBox.StandardButton.Ok
            box = QMessageBox(QMessageBox.Icon.Information, title, text, buttons, parent)
        return box.exec()
    
    def _mark_dirty(self):
        """Mark project as having unsaved changes."""
        if not self._dirty:
            self._dirty = True
            self._update_title()
    
    def _load_app_settings(self) -> dict:
        """Load application settings from disk."""
        try:
            if os.path.exists(self.SETTINGS_FILE):
                with open(self.SETTINGS_FILE, 'r', encoding='utf-8') as f:
                    return json.load(f)
        except Exception as e:
            print(f"Failed to load settings: {e}")
        return {}
    
    def _save_app_settings(self):
        """Save application settings to disk."""
        try:
            with open(self.SETTINGS_FILE, 'w', encoding='utf-8') as f:
                json.dump(self.app_settings, f, indent=2)
        except Exception as e:
            print(f"Failed to save settings: {e}")
    
    def _initialize_midi(self):
        """Initialize MIDI support on startup."""
        midi_mgr = get_midi_manager()
        if not midi_mgr.is_available:
            print("[MIDI] MIDI support not available (mido not installed)")
            return
        
        # Connect fader intensity signal for execution control
        midi_mgr.midi_fader_intensity.connect(self._on_midi_fader_intensity)
        
        # Load saved mappings
        saved_mappings = self.app_settings.get('midi_mappings', {})
        if saved_mappings:
            midi_mgr.load_mappings(saved_mappings)
            print(f"[MIDI] Loaded {len(saved_mappings)} saved mappings")
        
        # Load saved device mappings (which controller made each mapping)
        saved_devices = self.app_settings.get('midi_mapping_devices', {})
        if saved_devices:
            midi_mgr.load_mapping_devices(saved_devices)
            print(f"[MIDI] Loaded {len(saved_devices)} device mappings")
        
        # Load saved fader mappings
        self._setup_midi_fader_callbacks()
        
        # Try to connect to saved ports (supports both old single port and new multi-port)
        saved_ports = self.app_settings.get('midi_input_ports', [])
        if not saved_ports:
            # Backwards compatibility: check for old single port setting
            saved_port = self.app_settings.get('midi_input_port', '')
            if saved_port:
                saved_ports = [saved_port]
        
        if saved_ports:
            available_ports = midi_mgr.get_input_ports()
            for saved_port in saved_ports:
                if saved_port in available_ports:
                    if midi_mgr.connect(saved_port):
                        print(f"[MIDI] Auto-connected to: {saved_port}")
                else:
                    print(f"[MIDI] Saved port '{saved_port}' not available")
            
            # Start the watchdog to monitor connection and auto-reconnect after sleep/wake
            midi_mgr.start_watchdog(saved_ports)
            
            # Connect to reconnection signal to re-register callbacks and sync faders
            midi_mgr.reconnected.connect(self._on_midi_reconnected)
            
            # Register callbacks for all loaded mappings if any connections succeeded
            if midi_mgr.is_connected:
                self._register_midi_preset_callbacks()
                # Light up LEDs for all mapped buttons
                midi_mgr.refresh_all_leds()
                # Sync motorized faders to GUI state on startup after a short delay
                # (gives the controller time to be ready after connection)
                # - Master + Effect Speed keep their values
                # - All other mapped faders are forced to 0
                QTimer.singleShot(500, self._sync_faders_to_gui_on_startup)
        
        # Load dynamic MIDI settings
        dynamic_settings = self.app_settings.get('dynamic_midi', {})
        if dynamic_settings.get('enabled', False):
            midi_mgr.set_dynamic_mode_enabled(True)
            midi_mgr.set_dynamic_fader_count(dynamic_settings.get('fader_count', 8))
            slots = dynamic_settings.get('slots', {})
            midi_mgr.set_dynamic_fader_slots({int(k): v for k, v in slots.items()})
            self._setup_dynamic_midi_handlers()
            print(f"[DynamicMIDI] Loaded with {len(slots)} slot(s)")
        else:
            midi_mgr.set_dynamic_mode_enabled(False)

        # Start timecode input if enabled
        tc_settings = self.app_settings.get('timecode_source', {})
        if tc_settings.get('enabled', False):
            self._start_timecode_source()
        elif self.app_settings.get('network_mtc', {}).get('enabled', False):
            # Backward compat: old network_mtc setting without timecode_source
            self.app_settings['timecode_source'] = {
                'enabled': True,
                'source': 'network_mtc',
                'port': self.app_settings['network_mtc'].get('port', 5005),
            }
            self._start_timecode_source()

    
    def _register_midi_preset_callbacks(self):
        """Register MIDI callbacks for all presets that have mappings."""
        midi_mgr = get_midi_manager()
        # Register preset callbacks
        for preset in self.project.presets:
            mappings = midi_mgr.get_mappings_for_preset(preset.id)
            if mappings:
                midi_mgr.register_preset_callback(preset.id, lambda p=preset: self._execute_preset(p))
                # Also set the preset color for LED feedback
                preset_color = preset.color if preset.color else "#c97a50"
                midi_mgr.set_preset_color(preset.id, preset_color)
        # Register OFF button callback
        if midi_mgr.get_mappings_for_preset("__OFF__"):
            midi_mgr.register_preset_callback("__OFF__", self._execute_off)
            midi_mgr.set_preset_color("__OFF__", "#ff0000")
        # Register Blackout button callback
        if midi_mgr.get_mappings_for_preset("__BLACKOUT__"):
            midi_mgr.register_preset_callback("__BLACKOUT__", self._blackout)
            midi_mgr.set_preset_color("__BLACKOUT__", "#d35400")
        # Register shortcut button callbacks
        for page in self.project.shortcut_pages:
            for shortcut in page.shortcuts:
                shortcut_midi_id = f"shortcut_{shortcut.id}"
                if midi_mgr.get_mappings_for_preset(shortcut_midi_id):
                    midi_mgr.register_preset_callback(shortcut_midi_id, lambda s=shortcut: self._trigger_shortcut(s))
                    shortcut_color = shortcut.color if shortcut.color else "#c97a50"
                    midi_mgr.set_preset_color(shortcut_midi_id, shortcut_color)
        # Register visualizer item callbacks (video / effect buttons)
        viz_items = getattr(self.project, '_visualizer_items', [])
        for viz_item in viz_items:
            viz_preset_id = f"viz_{viz_item.id}"
            if midi_mgr.get_mappings_for_preset(viz_preset_id):
                midi_mgr.register_preset_callback(
                    viz_preset_id,
                    lambda it=viz_item: self._trigger_viz_item(it)
                )
                viz_color = viz_item.color if viz_item.color else "#4488cc"
                midi_mgr.set_preset_color(viz_preset_id, viz_color)
        # Register visualizer OFF button callback
        if midi_mgr.get_mappings_for_preset("viz_off"):
            try:
                from .visualizer_tab import _stop_visualizer
            except ImportError:
                from visualizer_tab import _stop_visualizer
            midi_mgr.register_preset_callback(
                "viz_off",
                lambda: _stop_visualizer(self)
            )
            midi_mgr.set_preset_color("viz_off", "#cc3333")
        # Register view icon callbacks
        try:
            try:
                from .views_manager import _get_views
            except ImportError:
                from views_manager import _get_views
            for v in _get_views(self):
                preset_id = f"__VIEW__:{v['id']}"
                if midi_mgr.get_mappings_for_preset(preset_id):
                    vid = v['id']
                    midi_mgr.register_preset_callback(
                        preset_id, lambda _vid=vid: self._load_view_from_tab_bar(_vid))
                    midi_mgr.set_preset_color(preset_id, "#5588cc")
        except Exception as e:
            print(f"[MIDI] Error registering view callbacks: {e}")
        print(f"[MIDI] Registered {len(midi_mgr._preset_callbacks)} callbacks")
    
    def _setup_midi_after_project_load(self):
        """Setup MIDI callbacks and LEDs after project is loaded."""
        midi_mgr = get_midi_manager()
        if not midi_mgr.is_available:
            return
        
        # Register callbacks now that we have presets
        self._register_midi_preset_callbacks()
        
        # Update LED colors with preset colors
        if midi_mgr.is_connected:
            midi_mgr.refresh_all_leds()
    
    def _on_midi_reconnected(self, port_name: str):
        """Handle MIDI device reconnection after sleep/wake.
        
        Re-registers all callbacks, syncs faders, and refreshes LEDs.
        """
        print(f"[MIDI] Handling reconnection to: {port_name}")
        midi_mgr = get_midi_manager()
        
        # Re-register preset callbacks
        self._register_midi_preset_callbacks()
        
        # Re-setup fader callbacks
        self._setup_midi_fader_callbacks()
        
        # Sync faders to GUI state after a short delay (device needs time to be ready)
        QTimer.singleShot(500, self._sync_faders_to_gui_on_startup)
        
        # Refresh LEDs
        QTimer.singleShot(600, midi_mgr.refresh_all_leds)
        
        # Show toast notification if available
        try:
            self.statusBar().showMessage(f"🎹 MIDI reconnected: {port_name}", 5000)
        except Exception:
            pass  # Status bar may not be available
        
        print(f"[MIDI] Reconnection handling complete for: {port_name}")

    def _get_controller_from_midi_key(self, midi_key: str) -> str:
        """Get the controller device name for a MIDI mapping.
        
        Args:
            midi_key: MIDI key like "note:60", "cc:1", "pb:1"
            
        Returns:
            Controller device name or type description
        """
        # Check if we have the actual device name stored
        midi_mgr = get_midi_manager()
        device_name = midi_mgr.get_mapping_device(midi_key)
        
        if device_name and device_name != "Unknown":
            # Clean up device name - remove "[0] " prefix if present
            clean_name = device_name
            if clean_name.startswith("[") and "] " in clean_name:
                clean_name = clean_name.split("] ", 1)[1]
            # Shorten long device names for display
            if len(clean_name) > 25:
                return clean_name[:22] + "..."
            return clean_name
        
        # Fall back to connected device name if only one device is connected
        connected = midi_mgr.get_connected_devices()
        if len(connected) == 1:
            # Use the connected device name
            clean_name = connected[0]
            if clean_name.startswith("[") and "] " in clean_name:
                clean_name = clean_name.split("] ", 1)[1]
            if len(clean_name) > 25:
                return clean_name[:22] + "..."
            return clean_name
        elif len(connected) > 1:
            # Multiple devices - can't determine which one, show type
            pass
        
        # Fall back to generic type if no device name stored
        if midi_key.startswith("note:"):
            return "Note (Pad/Key)"
        elif midi_key.startswith("cc:"):
            return "CC (Knob/Slider)"
        elif midi_key.startswith("pb:"):
            return "Pitch Bend"
        else:
            return "Unknown"
    
    def _format_fader_id_for_display(self, fader_id: str) -> str:
        """Format a fader ID for user-friendly display.
        
        Args:
            fader_id: Internal fader ID like "master", "effect_speed", "group_drums", "fixture_type_LED"
            
        Returns:
            Human-readable fader name
        """
        if fader_id == "master":
            return "Master Fader"
        elif fader_id == "effect_speed":
            return "Effect Speed"
        elif fader_id.startswith("group_"):
            return f"Group: {fader_id[6:]}"
        elif fader_id.startswith("fixture_type_"):
            return f"Type: {fader_id[13:]}"
        elif fader_id.startswith("fader_"):
            return f"Exec Fader {fader_id[6:]}"
        elif fader_id.startswith("ch_fader_"):
            return f"Channel Fader: {fader_id[9:]}"
        else:
            return fader_id

    def _show_dynamic_midi_setup(self):
        """Show the Dynamic MIDI Fader Mapping setup dialog."""
        midi_mgr = get_midi_manager()
        
        if not midi_mgr.is_available:
            QMessageBox.warning(
                self, "MIDI Not Available",
                "MIDI support is not available on this system."
            )
            return
        
        dialog = QDialog(self._get_active_window())
        dialog.setWindowTitle("Setup Dynamic MIDI Mapping")
        dialog.setMinimumSize(700, 550)
        dialog.resize(900, 600)  # Larger default size
        dialog.setStyleSheet(DARK_STYLESHEET)
        
        layout = QVBoxLayout(dialog)
        layout.setSpacing(15)
        
        # Header with enable toggle
