    def _populate_faders_layout_for_page(self, layout: QHBoxLayout, page_id: str):
        """Populate a faders layout with faders for a specific page."""
        # Clear existing
        while layout.count():
            item = layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
        
        if not page_id:
            return
        
        # Find the page
        page = None
        for p in self.project.faders.pages:
            if p.id == page_id:
                page = p
                break
        
        if not page:
            return
        
        # Use existing populate logic
        self._populate_faders_layout(layout, is_main=False, page_override=page)
    
    def _on_fader_window_page_tab_changed(self, page_tabs: QTabBar, tab_index: int):
        """Handle page tab selection change in a fader window."""
        if tab_index < 0 or tab_index >= len(self.project.faders.pages):
            return
        
        page = self.project.faders.pages[tab_index]
        page_id = page.id
        
        # Find which fader window this tab bar belongs to
        for win_id, win_data in self._fader_windows.items():
            if win_data.get('page_tabs') is page_tabs:
                win_data['page_id'] = page_id
                win_data['page_idx'] = tab_index
                # Keep the model's current_page_id in sync so that
                # delete / rename always target the correct page.
                self.project.faders.current_page_id = page_id
                # Also sync the main window's tab bar (if it exists)
                if hasattr(self, 'faders_page_tabs') and self.faders_page_tabs is not None:
                    try:
                        self.faders_page_tabs.blockSignals(True)
                        self.faders_page_tabs.setCurrentIndex(tab_index)
                        self.faders_page_tabs.blockSignals(False)
                    except RuntimeError:
                        pass
                # Refresh the faders layout for this window
                self._populate_faders_layout_for_page(win_data['faders_layout'], page_id)
                
                # Update dynamic MIDI fader sliders for the new page
                self._refresh_dynamic_faders_for_window(win_data)
                
                # Send MIDI feedback after a short delay to ensure UI is updated
                QTimer.singleShot(50, lambda idx=tab_index: self._send_page_fader_feedback(idx))
                break
    
    def _on_fader_window_page_changed(self, page_combo: QComboBox, page_name: str):
        """Handle page selection change in a fader window (legacy combo box support)."""
        print(f"[Faders] Page changed callback triggered! page_name='{page_name}'")
        print(f"[Faders] _fader_windows keys: {list(self._fader_windows.keys())}")
        
        if not page_name:
            print(f"[Faders] Exiting - no page_name")
            return
        
        # Find the page by name
        page_id = None
        page_idx = 0
        for i, page in enumerate(self.project.faders.pages):
            if page.name == page_name:
                page_id = page.id
                page_idx = i
                break
        
        if not page_id:
            print(f"[Faders] Exiting - no page_id found for '{page_name}'")
            return
        
        print(f"[Faders] Found page_id={page_id}, page_idx={page_idx}")
        
        # Find which fader window this combo belongs to
        found_window = False
        found_win_data = None
        for win_id, win_data in self._fader_windows.items():
            print(f"[Faders] Checking window '{win_id}': combo is same={win_data.get('page_combo') is page_combo}")
            if win_data.get('page_combo') is page_combo:
                found_window = True
                found_win_data = win_data
                win_data['page_id'] = page_id
                win_data['page_idx'] = page_idx  # Store page index for MIDI fader filtering
                # Refresh the faders layout for this window
                self._populate_faders_layout_for_page(win_data['faders_layout'], page_id)
                print(f"[Faders] Window '{win_id}' switched to page '{page_name}' (id={page_id}, page_idx={page_idx})")
                
                # Update dynamic MIDI fader sliders for the new page
                self._refresh_dynamic_faders_for_window(win_data)
                
                # Send MIDI feedback after a short delay to ensure UI is updated
                QTimer.singleShot(50, lambda idx=page_idx: self._send_page_fader_feedback(idx))
                break
        
        if not found_window:
            print(f"[Faders] WARNING: Could not find fader window for page_combo!")
    
    def _get_fader_lcd_label(self, fader_id: str, exec_assignments: dict = None) -> str:
        """Return a label string for a fader's V1-M scribble strip.

        Checks execution assignment first (preset name), then falls back to
        the fader number.  Result is up to 7 ASCII characters (one LCD row).
        """
        if exec_assignments is None:
            exec_assignments = self.app_settings.get('fader_execution_assignments', {})
        assigned = exec_assignments.get(fader_id)
        if assigned:
            if assigned == '__OFF__':
                return 'OFF'
            if assigned.startswith('cuelist:'):
                cid = assigned.split(':', 1)[1]
                for cl in self.project.cue_lists:
                    if cl.id == cid:
                        return cl.name[:7]
                return 'CueList'
            for preset in self.project.presets:
                if preset.id == assigned:
                    return preset.name[:7]
            return 'Preset'
        # No assignment — show fader number
        num = fader_id.replace('fader_', '')
        return f'Fdr {num}'

    def _get_fader_strip_color(self, fader_id: str, exec_assignments: dict = None) -> tuple[int, int, int]:
        """Return an (R, G, B) 0-255 tuple for a fader's scribble-strip backlight.

        Uses the assigned preset's colour when available, otherwise a dim
        default so the strips aren't dark.
        """
        if exec_assignments is None:
            exec_assignments = self.app_settings.get('fader_execution_assignments', {})
        assigned = exec_assignments.get(fader_id)
        if assigned and assigned != '__OFF__':
            # Try preset colour
            pid = assigned
            if assigned.startswith('cuelist:'):
                pid = None  # cue lists don't carry a colour — use default
            if pid:
                for preset in self.project.presets:
                    if preset.id == pid:
                        hex_col = getattr(preset, 'color', None)
                        if hex_col and hex_col.startswith('#') and len(hex_col) >= 7:
                            try:
                                r = int(hex_col[1:3], 16)
                                g = int(hex_col[3:5], 16)
                                b = int(hex_col[5:7], 16)
                                return (r, g, b)
                            except ValueError:
                                pass
                        break
            # Cue list or unrecognised — warm white
            return (80, 80, 60)
        # No assignment — dim grey
        return (30, 30, 30)

    def _send_page_fader_feedback(self, page_idx: int):
        """Send MIDI feedback for all faders on a page."""
        start_fader = page_idx * 8
        midi_mgr = get_midi_manager()
        has_v1m = midi_mgr.has_v1m_connection
        
        # Get dynamic fader slots (pb:1 -> slot 0, pb:2 -> slot 1, etc.)
        dynamic_slots = midi_mgr.get_dynamic_fader_slots()  # {slot_idx: midi_key}
        
        print(f"[Faders] Sending MIDI feedback for page {page_idx + 1} (faders {start_fader + 1}-{start_fader + 8})")
        print(f"[Faders] Dynamic slots: {dynamic_slots}")
        
        # Resolve fader labels for V1-M scribble strips
        exec_assignments = self.app_settings.get('fader_execution_assignments', {})
        
        strip_colors = []  # collect (R,G,B) per slot for bulk color update (V1-M only)
        
        for slot in range(8):
            fader_idx = start_fader + slot
            fader_num = fader_idx + 1
            fader_id = f"fader_{fader_num}"
            
            lcd_text = self._get_fader_lcd_label(fader_id, exec_assignments)
            if has_v1m:
                strip_colors.append(self._get_fader_strip_color(fader_id, exec_assignments))
            
            if hasattr(self, 'prog_faders') and fader_idx < len(self.prog_faders):
                value = self.prog_faders[fader_idx].value()
                
                # Get MIDI key for this slot from dynamic_slots
                midi_key = dynamic_slots.get(slot)
                
                if midi_key:
                    midi_value = int((value / 100) * 127)
                    midi_value = max(0, min(127, midi_value))
                    
                    print(f"[Faders] Slot {slot+1} -> value={value}% -> MIDI {midi_key}={midi_value}")
                    midi_mgr.send_fader_feedback(midi_key, midi_value)
                    
                    if has_v1m:
                        # Large LCD: name on top row, value on bottom row
                        val_str = f'{value:3d}%'
                        display = lcd_text.ljust(7) + val_str.ljust(7)
                        midi_mgr.update_v1m_lcd(slot + 1, display, row=0)
                        # Push to small per-channel scribble strip
                        midi_mgr.update_v1m_strip(slot + 1, upper=lcd_text[:7], lower=val_str)
                else:
                    print(f"[Faders] Slot {slot+1} -> no MIDI mapping for slot {slot}")
                    if has_v1m:
                        # Blank the strips for unmapped slots
                        midi_mgr.update_v1m_lcd(slot + 1, "", row=0)
                        midi_mgr.update_v1m_strip(slot + 1, upper='', lower='')
        
        # Send all 8 strip backlight colours in one batch (V1-M only)
        if has_v1m:
            midi_mgr.update_v1m_strip_colors(strip_colors)
    
    def _on_fader_window_closed(self, window_id: str):
        """Handle fader window being closed."""
        print(f"[Faders] Window '{window_id}' closed")
        
        # Remove from tracking
        if window_id in self._fader_windows:
            del self._fader_windows[window_id]
        if window_id in self._detached_windows:
            del self._detached_windows[window_id]
        
        # Window positions are only saved via View > Save Window Locations
        # No auto-save on window close
    
    def _refresh_all_fader_windows(self):
        """Refresh all fader windows to reflect updated fader data."""
        # Refresh main faders layout
        if hasattr(self, 'faders_layout') and self.faders_layout is not None:
            try:
                self._populate_faders_layout(self.faders_layout, is_main=True)
            except RuntimeError:
                self.faders_layout = None
        
        # Refresh detached fader windows (each showing its own page)
        for win_id, win_data in list(self._fader_windows.items()):
            try:
                layout = win_data.get('faders_layout')
                page_id = win_data.get('page_id')
                if layout:
                    self._populate_faders_layout_for_page(layout, page_id)
            except RuntimeError:
                pass  # Window was deleted
    
    def _refresh_all_fader_windows_combos(self):
        """Refresh page tabs in all fader windows (when pages are added/removed/renamed)."""
        for win_id, win_data in list(self._fader_windows.items()):
            try:
                page_tabs = win_data.get('page_tabs')
                current_page_id = win_data.get('page_id')
                
                if page_tabs:
                    page_tabs.blockSignals(True)
                    
                    # Remove existing tabs
                    while page_tabs.count() > 0:
                        page_tabs.removeTab(0)
                    
                    # Add tabs for each page
                    for page in self.project.faders.pages:
                        page_tabs.addTab(page.name)
                    
                    # Restore selected page if it still exists
                    restored = False
                    for idx, page in enumerate(self.project.faders.pages):
                        if page.id == current_page_id:
                            page_tabs.setCurrentIndex(idx)
                            restored = True
                            break
                    
                    if not restored and page_tabs.count() > 0:
                        # Page was deleted, select first page
                        page_tabs.setCurrentIndex(0)
                        win_data['page_id'] = self.project.faders.pages[0].id if self.project.faders.pages else None
                        # Refresh the faders to show the new page
                        layout = win_data.get('faders_layout')
                        if layout and win_data['page_id']:
                            self._populate_faders_layout_for_page(layout, win_data['page_id'])
                    
                    page_tabs.blockSignals(False)
            except RuntimeError:
                pass  # Window was deleted
    
    def _save_fader_windows_state(self):
        """Save the state of all fader windows (positions and page selections).
        
        Only saves currently open fader windows - closed windows are NOT preserved.
        Always saves the current window position.
        """
        # Only save currently open windows - start fresh
        fader_windows_data = {}
        
        for win_id, win_data in self._fader_windows.items():
            window = win_data['window']
            
            # Don't save if using fallback position (monitor disconnected)
            if not window.shouldSavePosition():
                # Keep existing saved data if available, just update page_id
                existing = self.app_settings.get('fader_windows', {}).get(win_id, {})
                if existing:
                    existing['page_id'] = win_data['page_id']
                    fader_windows_data[win_id] = existing
                continue
            
            # Always save the current position - this is what the user sees
            pos = window.pos()
            fader_windows_data[win_id] = {
                'x': pos.x(),
                'y': pos.y(),
                'width': window.width(),
                'height': window.height(),
                'page_id': win_data['page_id'],
                'always_on_top': window.isAlwaysOnTop()
            }
        
        self.app_settings['fader_windows'] = fader_windows_data
        self._save_app_settings()
    
    def _restore_fader_windows(self):
        """Restore previously open fader windows."""
        saved_faders = self.app_settings.get('fader_windows', {})
        for win_id, win_data in saved_faders.items():
            page_id = win_data.get('page_id')
            self._open_new_fader_window(
                window_id=win_id,
                page_id=page_id,
                saved_pos=win_data
            )
    
    def _is_position_on_visible_screen(self, x: int, y: int, w: int, h: int) -> bool:
        """Check if a window position would be visible on any connected screen.
        
        Returns True if at least 100x100 pixels of the window would be visible.
        """
        from PyQt6.QtWidgets import QApplication
        from PyQt6.QtCore import QRect
        
        # Create rect for the window
        window_rect = QRect(x, y, w, h)
        
        # Check all available screens
        screens = QApplication.screens()
        print(f"[ScreenCheck] Window rect: ({x}, {y}, {w}, {h}), checking {len(screens)} screens")
        for i, screen in enumerate(screens):
            screen_rect = screen.availableGeometry()
            print(f"[ScreenCheck] Screen {i}: {screen.name()} = ({screen_rect.x()}, {screen_rect.y()}, {screen_rect.width()}, {screen_rect.height()})")
            intersection = window_rect.intersected(screen_rect)
            # Consider visible if at least 100x100 px would be on screen
            if intersection.width() >= 100 and intersection.height() >= 100:
                print(f"[ScreenCheck] Position IS visible on screen {i}")
                return True
        
        print(f"[ScreenCheck] Position NOT visible on any screen")
        return False
    
    def _center_window_on_primary(self, window):
        """Center a window on the primary screen."""
        from PyQt6.QtWidgets import QApplication
        
        primary = QApplication.primaryScreen()
        if primary:
            screen_rect = primary.availableGeometry()
            x = screen_rect.x() + (screen_rect.width() - window.width()) // 2
            y = screen_rect.y() + (screen_rect.height() - window.height()) // 2
            window.move(x, y)
    
