        'midi_encoder_directions',
        'midi_relative_ccs',
        'dynamic_midi',
        # Fader assignments
        'fader_execution_assignments',
        'fader_position_assignments',
        'fader_shortcut_assignments',
        'fader_modes',
        'group_fader_colors',
        'group_fader_overrides',
        'prog_fader_overrides',
        # Stage / visualizer preferences
        'stage_layout_show_names',
        'stage_layout_locked',
        'stage_layout_mirror_beams',
        'viz_overlay_locked',
        'viz_overlay_rect_geom',
